import React from 'react';
import { useStore } from '../context/StoreContext';
import { Play, Pause, SkipBack, SkipForward, Repeat, Shuffle, Volume2, Heart } from './Icons';
import { PlayMode } from '../types';

const formatTime = (seconds: number) => {
  if (!seconds) return "0:00";
  const mins = Math.floor(seconds / 60);
  const secs = Math.floor(seconds % 60);
  return `${mins}:${secs.toString().padStart(2, '0')}`;
};

export const Player = () => {
  const { 
    currentTrack, isPlaying, togglePlay, nextTrack, prevTrack, 
    progress, duration, seek, volume, setVolume, playMode, toggleRepeat,
    isLiked, toggleLike
  } = useStore();

  if (!currentTrack) {
    return (
      <div className="fixed bottom-0 w-full h-24 bg-surface border-t border-surface-highlight flex items-center justify-center text-secondary">
        Select a track to start listening
      </div>
    );
  }

  return (
    <div className="fixed bottom-0 w-full h-24 bg-surface border-t border-surface-highlight px-4 flex items-center justify-between z-50">

      {/* Track Info */}
      <div className="flex items-center w-1/4 min-w-[180px]">
        <img src={currentTrack.cover} alt="Cover" className="h-14 w-14 rounded shadow mr-4" />
        <div className="flex flex-col overflow-hidden mr-4">
          <span className="text-sm font-semibold text-white truncate hover:underline cursor-pointer">{currentTrack.title}</span>
          <span className="text-xs text-secondary truncate hover:underline cursor-pointer">{currentTrack.artist}</span>
        </div>
        <button 
          onClick={() => toggleLike(currentTrack.id)} 
          className={`hover:scale-105 transition ${isLiked(currentTrack.id) ? 'text-primary' : 'text-secondary hover:text-white'}`}
        >
          <Heart size={20} fill={isLiked(currentTrack.id) ? 'currentColor' : 'none'} />
        </button>
      </div>

      {/* Controls */}
      <div className="flex flex-col items-center w-2/4 max-w-2xl">
        <div className="flex items-center gap-6 mb-2">
          <button className="text-secondary hover:text-white transition">
            <Shuffle size={20} />
          </button>
          <button onClick={prevTrack} className="text-secondary hover:text-white transition">
            <SkipBack size={24} fill="currentColor" />
          </button>
          <button 
            onClick={togglePlay} 
            className="w-8 h-8 bg-white rounded-full flex items-center justify-center hover:scale-105 transition text-black"
          >
            {isPlaying ? <Pause size={20} fill="currentColor" /> : <Play size={20} fill="currentColor" className="ml-1" />}
          </button>
          <button onClick={nextTrack} className="text-secondary hover:text-white transition">
            <SkipForward size={24} fill="currentColor" />
          </button>
          <button 
            onClick={toggleRepeat} 
            className={`transition ${playMode === PlayMode.REPEAT_TRACK ? 'text-primary' : 'text-secondary hover:text-white'}`}
          >
            <Repeat size={20} />
          </button>
        </div>

        <div className="flex items-center w-full gap-2 text-xs text-secondary">
          <span>{formatTime(progress)}</span>
          <div className="flex-1 h-1 bg-surface-highlight rounded-full relative group">
             <input
                type="range"
                min={0}
                max={duration || 100}
                value={progress}
                onChange={(e) => seek(Number(e.target.value))}
                className="absolute w-full h-full opacity-0 cursor-pointer z-10"
              />
              <div 
                className="h-full bg-white rounded-full group-hover:bg-primary transition-colors"
                style={{ width: `${(progress / (duration || 1)) * 100}%` }}
              />
          </div>
          <span>{formatTime(duration)}</span>
        </div>
      </div>

      {/* Volume */}
      <div className="flex items-center justify-end w-1/4 min-w-[150px] gap-2">
        <Volume2 size={20} className="text-secondary" />
        <div className="w-24 h-1 bg-surface-highlight rounded-full relative group">
            <input 
              type="range" 
              min={0} 
              max={1} 
              step={0.01} 
              value={volume}
              onChange={(e) => setVolume(Number(e.target.value))}
              className="absolute w-full h-full opacity-0 cursor-pointer z-10"
            />
            <div 
              className="h-full bg-white rounded-full group-hover:bg-primary transition-colors"
              style={{ width: `${volume * 100}%` }}
            />
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
