};

import React, { useState } from 'react';
import { useStore } from '../context/StoreContext';
import { Search as SearchIcon, Play, Heart } from '../components/Icons';

export const Search = () => {
  const { tracks, playTrack, isLiked, toggleLike } = useStore();
  const [query, setQuery] = useState("");

  const filteredTracks = tracks.filter(t => 
    t.title.toLowerCase().includes(query.toLowerCase()) || 
    t.artist.toLowerCase().includes(query.toLowerCase()) ||
    t.album.toLowerCase().includes(query.toLowerCase())
  );

  return (
    <div className="p-8 pb-32 bg-background flex-1 overflow-y-auto h-full">
      <div className="mb-8 relative">
        <SearchIcon className="absolute left-4 top-3.5 text-black" size={24} />
        <input 
          type="text" 
          placeholder="What do you want to listen to?" 
          className="w-full md:w-96 py-3 pl-12 pr-4 rounded-full text-black font-semibold focus:outline-none focus:ring-2 focus:ring-white"
          value={query}
          onChange={e => setQuery(e.target.value)}
          autoFocus
        />
      </div>

      {query && (
        <div className="flex flex-col gap-2">
           <h2 className="text-xl font-bold mb-4">Songs</h2>
           {filteredTracks.length === 0 ? (
             <div className="text-secondary">No results found for "{query}"</div>
           ) : (
             filteredTracks.map(track => (
               <div 
                 key={track.id} 
                 className="flex items-center justify-between p-3 rounded hover:bg-surface-highlight group"
               >
                 <div className="flex items-center gap-4 flex-1" onClick={() => playTrack(track)}>
                    <div className="relative w-10 h-10">
                      <img src={track.cover} className="w-full h-full object-cover" />
                      <div className="absolute inset-0 bg-black/50 flex items-center justify-center opacity-0 group-hover:opacity-100">
                        <Play size={16} fill="white" />
                      </div>
                    </div>
                    <div>
                      <div className="font-semibold text-white">{track.title}</div>
                      <div className="text-sm text-secondary">{track.artist}</div>
                    </div>
                 </div>
                 <div className="flex items-center gap-4">
                    <span className="text-sm text-secondary hidden md:block">{Math.floor(track.duration / 60)}:{(track.duration % 60).toString().padStart(2,'0')}</span>
                    <button onClick={() => toggleLike(track.id)} className={`${isLiked(track.id) ? 'text-primary' : 'text-secondary hover:text-white'}`}>
                      <Heart size={18} fill={isLiked(track.id) ? 'currentColor' : 'none'} />
                    </button>
                 </div>
               </div>
             ))
           )}
        </div>
      )}

      {!query && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
           {/* Categories placeholders */}
           {['Pop', 'Hip-Hop', 'Rock', 'Electronic', 'Indie', 'Focus', 'Sleep', 'Jazz'].map(genre => (
             <div key={genre} className="aspect-square bg-surface-highlight rounded-lg p-4 font-bold text-2xl relative overflow-hidden cursor-pointer hover:bg-surface">
                {genre}
                <div className="absolute -bottom-2 -right-4 w-24 h-24 bg-gradient-to-br from-transparent to-black/50 rotate-12 rounded"></div>
             </div>
           ))}
        </div>
      )}
    </div>
  );
};

import React from 'react';
import { useStore } from '../context/StoreContext';
import { Play, Heart, ListMusic, Trash2 } from '../components/Icons';

export const Library = () => {
  const { 
    view, playlists, tracks, albums, isLiked, toggleLike, playTrack, 
    addToPlaylist, removeFromPlaylist 
  } = useStore();

  // --- Render Album or Playlist Detail ---
  if (view.type === 'PLAYLIST' || view.type === 'ALBUM') {
    let title = "", subtitle = "", cover = "", items: any[] = [];
    let isPlaylist = view.type === 'PLAYLIST';

    if (isPlaylist) {
      const pl = playlists.find(p => p.id === (view as any).id);
      if (!pl) return <div>Not Found</div>;
      title = pl.name;
      subtitle = `Playlist • ${pl.tracks.length} songs`;
      cover = pl.tracks.length > 0 ? (tracks.find(t => t.id === pl.tracks[0])?.cover || "") : "https://picsum.photos/300/300?grayscale";
      items = pl.tracks.map(tid => tracks.find(t => t.id === tid)).filter(Boolean);
    } else {
      const alb = albums.find(a => a.id === (view as any).id);
      if (!alb) return <div>Not Found</div>;
      title = alb.title;
      subtitle = `Album • ${alb.artist} • ${alb.year}`;
      cover = alb.cover;
      items = alb.trackIds.map(tid => tracks.find(t => t.id === tid)).filter(Boolean);
    }

    return (
      <div className="h-full overflow-y-auto pb-32">
        {/* Header */}
        <div className="flex flex-col md:flex-row items-end gap-6 p-8 bg-gradient-to-b from-slate-700 to-background">
          <img src={cover} alt={title} className="w-48 h-48 shadow-2xl" />
          <div className="flex flex-col gap-2">
            <span className="uppercase text-xs font-bold">{view.type}</span>
            <h1 className="text-5xl md:text-7xl font-bold tracking-tighter">{title}</h1>
            <p className="text-secondary font-semibold">{subtitle}</p>
          </div>
        </div>

        {/* Action Bar */}
        <div className="px-8 py-6 bg-background/50 backdrop-blur-sm sticky top-0 z-10 flex items-center gap-6">
          <button 
             onClick={() => items.length > 0 && playTrack(items[0])}
             className="w-14 h-14 bg-primary rounded-full flex items-center justify-center hover:scale-105 transition shadow-lg"
          >
            <Play size={28} fill="black" className="ml-1 text-black" />
          </button>
        </div>

        {/* List */}
        <div className="px-8">
           <div className="grid grid-cols-[16px_1fr_1fr_40px] gap-4 px-4 py-2 border-b border-surface-highlight text-secondary text-sm mb-4">
             <span>#</span>
             <span>Title</span>
             <span className="hidden md:block">Album</span>
             <span><ListMusic size={16} /></span>
           </div>

           {items.map((track, idx) => (
             <div key={track.id} className="grid grid-cols-[16px_1fr_40px] md:grid-cols-[16px_1fr_1fr_40px] gap-4 px-4 py-3 rounded hover:bg-surface-highlight group items-center">
               <span className="text-secondary group-hover:hidden">{idx + 1}</span>
               <button onClick={() => playTrack(track)} className="hidden group-hover:block text-white"><Play size={12} fill="white"/></button>

               <div className="flex items-center gap-3 overflow-hidden">
                 <img src={track.cover} className="w-10 h-10" />
                 <div className="flex flex-col">
                   <span className="text-white font-medium truncate">{track.title}</span>
                   <span className="text-secondary text-xs group-hover:text-white">{track.artist}</span>
                 </div>
               </div>

               <span className="text-secondary text-sm hidden md:block truncate">{track.album}</span>

               <div className="flex items-center gap-3">
                 <button onClick={() => toggleLike(track.id)} className={`${isLiked(track.id) ? 'text-primary' : 'text-transparent group-hover:text-secondary hover:text-white'}`}>
                    <Heart size={16} fill={isLiked(track.id) ? 'currentColor' : 'none'} />
                 </button>
                 {isPlaylist && (view as any).id !== 'liked' && (
                    <button onClick={() => removeFromPlaylist((view as any).id, track.id)} className="text-transparent group-hover:text-secondary hover:text-red-500">
                      <Trash2 size={16} />
                    </button>
                 )}
               </div>
             </div>
           ))}
        </div>
      </div>
    );
  }

  // --- Default Library View (List of playlists/albums) ---
  return (
    <div className="p-8 pb-32 h-full overflow-y-auto bg-background">
      <h2 className="text-2xl font-bold mb-6">Your Library</h2>
      <div className="flex flex-wrap gap-2 mb-6">
        <span className="px-4 py-2 bg-surface hover:bg-surface-highlight rounded-full text-sm font-bold cursor-pointer transition">Playlists</span>
        <span className="px-4 py-2 bg-surface hover:bg-surface-highlight rounded-full text-sm font-bold cursor-pointer transition">Artists</span>
        <span className="px-4 py-2 bg-surface hover:bg-surface-highlight rounded-full text-sm font-bold cursor-pointer transition">Albums</span>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-4">
        {playlists.map(pl => (
           <div key={pl.id} className="p-4 bg-surface hover:bg-surface-highlight rounded-lg cursor-pointer transition group">
              <div className="aspect-square bg-gradient-to-br from-surface-highlight to-black mb-4 shadow-lg flex items-center justify-center">
                 <ListMusic size={48} className="text-secondary" />
              </div>
              <h3 className="font-bold truncate text-white">{pl.name}</h3>
              <p className="text-sm text-secondary">Playlist</p>
           </div>
        ))}
      </div>
    </div>
  );
};

import React from 'react';
import { StoreProvider, useStore } from './context/StoreContext';
import { Sidebar } from './components/Sidebar';
import { Player } from './components/Player';
import { Home } from './pages/Home';
import { Search } from './pages/Search';
import { Library } from './pages/Library';

const MainView = () => {
  const { view } = useStore();

  const renderContent = () => {
    switch (view.type) {
      case 'HOME': return <Home />;
      case 'SEARCH': return <Search />;
      case 'LIBRARY': return <Library />;
      case 'PLAYLIST': return <Library />; // Reusing library component for detail view
      case 'ALBUM': return <Library />;
      default: return <Home />;
    }
  };

  return (
    <div className="flex-1 h-full bg-background overflow-hidden relative">
      {renderContent()}
    </div>
  );
};

export default function App() {
  return (
    <StoreProvider>
      <div className="flex h-screen w-full bg-black text-white font-sans">
        <Sidebar />
        <main className="flex-1 flex flex-col relative">
           {/* Top bar filler (usually for search/back buttons in real app, kept minimal here) */}
           <div className="h-16 w-full absolute top-0 left-0 bg-transparent z-10 pointer-events-none" />
           <MainView />
           <Player />
        </main>
      </div>
    </StoreProvider>
  );
}

import React from 'react';
import { 
  Home, Search, Library, PlusSquare, Heart, Play, Pause, 
  SkipBack, SkipForward, Repeat, Shuffle, Volume2, ListMusic, Trash2, Mic2,
  ArrowLeft
} from 'lucide-react';

export { 
  Home, Search, Library, PlusSquare, Heart, Play, Pause, 
  SkipBack, SkipForward, Repeat, Shuffle, Volume2, ListMusic, Trash2, Mic2,
  ArrowLeft
};

import React, { createContext, useContext, useEffect, useRef, useState } from 'react';
import { Track, Playlist, Album, ViewState, PlayMode } from '../types';
import { generateInitialData, StorageService } from '../services/data';

interface StoreContextType {
  tracks: Track[];
  albums: Album[];
  playlists: Playlist[];
  currentTrack: Track | null;
  isPlaying: boolean;
  playMode: PlayMode;
  volume: number;
  progress: number;
  duration: number;
  view: ViewState;

  // Actions
  setView: (v: ViewState) => void;
  goBack: () => void;
  playTrack: (track: Track) => void;
  togglePlay: () => void;
  nextTrack: () => void;
  prevTrack: () => void;
  seek: (time: number) => void;
  setVolume: (vol: number) => void;
  toggleRepeat: () => void;
  createPlaylist: (name: string) => void;
  deletePlaylist: (id: string) => void;
  addToPlaylist: (playlistId: string, trackId: string) => void;
  removeFromPlaylist: (playlistId: string, trackId: string) => void;
  toggleLike: (trackId: string) => void;
  isLiked: (trackId: string) => boolean;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

export const StoreProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  // --- Data State ---
  const [tracks, setTracks] = useState<Track[]>([]);
  const [albums, setAlbums] = useState<Album[]>([]);
  const [playlists, setPlaylists] = useState<Playlist[]>([]);

  // --- Player State ---
  const [currentTrack, setCurrentTrack] = useState<Track | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [playMode, setPlayMode] = useState<PlayMode>(PlayMode.NORMAL);
  const [volume, setVolumeState] = useState(0.5);
  const [progress, setProgress] = useState(0);
  const [duration, setDuration] = useState(0);
  const [hasCountedListen, setHasCountedListen] = useState(false);

  // --- UI State ---
  const [view, setViewInternal] = useState<ViewState>({ type: 'HOME' });
  const [history, setHistory] = useState<ViewState[]>([]);

  // --- Refs ---
  const audioRef = useRef<HTMLAudioElement>(new Audio());
  const cumulativeTimeRef = useRef(0);
  const lastTimeRef = useRef(0);

  // --- Initialization ---
  useEffect(() => {
    const { tracks: initialTracks, albums: initialAlbums } = generateInitialData();

    // Load persisted play counts
    const storedPlays = StorageService.load<Record<string, number>>('huevify_plays', {});
    const mergedTracks = initialTracks.map(t => ({
      ...t,
      plays: storedPlays[t.id] ?? t.plays
    }));

    setTracks(mergedTracks);
    setAlbums(initialAlbums);

    const storedPlaylists = StorageService.load<Playlist[]>('huevify_playlists', [
      { id: 'liked', name: 'Liked Songs', tracks: [], isSystem: true }
    ]);
    setPlaylists(storedPlaylists);

    // Setup Audio
    audioRef.current.volume = 0.5;
  }, []);

  // --- Persistence Effects ---
  useEffect(() => {
    if (playlists.length > 0) {
      StorageService.save('huevify_playlists', playlists);
    }
  }, [playlists]);

  useEffect(() => {
    if (tracks.length > 0) {
      const playCounts = tracks.reduce((acc, t) => ({ ...acc, [t.id]: t.plays }), {});
      StorageService.save('huevify_plays', playCounts);
    }
  }, [tracks]);

  // --- Navigation Actions ---
  const setView = (newView: ViewState) => {
    // Don't push duplicates if clicking same link
    if (JSON.stringify(view) !== JSON.stringify(newView)) {
      setHistory(prev => [...prev, view]);
      setViewInternal(newView);
    }
  };

  const goBack = () => {
    if (history.length > 0) {
      const prev = history[history.length - 1];
      setHistory(h => h.slice(0, -1));
      setViewInternal(prev);
    } else {
      setViewInternal({ type: 'HOME' });
    }
  };

  // --- Playback State Reset ---
  useEffect(() => {
    cumulativeTimeRef.current = 0;
    lastTimeRef.current = 0;
    setHasCountedListen(false);
  }, [currentTrack]);

  // --- Audio Logic ---
  useEffect(() => {
    const audio = audioRef.current;

    const handleTimeUpdate = () => {
      const now = audio.currentTime;
      setProgress(now);

      const diff = now - lastTimeRef.current;
      // Only accumulate time if difference is small (continuous playback, not seeking)
      // Standard playback delta is usually ~0.25s. Seek is usually > 1s.
      if (diff > 0 && diff < 1.5) {
        cumulativeTimeRef.current += diff;
      }
      lastTimeRef.current = now;

      // Listen Count Logic: 30 seconds threshold
      if (cumulativeTimeRef.current > 30 && !hasCountedListen && currentTrack) {
        handleListenCount(currentTrack);
      }
    };

    const handleEnded = () => {
      if (playMode === PlayMode.REPEAT_TRACK) {
        audio.currentTime = 0;
        audio.play();
      } else {
        nextTrack();
      }
    };

    const handleLoadedMetadata = () => {
        setDuration(audio.duration);
    }

    audio.addEventListener('timeupdate', handleTimeUpdate);
    audio.addEventListener('ended', handleEnded);
    audio.addEventListener('loadedmetadata', handleLoadedMetadata);

    return () => {
      audio.removeEventListener('timeupdate', handleTimeUpdate);
      audio.removeEventListener('ended', handleEnded);
      audio.removeEventListener('loadedmetadata', handleLoadedMetadata);
    };
  }, [currentTrack, hasCountedListen, playMode, tracks]); 

  const handleListenCount = (track: Track) => {
    const lastListenKey = `last_listen_${track.id}`;
    const lastListenTime = StorageService.load<number>(lastListenKey, 0);
    const now = Date.now();

    // Secondary check: throttle by track duration just in case
    if (now - lastListenTime > track.duration * 1000) {
      const addedPlays = Math.floor(100 + Math.random() * 9900);

      setTracks(prev => prev.map(t => 
        t.id === track.id ? { ...t, plays: t.plays + addedPlays } : t
      ));

      StorageService.save(lastListenKey, now);
      console.log(`Listen counted for ${track.title}. +${addedPlays} plays.`);
    }
    setHasCountedListen(true);
  };

  const playTrack = (track: Track) => {
    if (currentTrack?.id === track.id) {
      togglePlay();
      return;
    }

    setCurrentTrack(track);
    // State reset handled in useEffect [currentTrack]
    audioRef.current.src = track.url;
    audioRef.current.play()
      .then(() => setIsPlaying(true))
      .catch(e => console.error("Audio play failed", e));
  };

  const togglePlay = () => {
    if (audioRef.current.paused) {
      audioRef.current.play();
      setIsPlaying(true);
    } else {
      audioRef.current.pause();
      setIsPlaying(false);
    }
  };

  const setVolume = (vol: number) => {
    setVolumeState(vol);
    audioRef.current.volume = vol;
  };

  const seek = (time: number) => {
    audioRef.current.currentTime = time;
    lastTimeRef.current = time; // Reset last time to prevent huge diff accumulation
    setProgress(time);
  };

  const getQueue = (): Track[] => {
    return tracks; 
  };

  const nextTrack = () => {
    const queue = getQueue();
    const idx = queue.findIndex(t => t.id === currentTrack?.id);
    if (idx !== -1 && idx < queue.length - 1) {
      playTrack(queue[idx + 1]);
    } else if (playMode !== PlayMode.REPEAT_OFF) {
        playTrack(queue[0]);
    }
  };

  const prevTrack = () => {
    const queue = getQueue();
    const idx = queue.findIndex(t => t.id === currentTrack?.id);
    if (audioRef.current.currentTime > 3) {
      audioRef.current.currentTime = 0;
      lastTimeRef.current = 0;
    } else if (idx > 0) {
      playTrack(queue[idx - 1]);
    }
  };

  const toggleRepeat = () => {
    if (playMode === PlayMode.NORMAL) setPlayMode(PlayMode.REPEAT_TRACK);
    else if (playMode === PlayMode.REPEAT_TRACK) setPlayMode(PlayMode.REPEAT_OFF);
    else setPlayMode(PlayMode.NORMAL);
  };

  // --- Library Actions ---

  const createPlaylist = (name: string) => {
    const newPl: Playlist = {
      id: `pl_${Date.now()}`,
      name,
      tracks: []
    };
    setPlaylists([...playlists, newPl]);
  };

  const deletePlaylist = (id: string) => {
    setPlaylists(playlists.filter(p => p.id !== id));
    if (view.type === 'PLAYLIST' && view.id === id) {
      setView({ type: 'HOME' });
    }
  };

  const addToPlaylist = (playlistId: string, trackId: string) => {
    setPlaylists(prev => prev.map(p => {
      if (p.id === playlistId && !p.tracks.includes(trackId)) {
        return { ...p, tracks: [...p.tracks, trackId] };
      }
      return p;
    }));
  };

  const removeFromPlaylist = (playlistId: string, trackId: string) => {
    setPlaylists(prev => prev.map(p => {
      if (p.id === playlistId) {
        return { ...p, tracks: p.tracks.filter(id => id !== trackId) };
      }
      return p;
    }));
  };

  const toggleLike = (trackId: string) => {
    const likedPl = playlists.find(p => p.id === 'liked');
    if (!likedPl) return;

    if (likedPl.tracks.includes(trackId)) {
      removeFromPlaylist('liked', trackId);
    } else {
      addToPlaylist('liked', trackId);
    }
  };

  const isLiked = (trackId: string) => {
    const likedPl = playlists.find(p => p.id === 'liked');
    return likedPl ? likedPl.tracks.includes(trackId) : false;
  };

  return (
    <StoreContext.Provider value={{
      tracks, albums, playlists, currentTrack, isPlaying, playMode, volume, progress, duration, view,
      setView, goBack, playTrack, togglePlay, nextTrack, prevTrack, seek, setVolume, toggleRepeat,
      createPlaylist, deletePlaylist, addToPlaylist, removeFromPlaylist, toggleLike, isLiked
    }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (!context) throw new Error("useStore must be used within StoreProvider");
  return context;
};

