        <div className="flex flex-col overflow-hidden mr-2 md:mr-4 flex-1">
          <span className="text-sm font-semibold text-white truncate cursor-pointer">{currentTrack.title}</span>
          <span className="text-xs text-secondary truncate cursor-pointer">{currentTrack.artist}</span>
        </div>
        <button 
          onClick={() => toggleLike(currentTrack.id)} 
          className={`hidden md:block hover:scale-105 transition ${isLiked(currentTrack.id) ? 'text-primary' : 'text-secondary hover:text-white'}`}
        >
