        </button>
      </div>

      {/* Controls (Desktop Centered) */}
      <div className="flex flex-col items-center w-auto md:w-2/4 max-w-2xl md:static absolute right-4 md:right-auto">
        <div className="flex items-center gap-4 md:gap-6 mb-0 md:mb-2">
