import React from 'react';
import { useStore } from '../context/StoreContext';
import { Play, Heart, ListMusic, Trash2, ArrowLeft, PlusSquare } from '../components/Icons';

export const Library = () => {
  const { 
    view, playlists, tracks, albums, isLiked, toggleLike, playTrack, 
    addToPlaylist, removeFromPlaylist, goBack, createPlaylist, setView, deletePlaylist
  } = useStore();

  const handleCreate = () => {
    const name = prompt("Enter playlist name:");
    if (name) createPlaylist(name);
  };

  // --- Render Album or Playlist Detail ---
  if (view.type === 'PLAYLIST' || view.type === 'ALBUM') {
    let title = "", subtitle = "", cover = "", items: any[] = [];
    let isPlaylist = view.type === 'PLAYLIST';

    if (isPlaylist) {
      const pl = playlists.find(p => p.id === (view as any).id);
      if (!pl) return <div>Not Found</div>;
      title = pl.name;
      subtitle = `Playlist • ${pl.tracks.length} songs`;
      cover = pl.tracks.length > 0 ? (tracks.find(t => t.id === pl.tracks[0])?.cover || "") : "https://picsum.photos/300/300?grayscale";
      items = pl.tracks.map(tid => tracks.find(t => t.id === tid)).filter(Boolean);
    } else {
      const alb = albums.find(a => a.id === (view as any).id);
      if (!alb) return <div>Not Found</div>;
      title = alb.title;
      subtitle = `Album • ${alb.artist} • ${alb.year}`;
      cover = alb.cover;
      items = alb.trackIds.map(tid => tracks.find(t => t.id === tid)).filter(Boolean);
    }

    return (
      <div className="h-full overflow-y-auto pb-32 relative">
        {/* Header */}
        <div className="relative p-6 md:p-8 bg-gradient-to-b from-slate-700 to-background">
          {/* Back Button */}
          <div className="absolute top-4 left-4 md:top-6 md:left-6 z-20">
            <button 
              onClick={goBack} 
              className="w-8 h-8 bg-black/50 hover:bg-black/80 rounded-full flex items-center justify-center text-white transition"
            >
              <ArrowLeft size={20} />
            </button>
          </div>

          <div className="flex flex-col items-center text-center md:flex-row md:items-end md:text-left gap-6 mt-8 md:mt-8">
            <img src={cover} alt={title} className="w-48 h-48 md:w-56 md:h-56 shadow-2xl shrink-0 object-cover" />
            <div className="flex flex-col gap-2">
              <span className="uppercase text-xs font-bold hidden md:block">{view.type}</span>
              <h1 className="text-3xl md:text-7xl font-bold tracking-tighter leading-tight">{title}</h1>
              <p className="text-secondary font-semibold text-sm md:text-base">{subtitle}</p>
            </div>
          </div>
        </div>

        {/* Action Bar */}
        <div className="px-6 md:px-8 py-4 md:py-6 bg-background/50 backdrop-blur-sm sticky top-0 z-10 flex items-center gap-6">
          <button 
             onClick={() => items.length > 0 && playTrack(items[0])}
             className="w-12 h-12 md:w-14 md:h-14 bg-primary rounded-full flex items-center justify-center hover:scale-105 transition shadow-lg"
          >
            <Play size={24} fill="black" className="ml-1 text-black md:w-7 md:h-7" />
          </button>
        </div>

        {/* List */}
        <div className="px-4 md:px-8">
           <div className="grid grid-cols-[16px_1fr_40px] md:grid-cols-[16px_1fr_1fr_40px] gap-4 px-4 py-2 border-b border-surface-highlight text-secondary text-sm mb-4">
             <span>#</span>
             <span>Title</span>
             <span className="hidden md:block">Album</span>
             <span><ListMusic size={16} /></span>
           </div>

           {items.map((track, idx) => (
             <div key={track.id} className="grid grid-cols-[16px_1fr_40px] md:grid-cols-[16px_1fr_1fr_40px] gap-4 px-4 py-3 rounded hover:bg-surface-highlight group items-center">
               <span className="text-secondary group-hover:hidden">{idx + 1}</span>
               <button onClick={() => playTrack(track)} className="hidden group-hover:block text-white"><Play size={12} fill="white"/></button>

               <div className="flex items-center gap-3 overflow-hidden">
                 <img src={track.cover} className="w-10 h-10" />
                 <div className="flex flex-col">
                   <span className="text-white font-medium truncate">{track.title}</span>
                   <span className="text-secondary text-xs group-hover:text-white">{track.artist}</span>
                 </div>
               </div>

               <span className="text-secondary text-sm hidden md:block truncate">{track.album}</span>

               <div className="flex items-center gap-3">
                 <button onClick={() => toggleLike(track.id)} className={`${isLiked(track.id) ? 'text-primary' : 'text-transparent group-hover:text-secondary hover:text-white'}`}>
                    <Heart size={16} fill={isLiked(track.id) ? 'currentColor' : 'none'} />
                 </button>
                 {isPlaylist && (view as any).id !== 'liked' && (
                    <button onClick={() => removeFromPlaylist((view as any).id, track.id)} className="text-transparent group-hover:text-secondary hover:text-red-500">
                      <Trash2 size={16} />
                    </button>
                 )}
               </div>
             </div>
           ))}
        </div>
      </div>
    );
  }

  // --- Default Library View (List of playlists/albums) ---
  return (
    <div className="p-8 pb-32 h-full overflow-y-auto bg-background">
      <h2 className="text-2xl font-bold mb-6">Your Library</h2>

      <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-4">
        {/* Create New Playlist Card */}
        <div 
          onClick={handleCreate}
          className="p-4 bg-surface hover:bg-surface-highlight rounded-lg cursor-pointer transition group flex flex-col justify-center items-center text-center min-h-[200px]"
        >
           <div className="w-16 h-16 rounded-full bg-surface-highlight group-hover:bg-white flex items-center justify-center mb-4 transition-colors">
              <PlusSquare size={32} className="text-secondary group-hover:text-black" />
           </div>
           <h3 className="font-bold text-white">Create Playlist</h3>
        </div>

        {/* Playlists */}
        {playlists.map(pl => (
           <div 
             key={pl.id} 
             onClick={() => setView({ type: 'PLAYLIST', id: pl.id })}
             className="p-4 bg-surface hover:bg-surface-highlight rounded-lg cursor-pointer transition group"
           >
              <div className={`aspect-square mb-4 shadow-lg flex items-center justify-center ${pl.id === 'liked' ? 'bg-gradient-to-br from-indigo-700 to-blue-300' : 'bg-surface-highlight'}`}>
                 {pl.id === 'liked' ? <Heart size={48} fill="white" className="text-white" /> : <ListMusic size={48} className="text-secondary" />}
              </div>
              <h3 className="font-bold truncate text-white">{pl.name}</h3>
              <p className="text-sm text-secondary">Playlist {pl.tracks.length > 0 ? `• ${pl.tracks.length} songs` : ''}</p>
           </div>
        ))}

        {/* Albums (Listed as part of library) */}
        {albums.map(album => (
          <div 
            key={album.id} 
            onClick={() => setView({ type: 'ALBUM', id: album.id })}
            className="p-4 bg-surface hover:bg-surface-highlight rounded-lg transition cursor-pointer group"
          >
            <div className="relative mb-4">
              <img src={album.cover} alt={album.title} className="w-full aspect-square object-cover rounded shadow-lg" />
            </div>
            <h4 className="font-bold truncate">{album.title}</h4>
            <p className="text-sm text-secondary truncate">{album.artist}</p>
          </div>
        ))}

      </div>
    </div>
  );
};

