export const Library = () => {
  const { 
    view, playlists, tracks, albums, isLiked, toggleLike, playTrack, 
    addToPlaylist, removeFromPlaylist, goBack, setCreatePlaylistOpen, setView, 
    toggleAlbumLike, isAlbumLiked
  } = useStore();

  const handleCreate = () => {
    setCreatePlaylistOpen(true);
  };

  const handleAddToPlaylist = (e: React.MouseEvent, trackId: string) => {
    e.stopPropagation();
    const availablePlaylists = playlists.filter(p => !p.isSystem);
    if (availablePlaylists.length === 0) {
        alert("Create a playlist first!");
        return;
    }

    // Simple prompt for prototype
    const list = availablePlaylists.map((p, i) => `${i + 1}. ${p.name}`).join('\n');
    const input = prompt(`Enter number of playlist to add to:\n${list}`);
    const index = parseInt(input || "0") - 1;

    if (index >= 0 && index < availablePlaylists.length) {
        addToPlaylist(availablePlaylists[index].id, trackId);
    }
  };

  // --- Render Album or Playlist Detail ---
  if (view.type === 'PLAYLIST' || view.type === 'ALBUM') {
    let title = "", subtitle = "", cover = "", description = "", items: any[] = [];
    let isPlaylist = view.type === 'PLAYLIST';
    let id = (view as any).id;
    let isLikedSongs = id === 'liked';

    if (isPlaylist) {
      const pl = playlists.find(p => p.id === id);
      if (!pl) return <div>Not Found</div>;
      title = pl.name;
      subtitle = `Playlist • ${pl.tracks.length} songs`;
      description = pl.description || "";

      // Cover Logic
      if (isLikedSongs) {
          // Liked songs always uses Heart cover, processed in JSX below
      } else if (pl.customCover) {
          cover = pl.customCover;
      } else {
          cover = pl.tracks.length > 0 ? (tracks.find(t => t.id === pl.tracks[0])?.cover || "") : "";
      }

      items = pl.tracks.map(tid => tracks.find(t => t.id === tid)).filter(Boolean);
    } else {
      const alb = albums.find(a => a.id === id);
      if (!alb) return <div>Not Found</div>;
      title = alb.title;
      subtitle = `Album • ${alb.artist} • ${alb.year}`;
      cover = alb.cover;
      items = alb.trackIds.map(tid => tracks.find(t => t.id === tid)).filter(Boolean);
    }

    return (
      <div className="h-full overflow-y-auto pb-32 relative">
        {/* Header */}
        <div className="relative p-6 md:p-8 bg-gradient-to-b from-slate-700 to-background">
          {/* Back Button */}
          <div className="absolute top-4 left-4 md:top-6 md:left-6 z-20">
            <button 
              onClick={goBack} 
              className="w-8 h-8 bg-black/50 hover:bg-black/80 rounded-full flex items-center justify-center text-white transition"
            >
              <ArrowLeft size={20} />
            </button>
          </div>

          <div className="flex flex-col items-center text-center md:flex-row md:items-end md:text-left gap-6 mt-8 md:mt-8">
            {/* Cover Art Logic */}
            <div className="w-48 h-48 md:w-56 md:h-56 shadow-2xl shrink-0 flex items-center justify-center bg-surface-highlight overflow-hidden">
                {isLikedSongs ? (
                    <div className="w-full h-full bg-gradient-to-br from-indigo-700 to-blue-300 flex items-center justify-center">
                        <Heart size={64} fill="white" className="text-white" />
                    </div>
                ) : cover ? (
                    <img src={cover} alt={title} className="w-full h-full object-cover" />
                ) : (
                    <ListMusic size={64} className="text-secondary" />
                )}
            </div>

            <div className="flex flex-col gap-2">
              <span className="uppercase text-xs font-bold hidden md:block">{view.type}</span>
              <h1 className="text-3xl md:text-7xl font-bold tracking-tighter leading-tight">{title}</h1>
              {description && <p className="text-secondary/80 text-sm md:text-base font-medium">{description}</p>}
              <p className="text-white font-semibold text-sm md:text-base mt-1">{subtitle}</p>
            </div>
          </div>
        </div>

        {/* Action Bar */}
        <div className="px-6 md:px-8 py-4 md:py-6 bg-background/50 backdrop-blur-sm sticky top-0 z-10 flex items-center gap-6">
          <button 
             onClick={() => items.length > 0 && playTrack(items[0])}
             className="w-12 h-12 md:w-14 md:h-14 bg-primary rounded-full flex items-center justify-center hover:scale-105 transition shadow-lg"
          >
            <Play size={24} fill="black" className="ml-1 text-black md:w-7 md:h-7" />
          </button>

          {/* Like Button for Album */}
          {!isPlaylist && (
             <button onClick={() => toggleAlbumLike(id)} className="hover:scale-105 transition">
                <Heart size={32} fill={isAlbumLiked(id) ? '#1ed760' : 'none'} className={isAlbumLiked(id) ? 'text-primary' : 'text-secondary hover:text-white'} />
             </button>
          )}
        </div>

        {/* List */}
        <div className="px-4 md:px-8">
           {/* PC Header */}
           <div className="hidden md:grid grid-cols-[16px_4fr_2fr_1fr_60px] gap-4 px-4 py-2 border-b border-surface-highlight text-secondary text-sm mb-4">
             <span>#</span>
             <span>Title</span>
             <span>Plays</span>
             <span><ListMusic size={16} /></span>
             <span></span>
           </div>

           {items.map((track, idx) => (
             <div key={track.id} className="grid grid-cols-[16px_1fr_60px] md:grid-cols-[16px_4fr_2fr_1fr_60px] gap-4 px-2 md:px-4 py-3 rounded hover:bg-surface-highlight group items-center">

               {/* Index / Play Icon */}
               <div className="w-4 flex justify-center">
                   <span className="text-secondary group-hover:hidden text-sm">{idx + 1}</span>
                   <button onClick={() => playTrack(track)} className="hidden group-hover:block text-white"><Play size={12} fill="white"/></button>
               </div>

               {/* Track Info */}
               <div className="flex items-center gap-3 overflow-hidden">
                 <img src={track.cover} className="w-10 h-10 md:hidden rounded" alt="" /> {/* Show cover on mobile only in list */}
                 <div className="flex flex-col overflow-hidden">
                   {/* Mobile: Title + (feat. Artist) */}
                   <span className="text-white font-medium truncate">
                      {track.title} 
                      <span className="md:hidden text-secondary font-normal"> (feat. {track.artist})</span>
                   </span>
                   {/* Mobile: Plays • Artist */}
                   <div className="md:hidden text-xs text-secondary truncate mt-0.5">
                      {formatPlays(track.plays)} • {track.artist}
                   </div>
                   {/* PC: Artist only */}
                   <span className="hidden md:block text-secondary text-xs group-hover:text-white hover:underline cursor-pointer">{track.artist}</span>
                 </div>
               </div>

               {/* PC: Plays */}
               <span className="text-secondary text-sm hidden md:block truncate">{formatPlays(track.plays)}</span>

               {/* PC: Duration */}
               <span className="text-secondary text-sm hidden md:block">{formatDuration(track.duration)}</span>

               {/* Actions */}
               <div className="flex items-center gap-3 justify-end">
                 <button onClick={() => toggleLike(track.id)} className={`${isLiked(track.id) ? 'text-primary' : 'text-transparent group-hover:text-secondary hover:text-white'}`}>
                    <Heart size={16} fill={isLiked(track.id) ? 'currentColor' : 'none'} />
                 </button>

                 {/* Add to Playlist Button */}
                 <button onClick={(e) => handleAddToPlaylist(e, track.id)} className="text-transparent group-hover:text-secondary hover:text-white" title="Add to Playlist">
                    <Plus size={16} />
                 </button>

                 {isPlaylist && !isLikedSongs && (
                    <button onClick={() => removeFromPlaylist((view as any).id, track.id)} className="text-transparent group-hover:text-secondary hover:text-red-500">
                      <Trash2 size={16} />
                    </button>
                 )}
               </div>
             </div>
           ))}
        </div>
      </div>
    );
  }

  // --- Default Library View (List of playlists/albums) ---
  return (
    <div className="p-4 md:p-8 pb-32 h-full overflow-y-auto bg-background">
      <h2 className="text-2xl font-bold mb-6">Your Library</h2>

      <div className="grid grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3 md:gap-4">
        {/* Create New Playlist Card */}
        <div 
          onClick={handleCreate}
          className="p-4 bg-surface hover:bg-surface-highlight rounded-lg cursor-pointer transition group flex flex-col justify-center items-center text-center min-h-[150px] md:min-h-[200px]"
        >
           <div className="w-12 h-12 md:w-16 md:h-16 rounded-full bg-surface-highlight group-hover:bg-white flex items-center justify-center mb-4 transition-colors">
              <PlusSquare size={24} className="text-secondary group-hover:text-black md:w-8 md:h-8" />
           </div>
           <h3 className="font-bold text-white text-sm md:text-base">Create Playlist</h3>
        </div>

        {/* Playlists */}
        {playlists.map(pl => {
           let cover = pl.customCover;
           if (!cover && pl.tracks.length > 0) {
               cover = tracks.find(t => t.id === pl.tracks[0])?.cover;
           }

           return (
           <div 
             key={pl.id} 
             onClick={() => setView({ type: 'PLAYLIST', id: pl.id })}
             className="p-3 md:p-4 bg-surface hover:bg-surface-highlight rounded-lg cursor-pointer transition group"
           >
              <div className={`aspect-square mb-2 md:mb-4 shadow-lg flex items-center justify-center rounded-md overflow-hidden ${pl.id === 'liked' ? 'bg-gradient-to-br from-indigo-700 to-blue-300' : 'bg-surface-highlight'}`}>
                 {pl.id === 'liked' ? (
                     <Heart size={32} fill="white" className="text-white md:w-12 md:h-12" />
                 ) : cover ? (
                     <img src={cover} alt={pl.name} className="w-full h-full object-cover" />
                 ) : (
                     <ListMusic size={32} className="text-secondary md:w-12 md:h-12" />
                 )}
              </div>
              <h3 className="font-bold truncate text-white text-sm md:text-base">{pl.name}</h3>
              <p className="text-xs md:text-sm text-secondary truncate">Playlist</p>
           </div>
           );
        })}

        {/* Liked Albums */}
        {albums.filter(a => isAlbumLiked(a.id)).map(album => (
           <div 
            key={album.id} 
            onClick={() => setView({ type: 'ALBUM', id: album.id })}
            className="p-3 md:p-4 bg-surface hover:bg-surface-highlight rounded-lg transition cursor-pointer group"
          >
            <div className="relative mb-2 md:mb-4">
              <img src={album.cover} alt={album.title} className="w-full aspect-square object-cover rounded-md shadow-lg" />
            </div>
            <h4 className="font-bold truncate text-white text-sm md:text-base">{album.title}</h4>
            <p className="text-xs md:text-sm text-secondary truncate">Album • {album.artist}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

import React from 'react';
import { StoreProvider, useStore } from './context/StoreContext';
import { Sidebar } from './components/Sidebar';
import { Player } from './components/Player';
import { MobileNav } from './components/MobileNav';
import { FullScreenPlayer } from './components/FullScreenPlayer';
import { CreatePlaylistModal } from './components/CreatePlaylistModal';
import { Home } from './pages/Home';
import { Search } from './pages/Search';
import { Library } from './pages/Library';

const MainView = () => {
  const { view } = useStore();

  const renderContent = () => {
    switch (view.type) {
      case 'HOME': return <Home />;
      case 'SEARCH': return <Search />;
      case 'LIBRARY': return <Library />;
      case 'PLAYLIST': return <Library />; // Reusing library component for detail view
      case 'ALBUM': return <Library />;
      default: return <Home />;
    }
  };

  return (
    <div className="flex-1 h-full bg-background overflow-hidden relative">
      {renderContent()}
    </div>
  );
};

export default function App() {
  return (
    <StoreProvider>
      <div className="flex h-screen w-full bg-black text-white font-sans">
        <Sidebar />
        <main className="flex-1 flex flex-col relative">
           {/* Top bar filler (usually for search/back buttons in real app, kept minimal here) */}
           <div className="h-16 w-full absolute top-0 left-0 bg-transparent z-10 pointer-events-none" />
           <MainView />
           <MobileNav />
           <Player />
           <FullScreenPlayer />
           <CreatePlaylistModal />
        </main>
      </div>
    </StoreProvider>
  );
}

export interface Track {
  id: string;
  title: string;
  artist: string;
  album: string;
  cover: string;
  duration: number; // in seconds
  url: string; // audio source
  plays: number;
  genre: string; // New field for recommendations
}

export interface Playlist {
  id: string;
  name: string;
  description?: string;
  customCover?: string; // Base64 or URL
  tracks: string[]; // array of track IDs
  isSystem?: boolean; // e.g. "Liked Songs"
}

export interface Album {
  id: string;
  title: string;
  artist: string;
  cover: string;
  trackIds: string[];
  year: number;
}

export type ViewState = 
  | { type: 'HOME' }
  | { type: 'SEARCH' }
  | { type: 'LIBRARY' }
  | { type: 'PLAYLIST'; id: string }
  | { type: 'ALBUM'; id: string };

export enum PlayMode {
  OFF = 'OFF',
  CONTEXT = 'CONTEXT', // Repeat Playlist/Album
  ONE = 'ONE', // Repeat One Track
}

import React from 'react';
import { 
  Home, Search, Library, PlusSquare, Heart, Play, Pause, 
  SkipBack, SkipForward, Repeat, Shuffle, Volume2, ListMusic, Trash2, Mic2,
  ArrowLeft, Plus, ChevronDown, Image, X, Check, Edit, MoreHorizontal
} from 'lucide-react';

export { 
  Home, Search, Library, PlusSquare, Heart, Play, Pause, 
  SkipBack, SkipForward, Repeat, Shuffle, Volume2, ListMusic, Trash2, Mic2,
  ArrowLeft, Plus, ChevronDown, Image, X, Check, Edit, MoreHorizontal
};

import React, { createContext, useContext, useEffect, useRef, useState } from 'react';
import { Track, Playlist, Album, ViewState, PlayMode } from '../types';
import { generateInitialData, StorageService } from '../services/data';

interface StoreContextType {
  tracks: Track[];
  albums: Album[];
  playlists: Playlist[];
  recommendations: Track[];
  currentTrack: Track | null;
  isPlaying: boolean;
  playMode: PlayMode;
  isShuffle: boolean;
  volume: number;
  progress: number;
  duration: number;
  view: ViewState;

  // Modal States
  isCreatePlaylistOpen: boolean;
  setCreatePlaylistOpen: (isOpen: boolean) => void;
  playlistIdToEdit: string | null; // If set, modal is in "Edit" mode
  setPlaylistIdToEdit: (id: string | null) => void;

  isMobilePlayerOpen: boolean;
  setMobilePlayerOpen: (isOpen: boolean) => void;

  isAddToPlaylistOpen: boolean;
  trackIdToAdd: string | null;
  openAddToPlaylist: (trackId: string) => void;
  closeAddToPlaylist: () => void;

  // Actions
  setView: (v: ViewState) => void;
  goBack: () => void;
  playTrack: (track: Track) => void;
  togglePlay: () => void;
  nextTrack: () => void;
  prevTrack: () => void;
  seek: (time: number) => void;
  setVolume: (vol: number) => void;
  toggleRepeat: () => void;
  toggleShuffle: () => void;

  createPlaylist: (name: string, description?: string, cover?: string) => void;
  editPlaylist: (id: string, name: string, description?: string, cover?: string) => void;
  deletePlaylist: (id: string) => void;
  addToPlaylist: (playlistId: string, trackId: string) => void;
  removeFromPlaylist: (playlistId: string, trackId: string) => void;

  toggleLike: (trackId: string) => void;
  isLiked: (trackId: string) => boolean;
  toggleAlbumLike: (albumId: string) => void;
  isAlbumLiked: (albumId: string) => boolean;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

export const StoreProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  // --- Data State ---
  const [tracks, setTracks] = useState<Track[]>([]);
  const [albums, setAlbums] = useState<Album[]>([]);
  const [playlists, setPlaylists] = useState<Playlist[]>([]);
  const [recommendations, setRecommendations] = useState<Track[]>([]);
  const [likedAlbumIds, setLikedAlbumIds] = useState<string[]>([]);

  // --- Player State ---
  const [currentTrack, setCurrentTrack] = useState<Track | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [playMode, setPlayMode] = useState<PlayMode>(PlayMode.OFF);
  const [isShuffle, setIsShuffle] = useState(false);
  const [volume, setVolumeState] = useState(0.5);
  const [progress, setProgress] = useState(0);
  const [duration, setDuration] = useState(0);
  const [hasCountedListen, setHasCountedListen] = useState(false);

  // --- UI State ---
  const [view, setViewInternal] = useState<ViewState>({ type: 'HOME' });
  const [history, setHistory] = useState<ViewState[]>([]);

  // Modals
  const [isCreatePlaylistOpen, setCreatePlaylistOpen] = useState(false);
  const [playlistIdToEdit, setPlaylistIdToEdit] = useState<string | null>(null);
  const [isMobilePlayerOpen, setMobilePlayerOpen] = useState(false);
  const [isAddToPlaylistOpen, setAddToPlaylistOpen] = useState(false);
  const [trackIdToAdd, setTrackIdToAdd] = useState<string | null>(null);

  // --- Refs ---
  const audioRef = useRef<HTMLAudioElement>(new Audio());
  const cumulativeTimeRef = useRef(0);
  const lastTimeRef = useRef(0);

  // --- Initialization ---
  useEffect(() => {
    const { tracks: initialTracks, albums: initialAlbums } = generateInitialData();

    // Load persisted play counts
    const storedPlays = StorageService.load<Record<string, number>>('huevify_plays', {});
    const mergedTracks = initialTracks.map(t => ({
      ...t,
      plays: storedPlays[t.id] ?? t.plays
    }));

    setTracks(mergedTracks);
    setAlbums(initialAlbums);

    const storedPlaylists = StorageService.load<Playlist[]>('huevify_playlists', [
      { id: 'liked', name: 'Liked Songs', tracks: [], isSystem: true, description: 'Your favorite tracks' }
    ]);
    setPlaylists(storedPlaylists);

    const storedLikedAlbums = StorageService.load<string[]>('huevify_liked_albums', []);
    setLikedAlbumIds(storedLikedAlbums);

    // Setup Audio
    audioRef.current.volume = 0.5;
  }, []);

  // --- Recommendation Engine ---
  useEffect(() => {
    if (tracks.length === 0) return;

    // 1. Analyze User Profile
    const genreScores: Record<string, number> = {};
    const likedPlaylist = playlists.find(p => p.id === 'liked');
    const likedIds = likedPlaylist ? likedPlaylist.tracks : [];

    tracks.forEach(t => {
      let score = 0;
      if (likedIds.includes(t.id)) score += 50;
      if (t.plays > 0) score += Math.log(t.plays) * 2;
      if (score > 0) {
        genreScores[t.genre] = (genreScores[t.genre] || 0) + score;
      }
    });

    const topGenres = Object.entries(genreScores)
      .sort(([, a], [, b]) => b - a)
      .slice(0, 3)
      .map(([g]) => g);

    const targetGenres = topGenres.length > 0 ? topGenres : tracks.map(t => t.genre);

    const candidates = tracks.filter(t => 
      targetGenres.includes(t.genre) && 
      !likedIds.includes(t.id)
    );

    const shuffled = [...candidates].sort(() => 0.5 - Math.random()).slice(0, 6);
    setRecommendations(shuffled);

  }, [tracks, playlists]);

  // --- Persistence Effects ---
  useEffect(() => {
    if (playlists.length > 0) {
      StorageService.save('huevify_playlists', playlists);
    }
  }, [playlists]);

  useEffect(() => {
    if (tracks.length > 0) {
      const playCounts = tracks.reduce((acc, t) => ({ ...acc, [t.id]: t.plays }), {});
      StorageService.save('huevify_plays', playCounts);
    }
  }, [tracks]);

  useEffect(() => {
    StorageService.save('huevify_liked_albums', likedAlbumIds);
  }, [likedAlbumIds]);

  // --- Navigation Actions ---
  const setView = (newView: ViewState) => {
    if (JSON.stringify(view) !== JSON.stringify(newView)) {
      setHistory(prev => [...prev, view]);
      setViewInternal(newView);
    }
    setMobilePlayerOpen(false);
  };

  const goBack = () => {
    if (history.length > 0) {
      const prev = history[history.length - 1];
      setHistory(h => h.slice(0, -1));
      setViewInternal(prev);
    } else {
      setViewInternal({ type: 'HOME' });
    }
  };

  // --- Playback State Reset ---
  useEffect(() => {
    cumulativeTimeRef.current = 0;
    lastTimeRef.current = 0;
    setHasCountedListen(false);
  }, [currentTrack]);

  // --- Audio Logic ---
  useEffect(() => {
    const audio = audioRef.current;

    const handleTimeUpdate = () => {
      const now = audio.currentTime;
      setProgress(now);
      const diff = now - lastTimeRef.current;
      if (diff > 0 && diff < 1.5) {
        cumulativeTimeRef.current += diff;
      }
      lastTimeRef.current = now;

      if (cumulativeTimeRef.current > 30 && !hasCountedListen && currentTrack) {
        handleListenCount(currentTrack);
      }
    };

    const handleEnded = () => {
      if (playMode === PlayMode.ONE) {
        audio.currentTime = 0;
        audio.play();
      } else {
        nextTrack();
      }
    };

    const handleLoadedMetadata = () => {
        setDuration(audio.duration);
    }

    audio.addEventListener('timeupdate', handleTimeUpdate);
    audio.addEventListener('ended', handleEnded);
    audio.addEventListener('loadedmetadata', handleLoadedMetadata);

    return () => {
      audio.removeEventListener('timeupdate', handleTimeUpdate);
      audio.removeEventListener('ended', handleEnded);
      audio.removeEventListener('loadedmetadata', handleLoadedMetadata);
    };
  }, [currentTrack, hasCountedListen, playMode, tracks, isShuffle]); // Depend on isShuffle/PlayMode

  const handleListenCount = (track: Track) => {
    const lastListenKey = `last_listen_${track.id}`;
    const lastListenTime = StorageService.load<number>(lastListenKey, 0);
    const now = Date.now();

    if (now - lastListenTime > track.duration * 1000) {
      const addedPlays = Math.floor(100 + Math.random() * 9900);
      setTracks(prev => prev.map(t => 
        t.id === track.id ? { ...t, plays: t.plays + addedPlays } : t
      ));
      StorageService.save(lastListenKey, now);
    }
    setHasCountedListen(true);
  };

  const playTrack = (track: Track) => {
    if (currentTrack?.id === track.id) {
      togglePlay();
      return;
    }
    setCurrentTrack(track);
    audioRef.current.src = track.url;
    audioRef.current.play()
      .then(() => setIsPlaying(true))
      .catch(e => console.error("Audio play failed", e));
  };

  const togglePlay = () => {
    if (audioRef.current.paused) {
      audioRef.current.play();
      setIsPlaying(true);
    } else {
      audioRef.current.pause();
      setIsPlaying(false);
    }
  };

  const setVolume = (vol: number) => {
    setVolumeState(vol);
    audioRef.current.volume = vol;
  };

  const seek = (time: number) => {
    audioRef.current.currentTime = time;
    lastTimeRef.current = time;
    setProgress(time);
  };

  const getQueue = (): Track[] => {
    // Ideally this should respect the context (album/playlist), but for now we use all tracks.
    // In a real app, 'queue' state would be separate.
    return tracks; 
  };

  const nextTrack = () => {
    const queue = getQueue();

    if (isShuffle) {
        const randomIdx = Math.floor(Math.random() * queue.length);
        playTrack(queue[randomIdx]);
        return;
    }

    const idx = queue.findIndex(t => t.id === currentTrack?.id);

    if (idx !== -1 && idx < queue.length - 1) {
      playTrack(queue[idx + 1]);
    } else if (playMode === PlayMode.CONTEXT) {
      // Loop back to start
      playTrack(queue[0]);
    } else {
      // End of queue, stop or wrap if desired. Here we stop.
      setIsPlaying(false);
      audioRef.current.pause();
      audioRef.current.currentTime = 0;
    }
  };

  const prevTrack = () => {
    if (audioRef.current.currentTime > 3) {
      audioRef.current.currentTime = 0;
      lastTimeRef.current = 0;
      return;
    }

    const queue = getQueue();
    const idx = queue.findIndex(t => t.id === currentTrack?.id);

    if (idx > 0) {
      playTrack(queue[idx - 1]);
    } else {
      playTrack(queue[queue.length - 1]); // Loop back to end? Or just start of this track.
    }
  };

  const toggleRepeat = () => {
    // Cycle: OFF -> CONTEXT (Loop) -> ONE (Track) -> OFF
    if (playMode === PlayMode.OFF) setPlayMode(PlayMode.CONTEXT);
    else if (playMode === PlayMode.CONTEXT) setPlayMode(PlayMode.ONE);
    else setPlayMode(PlayMode.OFF);
  };

  const toggleShuffle = () => {
    setIsShuffle(!isShuffle);
  };

  // --- Library Actions ---

  const createPlaylist = (name: string, description?: string, cover?: string) => {
    const newPl: Playlist = {
      id: `pl_${Date.now()}`,
      name,
      description: description || "",
      customCover: cover,
      tracks: []
    };
    setPlaylists([...playlists, newPl]);
  };

  const editPlaylist = (id: string, name: string, description?: string, cover?: string) => {
    setPlaylists(prev => prev.map(p => {
        if (p.id === id) {
            return { ...p, name, description, customCover: cover };
        }
        return p;
    }));
  };

  const deletePlaylist = (id: string) => {
    const confirmDelete = window.confirm("Are you sure you want to delete this playlist?");
    if (!confirmDelete) return;

    setPlaylists(playlists.filter(p => p.id !== id));
    if (view.type === 'PLAYLIST' && view.id === id) {
      setView({ type: 'HOME' });
    }
  };

  const addToPlaylist = (playlistId: string, trackId: string) => {
    setPlaylists(prev => prev.map(p => {
      if (p.id === playlistId && !p.tracks.includes(trackId)) {
        return { ...p, tracks: [...p.tracks, trackId] };
      }
      return p;
    }));
  };

  const removeFromPlaylist = (playlistId: string, trackId: string) => {
    setPlaylists(prev => prev.map(p => {
      if (p.id === playlistId) {
        return { ...p, tracks: p.tracks.filter(id => id !== trackId) };
      }
      return p;
    }));
  };

  const toggleLike = (trackId: string) => {
    const likedPl = playlists.find(p => p.id === 'liked');
    if (!likedPl) return;

    if (likedPl.tracks.includes(trackId)) {
      removeFromPlaylist('liked', trackId);
    } else {
      addToPlaylist('liked', trackId);
    }
  };

  const isLiked = (trackId: string) => {
    const likedPl = playlists.find(p => p.id === 'liked');
    return likedPl ? likedPl.tracks.includes(trackId) : false;
  };

  const toggleAlbumLike = (albumId: string) => {
    if (likedAlbumIds.includes(albumId)) {
        setLikedAlbumIds(prev => prev.filter(id => id !== albumId));
    } else {
        setLikedAlbumIds(prev => [...prev, albumId]);
    }
  };

  const isAlbumLiked = (albumId: string) => likedAlbumIds.includes(albumId);

  // Add To Playlist Modal Helper
  const openAddToPlaylist = (trackId: string) => {
    setTrackIdToAdd(trackId);
    setAddToPlaylistOpen(true);
  };

  const closeAddToPlaylist = () => {
    setAddToPlaylistOpen(false);
    setTrackIdToAdd(null);
  };

  return (
    <StoreContext.Provider value={{
      tracks, albums, playlists, recommendations, currentTrack, isPlaying, playMode, isShuffle, volume, progress, duration, view,
      isCreatePlaylistOpen, setCreatePlaylistOpen, playlistIdToEdit, setPlaylistIdToEdit,
