import { Library } from './pages/Library';

const MainView = () => {
  const { view } = useStore();

  const renderContent = () => {
    switch (view.type) {
      case 'HOME': return <Home />;
      case 'SEARCH': return <Search />;
      case 'LIBRARY': return <Library />;
      case 'PLAYLIST': return <Library />; // Reusing library component for detail view
      case 'ALBUM': return <Library />;
      case 'ARTIST': return <Library />;
      case 'CHARTS': return <Library />;
      default: return <Home />;
    }
  };

  // Removed overflow-y-auto here because individual pages handle their own scrolling
  // This allows sticky headers inside pages to work correctly against the page viewport
  return (
    <div className="flex-1 flex flex-col bg-background min-h-0 overflow-hidden relative">
      {renderContent()}
    </div>
  );
};

export default function App() {
  return (
    <StoreProvider>
      <div className="flex h-screen w-full bg-black text-white font-sans overflow-hidden">
        <Sidebar />
        <main className="flex-1 flex flex-col h-full overflow-hidden relative">
           {/* Top bar filler to prevent content from hiding behind transparent sticky headers too awkwardly */}
           <div className="h-16 w-full absolute top-0 left-0 bg-gradient-to-b from-black/20 to-transparent z-20 pointer-events-none" />
           <MainView />
           <MobileNav />
           <Player />
           <FullScreenPlayer />
           <CreatePlaylistModal />
           <AddToPlaylistModal />
        </main>
      </div>
    </StoreProvider>
  );
}

import React, { createContext, useContext, useEffect, useRef, useState } from 'react';
import { Track, Playlist, Album, ViewState, PlayMode } from '../types';
import { generateInitialData, StorageService } from '../services/data';

interface ArtistStats {
  monthlyPlays: number;
  globalRank: number;
}

interface StoreContextType {
  tracks: Track[];
  albums: Album[];
  playlists: Playlist[];
  recommendations: Track[];
  recentlyPlayed: Track[];
  followedArtists: string[];
  currentTrack: Track | null;
  isPlaying: boolean;
  playMode: PlayMode;
  isShuffle: boolean;
  volume: number;
  progress: number;
  duration: number;
  view: ViewState;

  // Modal States
  isCreatePlaylistOpen: boolean;
  setCreatePlaylistOpen: (isOpen: boolean) => void;
  playlistIdToEdit: string | null; // If set, modal is in "Edit" mode
  setPlaylistIdToEdit: (id: string | null) => void;

  isMobilePlayerOpen: boolean;
  setMobilePlayerOpen: (isOpen: boolean) => void;

  isAddToPlaylistOpen: boolean;
  trackIdToAdd: string | null;
  openAddToPlaylist: (trackId: string) => void;
  closeAddToPlaylist: () => void;

  // Actions
  setView: (v: ViewState) => void;
  goToArtist: (artistName: string) => void;
  getArtistStats: (artistName: string) => ArtistStats;
  toggleFollowArtist: (artistName: string) => void;
  isArtistFollowed: (artistName: string) => boolean;
  goBack: () => void;
  playTrack: (track: Track) => void;
  togglePlay: () => void;
  nextTrack: () => void;
  prevTrack: () => void;
  seek: (time: number) => void;
  setVolume: (vol: number) => void;
  toggleRepeat: () => void;
  toggleShuffle: () => void;

  createPlaylist: (name: string, description?: string, cover?: string) => void;
  editPlaylist: (id: string, name: string, description?: string, cover?: string) => void;
  deletePlaylist: (id: string) => void;
  addToPlaylist: (playlistId: string, trackId: string) => void;
  removeFromPlaylist: (playlistId: string, trackId: string) => void;

  toggleLike: (trackId: string) => void;
  isLiked: (trackId: string) => boolean;
  toggleAlbumLike: (albumId: string) => void;
  isAlbumLiked: (albumId: string) => boolean;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

export const StoreProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  // --- Data State ---
  const [tracks, setTracks] = useState<Track[]>([]);
  const [albums, setAlbums] = useState<Album[]>([]);
  const [playlists, setPlaylists] = useState<Playlist[]>([]);
  const [recommendations, setRecommendations] = useState<Track[]>([]);
  const [recentlyPlayed, setRecentlyPlayed] = useState<Track[]>([]);
  const [likedAlbumIds, setLikedAlbumIds] = useState<string[]>([]);
  const [followedArtists, setFollowedArtists] = useState<string[]>([]);

  // --- Player State ---
  const [currentTrack, setCurrentTrack] = useState<Track | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [playMode, setPlayMode] = useState<PlayMode>(PlayMode.OFF);
  const [isShuffle, setIsShuffle] = useState(false);
  const [volume, setVolumeState] = useState(0.5);
  const [progress, setProgress] = useState(0);
  const [duration, setDuration] = useState(0);
  const [hasCountedListen, setHasCountedListen] = useState(false);

  // --- UI State ---
  const [view, setViewInternal] = useState<ViewState>({ type: 'HOME' });
  const [history, setHistory] = useState<ViewState[]>([]);

  // Modals
  const [isCreatePlaylistOpen, setCreatePlaylistOpen] = useState(false);
  const [playlistIdToEdit, setPlaylistIdToEdit] = useState<string | null>(null);
  const [isMobilePlayerOpen, setMobilePlayerOpen] = useState(false);
  const [isAddToPlaylistOpen, setAddToPlaylistOpen] = useState(false);
  const [trackIdToAdd, setTrackIdToAdd] = useState<string | null>(null);

  // --- Refs ---
  const audioRef = useRef<HTMLAudioElement>(new Audio());
  const cumulativeTimeRef = useRef(0);
  const lastTimeRef = useRef(0);

  // --- Initialization ---
  useEffect(() => {
    const { tracks: initialTracks, albums: initialAlbums } = generateInitialData();

    // Load persisted play counts
    const storedPlays = StorageService.load<Record<string, number>>('huevify_plays', {});
    const mergedTracks = initialTracks.map(t => ({
      ...t,
      plays: storedPlays[t.id] ?? t.plays
    }));

    setTracks(mergedTracks);
    setAlbums(initialAlbums);

    const storedPlaylists = StorageService.load<Playlist[]>('huevify_playlists', [
      { id: 'liked', name: 'Liked Songs', tracks: [], isSystem: true, description: 'Your favorite tracks' }
    ]);
    setPlaylists(storedPlaylists);

    const storedLikedAlbums = StorageService.load<string[]>('huevify_liked_albums', []);
    setLikedAlbumIds(storedLikedAlbums);

    const storedFollowedArtists = StorageService.load<string[]>('huevify_followed_artists', []);
    setFollowedArtists(storedFollowedArtists);

    const storedRecent = StorageService.load<Track[]>('huevify_recent', []);
    setRecentlyPlayed(storedRecent);

    // Setup Audio
    audioRef.current.volume = 0.5;
  }, []);

  // --- Recommendation Engine ---
  useEffect(() => {
    if (tracks.length === 0) return;

    // 1. Analyze User Profile
    const genreScores: Record<string, number> = {};
    const likedPlaylist = playlists.find(p => p.id === 'liked');
    const likedIds = likedPlaylist ? likedPlaylist.tracks : [];

    tracks.forEach(t => {
      let score = 0;
      if (likedIds.includes(t.id)) score += 50;
      if (t.plays > 0) score += Math.log(t.plays) * 2;
      if (score > 0) {
        genreScores[t.genre] = (genreScores[t.genre] || 0) + score;
      }
    });

    const topGenres = Object.entries(genreScores)
      .sort(([, a], [, b]) => b - a)
      .slice(0, 3)
      .map(([g]) => g);

    const targetGenres = topGenres.length > 0 ? topGenres : tracks.map(t => t.genre);

    const candidates = tracks.filter(t => 
      targetGenres.includes(t.genre) && 
      !likedIds.includes(t.id)
    );

    const shuffled = [...candidates].sort(() => 0.5 - Math.random()).slice(0, 6);
    setRecommendations(shuffled);

  }, [tracks, playlists]);

  // --- Persistence Effects ---
  useEffect(() => {
    if (playlists.length > 0) {
      StorageService.save('huevify_playlists', playlists);
    }
  }, [playlists]);

  useEffect(() => {
    if (tracks.length > 0) {
      const playCounts = tracks.reduce((acc, t) => ({ ...acc, [t.id]: t.plays }), {});
      StorageService.save('huevify_plays', playCounts);
    }
  }, [tracks]);

  useEffect(() => {
    StorageService.save('huevify_liked_albums', likedAlbumIds);
  }, [likedAlbumIds]);

  useEffect(() => {
    StorageService.save('huevify_followed_artists', followedArtists);
  }, [followedArtists]);

  // --- Navigation Actions ---
  const setView = (newView: ViewState) => {
    if (JSON.stringify(view) !== JSON.stringify(newView)) {
      setHistory(prev => [...prev, view]);
      setViewInternal(newView);
    }
    setMobilePlayerOpen(false);
  };

  const goToArtist = (artistName: string) => {
    setView({ type: 'ARTIST', id: artistName });
    setMobilePlayerOpen(false);
  }

  const goBack = () => {
    if (history.length > 0) {
      const prev = history[history.length - 1];
      setHistory(h => h.slice(0, -1));
      setViewInternal(prev);
    } else {
      setViewInternal({ type: 'HOME' });
    }
  };

  // --- Artist Stats Calculation (Deterministic) ---
  const getArtistStats = (artistName: string): ArtistStats => {
    const artistPlayMap: Record<string, number> = {};
    tracks.forEach(t => {
        artistPlayMap[t.artist] = (artistPlayMap[t.artist] || 0) + t.plays;
    });

    const sortedArtists = Object.entries(artistPlayMap).sort(([, a], [, b]) => b - a);
    const rankIndex = sortedArtists.findIndex(([name]) => name === artistName);

    const totalPlays = artistPlayMap[artistName] || 0;
    const monthlyPlays = Math.floor(totalPlays * 0.45); 

    return {
        monthlyPlays,
        globalRank: rankIndex === -1 ? 999 : rankIndex + 1
    };
  };

  const toggleFollowArtist = (artistName: string) => {
    setFollowedArtists(prev => {
        if (prev.includes(artistName)) {
            return prev.filter(a => a !== artistName);
        } else {
            return [...prev, artistName];
        }
    });
  };

  const isArtistFollowed = (artistName: string) => followedArtists.includes(artistName);

  // --- Playback State Reset ---
  useEffect(() => {
    cumulativeTimeRef.current = 0;
    lastTimeRef.current = 0;
    setHasCountedListen(false);
  }, [currentTrack]);

  // --- Audio Logic ---
  useEffect(() => {
    const audio = audioRef.current;

    const handleTimeUpdate = () => {
      const now = audio.currentTime;
      setProgress(now);
      const diff = now - lastTimeRef.current;
      if (diff > 0 && diff < 1.5) {
        cumulativeTimeRef.current += diff;
      }
      lastTimeRef.current = now;

      if (cumulativeTimeRef.current > 30 && !hasCountedListen && currentTrack) {
        handleListenCount(currentTrack);
      }
    };

    const handleEnded = () => {
      if (playMode === PlayMode.ONE) {
        audio.currentTime = 0;
        audio.play();
      } else {
        nextTrack();
      }
    };

    const handleLoadedMetadata = () => {
        setDuration(audio.duration);
    }

    audio.addEventListener('timeupdate', handleTimeUpdate);
    audio.addEventListener('ended', handleEnded);
    audio.addEventListener('loadedmetadata', handleLoadedMetadata);

    return () => {
      audio.removeEventListener('timeupdate', handleTimeUpdate);
      audio.removeEventListener('ended', handleEnded);
      audio.removeEventListener('loadedmetadata', handleLoadedMetadata);
    };
  }, [currentTrack, hasCountedListen, playMode, tracks, isShuffle]);

  const handleListenCount = (track: Track) => {
    const lastListenKey = `last_listen_${track.id}`;
    const lastListenTime = StorageService.load<number>(lastListenKey, 0);
    const now = Date.now();

    if (now - lastListenTime > track.duration * 1000) {
      const addedPlays = Math.floor(100 + Math.random() * 9900);
      setTracks(prev => prev.map(t => 
        t.id === track.id ? { ...t, plays: t.plays + addedPlays } : t
      ));
      StorageService.save(lastListenKey, now);
    }
    setHasCountedListen(true);
  };

  const playTrack = (track: Track) => {
    setRecentlyPlayed(prev => {
        const filtered = prev.filter(t => t.id !== track.id);
        const newHistory = [track, ...filtered].slice(0, 10);
        StorageService.save('huevify_recent', newHistory);
        return newHistory;
    });

    if (currentTrack?.id === track.id) {
      togglePlay();
      return;
    }
    setCurrentTrack(track);
    audioRef.current.src = track.url;
    audioRef.current.play()
      .then(() => setIsPlaying(true))
      .catch(e => console.error("Audio play failed", e));
  };

  const togglePlay = () => {
    if (audioRef.current.paused) {
      audioRef.current.play();
      setIsPlaying(true);
    } else {
      audioRef.current.pause();
      setIsPlaying(false);
    }
  };

  const setVolume = (vol: number) => {
    setVolumeState(vol);
    audioRef.current.volume = vol;
  };

  const seek = (time: number) => {
    audioRef.current.currentTime = time;
    lastTimeRef.current = time;
    setProgress(time);
  };

  const getQueue = (): Track[] => {
    if (view.type === 'PLAYLIST' && (view as any).id === 'history') {
        return recentlyPlayed;
    }
    return tracks; 
  };

  const nextTrack = () => {
    const queue = getQueue();
    if (isShuffle) {
        const randomIdx = Math.floor(Math.random() * queue.length);
        playTrack(queue[randomIdx]);
        return;
    }
    const idx = queue.findIndex(t => t.id === currentTrack?.id);
    if (idx !== -1 && idx < queue.length - 1) {
      playTrack(queue[idx + 1]);
    } else if (playMode === PlayMode.CONTEXT) {
      playTrack(queue[0]);
    } else {
      setIsPlaying(false);
      audioRef.current.pause();
      audioRef.current.currentTime = 0;
    }
  };

  const prevTrack = () => {
    if (audioRef.current.currentTime > 3) {
      audioRef.current.currentTime = 0;
      lastTimeRef.current = 0;
      return;
    }
    const queue = getQueue();
    const idx = queue.findIndex(t => t.id === currentTrack?.id);
    if (idx > 0) {
      playTrack(queue[idx - 1]);
    } else {
      playTrack(queue[queue.length - 1]);
    }
  };

  const toggleRepeat = () => {
    if (playMode === PlayMode.OFF) setPlayMode(PlayMode.CONTEXT);
    else if (playMode === PlayMode.CONTEXT) setPlayMode(PlayMode.ONE);
    else setPlayMode(PlayMode.OFF);
  };

  const toggleShuffle = () => {
    setIsShuffle(!isShuffle);
  };

  // --- Library Actions ---

  const createPlaylist = (name: string, description?: string, cover?: string) => {
    const newPl: Playlist = {
      id: `pl_${Date.now()}`,
      name,
      description: description || "",
      customCover: cover,
      tracks: []
    };
    setPlaylists(prev => [...prev, newPl]);
  };

  const editPlaylist = (id: string, name: string, description?: string, cover?: string) => {
    setPlaylists(prev => prev.map(p => {
        if (p.id === id) {
            return { ...p, name, description, customCover: cover };
        }
        return p;
    }));
  };

  // Fixed Delete Logic: Immediate navigation + robust state update
  const deletePlaylist = (id: string) => {
    if (window.confirm("Are you sure you want to delete this playlist? This action cannot be undone.")) {
        // 1. Navigate away if we are currently viewing this playlist
        if (view.type === 'PLAYLIST' && (view as any).id === id) {
             setViewInternal({ type: 'LIBRARY' });
        }

        // 2. Perform deletion in next tick to ensure view transition started
        setTimeout(() => {
            setPlaylists(currentPlaylists => {
                const updated = currentPlaylists.filter(p => p.id !== id);
                StorageService.save('huevify_playlists', updated);
                return updated;
            });
        }, 0);
    }
  };

  const addToPlaylist = (playlistId: string, trackId: string) => {
    setPlaylists(prev => prev.map(p => {
      if (p.id === playlistId && !p.tracks.includes(trackId)) {
        return { ...p, tracks: [...p.tracks, trackId] };
      }
      return p;
    }));
  };

  const removeFromPlaylist = (playlistId: string, trackId: string) => {
    setPlaylists(prev => prev.map(p => {
      if (p.id === playlistId) {
        return { ...p, tracks: p.tracks.filter(id => id !== trackId) };
      }
      return p;
    }));
  };

  const toggleLike = (trackId: string) => {
    const likedPl = playlists.find(p => p.id === 'liked');
    if (!likedPl) return;

    if (likedPl.tracks.includes(trackId)) {
      removeFromPlaylist('liked', trackId);
    } else {
      addToPlaylist('liked', trackId);
    }
  };

  const isLiked = (trackId: string) => {
    const likedPl = playlists.find(p => p.id === 'liked');
    return likedPl ? likedPl.tracks.includes(trackId) : false;
  };

  const toggleAlbumLike = (albumId: string) => {
    if (likedAlbumIds.includes(albumId)) {
        setLikedAlbumIds(prev => prev.filter(id => id !== albumId));
    } else {
        setLikedAlbumIds(prev => [...prev, albumId]);
    }
  };

  const isAlbumLiked = (albumId: string) => likedAlbumIds.includes(albumId);

  const openAddToPlaylist = (trackId: string) => {
    setTrackIdToAdd(trackId);
    setAddToPlaylistOpen(true);
  };

  const closeAddToPlaylist = () => {
    setAddToPlaylistOpen(false);
    setTrackIdToAdd(null);
  };

  return (
    <StoreContext.Provider value={{
      tracks, albums, playlists, recommendations, recentlyPlayed, followedArtists, currentTrack, isPlaying, playMode, isShuffle, volume, progress, duration, view,
      isCreatePlaylistOpen, setCreatePlaylistOpen, playlistIdToEdit, setPlaylistIdToEdit,
      isMobilePlayerOpen, setMobilePlayerOpen,
      isAddToPlaylistOpen, trackIdToAdd, openAddToPlaylist, closeAddToPlaylist,
      setView, goToArtist, getArtistStats, toggleFollowArtist, isArtistFollowed, goBack, playTrack, togglePlay, nextTrack, prevTrack, seek, setVolume, toggleRepeat, toggleShuffle,
      createPlaylist, editPlaylist, deletePlaylist, addToPlaylist, removeFromPlaylist, toggleLike, isLiked,
      toggleAlbumLike, isAlbumLiked
    }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (!context) throw new Error("useStore must be used within StoreProvider");
  return context;
};

import React from 'react';
import { useStore } from '../context/StoreContext';
import { Play, ListMusic } from '../components/Icons';

const formatDuration = (seconds: number) => {
    const min = Math.floor(seconds / 60);
    const sec = Math.floor(seconds % 60);
    return `${min}:${sec.toString().padStart(2, '0')}`;
};

export const Home = () => {
  const { albums, setView, tracks, playTrack, recommendations, recentlyPlayed } = useStore();

  const allCharts = [...tracks].sort((a, b) => b.plays - a.plays).slice(0, 25);
  const previewCharts = allCharts.slice(0, 5);

  return (
    <div className="p-4 md:p-8 pb-64 w-full h-full overflow-y-auto page-enter">
      <h2 className="text-2xl md:text-3xl font-bold mb-6 animate-appear" style={{animationDelay: '0.1s'}}>Good evening</h2>

      <div className="flex flex-col md:grid md:grid-cols-2 lg:grid-cols-3 gap-4 mb-8 animate-appear" style={{animationDelay: '0.2s'}}>

        {/* Liked Songs */}
        <div 
          onClick={() => setView({ type: 'PLAYLIST', id: 'liked' })}
          className="bg-surface/50 hover:bg-surface rounded overflow-hidden flex items-center cursor-pointer transition group order-first hover-scale"
        >
          <div className="w-16 h-16 md:w-20 md:h-20 bg-gradient-to-br from-indigo-700 to-blue-300 flex items-center justify-center shrink-0">
            <span className="text-2xl font-bold">♥</span>
          </div>
          <span className="font-bold ml-4">Liked Songs</span>
          <div className="ml-auto mr-4 w-10 h-10 bg-primary rounded-full flex items-center justify-center shadow-lg opacity-0 group-hover:opacity-100 transition translate-y-2 group-hover:translate-y-0">
            <Play fill="black" className="text-black ml-1" />
          </div>
        </div>

        {/* Recently Played */}
        {recentlyPlayed.length > 0 && (
            <div 
                onClick={() => setView({ type: 'PLAYLIST', id: 'history' })}
                className="bg-surface/50 hover:bg-surface rounded overflow-hidden flex items-center cursor-pointer transition group order-2 hover-scale"
            >
                <div className="w-16 h-16 md:w-20 md:h-20 bg-surface-highlight flex items-center justify-center shrink-0">
                    <ListMusic size={32} className="text-secondary" />
                </div>
                <div className="flex flex-col ml-4 overflow-hidden">
                    <span className="font-bold">Recently Played</span>
                    <span className="text-xs text-secondary truncate">{recentlyPlayed.length} tracks</span>
                </div>
                <div className="ml-auto mr-4 w-10 h-10 bg-primary rounded-full flex items-center justify-center shadow-lg opacity-0 group-hover:opacity-100 transition translate-y-2 group-hover:translate-y-0">
                    <Play fill="black" className="text-black ml-1" />
                </div>
            </div>
        )}

      </div>

      {recommendations.length > 0 && (
        <div className="mb-8 animate-appear" style={{animationDelay: '0.3s'}}>
          <h3 className="text-xl md:text-2xl font-bold mb-4">Recommended for you</h3>
          <div className="flex overflow-x-auto gap-4 md:grid md:grid-cols-4 lg:grid-cols-6 pb-4 md:pb-0 snap-x no-scrollbar">
             {recommendations.map(track => (
               <div 
                 key={track.id} 
                 onClick={() => playTrack(track)}
                 className="min-w-[140px] md:min-w-0 p-3 md:p-4 bg-surface hover:bg-surface-highlight rounded-lg transition cursor-pointer group snap-start flex-col flex-shrink-0 hover-scale"
               >
                 <div className="relative mb-3 md:mb-4">
                   <img src={track.cover} alt={track.title} className="w-full aspect-square object-cover rounded shadow-lg" />
                   <div className="absolute bottom-2 right-2 w-10 h-10 bg-primary rounded-full flex items-center justify-center shadow-xl opacity-0 translate-y-2 group-hover:opacity-100 group-hover:translate-y-0 transition-all duration-300">
                     <Play fill="black" size={20} className="text-black ml-1" />
                   </div>
                 </div>
                 <h4 className="font-bold truncate text-sm">{track.title}</h4>
                 <p className="text-xs text-secondary truncate">{track.artist}</p>
               </div>
             ))}
          </div>
        </div>
      )}

      <div className="flex items-end justify-between mb-4 animate-appear" style={{animationDelay: '0.4s'}}>
          <h3 className="text-xl md:text-2xl font-bold">Daily Charts (Top 25)</h3>
          <button 
            onClick={() => setView({ type: 'CHARTS' })}
            className="text-xs font-bold text-secondary hover:text-white uppercase tracking-wider mb-1"
          >
            Show All
          </button>
      </div>

      <div className="flex flex-col gap-2 mb-8 animate-slide-up" style={{animationDelay: '0.5s'}}>
        {previewCharts.map((track, idx) => (
          <div 
            key={track.id} 
            className="grid grid-cols-[16px_1fr_60px] md:grid-cols-[16px_1fr_80px_60px] items-center gap-4 p-2 rounded hover:bg-surface-highlight group cursor-pointer"
            onClick={() => playTrack(track)}
          >
            <div className="w-4 text-center">
                 <span className="text-secondary font-mono block group-hover:hidden text-sm">{idx + 1}</span>
                 <Play size={16} fill="white" className="hidden group-hover:block" />
            </div>

            <div className="flex items-center gap-3 md:gap-4 flex-1 overflow-hidden">
                <img src={track.cover} alt={track.title} className="w-10 h-10 md:w-10 md:h-10 rounded" />
                <div className="flex-1 overflow-hidden">
                  <div className="font-semibold text-white truncate group-hover:underline text-sm md:text-base">{track.title}</div>
                  <div className="text-xs text-secondary truncate">{track.artist}</div>
                </div>
            </div>

            <div className="text-xs text-secondary hidden md:block">{track.plays.toLocaleString()} plays</div>
            <div className="text-xs text-secondary text-right">{formatDuration(track.duration)}</div>
          </div>
        ))}
      </div>

      <h3 className="text-xl md:text-2xl font-bold mb-4 animate-appear" style={{animationDelay: '0.6s'}}>Popular Albums</h3>
      <div className="flex overflow-x-auto gap-4 md:grid md:grid-cols-4 lg:grid-cols-5 pb-4 md:pb-0 snap-x no-scrollbar animate-slide-up" style={{animationDelay: '0.7s'}}>
        {albums.map(album => (
          <div 
            key={album.id} 
            onClick={() => setView({ type: 'ALBUM', id: album.id })}
            className="min-w-[150px] md:min-w-0 p-3 md:p-4 bg-surface hover:bg-surface-highlight rounded-lg transition cursor-pointer group snap-start flex-shrink-0 hover-scale"
          >
            <div className="relative mb-3 md:mb-4">
              <img src={album.cover} alt={album.title} className="w-full aspect-square object-cover rounded shadow-lg" />
              <div className="absolute bottom-2 right-2 w-12 h-12 bg-primary rounded-full flex items-center justify-center shadow-xl opacity-0 translate-y-2 group-hover:opacity-100 group-hover:translate-y-0 transition-all duration-300">
                <Play fill="black" size={24} className="text-black ml-1" />
              </div>
            </div>
            <h4 className="font-bold truncate text-sm md:text-base">{album.title}</h4>
            <p className="text-xs md:text-sm text-secondary truncate">{album.artist} • {album.year}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

import React from 'react';
import { useStore } from '../context/StoreContext';
import { Play, Heart, ListMusic, Trash2, ArrowLeft, PlusSquare, Plus, Edit, Mic2 } from '../components/Icons';

const formatDuration = (seconds: number) => {
    const min = Math.floor(seconds / 60);
    const sec = Math.floor(seconds % 60);
    return `${min}:${sec.toString().padStart(2, '0')}`;
};

const formatPlays = (plays: number) => {
    return new Intl.NumberFormat('en-US').format(plays);
};

export const Library = () => {
  const { 
    view, playlists, tracks, albums, isLiked, toggleLike, playTrack, 
    removeFromPlaylist, goBack, setCreatePlaylistOpen, setPlaylistIdToEdit, setView, 
    toggleAlbumLike, isAlbumLiked, deletePlaylist, openAddToPlaylist, recentlyPlayed,
    goToArtist, getArtistStats, followedArtists, toggleFollowArtist, isArtistFollowed
  } = useStore();

  const handleCreate = () => {
    setPlaylistIdToEdit(null);
    setCreatePlaylistOpen(true);
  };

  const handleEdit = (id: string) => {
      setPlaylistIdToEdit(id);
      setCreatePlaylistOpen(true);
  };

  // --- CHARTS VIEW ---
  if (view.type === 'CHARTS') {
      const chartTracks = [...tracks].sort((a, b) => b.plays - a.plays).slice(0, 25);
      return (
        <div className="h-full overflow-y-auto pb-32 relative w-full page-enter">
            <div className="p-8 bg-gradient-to-b from-purple-900 to-background animate-appear">
                 <div className="absolute top-4 left-4 z-20">
                    <button onClick={goBack} className="w-8 h-8 bg-black/50 rounded-full flex items-center justify-center text-white"><ArrowLeft size={20}/></button>
                 </div>
                 <h1 className="text-4xl md:text-6xl font-bold mt-8 mb-4">Top 25 Charts</h1>
                 <p className="text-white/70">The most played tracks today.</p>
            </div>
            <div className="px-4 md:px-8 py-4 animate-slide-up" style={{animationDelay: '0.2s'}}>
               {chartTracks.map((track, idx) => (
                   <div key={track.id} className="grid grid-cols-[30px_1fr_60px] md:grid-cols-[30px_4fr_2fr_1fr_60px] gap-4 px-2 py-3 rounded hover:bg-surface-highlight group items-center">
                        <div className="flex justify-center text-xl font-bold text-secondary">{idx + 1}</div>
                        <div className="flex items-center gap-3 overflow-hidden">
                             <img src={track.cover} className="w-10 h-10 rounded" alt="" />
                             <div className="flex flex-col overflow-hidden">
                                <span className="text-white font-medium truncate">{track.title}</span>
                                <span onClick={(e) => { e.stopPropagation(); goToArtist(track.artist); }} className="text-xs text-secondary hover:underline cursor-pointer">{track.artist}</span>
                             </div>
                        </div>
                        <span className="text-secondary text-sm hidden md:block truncate">{formatPlays(track.plays)} plays</span>
                        <span className="text-secondary text-sm hidden md:block">{formatDuration(track.duration)}</span>
                        <div className="flex items-center gap-3 justify-end">
                            <button onClick={() => toggleLike(track.id)} className={`${isLiked(track.id) ? 'text-primary' : 'text-transparent group-hover:text-secondary hover:text-white'}`}>
                                <Heart size={16} fill={isLiked(track.id) ? 'currentColor' : 'none'} />
                            </button>
                            <button onClick={() => playTrack(track)} className="text-white"><Play size={20} fill="white"/></button>
                        </div>
                   </div>
               ))}
            </div>
        </div>
      );
  }

  // --- ARTIST VIEW ---
  if (view.type === 'ARTIST') {
      const artistName = (view as any).id;
      const artistTracks = tracks.filter(t => t.artist === artistName);
      const topTracks = [...artistTracks].sort((a, b) => b.plays - a.plays).slice(0, 5);
      const artistAlbums = albums.filter(a => a.artist === artistName);

      const { monthlyPlays, globalRank } = getArtistStats(artistName);
      const totalPlays = artistTracks.reduce((acc, t) => acc + t.plays, 0);
      const isFollowing = isArtistFollowed(artistName);

      return (
        <div className="h-full overflow-y-auto pb-32 relative w-full page-enter">
            {/* Artist Header */}
            <div 
                className="relative h-[40vh] bg-cover bg-center flex items-end p-8 animate-appear"
                style={{ backgroundImage: artistTracks.length ? `linear-gradient(to bottom, rgba(0,0,0,0.2), #121212), url(${artistTracks[0].cover})` : '' }}
            >
                <div className="absolute top-4 left-4 z-20">
                    <button onClick={goBack} className="w-8 h-8 bg-black/50 rounded-full flex items-center justify-center text-white"><ArrowLeft size={20}/></button>
                </div>
                <div className="relative z-10 w-full">
                    <div className="flex items-center gap-2 mb-2 text-white">
                        <div className="bg-blue-600 text-white text-[10px] font-bold px-2 py-1 rounded-full flex items-center gap-1">
                            <span className="w-3 h-3 bg-white rounded-full flex items-center justify-center"><i className="block w-1 h-1 bg-blue-600 rounded-full"></i></span>
                            Verified Artist
                        </div>
                    </div>
                    <h1 className="text-5xl md:text-8xl font-bold tracking-tight mb-4">{artistName}</h1>
                    <p className="text-white font-medium text-lg drop-shadow-md">{formatPlays(monthlyPlays)} monthly plays</p>
                </div>
            </div>

            <div className="px-4 md:px-8 py-6 animate-slide-up" style={{animationDelay: '0.2s'}}>
                <div className="flex items-center gap-4 mb-8">
                    <button onClick={() => topTracks.length && playTrack(topTracks[0])} className="w-14 h-14 bg-primary rounded-full flex items-center justify-center hover:scale-105 transition shadow-lg">
                        <Play size={28} fill="black" className="ml-1 text-black" />
                    </button>

                    {/* Follow Button */}
                    <button 
                        onClick={() => toggleFollowArtist(artistName)}
                        className={`px-6 py-1.5 font-bold text-sm rounded-full uppercase tracking-widest border transition ${isFollowing ? 'border-white text-white hover:bg-white/10' : 'border-secondary text-white hover:border-white'}`}
                    >
                        {isFollowing ? 'Following' : 'Follow'}
                    </button>

                    <button className="text-secondary hover:text-white"><ListMusic size={24}/></button>
                </div>

                <div className="flex flex-col md:flex-row gap-8">
                    {/* Main Content */}
                    <div className="flex-1">
                        <h2 className="text-2xl font-bold mb-4">Popular</h2>
                        <div className="flex flex-col gap-1 mb-8">
                            {topTracks.map((track, idx) => (
                                <div key={track.id} className="grid grid-cols-[20px_1fr_60px] md:grid-cols-[20px_1fr_60px_60px] items-center gap-4 p-2 rounded hover:bg-surface-highlight group cursor-pointer" onClick={() => playTrack(track)}>
                                    <span className="text-secondary text-sm">{idx + 1}</span>
                                    <div className="flex items-center gap-3">
                                        <img src={track.cover} className="w-10 h-10 rounded" alt=""/>
                                        <span className="font-medium text-white truncate">{track.title}</span>
                                    </div>
                                    <span className="text-secondary text-sm hidden md:block">{formatPlays(track.plays)}</span>
                                    <span className="text-secondary text-sm text-right">{formatDuration(track.duration)}</span>
                                </div>
                            ))}
                        </div>

                        <h2 className="text-2xl font-bold mb-4">Discography</h2>
                        <div className="flex overflow-x-auto gap-4 pb-4">
                            {artistAlbums.map(album => (
                                <div key={album.id} onClick={() => setView({type: 'ALBUM', id: album.id})} className="min-w-[150px] bg-surface p-4 rounded-md cursor-pointer hover:bg-surface-highlight hover-scale">
                                    <img src={album.cover} className="w-full aspect-square object-cover rounded mb-2 shadow-lg" />
                                    <div className="font-bold truncate">{album.title}</div>
                                    <div className="text-sm text-secondary">{album.year} • Album</div>
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* About Column */}
                    <div className="w-full md:w-1/3">
                        <h2 className="text-2xl font-bold mb-4">About</h2>
                        <div className="bg-surface rounded-lg overflow-hidden relative group cursor-pointer h-96 hover:scale-[1.02] transition">
                            {topTracks[0] && <img src={topTracks[0].cover} className="w-full h-full object-cover opacity-60 group-hover:opacity-40 transition" />}
                            <div className="absolute inset-0 p-6 flex flex-col justify-end">
                                <div className="mb-4">
                                    <div className="text-3xl font-bold text-white mb-2">#{globalRank}</div>
                                    <div className="text-sm font-bold uppercase tracking-widest text-white">in the world</div>
                                </div>
                                <p className="text-white font-medium line-clamp-3">
                                    {artistName} is a chart-topping artist known for their unique blend of {artistTracks[0]?.genre || 'music'}. 
                                    With over {formatPlays(totalPlays)} total streams, they continue to redefine the sound of modern music.
                                </p>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
      )
  }

  // --- Render Album or Playlist Detail ---
  if (view.type === 'PLAYLIST' || view.type === 'ALBUM') {
    let title = "", subtitle = "", cover = "", description = "", items: any[] = [];
    let year: number | undefined = undefined;
    let label = "";
    let isPlaylist = view.type === 'PLAYLIST';
    let id = (view as any).id;
    let isLikedSongs = id === 'liked';
    let isHistory = id === 'history';
    let isSystem = false;

    if (isPlaylist) {
      if (isHistory) {
         title = "Recently Played";
         subtitle = `${recentlyPlayed.length} tracks`;
         isSystem = true;
         items = recentlyPlayed;
         if (recentlyPlayed.length > 0) cover = recentlyPlayed[0].cover;
      } else {
          const pl = playlists.find(p => p.id === id);
          if (!pl) {
             return (
                 <div className="flex flex-col items-center justify-center h-full pb-32">
                     <h2 className="text-2xl font-bold mb-4">Playlist not found</h2>
                     <button onClick={() => setView({type:'HOME'})} className="px-6 py-2 bg-white text-black rounded-full font-bold">Return Home</button>
                 </div>
             );
          }
          title = pl.name;
          subtitle = `Playlist • ${pl.tracks.length} songs`;
          description = pl.description || "";
          isSystem = !!pl.isSystem;
          label = "Huevify User Playlist";

          if (isLikedSongs) {
          } else if (pl.customCover) {
              cover = pl.customCover;
          } else {
              cover = pl.tracks.length > 0 ? (tracks.find(t => t.id === pl.tracks[0])?.cover || "") : "";
          }
          items = pl.tracks.map(tid => tracks.find(t => t.id === tid)).filter(Boolean);
      }
    } else {
      const alb = albums.find(a => a.id === id);
      if (!alb) return <div>Not Found</div>;
      title = alb.title;
      subtitle = `Album • ${alb.artist}`;
      if (alb.year) subtitle += ` • ${alb.year}`;
      cover = alb.cover;
      items = alb.trackIds.map(tid => tracks.find(t => t.id === tid)).filter(Boolean);
      year = alb.year;
      label = alb.recordLabel || "Huevify Records";
    }

    const totalDurationSeconds = items.reduce((acc, t) => acc + t.duration, 0);
    const totalMinutes = Math.floor(totalDurationSeconds / 60);
    const totalReleasePlays = items.reduce((acc, t) => acc + t.plays, 0);

    return (
      <div className="h-full overflow-y-auto pb-64 relative w-full page-enter">
        {/* Header */}
        <div className="relative p-6 md:p-8 bg-gradient-to-b from-slate-700 to-background animate-appear">
          {/* Back Button */}
          <div className="absolute top-4 left-4 md:top-6 md:left-6 z-20">
            <button 
              onClick={goBack} 
              className="w-8 h-8 bg-black/50 hover:bg-black/80 rounded-full flex items-center justify-center text-white transition"
            >
              <ArrowLeft size={20} />
            </button>
          </div>

          <div className="flex flex-col items-center text-center md:flex-row md:items-end md:text-left gap-6 mt-8 md:mt-8">
            {/* Cover Art Logic */}
            <div className="w-48 h-48 md:w-56 md:h-56 shadow-2xl shrink-0 flex items-center justify-center bg-surface-highlight overflow-hidden rounded-md animate-appear" style={{animationDelay: '0.1s'}}>
                {isLikedSongs ? (
                    <div className="w-full h-full bg-gradient-to-br from-indigo-700 to-blue-300 flex items-center justify-center">
                        <Heart size={64} fill="white" className="text-white" />
                    </div>
                ) : isHistory ? (
                    <div className="w-full h-full bg-surface-highlight flex items-center justify-center">
                        <ListMusic size={64} className="text-secondary" />
                    </div>
                ) : cover ? (
                    <img src={cover} alt={title} className="w-full h-full object-cover" />
                ) : (
                    <ListMusic size={64} className="text-secondary" />
                )}
            </div>

            <div className="flex flex-col gap-2 w-full md:w-auto animate-appear" style={{animationDelay: '0.2s'}}>
              <span className="uppercase text-xs font-bold hidden md:block">{view.type}</span>
              <h1 className="text-3xl md:text-7xl font-bold tracking-tighter leading-tight line-clamp-2">
                  {title}
              </h1>
              {description && <p className="text-secondary/80 text-sm md:text-base font-medium">{description}</p>}
              <p className="text-white font-semibold text-sm md:text-base mt-1">{subtitle}</p>

              {/* Mobile Actions Row - Hidden on Desktop */}
              {isPlaylist && !isSystem && (
                  <div className="flex gap-4 justify-center md:justify-start mt-2 md:hidden">
                      <button onClick={() => handleEdit(id)} className="text-xs border border-secondary/50 rounded-full px-3 py-1 text-secondary hover:text-white hover:border-white">
                          Edit
                      </button>
                      <button onClick={(e) => { e.stopPropagation(); deletePlaylist(id); }} className="text-xs border border-secondary/50 rounded-full px-3 py-1 text-secondary hover:text-white hover:border-white">
                          Delete
                      </button>
                  </div>
              )}
            </div>
          </div>
        </div>

        {/* Action Bar - Increased z-index to 30 */}
        <div className="px-6 md:px-8 py-4 md:py-6 bg-background/50 backdrop-blur-sm sticky top-0 z-30 flex items-center gap-6 animate-appear" style={{animationDelay: '0.3s'}}>
          <button 
             onClick={() => items.length > 0 && playTrack(items[0])}
             className="w-12 h-12 md:w-14 md:h-14 bg-primary rounded-full flex items-center justify-center hover:scale-105 transition shadow-lg"
          >
            <Play size={24} fill="black" className="ml-1 text-black md:w-7 md:h-7" />
          </button>

          {/* Like Button for Album */}
          {!isPlaylist && (
             <button onClick={() => toggleAlbumLike(id)} className="hover:scale-105 transition">
                <Heart size={32} fill={isAlbumLiked(id) ? '#1ed760' : 'none'} className={isAlbumLiked(id) ? 'text-primary' : 'text-secondary hover:text-white'} />
             </button>
          )}

          {/* Desktop Edit Button for Playlist */}
          {isPlaylist && !isSystem && (
              <div className="hidden md:flex gap-4 ml-auto">
                 <button onClick={() => handleEdit(id)} className="text-secondary hover:text-white hover:scale-105"><Edit size={24}/></button>
                 {/* Explicitly stop propagation to prevent bubbling issues */}
                 <button onClick={(e) => { e.stopPropagation(); deletePlaylist(id); }} className="text-secondary hover:text-white hover:scale-105"><Trash2 size={24}/></button>
              </div>
          )}
        </div>

        {/* List */}
        <div className="px-4 md:px-8 animate-slide-up" style={{animationDelay: '0.4s'}}>
           {/* PC Header */}
           <div className="hidden md:grid grid-cols-[16px_4fr_2fr_1fr_60px] gap-4 px-4 py-2 border-b border-surface-highlight text-secondary text-sm mb-4">
             <span>#</span>
             <span>Title</span>
             <span>Plays</span>
             <span><ListMusic size={16} /></span>
             <span></span>
           </div>

           {items.map((track, idx) => (
             <div key={track.id} className="grid grid-cols-[16px_1fr_60px] md:grid-cols-[16px_4fr_2fr_1fr_60px] gap-4 px-2 md:px-4 py-3 rounded hover:bg-surface-highlight group items-center">

               {/* Index / Play Icon */}
               <div className="w-4 flex justify-center">
                   <span className="text-secondary group-hover:hidden text-sm">{idx + 1}</span>
                   <button onClick={() => playTrack(track)} className="hidden group-hover:block text-white"><Play size={12} fill="white"/></button>
               </div>

               {/* Track Info */}
               <div className="flex items-center gap-3 overflow-hidden">
                 <img src={track.cover} className="w-10 h-10 md:hidden rounded" alt="" /> {/* Show cover on mobile only in list */}
                 <div className="flex flex-col overflow-hidden">
                   {/* Mobile: Title + (feat. Artist) */}
                   <span className="text-white font-medium truncate">
                      {track.title} 
                      <span className="md:hidden text-secondary font-normal"> (feat. {track.artist})</span>
                   </span>
                   {/* Mobile: Plays • Artist */}
                   <div className="md:hidden text-xs text-secondary truncate mt-0.5">
                      {formatPlays(track.plays)} • {track.artist}
                   </div>
                   {/* PC: Artist only - Clickable */}
                   <span 
                        onClick={(e) => { e.stopPropagation(); goToArtist(track.artist); }} 
                        className="hidden md:block text-secondary text-xs group-hover:text-white hover:underline cursor-pointer"
                   >
                       {track.artist}
                   </span>
                 </div>
               </div>

               {/* PC: Plays */}
               <span className="text-secondary text-sm hidden md:block truncate">{formatPlays(track.plays)}</span>

               {/* PC: Duration */}
               <span className="text-secondary text-sm hidden md:block">{formatDuration(track.duration)}</span>

               {/* Actions */}
               <div className="flex items-center gap-3 justify-end">
                 <button onClick={() => toggleLike(track.id)} className={`${isLiked(track.id) ? 'text-primary' : 'text-transparent group-hover:text-secondary hover:text-white'}`}>
                    <Heart size={16} fill={isLiked(track.id) ? 'currentColor' : 'none'} />
                 </button>

                 {/* Add to Playlist Button */}
                 <button onClick={(e) => { e.stopPropagation(); openAddToPlaylist(track.id); }} className="text-transparent group-hover:text-secondary hover:text-white" title="Add to Playlist">
                    <Plus size={16} />
                 </button>

                 {isPlaylist && !isLikedSongs && !isHistory && (
                    <button onClick={() => removeFromPlaylist((view as any).id, track.id)} className="text-transparent group-hover:text-secondary hover:text-red-500">
                      <Trash2 size={16} />
                    </button>
                 )}
               </div>
             </div>
           ))}

           {/* Release Footer */}
           {items.length > 0 && (
             <div className="mt-8 pt-8 border-t border-surface-highlight text-secondary text-sm font-medium pb-8 flex flex-col gap-1">
                 {year && <p>Released {year}</p>}
                 <p>{items.length} songs, {totalMinutes} min</p>
                 <p>{formatPlays(totalReleasePlays)} plays</p>
                 <p className="mt-4 text-[10px] uppercase tracking-widest font-bold">© {label}</p>
             </div>
           )}
        </div>
      </div>
    );
  }

  // --- Default Library View (List of playlists/albums) ---
  return (
    <div className="p-4 md:p-8 pb-32 h-full overflow-y-auto bg-background page-enter">
      <h2 className="text-2xl font-bold mb-6 animate-appear">Your Library</h2>

      <div className="grid grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3 md:gap-4 animate-slide-up" style={{animationDelay: '0.1s'}}>
        {/* Create New Playlist Card */}
        <div 
          onClick={handleCreate}
          className="p-4 bg-surface hover:bg-surface-highlight rounded-lg cursor-pointer transition group flex flex-col justify-center items-center text-center min-h-[150px] md:min-h-[200px] hover-scale"
        >
           <div className="w-12 h-12 md:w-16 md:h-16 rounded-full bg-surface-highlight group-hover:bg-white flex items-center justify-center mb-4 transition-colors">
              <PlusSquare size={24} className="text-secondary group-hover:text-black md:w-8 md:h-8" />
           </div>
           <h3 className="font-bold text-white text-sm md:text-base">Create Playlist</h3>
        </div>

        {/* Playlists */}
        {playlists.map(pl => {
           let cover = pl.customCover;
           if (!cover && pl.tracks.length > 0) {
               cover = tracks.find(t => t.id === pl.tracks[0])?.cover;
           }

           return (
           <div 
             key={pl.id} 
             onClick={() => setView({ type: 'PLAYLIST', id: pl.id })}
             className="p-3 md:p-4 bg-surface hover:bg-surface-highlight rounded-lg cursor-pointer transition group hover-scale"
           >
              <div className={`aspect-square mb-2 md:mb-4 shadow-lg flex items-center justify-center rounded-md overflow-hidden ${pl.id === 'liked' ? 'bg-gradient-to-br from-indigo-700 to-blue-300' : 'bg-surface-highlight'}`}>
                 {pl.id === 'liked' ? (
                     <Heart size={32} fill="white" className="text-white md:w-12 md:h-12" />
                 ) : cover ? (
                     <img src={cover} alt={pl.name} className="w-full h-full object-cover" />
                 ) : (
                     <ListMusic size={32} className="text-secondary md:w-12 md:h-12" />
                 )}
              </div>
              <h3 className="font-bold truncate text-white text-sm md:text-base">{pl.name}</h3>
              <p className="text-xs md:text-sm text-secondary truncate">Playlist</p>
           </div>
           );
        })}

        {/* Followed Artists */}
        {followedArtists.map(artist => {
            // Find a cover image for the artist from tracks
            const cover = tracks.find(t => t.artist === artist)?.cover || "";
            return (
                <div 
                    key={artist}
                    onClick={() => goToArtist(artist)}
                    className="p-3 md:p-4 bg-surface hover:bg-surface-highlight rounded-lg transition cursor-pointer group flex flex-col items-center text-center hover-scale"
                >
                    <div className="aspect-square w-full mb-2 md:mb-4 shadow-lg rounded-full overflow-hidden">
                        {cover ? (
                            <img src={cover} alt={artist} className="w-full h-full object-cover" />
                        ) : (
                            <div className="w-full h-full bg-surface-highlight flex items-center justify-center">
                                <Mic2 size={32} className="text-secondary" />
                            </div>
                        )}
                    </div>
                    <h4 className="font-bold truncate text-white text-sm md:text-base w-full">{artist}</h4>
                    <p className="text-xs md:text-sm text-secondary truncate">Artist</p>
                </div>
            );
        })}

        {/* Liked Albums */}
        {albums.filter(a => isAlbumLiked(a.id)).map(album => (
           <div 
