      </div>

      <div className="absolute top-0 left-0 w-full h-[2px] bg-transparent md:hidden pointer-events-none">
        <div className="h-full bg-primary" style={{ width: `${(progress / (duration || 1)) * 100}%` }} />
      </div>
    </div>
  );
};

