export interface Track {
  id: string;
  title: string;
  artist: string;
  album: string;
  cover: string;
  duration: number; // in seconds
  url: string; // audio source
  plays: number;
  genre: string; // New field for recommendations
}

export interface Playlist {
  id: string;
  name: string;
  description?: string;
  customCover?: string; // Base64 or URL
  tracks: string[]; // array of track IDs
  isSystem?: boolean; // e.g. "Liked Songs"
  ownerId?: string; // ID of the user who created this playlist
}

export interface Album {
  id: string;
  title: string;
  artist: string;
  cover: string;
  trackIds: string[];
  year: number;
  recordLabel?: string;
}

export interface User {
  id: string;
  username: string;
  password: string; // Stored locally for this prototype
  displayName: string;
  avatar?: string; // Base64
}

export type ViewState = 
  | { type: 'HOME' }
  | { type: 'SEARCH' }
  | { type: 'LIBRARY' }
  | { type: 'PLAYLIST'; id: string }
  | { type: 'ALBUM'; id: string }
  | { type: 'ARTIST'; id: string }
  | { type: 'CHARTS' };

export enum PlayMode {
  OFF = 'OFF',
  CONTEXT = 'CONTEXT', // Repeat Playlist/Album
  ONE = 'ONE', // Repeat One Track
}

import React, { createContext, useContext, useEffect, useRef, useState } from 'react';
import { Track, Playlist, Album, ViewState, PlayMode, User } from '../types.ts';
import { generateInitialData, StorageService } from '../services/data.ts';

interface ArtistStats {
  monthlyPlays: number;
  globalRank: number;
}

interface StoreContextType {
  // Auth
  currentUser: User | null;
  login: (username: string, pass: string) => boolean;
  register: (user: Omit<User, 'id'>) => boolean;
  logout: () => void;

  tracks: Track[];
  albums: Album[];
  playlists: Playlist[];
  recommendations: Track[];
  recentlyPlayed: Track[];
  followedArtists: string[];
  currentTrack: Track | null;
  isPlaying: boolean;
  playMode: PlayMode;
  isShuffle: boolean;
  volume: number;
  progress: number;
  duration: number;
  view: ViewState;

  // Modal States
  isCreatePlaylistOpen: boolean;
  setCreatePlaylistOpen: (isOpen: boolean) => void;
  playlistIdToEdit: string | null; 
  setPlaylistIdToEdit: (id: string | null) => void;

  isMobilePlayerOpen: boolean;
  setMobilePlayerOpen: (isOpen: boolean) => void;

  isAddToPlaylistOpen: boolean;
  trackIdToAdd: string | null;
  openAddToPlaylist: (trackId: string) => void;
  closeAddToPlaylist: () => void;

  isDeleteModalOpen: boolean;
  playlistToDelete: string | null;
  openDeleteModal: (id: string) => void;
  closeDeleteModal: () => void;
  confirmDeletePlaylist: () => void;

  isProfileModalOpen: boolean;
  setProfileModalOpen: (isOpen: boolean) => void;

  // Actions
  setView: (v: ViewState) => void;
  goToArtist: (artistName: string) => void;
  getArtistStats: (artistName: string) => ArtistStats;
  toggleFollowArtist: (artistName: string) => void;
  isArtistFollowed: (artistName: string) => boolean;
  goBack: () => void;
  playTrack: (track: Track) => void;
  togglePlay: () => void;
  nextTrack: () => void;
  prevTrack: () => void;
  seek: (time: number) => void;
  setVolume: (vol: number) => void;
  toggleRepeat: () => void;
  toggleShuffle: () => void;

  createPlaylist: (name: string, description?: string, cover?: string) => void;
  editPlaylist: (id: string, name: string, description?: string, cover?: string) => void;
  deletePlaylist: (id: string) => void; 
  addToPlaylist: (playlistId: string, trackId: string) => void;
  removeFromPlaylist: (playlistId: string, trackId: string) => void;

  toggleLike: (trackId: string) => void;
  isLiked: (trackId: string) => boolean;
  toggleAlbumLike: (albumId: string) => void;
  isAlbumLiked: (albumId: string) => boolean;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

export const StoreProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  // --- Auth State ---
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  // --- Data State ---
  const [tracks, setTracks] = useState<Track[]>([]);
  const [albums, setAlbums] = useState<Album[]>([]);
  const [playlists, setPlaylists] = useState<Playlist[]>([]);
  const [recommendations, setRecommendations] = useState<Track[]>([]);
  const [recentlyPlayed, setRecentlyPlayed] = useState<Track[]>([]);
  const [likedAlbumIds, setLikedAlbumIds] = useState<string[]>([]);
  const [followedArtists, setFollowedArtists] = useState<string[]>([]);

  // --- Player State ---
  const [currentTrack, setCurrentTrack] = useState<Track | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [playMode, setPlayMode] = useState<PlayMode>(PlayMode.OFF);
  const [isShuffle, setIsShuffle] = useState(false);
  const [volume, setVolumeState] = useState(0.5);
  const [progress, setProgress] = useState(0);
  const [duration, setDuration] = useState(0);
  const [hasCountedListen, setHasCountedListen] = useState(false);

  // --- UI State ---
  const [view, setViewInternal] = useState<ViewState>({ type: 'HOME' });
  const [history, setHistory] = useState<ViewState[]>([]);

  // Modals
  const [isCreatePlaylistOpen, setCreatePlaylistOpen] = useState(false);
  const [playlistIdToEdit, setPlaylistIdToEdit] = useState<string | null>(null);
  const [isMobilePlayerOpen, setMobilePlayerOpen] = useState(false);
  const [isAddToPlaylistOpen, setAddToPlaylistOpen] = useState(false);
  const [trackIdToAdd, setTrackIdToAdd] = useState<string | null>(null);
  const [isProfileModalOpen, setProfileModalOpen] = useState(false);

  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [playlistToDelete, setPlaylistToDelete] = useState<string | null>(null);

  // --- Refs ---
  const audioRef = useRef<HTMLAudioElement>(new Audio());
  const cumulativeTimeRef = useRef(0);
  const lastTimeRef = useRef(0);

  // --- Initialization ---
  useEffect(() => {
    // 1. Check Session
    const sessionUser = StorageService.load<User | null>('huevify_current_user', null);
    if (sessionUser) {
        setCurrentUser(sessionUser);
    }

    // 2. Load Content
    const { tracks: initialTracks, albums: initialAlbums } = generateInitialData();

    // Load persisted play counts
    const storedPlays = StorageService.load<Record<string, number>>('huevify_plays', {});
    const mergedTracks = initialTracks.map(t => ({
      ...t,
      plays: storedPlays[t.id] ?? t.plays
    }));

    setTracks(mergedTracks);
    setAlbums(initialAlbums);

    const storedLikedAlbums = StorageService.load<string[]>('huevify_liked_albums', []);
    setLikedAlbumIds(storedLikedAlbums);

    const storedFollowedArtists = StorageService.load<string[]>('huevify_followed_artists', []);
    setFollowedArtists(storedFollowedArtists);

    const storedRecent = StorageService.load<Track[]>('huevify_recent', []);
    setRecentlyPlayed(storedRecent);

    // Setup Audio
    audioRef.current.volume = 0.5;
  }, []);

  // --- Playlist Loading & Isolation ---
  useEffect(() => {
    const allPlaylists = StorageService.load<Playlist[]>('huevify_playlists', [
      { id: 'liked', name: 'Liked Songs', tracks: [], isSystem: true, description: 'Your favorite tracks' }
    ]);

    // Filter playlists: Show system playlists + playlists owned by current user
    // If no user is logged in, show only system playlists
    const visiblePlaylists = allPlaylists.filter(p => 
      p.isSystem || (currentUser && p.ownerId === currentUser.id)
    );

    setPlaylists(visiblePlaylists);
  }, [currentUser]);

  // --- Auth Methods ---

  const login = (username: string, pass: string): boolean => {
    const users = StorageService.load<User[]>('huevify_users', []);
    const user = users.find(u => u.username === username && u.password === pass);
    if (user) {
        setCurrentUser(user);
        StorageService.save('huevify_current_user', user);
        return true;
    }
    return false;
  };

  const register = (newUser: Omit<User, 'id'>): boolean => {
      const users = StorageService.load<User[]>('huevify_users', []);
      if (users.some(u => u.username === newUser.username)) {
          return false; // User exists
      }

      const user: User = {
          ...newUser,
          id: `user_${Date.now()}`
      };

      const updatedUsers = [...users, user];
      StorageService.save('huevify_users', updatedUsers);

      // Auto login
      setCurrentUser(user);
      StorageService.save('huevify_current_user', user);
      return true;
  };

  const logout = () => {
      setCurrentUser(null);
      StorageService.save('huevify_current_user', null);
      setProfileModalOpen(false);

      // Stop audio
      setIsPlaying(false);
      audioRef.current.pause();
      setCurrentTrack(null);
      setViewInternal({ type: 'HOME' });
  };

  // --- Recommendation Engine ---
  useEffect(() => {
    if (tracks.length === 0) return;

    // 1. Analyze User Profile
    const genreScores: Record<string, number> = {};
    const likedPlaylist = playlists.find(p => p.id === 'liked');
    const likedIds = likedPlaylist ? likedPlaylist.tracks : [];

    tracks.forEach(t => {
      let score = 0;
      if (likedIds.includes(t.id)) score += 50;
      if (t.plays > 0) score += Math.log(t.plays) * 2;
      if (score > 0) {
        genreScores[t.genre] = (genreScores[t.genre] || 0) + score;
      }
    });

    const topGenres = Object.entries(genreScores)
      .sort(([, a], [, b]) => b - a)
      .slice(0, 3)
      .map(([g]) => g);

    const targetGenres = topGenres.length > 0 ? topGenres : tracks.map(t => t.genre);

    const candidates = tracks.filter(t => 
      targetGenres.includes(t.genre) && 
      !likedIds.includes(t.id)
    );

    const shuffled = [...candidates].sort(() => 0.5 - Math.random()).slice(0, 6);
    setRecommendations(shuffled);

  }, [tracks, playlists]);

  // --- Persistence Effects ---

  // REMOVED the playlist auto-save useEffect to prevents overwriting global data with user filtered data.
  // Playlist persistence is now handled manually in create/edit/delete functions.

  useEffect(() => {
    if (tracks.length > 0) {
      const playCounts = tracks.reduce((acc, t) => ({ ...acc, [t.id]: t.plays }), {});
      StorageService.save('huevify_plays', playCounts);
    }
  }, [tracks]);

  useEffect(() => {
    StorageService.save('huevify_liked_albums', likedAlbumIds);
  }, [likedAlbumIds]);

  useEffect(() => {
    StorageService.save('huevify_followed_artists', followedArtists);
  }, [followedArtists]);

  // --- Navigation Actions ---
  const setView = (newView: ViewState) => {
    if (JSON.stringify(view) !== JSON.stringify(newView)) {
      setHistory(prev => [...prev, view]);
      setViewInternal(newView);
    }
    setMobilePlayerOpen(false);
  };

  const goToArtist = (artistName: string) => {
    setView({ type: 'ARTIST', id: artistName });
    setMobilePlayerOpen(false);
  }

  const goBack = () => {
    if (history.length > 0) {
      const prev = history[history.length - 1];
      setHistory(h => h.slice(0, -1));
      setViewInternal(prev);
    } else {
      setViewInternal({ type: 'HOME' });
    }
  };

  // --- Artist Stats Calculation ---
  const getArtistStats = (artistName: string): ArtistStats => {
    const artistPlayMap: Record<string, number> = {};
    tracks.forEach(t => {
        artistPlayMap[t.artist] = (artistPlayMap[t.artist] || 0) + t.plays;
    });

    const sortedArtists = Object.entries(artistPlayMap).sort(([, a], [, b]) => b - a);
    const rankIndex = sortedArtists.findIndex(([name]) => name === artistName);

    const totalPlays = artistPlayMap[artistName] || 0;
    const monthlyPlays = Math.floor(totalPlays * 0.45); 

    return {
        monthlyPlays,
        globalRank: rankIndex === -1 ? 999 : rankIndex + 1
    };
  };

  const toggleFollowArtist = (artistName: string) => {
    setFollowedArtists(prev => {
        if (prev.includes(artistName)) {
            return prev.filter(a => a !== artistName);
        } else {
            return [...prev, artistName];
        }
    });
  };

  const isArtistFollowed = (artistName: string) => followedArtists.includes(artistName);

  // --- Playback State Reset ---
  useEffect(() => {
    cumulativeTimeRef.current = 0;
    lastTimeRef.current = 0;
    setHasCountedListen(false);
  }, [currentTrack]);

  // --- Audio Logic ---
  useEffect(() => {
    const audio = audioRef.current;

    const handleTimeUpdate = () => {
      const now = audio.currentTime;
      setProgress(now);
      const diff = now - lastTimeRef.current;
      if (diff > 0 && diff < 1.5) {
        cumulativeTimeRef.current += diff;
      }
      lastTimeRef.current = now;

      if (cumulativeTimeRef.current > 30 && !hasCountedListen && currentTrack) {
        handleListenCount(currentTrack);
      }
    };

    const handleEnded = () => {
      if (playMode === PlayMode.ONE) {
        audio.currentTime = 0;
        audio.play();
      } else {
        nextTrack();
      }
    };

    const handleLoadedMetadata = () => {
        setDuration(audio.duration);
    }

    audio.addEventListener('timeupdate', handleTimeUpdate);
    audio.addEventListener('ended', handleEnded);
    audio.addEventListener('loadedmetadata', handleLoadedMetadata);

    return () => {
      audio.removeEventListener('timeupdate', handleTimeUpdate);
      audio.removeEventListener('ended', handleEnded);
      audio.removeEventListener('loadedmetadata', handleLoadedMetadata);
    };
  }, [currentTrack, hasCountedListen, playMode, tracks, isShuffle]);

  const handleListenCount = (track: Track) => {
    const lastListenKey = `last_listen_${track.id}`;
    const lastListenTime = StorageService.load<number>(lastListenKey, 0);
    const now = Date.now();

    if (now - lastListenTime > track.duration * 1000) {
      const addedPlays = Math.floor(100 + Math.random() * 9900);
      setTracks(prev => prev.map(t => 
        t.id === track.id ? { ...t, plays: t.plays + addedPlays } : t
      ));
      StorageService.save(lastListenKey, now);
    }
    setHasCountedListen(true);
  };

  const playTrack = (track: Track) => {
    setRecentlyPlayed(prev => {
        const filtered = prev.filter(t => t.id !== track.id);
        const newHistory = [track, ...filtered].slice(0, 10);
        StorageService.save('huevify_recent', newHistory);
        return newHistory;
    });

    if (currentTrack?.id === track.id) {
      togglePlay();
      return;
    }
    setCurrentTrack(track);
    audioRef.current.src = track.url;
    audioRef.current.play()
      .then(() => setIsPlaying(true))
      .catch(e => console.error("Audio play failed", e));
  };

  const togglePlay = () => {
    if (audioRef.current.paused) {
      audioRef.current.play();
      setIsPlaying(true);
    } else {
      audioRef.current.pause();
      setIsPlaying(false);
    }
  };

  const setVolume = (vol: number) => {
    setVolumeState(vol);
    audioRef.current.volume = vol;
  };

  const seek = (time: number) => {
    audioRef.current.currentTime = time;
    lastTimeRef.current = time;
    setProgress(time);
  };

  const getQueue = (): Track[] => {
    if (view.type === 'PLAYLIST' && (view as any).id === 'history') {
        return recentlyPlayed;
    }
    return tracks; 
  };

  const nextTrack = () => {
    const queue = getQueue();
    if (isShuffle) {
        const randomIdx = Math.floor(Math.random() * queue.length);
        playTrack(queue[randomIdx]);
        return;
    }
    const idx = queue.findIndex(t => t.id === currentTrack?.id);
    if (idx !== -1 && idx < queue.length - 1) {
      playTrack(queue[idx + 1]);
    } else if (playMode === PlayMode.CONTEXT) {
      playTrack(queue[0]);
    } else {
      setIsPlaying(false);
      audioRef.current.pause();
      audioRef.current.currentTime = 0;
    }
  };

  const prevTrack = () => {
    if (audioRef.current.currentTime > 3) {
      audioRef.current.currentTime = 0;
      lastTimeRef.current = 0;
      return;
    }
    const queue = getQueue();
    const idx = queue.findIndex(t => t.id === currentTrack?.id);
    if (idx > 0) {
      playTrack(queue[idx - 1]);
    } else {
      playTrack(queue[queue.length - 1]);
    }
  };

  const toggleRepeat = () => {
    if (playMode === PlayMode.OFF) setPlayMode(PlayMode.CONTEXT);
    else if (playMode === PlayMode.CONTEXT) setPlayMode(PlayMode.ONE);
    else setPlayMode(PlayMode.OFF);
  };

  const toggleShuffle = () => {
    setIsShuffle(!isShuffle);
  };

  // --- Library Actions (UPDATED FOR PERSISTENCE) ---

  // Helper to sync global storage and local state
  const syncPlaylists = (newGlobalPlaylists: Playlist[]) => {
      StorageService.save('huevify_playlists', newGlobalPlaylists);

      const visible = newGlobalPlaylists.filter(p => 
         p.isSystem || (currentUser && p.ownerId === currentUser.id)
      );
      setPlaylists(visible);
  };

  const createPlaylist = (name: string, description?: string, cover?: string) => {
    if (!currentUser) return;

    const newPl: Playlist = {
      id: `pl_${Date.now()}`,
      name,
      description: description || "",
      customCover: cover,
      tracks: [],
      ownerId: currentUser.id
    };

    const all = StorageService.load<Playlist[]>('huevify_playlists', []);
    syncPlaylists([...all, newPl]);
  };

  const editPlaylist = (id: string, name: string, description?: string, cover?: string) => {
    const all = StorageService.load<Playlist[]>('huevify_playlists', []);
    const updated = all.map(p => {
        if (p.id === id) {
            return { ...p, name, description, customCover: cover };
        }
        return p;
    });
    syncPlaylists(updated);
  };

  const openDeleteModal = (id: string) => {
      setPlaylistToDelete(id);
      setIsDeleteModalOpen(true);
  };

  const closeDeleteModal = () => {
      setIsDeleteModalOpen(false);
      setPlaylistToDelete(null);
  };

  const confirmDeletePlaylist = () => {
    if (!playlistToDelete) return;
    const id = playlistToDelete;

    if (view.type === 'PLAYLIST' && (view as any).id === id) {
        setViewInternal({ type: 'LIBRARY' });
    }

    const all = StorageService.load<Playlist[]>('huevify_playlists', []);
    const updated = all.filter(p => p.id !== id);
    syncPlaylists(updated);

    closeDeleteModal();
  };

  const deletePlaylist = (id: string) => {
      openDeleteModal(id);
  };

  const addToPlaylist = (playlistId: string, trackId: string) => {
    const all = StorageService.load<Playlist[]>('huevify_playlists', []);
    const updated = all.map(p => {
      if (p.id === playlistId && !p.tracks.includes(trackId)) {
        return { ...p, tracks: [...p.tracks, trackId] };
      }
      return p;
    });
    syncPlaylists(updated);
  };

  const removeFromPlaylist = (playlistId: string, trackId: string) => {
    const all = StorageService.load<Playlist[]>('huevify_playlists', []);
    const updated = all.map(p => {
      if (p.id === playlistId) {
        return { ...p, tracks: p.tracks.filter(id => id !== trackId) };
      }
      return p;
    });
    syncPlaylists(updated);
  };

  const toggleLike = (trackId: string) => {
    // Note: 'liked' is a system playlist. For this prototype, we share it or check permissions.
    // To ensure consistency, we just use addToPlaylist/removeFromPlaylist which now handles storage safely.

    // We need to check local state to decide whether to add or remove
    const likedPl = playlists.find(p => p.id === 'liked');
    if (!likedPl) return;

    if (likedPl.tracks.includes(trackId)) {
      removeFromPlaylist('liked', trackId);
    } else {
      addToPlaylist('liked', trackId);
    }
  };

  const isLiked = (trackId: string) => {
    const likedPl = playlists.find(p => p.id === 'liked');
    return likedPl ? likedPl.tracks.includes(trackId) : false;
  };

  const toggleAlbumLike = (albumId: string) => {
    if (likedAlbumIds.includes(albumId)) {
        setLikedAlbumIds(prev => prev.filter(id => id !== albumId));
    } else {
        setLikedAlbumIds(prev => [...prev, albumId]);
    }
  };

  const isAlbumLiked = (albumId: string) => likedAlbumIds.includes(albumId);

  const openAddToPlaylist = (trackId: string) => {
    setTrackIdToAdd(trackId);
    setAddToPlaylistOpen(true);
  };

  const closeAddToPlaylist = () => {
    setAddToPlaylistOpen(false);
    setTrackIdToAdd(null);
  };

  return (
    <StoreContext.Provider value={{
      currentUser, login, register, logout,
      tracks, albums, playlists, recommendations, recentlyPlayed, followedArtists, currentTrack, isPlaying, playMode, isShuffle, volume, progress, duration, view,
      isCreatePlaylistOpen, setCreatePlaylistOpen, playlistIdToEdit, setPlaylistIdToEdit,
      isMobilePlayerOpen, setMobilePlayerOpen,
      isAddToPlaylistOpen, trackIdToAdd, openAddToPlaylist, closeAddToPlaylist,
      isDeleteModalOpen, playlistToDelete, openDeleteModal, closeDeleteModal, confirmDeletePlaylist,
      isProfileModalOpen, setProfileModalOpen,
      setView, goToArtist, getArtistStats, toggleFollowArtist, isArtistFollowed, goBack, playTrack, togglePlay, nextTrack, prevTrack, seek, setVolume, toggleRepeat, toggleShuffle,
      createPlaylist, editPlaylist, deletePlaylist, addToPlaylist, removeFromPlaylist, toggleLike, isLiked,
      toggleAlbumLike, isAlbumLiked
    }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (!context) throw new Error("useStore must be used within StoreProvider");
  return context;
};

import React, { useState, useRef } from 'react';
import { useStore } from '../context/StoreContext.tsx';
import { Camera, X } from './Icons.tsx';

type AuthMode = 'LANDING' | 'LOGIN' | 'REGISTER';

export const Auth = () => {
  const { login, register } = useStore();
  const [mode, setMode] = useState<AuthMode>('LANDING');

  // Login State
  const [loginUsername, setLoginUsername] = useState("");
  const [loginPass, setLoginPass] = useState("");
  const [loginError, setLoginError] = useState("");

  // Register State
  const [regDisplayName, setRegDisplayName] = useState("");
  const [regUsername, setRegUsername] = useState("");
  const [regPass, setRegPass] = useState("");
  const [regConfirmPass, setRegConfirmPass] = useState("");
  const [regAvatar, setRegAvatar] = useState<string>("");
  const [regError, setRegError] = useState("");
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setLoginError("");
    const success = login(loginUsername, loginPass);
    if (!success) {
        setLoginError("Invalid username or password");
    }
  };

  const handleRegister = (e: React.FormEvent) => {
    e.preventDefault();
    setRegError("");

    if (!regDisplayName || !regUsername || !regPass) {
        setRegError("Please fill in all fields");
        return;
    }

    if (regPass !== regConfirmPass) {
        setRegError("Passwords do not match");
        return;
    }

    const success = register({
        username: regUsername,
        password: regPass,
        displayName: regDisplayName,
        avatar: regAvatar || undefined
    });

    if (!success) {
        setRegError("Username already taken");
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setRegAvatar(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="fixed inset-0 bg-background text-white z-[100] overflow-y-auto">
       <div className="absolute inset-0 bg-gradient-to-b from-huevify/40 to-black z-0 pointer-events-none fixed" />

       <div className="min-h-full flex items-center justify-center p-4">
           <div className="z-10 w-full max-w-md bg-surface p-8 rounded-xl shadow-2xl border border-surface-highlight animate-in fade-in zoom-in duration-300 relative my-4">

               <div className="flex flex-col items-center mb-8">
                    <div className="w-16 h-16 bg-huevify rounded-full flex items-center justify-center text-4xl font-bold mb-4 shadow-lg">H</div>
                    <h1 className="text-3xl font-bold tracking-tighter">Huevify</h1>
                    <p className="text-secondary mt-2 text-center">Millions of songs. Free on Huevify.</p>
               </div>

               {mode === 'LANDING' && (
                   <div className="flex flex-col gap-4">
                       <button 
                            onClick={() => setMode('LOGIN')}
                            className="w-full py-3 bg-white text-black font-bold rounded-full hover:scale-105 transition"
                       >
                           Log in
                       </button>
                       <button 
                            onClick={() => setMode('REGISTER')}
                            className="w-full py-3 bg-transparent border border-secondary text-secondary font-bold rounded-full hover:border-white hover:text-white transition"
                       >
                           Sign up free
                       </button>
                   </div>
               )}

               {mode === 'LOGIN' && (
                   <form onSubmit={handleLogin} className="flex flex-col gap-4">
                       <h2 className="text-xl font-bold text-center mb-2">Log in to Huevify</h2>
                       {loginError && <div className="bg-red-500/20 text-red-500 text-sm p-3 rounded text-center">{loginError}</div>}

                       <div className="flex flex-col gap-1">
                           <label className="text-sm font-bold">Username</label>
                           <input 
                                type="text" 
                                className="bg-background border border-secondary/30 rounded p-3 focus:border-white focus:outline-none"
                                placeholder="Username"
                                value={loginUsername}
                                onChange={e => setLoginUsername(e.target.value)}
                           />
                       </div>

                       <div className="flex flex-col gap-1">
                           <label className="text-sm font-bold">Password</label>
                           <input 
                                type="password" 
                                className="bg-background border border-secondary/30 rounded p-3 focus:border-white focus:outline-none"
                                placeholder="Password"
                                value={loginPass}
                                onChange={e => setLoginPass(e.target.value)}
                           />
                       </div>

                       <button type="submit" className="w-full py-3 bg-primary text-black font-bold rounded-full hover:scale-105 transition mt-4">Log In</button>

                       <button 
                            type="button" 
                            onClick={() => setMode('LANDING')} 
                            className="text-secondary text-sm hover:text-white mt-2"
                        >
                            Cancel
                       </button>
                   </form>
               )}

               {mode === 'REGISTER' && (
                   <form onSubmit={handleRegister} className="flex flex-col gap-4">
                       <h2 className="text-xl font-bold text-center mb-2">Sign up for free</h2>
                       {regError && <div className="bg-red-500/20 text-red-500 text-sm p-3 rounded text-center">{regError}</div>}

                       {/* Avatar Upload */}
                       <div className="flex justify-center mb-2">
                            <div 
                                onClick={() => fileInputRef.current?.click()}
                                className="w-24 h-24 rounded-full bg-surface-highlight flex items-center justify-center cursor-pointer hover:opacity-80 transition relative overflow-hidden group"
                            >
                                {regAvatar ? (
                                    <img src={regAvatar} alt="Avatar" className="w-full h-full object-cover" />
                                ) : (
                                    <Camera size={32} className="text-secondary" />
                                )}
                                <div className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition">
                                    <span className="text-[10px] font-bold">UPLOAD</span>
                                </div>
                            </div>
                            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileChange} />
                       </div>

                       <div className="flex flex-col gap-1">
                           <label className="text-sm font-bold">Display Name</label>
                           <input 
                                type="text" 
                                className="bg-background border border-secondary/30 rounded p-3 focus:border-white focus:outline-none"
                                placeholder="What should we call you?"
                                value={regDisplayName}
                                onChange={e => setRegDisplayName(e.target.value)}
                           />
                       </div>

                       <div className="flex flex-col gap-1">
                           <label className="text-sm font-bold">Username</label>
                           <input 
                                type="text" 
                                className="bg-background border border-secondary/30 rounded p-3 focus:border-white focus:outline-none"
                                placeholder="Unique username"
                                value={regUsername}
                                onChange={e => setRegUsername(e.target.value)}
                           />
                       </div>

                       <div className="flex flex-col gap-1">
                           <label className="text-sm font-bold">Password</label>
                           <input 
                                type="password" 
                                className="bg-background border border-secondary/30 rounded p-3 focus:border-white focus:outline-none"
                                placeholder="Create a password"
                                value={regPass}
                                onChange={e => setRegPass(e.target.value)}
                           />
                       </div>

                       <div className="flex flex-col gap-1">
                           <label className="text-sm font-bold">Confirm Password</label>
                           <input 
                                type="password" 
                                className="bg-background border border-secondary/30 rounded p-3 focus:border-white focus:outline-none"
                                placeholder="Enter password again"
                                value={regConfirmPass}
                                onChange={e => setRegConfirmPass(e.target.value)}
                           />
                       </div>

                       <button type="submit" className="w-full py-3 bg-primary text-black font-bold rounded-full hover:scale-105 transition mt-4">Sign Up</button>

                       <button 
                            type="button" 
                            onClick={() => setMode('LANDING')} 
                            className="text-secondary text-sm hover:text-white mt-2"
                        >
                            Cancel
                       </button>
                   </form>
               )}

           </div>
       </div>
    </div>
  );
};

export interface Track {
  id: string;
  title: string;
  artist: string;
  album: string;
  cover: string;
  duration: number; // in seconds
  url: string; // audio source
  plays: number;
  genre: string; // New field for recommendations
}

export interface Playlist {
  id: string;
  name: string;
  description?: string;
  customCover?: string; // Base64 or URL
  tracks: string[]; // array of track IDs
  isSystem?: boolean; // e.g. "Liked Songs"
  ownerId?: string; // ID of the user who created this playlist

  // New fields for Public/Private feature
  isPublic?: boolean;
  creatorName?: string;
  creatorAvatar?: string;
  savedBy?: string[]; // Array of User IDs who added this playlist to their library
}

export interface Album {
  id: string;
  title: string;
  artist: string;
  cover: string;
  trackIds: string[];
  year: number;
  recordLabel?: string;
}

export interface User {
  id: string;
  username: string;
  password: string; // Stored locally for this prototype
  displayName: string;
  avatar?: string; // Base64
}

export type ViewState = 
  | { type: 'HOME' }
  | { type: 'SEARCH' }
  | { type: 'LIBRARY' }
  | { type: 'PLAYLIST'; id: string }
  | { type: 'ALBUM'; id: string }
  | { type: 'ARTIST'; id: string }
  | { type: 'CHARTS' };

export enum PlayMode {
  OFF = 'OFF',
  CONTEXT = 'CONTEXT', // Repeat Playlist/Album
  ONE = 'ONE', // Repeat One Track
}

import React, { createContext, useContext, useEffect, useRef, useState } from 'react';
import { Track, Playlist, Album, ViewState, PlayMode, User } from '../types.ts';
import { generateInitialData, StorageService } from '../services/data.ts';

interface ArtistStats {
  monthlyPlays: number;
  globalRank: number;
}

interface StoreContextType {
  // Auth
  currentUser: User | null;
  login: (username: string, pass: string) => boolean;
  register: (user: Omit<User, 'id'>) => boolean;
  logout: () => void;

  tracks: Track[];
  albums: Album[];
  playlists: Playlist[]; // Now contains ALL playlists (system + all users' public + current user's private)
  recommendations: Track[];
  recentlyPlayed: Track[];
  followedArtists: string[];
  currentTrack: Track | null;
  isPlaying: boolean;
  playMode: PlayMode;
  isShuffle: boolean;
  volume: number;
  progress: number;
  duration: number;
  view: ViewState;

  // Modal States
  isCreatePlaylistOpen: boolean;
  setCreatePlaylistOpen: (isOpen: boolean) => void;
  playlistIdToEdit: string | null; 
  setPlaylistIdToEdit: (id: string | null) => void;

  isMobilePlayerOpen: boolean;
  setMobilePlayerOpen: (isOpen: boolean) => void;

  isAddToPlaylistOpen: boolean;
  trackIdToAdd: string | null;
  openAddToPlaylist: (trackId: string) => void;
  closeAddToPlaylist: () => void;

  isDeleteModalOpen: boolean;
  playlistToDelete: string | null;
  openDeleteModal: (id: string) => void;
  closeDeleteModal: () => void;
