  const previewCharts = allCharts.slice(0, 5);

  const getGreeting = () => {
      const hour = new Date().getHours();
      const lang = appSettings.language;

      let morning = "Good morning";
      let afternoon = "Good afternoon";
      let evening = "Good evening";

      if (lang === 'Spanish') { morning = "Buenos días"; afternoon = "Buenas tardes"; evening = "Buenas noches"; }
      if (lang === 'French') { morning = "Bonjour"; afternoon = "Bon après-midi"; evening = "Bonsoir"; }
      if (lang === 'German') { morning = "Guten Morgen"; afternoon = "Guten Tag"; evening = "Guten Abend"; }
      if (lang === 'Japanese') { morning = "おはようございます"; afternoon = "こんにちは"; evening = "こんばんは"; }

      if (hour < 12) return morning;
      if (hour < 18) return afternoon;
      return evening;
  };

  return (
    <div className="p-4 md:p-8 pb-64 w-full h-full overflow-y-auto page-enter">
      {/* Mobile Header with Avatar */}
