                          <select value={distGenre} onChange={e => setDistGenre(e.target.value)} className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none">
                              {['Pop', 'Rap/Hip-Hop', 'R&B', 'Electronic/Dance', 'Rock', 'Indie'].map(g => <option key={g} value={g}>{g}</option>)}
                          </select>
                          <input type="text" placeholder={`Label* (Default: ${currentArtist?.artistName})`} value={distLabel} onChange={e => setDistLabel(e.target.value)} className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none"/>
                      </div>
                  </div>
              )}

              {distStep === 2 && (
                  <div className="flex flex-col gap-4">
                      {distTracks.map((track, idx) => (
                          <div key={idx} className="bg-surface-highlight p-4 rounded flex items-center gap-4">
                              <span className="font-bold text-secondary">{idx + 1}</span>
                              <div className="flex-1 grid grid-cols-2 gap-4">
                                  <input type="text" placeholder="Track Title*" value={track.title} onChange={e => updateTrack(idx, 'title', e.target.value)} className="bg-background p-2 rounded text-sm"/>
                                  <input type="text" placeholder="Feat (optional)" value={track.feat || ""} onChange={e => updateTrack(idx, 'feat', e.target.value)} className="bg-background p-2 rounded text-sm"/>
                              </div>
                              <label className="flex items-center gap-2 cursor-pointer">
                                  <input type="checkbox" checked={track.explicit} onChange={e => updateTrack(idx, 'explicit', e.target.checked)} />
