              <div className="flex items-center gap-4">
                  <div className="w-16 h-16 rounded-full bg-zinc-700 overflow-hidden relative group cursor-pointer border-2 border-primary">
                      {currentArtist?.avatar ? <img src={currentArtist.avatar} className="w-full h-full object-cover"/> : <Mic2 className="text-secondary m-4"/>}
                      <div className="absolute inset-0 bg-black/50 flex items-center justify-center opacity-0 group-hover:opacity-100 transition" onClick={() => fileInputRef.current?.click()}>
