              <div 
                  onClick={() => setView('DISTRIBUTION')}
                  className="bg-primary p-6 rounded-xl border border-primary text-black cursor-pointer hover:scale-[1.02] transition flex flex-col justify-between"
              >
                  <h3 className="text-black/70 text-sm font-bold uppercase mb-2">New Release</h3>
                  <div className="flex items-center gap-2 text-2xl font-bold"><UploadCloud/> Upload</div>
              </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="bg-surface p-6 rounded-xl border border-surface-highlight">
                  <h3 className="font-bold text-xl mb-4">My Releases</h3>
                  <div className="flex flex-col gap-3">
                      {releaseRequests.filter(r => r.artistId === currentArtist?.id).length === 0 && <span className="text-secondary">No releases yet.</span>}
                      {releaseRequests.filter(r => r.artistId === currentArtist?.id).map(r => (
                          <div key={r.id} className="flex items-center gap-3 p-2 bg-surface-highlight rounded opacity-80 hover:opacity-100">
                              <img src={r.cover} className="w-10 h-10 rounded"/>
                              <div className="flex-1">
                                  <div className="font-bold truncate">{r.title}</div>
                                  <div className="text-xs text-secondary">{new Date(r.releaseDate).toLocaleDateString()}</div>
                              </div>
                              <div className={`text-[10px] font-bold px-2 py-1 rounded uppercase ${r.status === 'LIVE' ? 'bg-green-500 text-black' : r.status === 'APPROVED' ? 'bg-blue-500 text-black' : r.status === 'REJECTED' ? 'bg-red-500 text-white' : 'bg-yellow-500 text-black'}`}>
                                  {r.status}
                              </div>
                          </div>
                      ))}
                  </div>
              </div>

              <div className="bg-surface p-6 rounded-xl border border-surface-highlight">
                  <h3 className="font-bold text-xl mb-4">Artist's Pick</h3>
                  <p className="text-sm text-secondary mb-4">Highlight a track or album on your profile.</p>
                  <button className="w-full py-2 border border-secondary text-secondary rounded hover:text-white hover:border-white">Select Content (Coming Soon)</button>
              </div>
          </div>

      </div>
      );
  };


  return (
    <div className="fixed inset-0 bg-black z-[200] flex items-center justify-center animate-in fade-in duration-200">
        <button 
          onClick={() => setArtistHubOpen(false)} 
          className="absolute top-4 right-4 text-secondary hover:text-white z-50"
        >
          <X size={32} />
        </button>

        {view === 'AUTH' && renderAuth()}
        {view === 'MOD_DASH' && renderModDash()}
        {view === 'ARTIST_DASH' && renderArtistDash()}
        {view === 'DISTRIBUTION' && renderDistributionWizard()}
    </div>
  );
};

