import { Sidebar } from './components/Sidebar.tsx';
import { Player } from './components/Player.tsx';
import { MobileNav } from './components/MobileNav.tsx';
import { FullScreenPlayer } from './components/FullScreenPlayer.tsx';
import { CreatePlaylistModal } from './components/CreatePlaylistModal.tsx';
import { AddToPlaylistModal } from './components/AddToPlaylistModal.tsx';
import { DeletePlaylistModal } from './components/DeletePlaylistModal.tsx';
import { ProfileModal } from './components/ProfileModal.tsx';
import { ArtistHub } from './components/ArtistHub.tsx';
import { Auth } from './components/Auth.tsx';
import { Home } from './pages/Home.tsx';
import { Search } from './pages/Search.tsx';
import { Library } from './pages/Library.tsx';

const MainView = () => {
  const { view } = useStore();

  const renderContent = () => {
    switch (view.type) {
      case 'HOME': return <Home />;
      case 'SEARCH': return <Search />;
      case 'LIBRARY': return <Library />;
      case 'PLAYLIST': return <Library />;
      case 'ALBUM': return <Library />;
      case 'ARTIST': return <Library />;
      case 'CHARTS': return <Library />;
      default: return <Home />;
    }
  };

  return (
    <div className="flex-1 flex flex-col bg-background min-h-0 overflow-hidden relative">
      {renderContent()}
    </div>
  );
};

const AppContent = () => {
    const { currentUser } = useStore();

    if (!currentUser) {
        return <Auth />;
    }

    return (
        <div className="flex h-screen w-full bg-black text-white font-sans overflow-hidden">
        <Sidebar />
        <main className="flex-1 flex flex-col h-full overflow-hidden relative">
           <div className="h-16 w-full absolute top-0 left-0 bg-gradient-to-b from-black/20 to-transparent z-20 pointer-events-none" />
           <MainView />
           <MobileNav />
           <Player />
           <FullScreenPlayer />
           <CreatePlaylistModal />
           <AddToPlaylistModal />
           <DeletePlaylistModal />
           <ProfileModal />
           <ArtistHub />
        </main>
      </div>
    );
};

export default function App() {
  return (
    <StoreProvider>
      <AppContent />
    </StoreProvider>
  );
}

import React, { useState, useRef } from 'react';
import { useStore } from '../context/StoreContext.tsx';
import { 
  X, Mic2, Shield, User, UploadCloud, Calendar, FileAudio, 
  CheckCircle, XCircle, Clock, MoreVertical, Image, Plus,
  Edit, ArrowLeft, Camera
} from './Icons.tsx';
import { DistributionTrack } from '../types.ts';

type HubView = 'AUTH' | 'ARTIST_DASH' | 'MOD_DASH' | 'DISTRIBUTION';

export const ArtistHub = () => {
  const { 
    isArtistHubOpen, setArtistHubOpen, currentArtist, currentModerator, 
    loginArtistOrMod, registerArtist, logoutArtistHub, artistAccounts,
    releaseRequests, profileEditRequests, approveArtist, rejectArtist,
    approveRelease, rejectRelease, approveProfileEdit, rejectProfileEdit,
    submitRelease, getArtistStats, submitProfileEdit
  } = useStore();

  const [view, setView] = useState<HubView>('AUTH');

  // Auth State
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [role, setRole] = useState<'ARTIST' | 'MODERATOR'>('ARTIST');
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [artistName, setArtistName] = useState("");
  const [message, setMessage] = useState("");

  // Distribution State
  const [distStep, setDistStep] = useState(1);
  const [distTitle, setDistTitle] = useState("");
  const [distGenre, setDistGenre] = useState("Pop");
  const [distLabel, setDistLabel] = useState("");
  const [distCover, setDistCover] = useState<string>("");
  const [distTracks, setDistTracks] = useState<DistributionTrack[]>([]);
  const [distDate, setDistDate] = useState("");
  const [distTime, setDistTime] = useState("00:00");
  const [distMsg, setDistMsg] = useState("");

  // Profile Edit State
  const [isEditProfileOpen, setEditProfileOpen] = useState(false);
  const [peAvatar, setPeAvatar] = useState("");
  const fileInputRef = useRef<HTMLInputElement>(null);
  const coverInputRef = useRef<HTMLInputElement>(null);

  if (!isArtistHubOpen) return null;

  const handleLogin = (e: React.FormEvent) => {
      e.preventDefault();
      setMessage("");
      const res = loginArtistOrMod(username, password, role);
      if (res.success) {
          if (role === 'ARTIST') setView('ARTIST_DASH');
          else setView('MOD_DASH');
      } else {
          setMessage(res.message || "Login failed");
      }
  };

  const handleRegister = (e: React.FormEvent) => {
      e.preventDefault();
      if (role === 'MODERATOR') {
          // Should normally allow only one, but logic in store checks creds.
          // Registration for mod is technically disabled in prompt logic (only 1 mod exists).
          // But if user insists... 
          setMessage("Moderator registration is closed. Contact admin.");
          return;
      }

      const res = registerArtist({
          artistName, username, password,
          artistPick: undefined
      });

      if (res.success) {
          setMessage("Registration sent for approval.");
          setAuthMode('LOGIN');
      } else {
          setMessage(res.message || "Error registering");
      }
  };

  // --- Distribution Handlers ---
  const handleAddTrack = () => {
      setDistTracks([...distTracks, { title: "", explicit: false, feat: "", duration: 180, fileUrl: "https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3" }]);
  };

  const updateTrack = (idx: number, field: keyof DistributionTrack, val: any) => {
      const newTracks = [...distTracks];
      newTracks[idx] = { ...newTracks[idx], [field]: val };
      setDistTracks(newTracks);
  };

  const handleSubmitRelease = () => {
      if (!distTitle || !distCover || distTracks.length === 0 || !distDate) {
          alert("Please fill all required fields");
          return;
      }

      const dateTime = new Date(`${distDate}T${distTime}`);

      submitRelease({
          title: distTitle,
          genre: distGenre,
          label: distLabel || (currentArtist?.artistName || ""),
          cover: distCover,
          tracks: distTracks,
          releaseDate: dateTime.toISOString(),
          releaseMessage: distMsg
      });

      alert("Release submitted for approval!");
      setView('ARTIST_DASH');
      // Reset
      setDistStep(1); setDistTitle(""); setDistTracks([]); setDistCover("");
  };

  const handleCoverUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onloadend = () => setDistCover(reader.result as string);
          reader.readAsDataURL(file);
      }
  };

  // --- RENDERERS ---

  const renderAuth = () => (
      <div className="w-full max-w-md bg-surface p-8 rounded-xl shadow-2xl border border-surface-highlight">
          <div className="flex justify-center mb-6">
              <div className="w-16 h-16 bg-primary/20 rounded-full flex items-center justify-center">
                  {role === 'ARTIST' ? <Mic2 size={32} className="text-primary" /> : <Shield size={32} className="text-primary" />}
              </div>
          </div>
          <h2 className="text-2xl font-bold text-center mb-6">{authMode === 'LOGIN' ? 'Log in to' : 'Join'} Huevify For {role === 'ARTIST' ? 'Artists' : 'Moderators'}</h2>

          <div className="flex bg-surface-highlight p-1 rounded-full mb-6">
              <button 
                  onClick={() => setRole('ARTIST')} 
                  className={`flex-1 py-2 rounded-full text-sm font-bold transition ${role === 'ARTIST' ? 'bg-primary text-black' : 'text-secondary hover:text-white'}`}
              >
                  Artist
              </button>
              <button 
                  onClick={() => setRole('MODERATOR')}
                  className={`flex-1 py-2 rounded-full text-sm font-bold transition ${role === 'MODERATOR' ? 'bg-primary text-black' : 'text-secondary hover:text-white'}`}
              >
                  Moderator
              </button>
          </div>

          {message && <div className="bg-red-500/20 text-red-500 p-3 rounded mb-4 text-center text-sm">{message}</div>}

          <form onSubmit={authMode === 'LOGIN' ? handleLogin : handleRegister} className="flex flex-col gap-4">
              {authMode === 'REGISTER' && role === 'ARTIST' && (
                  <input 
                      type="text" placeholder="Artist Name" value={artistName} onChange={e => setArtistName(e.target.value)}
                      className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none"
                  />
              )}
              <input 
                  type="text" placeholder="Username" value={username} onChange={e => setUsername(e.target.value)}
                  className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none"
              />
              <input 
                  type="password" placeholder="Password" value={password} onChange={e => setPassword(e.target.value)}
                  className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none"
              />

              <button type="submit" className="bg-primary text-black font-bold py-3 rounded-full hover:scale-105 transition mt-2">
                  {authMode === 'LOGIN' ? 'Log In' : 'Submit Application'}
              </button>
          </form>

          <p className="text-center text-secondary text-sm mt-4">
              {authMode === 'LOGIN' ? "Don't have an account?" : "Already have an account?"} 
              <button onClick={() => { setAuthMode(authMode === 'LOGIN' ? 'REGISTER' : 'LOGIN'); setMessage(""); }} className="text-white font-bold ml-1 hover:underline">
                  {authMode === 'LOGIN' ? 'Sign up' : 'Log in'}
              </button>
          </p>
      </div>
  );

  const renderModDash = () => (
      <div className="w-full h-full flex flex-col p-6">
          <div className="flex justify-between items-center mb-8">
              <h1 className="text-3xl font-bold flex items-center gap-3"><Shield className="text-primary"/> Moderator Dashboard</h1>
              <button onClick={() => { logoutArtistHub(); setView('AUTH'); }} className="text-secondary hover:text-white">Log Out</button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 h-full overflow-hidden">
              {/* Artist Requests */}
              <div className="bg-surface rounded-xl p-4 flex flex-col overflow-hidden border border-surface-highlight">
                  <h3 className="font-bold mb-4 flex items-center gap-2 text-primary"><User size={18}/> Pending Artists</h3>
                  <div className="overflow-y-auto flex-1 flex flex-col gap-3">
                      {artistAccounts.filter(a => a.status === 'PENDING').length === 0 && <span className="text-secondary text-sm">No pending requests</span>}
                      {artistAccounts.filter(a => a.status === 'PENDING').map(a => (
                          <div key={a.id} className="p-3 bg-surface-highlight rounded flex justify-between items-center">
                              <div>
                                  <div className="font-bold">{a.artistName}</div>
                                  <div className="text-xs text-secondary">@{a.username}</div>
                              </div>
                              <div className="flex gap-2">
                                  <button onClick={() => approveArtist(a.id)} className="text-green-500 hover:scale-110"><CheckCircle size={20}/></button>
                                  <button onClick={() => rejectArtist(a.id)} className="text-red-500 hover:scale-110"><XCircle size={20}/></button>
                              </div>
                          </div>
                      ))}
                  </div>
              </div>

              {/* Release Requests */}
              <div className="bg-surface rounded-xl p-4 flex flex-col overflow-hidden border border-surface-highlight">
                  <h3 className="font-bold mb-4 flex items-center gap-2 text-primary"><UploadCloud size={18}/> Pending Releases</h3>
                  <div className="overflow-y-auto flex-1 flex flex-col gap-3">
                      {releaseRequests.filter(r => r.status === 'PENDING').length === 0 && <span className="text-secondary text-sm">No pending releases</span>}
                      {releaseRequests.filter(r => r.status === 'PENDING').map(r => (
                          <div key={r.id} className="p-3 bg-surface-highlight rounded flex flex-col gap-2">
                              <div className="flex items-center gap-3">
                                  <img src={r.cover} className="w-10 h-10 rounded" alt=""/>
                                  <div className="flex-1 overflow-hidden">
                                      <div className="font-bold truncate">{r.title}</div>
                                      <div className="text-xs text-secondary">{r.artistName} • {r.tracks.length} tracks</div>
                                  </div>
                              </div>
                              <div className="text-xs text-secondary bg-black/20 p-2 rounded">
                                  Msg: {r.releaseMessage || "None"} <br/>
                                  Date: {new Date(r.releaseDate).toLocaleString()}
                              </div>
                              <div className="flex gap-2 justify-end">
                                  <button onClick={() => approveRelease(r.id)} className="text-green-500 hover:text-white text-xs font-bold uppercase border border-green-500 px-2 py-1 rounded hover:bg-green-500 transition">Approve</button>
                                  <button onClick={() => rejectRelease(r.id)} className="text-red-500 hover:text-white text-xs font-bold uppercase border border-red-500 px-2 py-1 rounded hover:bg-red-500 transition">Reject</button>
                              </div>
                          </div>
                      ))}
                  </div>
              </div>

              {/* Profile Edits */}
              <div className="bg-surface rounded-xl p-4 flex flex-col overflow-hidden border border-surface-highlight">
                  <h3 className="font-bold mb-4 flex items-center gap-2 text-primary"><Edit size={18}/> Profile Edits</h3>
                  <div className="overflow-y-auto flex-1 flex flex-col gap-3">
                      {profileEditRequests.filter(r => r.status === 'PENDING').length === 0 && <span className="text-secondary text-sm">No pending edits</span>}
                      {profileEditRequests.filter(r => r.status === 'PENDING').map(r => (
                          <div key={r.id} className="p-3 bg-surface-highlight rounded flex flex-col gap-2">
                               <div className="font-bold text-sm">{r.artistName} wants to update profile</div>
                               {r.newAvatar && (
                                   <div className="flex items-center gap-2">
                                       <img src={r.newAvatar} className="w-8 h-8 rounded-full" />
                                       <span className="text-xs text-secondary">New Avatar</span>
                                   </div>
                               )}
                               {r.newArtistPick && (
                                   <div className="text-xs text-secondary">New Artist Pick updated</div>
                               )}
                               <div className="flex gap-2 justify-end">
                                  <button onClick={() => approveProfileEdit(r.id)} className="text-green-500 hover:text-white text-xs font-bold uppercase border border-green-500 px-2 py-1 rounded hover:bg-green-500 transition">Approve</button>
                                  <button onClick={() => rejectProfileEdit(r.id)} className="text-red-500 hover:text-white text-xs font-bold uppercase border border-red-500 px-2 py-1 rounded hover:bg-red-500 transition">Reject</button>
                              </div>
                          </div>
                      ))}
                  </div>
              </div>

          </div>
      </div>
  );

  const renderDistributionWizard = () => (
      <div className="w-full h-full flex flex-col p-6 max-w-4xl mx-auto">
          <div className="flex items-center gap-4 mb-6">
              <button onClick={() => setView('ARTIST_DASH')} className="text-secondary hover:text-white"><ArrowLeft/></button>
              <h1 className="text-3xl font-bold">Upload Release</h1>
          </div>

          <div className="flex items-center justify-between mb-8 px-8">
              <div className={`flex flex-col items-center ${distStep >= 1 ? 'text-primary' : 'text-secondary'}`}>
                  <div className={`w-8 h-8 rounded-full border-2 flex items-center justify-center font-bold mb-2 ${distStep >= 1 ? 'border-primary bg-primary text-black' : 'border-secondary'}`}>1</div>
                  <span className="text-xs font-bold uppercase">Basic Info</span>
              </div>
              <div className={`h-1 flex-1 mx-4 ${distStep >= 2 ? 'bg-primary' : 'bg-surface-highlight'}`} />
              <div className={`flex flex-col items-center ${distStep >= 2 ? 'text-primary' : 'text-secondary'}`}>
                  <div className={`w-8 h-8 rounded-full border-2 flex items-center justify-center font-bold mb-2 ${distStep >= 2 ? 'border-primary bg-primary text-black' : 'border-secondary'}`}>2</div>
                  <span className="text-xs font-bold uppercase">Tracklist</span>
              </div>
              <div className={`h-1 flex-1 mx-4 ${distStep >= 3 ? 'bg-primary' : 'bg-surface-highlight'}`} />
              <div className={`flex flex-col items-center ${distStep >= 3 ? 'text-primary' : 'text-secondary'}`}>
                  <div className={`w-8 h-8 rounded-full border-2 flex items-center justify-center font-bold mb-2 ${distStep >= 3 ? 'border-primary bg-primary text-black' : 'border-secondary'}`}>3</div>
                  <span className="text-xs font-bold uppercase">Schedule</span>
              </div>
          </div>

          <div className="flex-1 overflow-y-auto bg-surface rounded-xl p-8 border border-surface-highlight mb-6">
              {distStep === 1 && (
                  <div className="flex flex-col md:flex-row gap-8">
                      <div className="flex flex-col items-center">
                          <div 
                             onClick={() => coverInputRef.current?.click()}
                             className="w-48 h-48 bg-surface-highlight rounded shadow-inner flex items-center justify-center cursor-pointer hover:bg-zinc-800 transition relative overflow-hidden group border-2 border-dashed border-secondary"
                          >
                              {distCover ? <img src={distCover} className="w-full h-full object-cover"/> : <div className="text-center p-4"><Image size={32} className="mx-auto mb-2 text-secondary"/> <span className="text-xs text-secondary">Upload Cover*</span></div>}
                          </div>
                          <input type="file" ref={coverInputRef} className="hidden" accept="image/*" onChange={handleCoverUpload} />
                      </div>
                      <div className="flex-1 flex flex-col gap-4">
                          <input type="text" placeholder="Release Title*" value={distTitle} onChange={e => setDistTitle(e.target.value)} className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none"/>
                          <select value={distGenre} onChange={e => setDistGenre(e.target.value)} className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none">
                              {['Pop', 'Rap/Hip-Hop', 'R&B', 'Electronic/Dance', 'Rock', 'Indie'].map(g => <option key={g} value={g}>{g}</option>)}
                          </select>
                          <input type="text" placeholder={`Label* (Default: ${currentArtist?.artistName})`} value={distLabel} onChange={e => setDistLabel(e.target.value)} className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none"/>
                      </div>
                  </div>
              )}

              {distStep === 2 && (
                  <div className="flex flex-col gap-4">
                      {distTracks.map((track, idx) => (
                          <div key={idx} className="bg-surface-highlight p-4 rounded flex items-center gap-4">
                              <span className="font-bold text-secondary">{idx + 1}</span>
                              <div className="flex-1 grid grid-cols-2 gap-4">
                                  <input type="text" placeholder="Track Title*" value={track.title} onChange={e => updateTrack(idx, 'title', e.target.value)} className="bg-background p-2 rounded text-sm"/>
                                  <input type="text" placeholder="Feat (optional)" value={track.feat || ""} onChange={e => updateTrack(idx, 'feat', e.target.value)} className="bg-background p-2 rounded text-sm"/>
                              </div>
                              <label className="flex items-center gap-2 cursor-pointer">
                                  <input type="checkbox" checked={track.explicit} onChange={e => updateTrack(idx, 'explicit', e.target.checked)} />
                                  <span className="text-xs uppercase font-bold text-secondary">Explicit</span>
                              </label>
                              <button onClick={() => setDistTracks(distTracks.filter((_, i) => i !== idx))} className="text-red-500"><XCircle/></button>
                          </div>
                      ))}
                      <button onClick={handleAddTrack} className="py-3 border-2 border-dashed border-secondary rounded text-secondary hover:text-white hover:border-white font-bold transition flex items-center justify-center gap-2">
                          <Plus size={20}/> Add Track
                      </button>
                  </div>
              )}

              {distStep === 3 && (
                  <div className="flex flex-col gap-6 max-w-md mx-auto">
                      <div className="flex flex-col gap-2">
                          <label className="font-bold text-sm uppercase text-secondary">Release Date*</label>
                          <input type="date" value={distDate} onChange={e => setDistDate(e.target.value)} className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none text-white"/>
                      </div>
                      <div className="flex flex-col gap-2">
                          <label className="font-bold text-sm uppercase text-secondary">Release Time*</label>
                          <input type="time" value={distTime} onChange={e => setDistTime(e.target.value)} className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none text-white"/>
                      </div>
                      <div className="flex flex-col gap-2">
                          <label className="font-bold text-sm uppercase text-secondary">Message to Moderator</label>
                          <textarea value={distMsg} onChange={e => setDistMsg(e.target.value)} className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none h-24 resize-none"/>
                      </div>
                  </div>
              )}
          </div>

          <div className="flex justify-between">
              {distStep > 1 ? <button onClick={() => setDistStep(distStep - 1)} className="px-6 py-3 rounded-full font-bold text-white hover:bg-surface-highlight">Back</button> : <div></div>}
              {distStep < 3 ? (
                  <button onClick={() => setDistStep(distStep + 1)} className="px-6 py-3 rounded-full bg-white text-black font-bold hover:scale-105 transition">Next</button>
              ) : (
                  <button onClick={handleSubmitRelease} className="px-6 py-3 rounded-full bg-primary text-black font-bold hover:scale-105 transition">Submit Release</button>
              )}
          </div>
      </div>
  );

  const renderArtistDash = () => {
      const stats = currentArtist ? getArtistStats(currentArtist.artistName) : { monthlyPlays: 0, globalRank: 0 };

      const handleAvatarChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
          const reader = new FileReader();
          reader.onloadend = () => {
             // Submit profile edit request
             submitProfileEdit({ newAvatar: reader.result as string });
             alert("Profile photo update sent to moderation");
          };
          reader.readAsDataURL(file);
        }
      };

      return (
      <div className="w-full h-full flex flex-col p-6 overflow-y-auto">
          <div className="flex justify-between items-center mb-8">
              <div className="flex items-center gap-4">
                  <div className="w-16 h-16 rounded-full bg-zinc-700 overflow-hidden relative group cursor-pointer border-2 border-primary">
                      {currentArtist?.avatar ? <img src={currentArtist.avatar} className="w-full h-full object-cover"/> : <Mic2 className="text-secondary m-4"/>}
                      <div className="absolute inset-0 bg-black/50 flex items-center justify-center opacity-0 group-hover:opacity-100 transition" onClick={() => fileInputRef.current?.click()}>
                          <Camera className="text-white"/>
                      </div>
                      <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleAvatarChange} />
                  </div>
                  <div>
                      <h1 className="text-3xl font-bold">{currentArtist?.artistName}</h1>
                      <div className="flex gap-2 text-sm text-secondary">
                          <span className="bg-primary/20 text-primary px-2 py-0.5 rounded-full font-bold text-xs">VERIFIED ARTIST</span>
                      </div>
                  </div>
              </div>
              <button onClick={() => { logoutArtistHub(); setView('AUTH'); }} className="text-secondary hover:text-white">Log Out</button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
              <div className="bg-surface p-6 rounded-xl border border-surface-highlight">
                  <h3 className="text-secondary text-sm font-bold uppercase mb-2">Monthly Listeners</h3>
                  <div className="text-4xl font-bold">{stats.monthlyPlays.toLocaleString()}</div>
              </div>
              <div className="bg-surface p-6 rounded-xl border border-surface-highlight">
                  <h3 className="text-secondary text-sm font-bold uppercase mb-2">Global Rank</h3>
                  <div className="text-4xl font-bold">#{stats.globalRank}</div>
              </div>
              <div 
                  onClick={() => setView('DISTRIBUTION')}
                  className="bg-primary p-6 rounded-xl border border-primary text-black cursor-pointer hover:scale-[1.02] transition flex flex-col justify-between"
              >
                  <h3 className="text-black/70 text-sm font-bold uppercase mb-2">New Release</h3>
                  <div className="flex items-center gap-2 text-2xl font-bold"><UploadCloud/> Upload</div>
              </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="bg-surface p-6 rounded-xl border border-surface-highlight">
                  <h3 className="font-bold text-xl mb-4">My Releases</h3>
                  <div className="flex flex-col gap-3">
                      {releaseRequests.filter(r => r.artistId === currentArtist?.id).length === 0 && <span className="text-secondary">No releases yet.</span>}
                      {releaseRequests.filter(r => r.artistId === currentArtist?.id).map(r => (
                          <div key={r.id} className="flex items-center gap-3 p-2 bg-surface-highlight rounded opacity-80 hover:opacity-100">
                              <img src={r.cover} className="w-10 h-10 rounded"/>
                              <div className="flex-1">
                                  <div className="font-bold truncate">{r.title}</div>
                                  <div className="text-xs text-secondary">{new Date(r.releaseDate).toLocaleDateString()}</div>
                              </div>
                              <div className={`text-[10px] font-bold px-2 py-1 rounded uppercase ${r.status === 'LIVE' ? 'bg-green-500 text-black' : r.status === 'APPROVED' ? 'bg-blue-500 text-black' : r.status === 'REJECTED' ? 'bg-red-500 text-white' : 'bg-yellow-500 text-black'}`}>
                                  {r.status}
                              </div>
                          </div>
                      ))}
                  </div>
              </div>

              <div className="bg-surface p-6 rounded-xl border border-surface-highlight">
                  <h3 className="font-bold text-xl mb-4">Artist's Pick</h3>
                  <p className="text-sm text-secondary mb-4">Highlight a track or album on your profile.</p>
                  <button className="w-full py-2 border border-secondary text-secondary rounded hover:text-white hover:border-white">Select Content (Coming Soon)</button>
              </div>
          </div>

      </div>
      );
  };


  return (
    <div className="fixed inset-0 bg-black z-[200] flex items-center justify-center animate-in fade-in duration-200">
        <button 
          onClick={() => setArtistHubOpen(false)} 
          className="absolute top-4 right-4 text-secondary hover:text-white z-50"
        >
          <X size={32} />
        </button>

        {view === 'AUTH' && renderAuth()}
        {view === 'MOD_DASH' && renderModDash()}
        {view === 'ARTIST_DASH' && renderArtistDash()}
        {view === 'DISTRIBUTION' && renderDistributionWizard()}
    </div>
  );
};

export interface Track {
  id: string;
  title: string;
  artist: string;
  album: string;
  cover: string; // Keep for track display consistency, usually points to active album cover
  duration: number; // in seconds
  url: string; // audio source
  plays: number;
  genre: string; // New field for recommendations
  explicit?: boolean;
  feat?: string;
}

export interface DailyChartTrack extends Track {
  dailyPlays: number;
}

export interface Playlist {
  id: string;
  name: string;
  description?: string;
  customCover?: string; // Base64 or URL
  tracks: string[]; // array of track IDs
  isSystem?: boolean; // e.g. "Liked Songs"
  ownerId?: string; // ID of the user who created this playlist

  // New fields for Public/Private feature
  isPublic?: boolean;
  creatorName?: string;
  creatorAvatar?: string;
  savedBy?: string[]; // Array of User IDs who added this playlist to their library
}

export interface Album {
  id: string;
  title: string;
  artist: string;
  covers: string[]; // Changed from single cover to array
  trackIds: string[];
  year: number;
  recordLabel?: string;
}

export interface User {
  id: string;
  username: string;
  password: string; // Stored locally for this prototype
  displayName: string;
  avatar?: string; // Base64
}

export interface AppSettings {
  accentColor: string;
  language: 'English' | 'Russian';
  highQualityAudio: boolean;
  autoPlay: boolean;
  crossfade: number; // seconds
  albumCoverIndexes: Record<string, number>; // Stores user preference for album covers
}

export type ViewState = 
  | { type: 'HOME' }
  | { type: 'SEARCH' }
  | { type: 'LIBRARY' }
  | { type: 'PLAYLIST'; id: string }
  | { type: 'ALBUM'; id: string }
  | { type: 'ARTIST'; id: string }
  | { type: 'CHARTS' };

export enum PlayMode {
  OFF = 'OFF',
  CONTEXT = 'CONTEXT', // Repeat Playlist/Album
  ONE = 'ONE', // Repeat One Track
}

// --- ARTIST HUB TYPES ---

export type ArtistVerificationStatus = 'PENDING' | 'APPROVED' | 'REJECTED';

export interface ArtistAccount {
  id: string; // Unique ID for the account
  artistName: string; // Displays as the Artist Name in app
  username: string; // Login username
  password: string; 
  avatar?: string;
  status: ArtistVerificationStatus;
  artistPick?: {
    type: 'TRACK' | 'ALBUM' | 'PLAYLIST';
    id: string;
    image?: string;
    subtitle?: string;
  };
}

export interface ModeratorAccount {
  username: string;
  password: string;
}

export interface DistributionTrack {
  title: string;
  explicit: boolean;
  feat?: string;
  fileUrl: string; // Mocked for prototype
  duration: number;
}

export type ReleaseType = 'Single' | 'Album' | 'EP' | 'Mixtape';

export interface ReleaseRequest {
  id: string;
  artistId: string;
  artistName: string;
  status: 'PENDING' | 'APPROVED' | 'REJECTED' | 'LIVE';

  // Info
  title: string;
  type: ReleaseType;
  genre: string;
  label: string;
  cover: string;

  // Tracks
  tracks: DistributionTrack[];

  // Schedule
  releaseDate: string; // ISO String
  releaseMessage?: string;
}

export interface ProfileEditRequest {
  id: string;
  artistId: string;
  artistName: string;
  newAvatar?: string;
  newArtistPick?: ArtistAccount['artistPick'];
  status: 'PENDING' | 'APPROVED' | 'REJECTED';
}

import React, { createContext, useContext, useEffect, useRef, useState } from 'react';
import { Track, Playlist, Album, ViewState, PlayMode, User, AppSettings, DailyChartTrack, ArtistAccount, ReleaseRequest, ProfileEditRequest, ModeratorAccount } from '../types.ts';
import { generateInitialData, StorageService } from '../services/data.ts';

interface ArtistStats {
