      if (!album || !album.covers || album.covers.length === 0) return "";
      const index = appSettings.albumCoverIndexes[albumId] || 0;
      return album.covers[index] || album.covers[0];
  };

  const changeAlbumCover = (albumId: string, direction: 'next' | 'prev') => {
      const album = albums.find(a => a.id === albumId);
      if (!album) return;

      const currentIndex = appSettings.albumCoverIndexes[albumId] || 0;
      const total = album.covers.length;
      let newIndex = direction === 'next' ? currentIndex + 1 : currentIndex - 1;

      if (newIndex >= total) newIndex = 0;
      if (newIndex < 0) newIndex = total - 1;

      updateSettings({
          albumCoverIndexes: {
              ...appSettings.albumCoverIndexes,
              [albumId]: newIndex
          }
      });
  };

