import React, { useState, useRef, useEffect } from 'react';
import { useStore } from '../context/StoreContext.tsx';
import { 
  X, Mic2, Shield, User, UploadCloud, Calendar, FileAudio, 
  CheckCircle, XCircle, Clock, MoreVertical, Image, Plus,
  Edit, ArrowLeft, Camera, LogOut, ChevronDown, Trash2, ListMusic, Check
} from './Icons.tsx';
import { DistributionTrack, ReleaseType, ReleaseRequest } from '../types.ts';

type HubView = 'AUTH' | 'ARTIST_DASH' | 'MOD_DASH' | 'DISTRIBUTION' | 'PROFILE_EDIT' | 'ARTIST_PICK';

export const ArtistHub = () => {
  const { 
    isArtistHubOpen, setArtistHubOpen, currentArtist, currentModerator, 
    loginArtistOrMod, registerArtist, registerModerator, logoutArtistHub, artistAccounts,
    releaseRequests, profileEditRequests, approveArtist, rejectArtist,
    approveRelease, rejectRelease, approveProfileEdit, rejectProfileEdit,
    submitRelease, getArtistStats, submitProfileEdit, hasModerator, existingArtists,
    deleteRelease, getTrackByHueq
  } = useStore();

  const [view, setView] = useState<HubView>('AUTH');

  // Auth State
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [role, setRole] = useState<'ARTIST' | 'MODERATOR'>('ARTIST');
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");

  // Artist Registration Logic
  const [artistNameSelection, setArtistNameSelection] = useState("");
  const [isCreatingNewArtist, setIsCreatingNewArtist] = useState(false);
  const [newArtistAlias, setNewArtistAlias] = useState("");

  const [message, setMessage] = useState("");

  // Distribution State
  const [distStep, setDistStep] = useState(1);
  const [distTitle, setDistTitle] = useState("");
  const [distType, setDistType] = useState<ReleaseType>('Single');
  const [distGenre, setDistGenre] = useState("Pop");
  const [distLabel, setDistLabel] = useState("");
  const [distCovers, setDistCovers] = useState<string[]>([]);
  const [distMainArtists, setDistMainArtists] = useState<string[]>([]);
  const [distMainArtistInput, setDistMainArtistInput] = useState("");
  const [distTracks, setDistTracks] = useState<DistributionTrack[]>([]);
  const [distDate, setDistDate] = useState("");
  const [distTime, setDistTime] = useState("00:00");
  const [distMsg, setDistMsg] = useState("");

  // Edit Profile State
  const [editBio, setEditBio] = useState("");

  // Release Detail Modal State
  const [selectedRelease, setSelectedRelease] = useState<ReleaseRequest | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const coverInputRef = useRef<HTMLInputElement>(null);
  const trackInputRef = useRef<HTMLInputElement>(null);

  if (!isArtistHubOpen) return null;

  const handleLogin = (e: React.FormEvent) => {
      e.preventDefault();
      setMessage("");
      const res = loginArtistOrMod(username, password, role);
      if (res.success) {
          if (role === 'ARTIST') {
              setView('ARTIST_DASH');
              setEditBio(currentArtist?.bio || "");
          }
          else setView('MOD_DASH');
      } else {
          setMessage(res.message || "Login failed");
      }
  };

  const handleRegister = (e: React.FormEvent) => {
      e.preventDefault();

      if (role === 'MODERATOR') {
          if (hasModerator) {
              setMessage("Moderator registration is closed.");
              return;
          }
          const res = registerModerator({ username, password });
          if (res.success) {
              setMessage("Moderator registered! Please login.");
              setAuthMode('LOGIN');
          } else {
              setMessage(res.message || "Error registering moderator");
          }
          return;
      }

      // Artist Registration
      const finalArtistName = isCreatingNewArtist ? newArtistAlias : artistNameSelection;

      if (!finalArtistName) {
          setMessage("Please select or enter an artist name.");
          return;
      }

      const res = registerArtist({
          artistName: finalArtistName, 
          username, 
          password,
          artistPick: undefined
      });

      if (res.success) {
          setMessage("Registration sent for approval.");
          setAuthMode('LOGIN');
      } else {
          setMessage(res.message || "Error registering");
      }
  };

  // --- Distribution Handlers ---
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const objectUrl = URL.createObjectURL(file);
          const newTrack: DistributionTrack = {
              title: file.name.replace(/\.[^/.]+$/, ""),
              explicit: false,
              feat: "",
              mainArtists: [],
              duration: 180,
              fileUrl: objectUrl
          };
          setDistTracks([...distTracks, newTrack]);
      }
  };

  const updateTrack = (idx: number, field: keyof DistributionTrack, val: any) => {
      const newTracks = [...distTracks];
      newTracks[idx] = { ...newTracks[idx], [field]: val };
      setDistTracks(newTracks);
  };

  const addTrackMainArtist = (idx: number, artist: string) => {
      if(!artist) return;
      const newTracks = [...distTracks];
      const current = newTracks[idx].mainArtists || [];
      if(!current.includes(artist)) {
          newTracks[idx] = { ...newTracks[idx], mainArtists: [...current, artist] };
          setDistTracks(newTracks);
      }
  };

  const removeTrackMainArtist = (trackIdx: number, artistIdx: number) => {
      const newTracks = [...distTracks];
      const current = newTracks[trackIdx].mainArtists || [];
      newTracks[trackIdx].mainArtists = current.filter((_, i) => i !== artistIdx);
      setDistTracks(newTracks);
  };

  const handleHueqBlur = (idx: number, hueq: string) => {
      if (!hueq) return;
      const existing = getTrackByHueq(hueq);
      if (existing) {
          // Auto-fill metadata
          updateTrack(idx, 'title', existing.title);
          updateTrack(idx, 'explicit', existing.explicit || false);
          updateTrack(idx, 'feat', existing.feat || "");
          updateTrack(idx, 'existingHueq', hueq);
          updateTrack(idx, 'fileUrl', existing.url); // Use existing URL
          alert(`HUEQ Found! Track details auto-filled: ${existing.title}`);
      } else {
          // Keep the HUEQ user typed, but don't autofill if not found.
          updateTrack(idx, 'existingHueq', hueq);
      }
  };

  const handleNextStep = () => {
      if (distStep === 1) {
          if (!distTitle || !distType || !distGenre || distCovers.length === 0) {
              alert("Please complete all required fields (Title, Type, Genre, Covers) marked with *");
              return;
          }
      }
      if (distStep === 2) {
          if (distTracks.length === 0) {
              alert("Please add at least one track.");
              return;
          }
      }
      setDistStep(prev => prev + 1);
  };

  const handleCancelRelease = () => {
      if (confirm("Are you sure you want to cancel? All progress will be lost.")) {
          setDistStep(1); setDistTitle(""); setDistTracks([]); setDistCovers([]); setDistMsg(""); setDistMainArtists([]);
          setView('ARTIST_DASH');
      }
  };

  const handleSubmitRelease = () => {
      if (!distDate || !distTime) {
          alert("Please specify Release Date and Time.");
          return;
      }

      const dateTime = new Date(`${distDate}T${distTime}:00+03:00`);

      submitRelease({
          title: distTitle,
          type: distType,
          genre: distGenre,
          label: distLabel || (currentArtist?.artistName || ""),
          covers: distCovers, // Changed to array
          additionalMainArtists: distMainArtists,
          tracks: distTracks,
          releaseDate: dateTime.toISOString(),
          releaseMessage: distMsg
      });

      alert("Release submitted for approval!");
      setView('ARTIST_DASH');
      // Reset
      setDistStep(1); setDistTitle(""); setDistTracks([]); setDistCovers([]); setDistMsg(""); setDistMainArtists([]);
  };

  const handleCoverUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const files = e.target.files;
      if (files && files.length > 0) {
          Array.from(files).forEach(file => {
              const reader = new FileReader();
              reader.onloadend = () => setDistCovers(prev => [...prev, reader.result as string]);
              reader.readAsDataURL(file);
          });
      }
  };

  const handleProfileUpdate = () => {
      if (!currentArtist) return;
      submitProfileEdit({ newBio: editBio });
      alert("Bio update sent for approval.");
      setView('ARTIST_DASH');
  };

  // --- RENDERERS ---

  const renderAuth = () => (
      <div className="w-full max-w-md bg-surface p-8 rounded-xl shadow-2xl border border-surface-highlight">
          <div className="flex justify-center mb-6">
              <div className="w-16 h-16 bg-primary/20 rounded-full flex items-center justify-center">
                  {role === 'ARTIST' ? <Mic2 size={32} className="text-primary" /> : <Shield size={32} className="text-primary" />}
              </div>
          </div>
          <h2 className="text-2xl font-bold text-center mb-6">{authMode === 'LOGIN' ? 'Log in to' : 'Join'} Huevify For {role === 'ARTIST' ? 'Artists' : 'Moderators'}</h2>

          <div className="flex bg-surface-highlight p-1 rounded-full mb-6">
              <button 
                  onClick={() => setRole('ARTIST')} 
                  className={`flex-1 py-2 rounded-full text-sm font-bold transition ${role === 'ARTIST' ? 'bg-primary text-black' : 'text-secondary hover:text-white'}`}
              >
                  Artist
              </button>

              {(!hasModerator || authMode === 'LOGIN') && (
                  <button 
                      onClick={() => setRole('MODERATOR')}
                      className={`flex-1 py-2 rounded-full text-sm font-bold transition ${role === 'MODERATOR' ? 'bg-primary text-black' : 'text-secondary hover:text-white'}`}
                  >
                      Moderator
                  </button>
              )}
          </div>

          {message && <div className="bg-red-500/20 text-red-500 p-3 rounded mb-4 text-center text-sm">{message}</div>}

          <form onSubmit={authMode === 'LOGIN' ? handleLogin : handleRegister} className="flex flex-col gap-4">

              {authMode === 'REGISTER' && role === 'ARTIST' && (
                  <div className="flex flex-col gap-2">
                      {!isCreatingNewArtist ? (
                          <div className="relative">
                              <select 
                                  value={artistNameSelection}
                                  onChange={(e) => setArtistNameSelection(e.target.value)}
                                  className="w-full bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none appearance-none"
                              >
                                  <option value="">Select Artist...</option>
                                  {existingArtists.map(a => <option key={a} value={a}>{a}</option>)}
                              </select>
                              <ChevronDown className="absolute right-3 top-3 text-secondary pointer-events-none" size={20}/>
                          </div>
                      ) : (
                          <input 
                              type="text" 
                              placeholder="New Artist Alias" 
                              value={newArtistAlias} 
                              onChange={e => setNewArtistAlias(e.target.value)}
                              className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none"
                          />
                      )}

                      <label className="flex items-center gap-2 cursor-pointer mt-1">
                          <input 
                              type="checkbox" 
                              checked={isCreatingNewArtist}
                              onChange={e => setIsCreatingNewArtist(e.target.checked)}
                          />
                          <span className="text-xs text-secondary">Create new artist</span>
                      </label>
                  </div>
              )}

              <input 
                  type="text" placeholder="Username" value={username} onChange={e => setUsername(e.target.value)}
                  className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none"
              />
              <input 
                  type="password" placeholder="Password" value={password} onChange={e => setPassword(e.target.value)}
                  className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none"
              />

              <button type="submit" className="bg-primary text-black font-bold py-3 rounded-full hover:scale-105 transition mt-2">
                  {authMode === 'LOGIN' ? 'Log In' : 'Submit Application'}
              </button>
          </form>

          <p className="text-center text-secondary text-sm mt-4">
              {authMode === 'LOGIN' ? "Don't have an account?" : "Already have an account?"} 
              <button onClick={() => { setAuthMode(authMode === 'LOGIN' ? 'REGISTER' : 'LOGIN'); setMessage(""); }} className="text-white font-bold ml-1 hover:underline">
                  {authMode === 'LOGIN' ? 'Sign up' : 'Log in'}
              </button>
          </p>
      </div>
  );

  const renderModDash = () => (
      <div className="w-full h-full flex flex-col p-6 relative">
          <div className="flex justify-between items-center mb-8">
              <h1 className="text-3xl font-bold flex items-center gap-3"><Shield className="text-primary"/> Moderator Dashboard</h1>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 h-full overflow-hidden pb-16">
              {/* Artist Requests */}
              <div className="bg-surface rounded-xl p-4 flex flex-col overflow-hidden border border-surface-highlight">
                  <h3 className="font-bold mb-4 flex items-center gap-2 text-primary"><User size={18}/> Pending Artists</h3>
                  <div className="overflow-y-auto flex-1 flex flex-col gap-3">
                      {artistAccounts.filter(a => a.status === 'PENDING').length === 0 && <span className="text-secondary text-sm">No pending requests</span>}
                      {artistAccounts.filter(a => a.status === 'PENDING').map(a => (
                          <div key={a.id} className="p-3 bg-surface-highlight rounded flex justify-between items-center">
                              <div>
                                  <div className="font-bold">{a.artistName}</div>
                                  <div className="text-xs text-secondary">@{a.username}</div>
                              </div>
                              <div className="flex gap-2">
                                  <button onClick={() => approveArtist(a.id)} className="text-green-500 hover:scale-110"><CheckCircle size={20}/></button>
                                  <button onClick={() => rejectArtist(a.id)} className="text-red-500 hover:scale-110"><XCircle size={20}/></button>
                              </div>
                          </div>
                      ))}
                  </div>
              </div>

              {/* Release Requests */}
              <div className="bg-surface rounded-xl p-4 flex flex-col overflow-hidden border border-surface-highlight">
                  <h3 className="font-bold mb-4 flex items-center gap-2 text-primary"><UploadCloud size={18}/> Pending Releases</h3>
                  <div className="overflow-y-auto flex-1 flex flex-col gap-3">
                      {releaseRequests.filter(r => r.status === 'PENDING').length === 0 && <span className="text-secondary text-sm">No pending releases</span>}
                      {releaseRequests.filter(r => r.status === 'PENDING').map(r => (
                          <div key={r.id} className="p-3 bg-surface-highlight rounded flex flex-col gap-2 cursor-pointer hover:bg-zinc-800" onClick={() => setSelectedRelease(r)}>
                              <div className="flex items-center gap-3">
                                  <img src={r.covers[0]} className="w-10 h-10 rounded" alt=""/>
                                  <div className="flex-1 overflow-hidden">
                                      <div className="font-bold truncate">{r.title}</div>
                                      <div className="text-xs text-secondary">{r.artistName} • {r.type} • {r.tracks.length} tracks</div>
                                  </div>
                              </div>
                              <div className="text-xs text-secondary bg-black/20 p-2 rounded">
                                  Msg: {r.releaseMessage || "None"} <br/>
                                  Date: {new Date(r.releaseDate).toLocaleString()}
                              </div>
                              <div className="flex gap-2 justify-end mt-2" onClick={e => e.stopPropagation()}>
                                  <button onClick={() => approveRelease(r.id)} className="text-green-500 hover:text-white text-xs font-bold uppercase border border-green-500 px-2 py-1 rounded hover:bg-green-500 transition">Approve</button>
                                  <button onClick={() => rejectRelease(r.id)} className="text-red-500 hover:text-white text-xs font-bold uppercase border border-red-500 px-2 py-1 rounded hover:bg-red-500 transition">Reject</button>
                              </div>
                          </div>
                      ))}
                  </div>
              </div>

              {/* Profile Edits */}
              <div className="bg-surface rounded-xl p-4 flex flex-col overflow-hidden border border-surface-highlight">
                  <h3 className="font-bold mb-4 flex items-center gap-2 text-primary"><Edit size={18}/> Profile Edits</h3>
                  <div className="overflow-y-auto flex-1 flex flex-col gap-3">
                      {profileEditRequests.filter(r => r.status === 'PENDING').length === 0 && <span className="text-secondary text-sm">No pending edits</span>}
                      {profileEditRequests.filter(r => r.status === 'PENDING').map(r => (
                          <div key={r.id} className="p-3 bg-surface-highlight rounded flex flex-col gap-2">
                               <div className="font-bold text-sm">{r.artistName} updates</div>
                               {r.newAvatar && <div className="text-xs text-secondary">New Avatar</div>}
                               {r.newBio && <div className="text-xs text-secondary bg-black/20 p-1 rounded italic line-clamp-2">Bio: {r.newBio}</div>}
                               {r.newArtistPick && <div className="text-xs text-secondary bg-black/20 p-1 rounded italic">New Pick: {r.newArtistPick.subtitle}</div>}
                               <div className="flex gap-2 justify-end">
                                  <button onClick={() => approveProfileEdit(r.id)} className="text-green-500 hover:text-white text-xs font-bold uppercase border border-green-500 px-2 py-1 rounded hover:bg-green-500 transition">Approve</button>
                                  <button onClick={() => rejectProfileEdit(r.id)} className="text-red-500 hover:text-white text-xs font-bold uppercase border border-red-500 px-2 py-1 rounded hover:bg-red-500 transition">Reject</button>
                              </div>
                          </div>
                      ))}
                  </div>
              </div>
          </div>

          {/* Log Out Button */}
          <div className="absolute bottom-6 left-6">
              <button 
                  onClick={() => { logoutArtistHub(); setView('AUTH'); }} 
                  className="flex items-center gap-2 px-4 py-2 bg-surface-highlight rounded-full text-secondary hover:text-white hover:bg-red-500 hover:text-white transition font-bold"
              >
                  <LogOut size={18} />
                  Log Out
              </button>
          </div>

          {selectedRelease && (
              <div className="absolute inset-0 bg-black/90 z-50 flex items-center justify-center p-4">
                  <div className="bg-surface w-full max-w-lg max-h-[80vh] overflow-y-auto rounded-xl p-6 relative">
                      <button onClick={() => setSelectedRelease(null)} className="absolute top-4 right-4 text-white"><X size={24}/></button>
                      <h2 className="text-2xl font-bold mb-4">Release Details</h2>
                      <div className="flex gap-4 mb-4">
                          <img src={selectedRelease.covers[0]} className="w-24 h-24 rounded object-cover" />
                          <div>
                              <div className="font-bold text-xl">{selectedRelease.title}</div>
                              <div className="text-secondary">{selectedRelease.type}</div>
                              <div className="text-secondary text-sm">Status: {selectedRelease.status}</div>
                              {selectedRelease.generatedHueq && <div className="text-xs text-primary font-mono mt-1">Ref ID: {selectedRelease.id}</div>}
                          </div>
                      </div>
                      <h3 className="font-bold mb-2">Tracks & HUEQ Codes</h3>
                      <div className="flex flex-col gap-2">
                          {selectedRelease.tracks.map((t, i) => (
                              <div key={i} className="bg-surface-highlight p-2 rounded text-sm flex justify-between items-center">
                                  <span>{i+1}. {t.title}</span>
                                  <span className="text-secondary font-mono bg-black/30 px-2 py-0.5 rounded text-xs">
                                      {t.generatedHueq || t.existingHueq || (selectedRelease.status === 'LIVE' ? "Generating..." : "Pending Approval")}
                                  </span>
                              </div>
                          ))}
                      </div>
                  </div>
              </div>
          )}
      </div>
  );

  const renderArtistDash = () => {
    if (!currentArtist) return null;
    const myReleases = releaseRequests.filter(r => r.artistId === currentArtist.id);
    const stats = getArtistStats(currentArtist.artistName);

    return (
        <div className="w-full h-full flex flex-col p-6 relative">
            <div className="flex justify-between items-center mb-8">
                <div className="flex items-center gap-4">
                    <div className="w-16 h-16 rounded-full overflow-hidden bg-zinc-800">
                        {currentArtist.avatar ? <img src={currentArtist.avatar} className="w-full h-full object-cover" /> : <User size={32} className="text-secondary m-auto h-full" />}
                    </div>
                    <div>
                        <h1 className="text-3xl font-bold flex items-center gap-2">{currentArtist.artistName} <CheckCircle size={20} className="text-blue-500" fill="white" /></h1>
                        <p className="text-secondary text-sm">Artist Dashboard</p>
                    </div>
                </div>
                <div className="flex items-center gap-4 bg-surface px-4 py-2 rounded-lg border border-surface-highlight">
                    <div className="text-center">
                        <div className="text-xs text-secondary uppercase font-bold">Monthly Listeners</div>
                        <div className="font-bold text-xl">{stats.monthlyPlays.toLocaleString()}</div>
                    </div>
                    <div className="w-px h-8 bg-surface-highlight"></div>
                    <div className="text-center">
                        <div className="text-xs text-secondary uppercase font-bold">Global Rank</div>
                        <div className="font-bold text-xl">#{stats.globalRank}</div>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
                <button onClick={() => setView('DISTRIBUTION')} className="bg-primary text-black p-4 rounded-xl flex flex-col items-center justify-center gap-2 hover:scale-105 transition font-bold h-32">
                    <UploadCloud size={32}/>
                    Upload New Release
                </button>
                <button onClick={() => setView('PROFILE_EDIT')} className="bg-surface border border-surface-highlight p-4 rounded-xl flex flex-col items-center justify-center gap-2 hover:bg-surface-highlight transition font-bold h-32">
                    <Edit size={32} className="text-secondary"/>
                    Edit Profile
                </button>
                <button onClick={() => setView('ARTIST_PICK')} className="bg-surface border border-surface-highlight p-4 rounded-xl flex flex-col items-center justify-center gap-2 hover:bg-surface-highlight transition font-bold h-32">
                    <ListMusic size={32} className="text-secondary"/>
                    Select Artist Pick
                </button>
                <div className="bg-surface border border-surface-highlight p-4 rounded-xl flex flex-col justify-center gap-1 h-32">
                    <span className="text-xs text-secondary font-bold uppercase">Status</span>
                    <div className="flex items-center gap-2 font-bold text-green-500"><CheckCircle size={16}/> Verified Artist</div>
                    <div className="text-xs text-secondary mt-1">Access to all features</div>
                </div>
            </div>

            <h2 className="text-2xl font-bold mb-4">My Releases</h2>
            <div className="flex-1 overflow-y-auto bg-surface rounded-xl border border-surface-highlight">
                <table className="w-full text-left border-collapse">
                    <thead className="bg-surface-highlight text-secondary text-xs uppercase font-bold sticky top-0">
                        <tr>
                            <th className="p-4">Release</th>
                            <th className="p-4">Type</th>
                            <th className="p-4">Date</th>
                            <th className="p-4">Status</th>
                            <th className="p-4 text-right">Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        {myReleases.length === 0 && (
                            <tr>
                                <td colSpan={5} className="p-8 text-center text-secondary">You haven't uploaded any releases yet.</td>
                            </tr>
                        )}
                        {myReleases.map(r => (
                            <tr key={r.id} className="border-b border-surface-highlight hover:bg-white/5 transition">
                                <td className="p-4 flex items-center gap-3">
                                    <img src={r.covers[0]} className="w-10 h-10 rounded object-cover" />
                                    <span className="font-bold">{r.title}</span>
                                </td>
                                <td className="p-4 text-sm text-secondary">{r.type}</td>
                                <td className="p-4 text-sm text-secondary">{new Date(r.releaseDate).toLocaleDateString()}</td>
                                <td className="p-4">
                                    <span className={`px-2 py-1 rounded text-xs font-bold uppercase ${
                                        r.status === 'LIVE' ? 'bg-green-500/20 text-green-500' :
                                        r.status === 'APPROVED' ? 'bg-blue-500/20 text-blue-500' :
                                        r.status === 'REJECTED' ? 'bg-red-500/20 text-red-500' :
                                        'bg-yellow-500/20 text-yellow-500'
                                    }`}>
                                        {r.status}
                                    </span>
                                </td>
                                <td className="p-4 text-right">
                                    <button onClick={() => deleteRelease(r.id)} className="text-secondary hover:text-red-500 transition">
                                        <Trash2 size={18}/>
                                    </button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

             {/* Log Out Button */}
            <div className="absolute bottom-6 left-6">
                <button 
                    onClick={() => { logoutArtistHub(); setView('AUTH'); }} 
                    className="flex items-center gap-2 px-4 py-2 bg-surface-highlight rounded-full text-secondary hover:text-white hover:bg-red-500 hover:text-white transition font-bold"
                >
                    <LogOut size={18} />
                    Log Out
                </button>
            </div>
        </div>
    );
};

const renderProfileEdit = () => (
    <div className="w-full max-w-2xl mx-auto p-6">
        <button onClick={() => setView('ARTIST_DASH')} className="mb-4 flex items-center gap-2 text-secondary hover:text-white"><ArrowLeft/> Back to Dashboard</button>
        <h1 className="text-2xl font-bold mb-6">Edit Artist Profile</h1>

        <div className="flex flex-col gap-6">
            <div className="flex flex-col gap-2">
                <label className="font-bold text-sm uppercase text-secondary">Artist Bio</label>
                <textarea 
                    value={editBio} 
                    onChange={e => setEditBio(e.target.value)} 
                    className="bg-background p-4 rounded-xl border border-surface-highlight focus:border-primary focus:outline-none h-48 resize-none text-white leading-relaxed"
                    placeholder="Tell your fans about yourself..."
                />
                <p className="text-xs text-secondary">Bio updates require moderator approval.</p>
            </div>

            <button 
                onClick={handleProfileUpdate}
