        </button>
        <span className="text-xs font-bold tracking-widest uppercase">Now Playing</span>
        <button className="text-white" onClick={() => openAddToPlaylist(currentTrack.id)}>
          <Plus size={24} />
        </button>
      </div>

      {/* Cover Art */}
      <div className="flex-1 flex items-center justify-center mb-8">
        <div className="w-full aspect-square shadow-2xl rounded-lg overflow-hidden">
          <img src={currentTrack.cover} alt={currentTrack.title} className="w-full h-full object-cover" />
        </div>
      </div>

      {/* Track Info */}
      <div className="flex justify-between items-center mb-6">
        <div className="flex flex-col overflow-hidden mr-4">
          <h2 className="text-2xl font-bold text-white truncate marquee">{currentTrack.title}</h2>
          <div className="text-lg text-secondary truncate">
              {allArtists.map((a, i) => (
                  <span key={a}>
                      {i > 0 && ", "}
                      <span 
                        onClick={() => { setMobilePlayerOpen(false); goToArtist(a); }} 
                        className="underline decoration-transparent hover:decoration-secondary cursor-pointer transition"
                      >
                          {a}
                      </span>
                  </span>
              ))}
          </div>
        </div>
        <button 
            onClick={() => toggleLike(currentTrack.id)}
            className={`${isLiked(currentTrack.id) ? 'text-primary' : 'text-white'}`}
        >
            <Heart size={32} fill={isLiked(currentTrack.id) ? 'currentColor' : 'none'} />
        </button>
      </div>

      {/* Progress */}
      <div className="mb-6">
        <div className="w-full h-1 bg-surface-highlight rounded-full mb-2 relative group">
           <input
              type="range"
              min={0}
              max={duration || 100}
              value={progress}
              onChange={(e) => seek(Number(e.target.value))}
              className="absolute w-full h-full opacity-0 cursor-pointer z-10"
            />
            <div 
              className="h-full bg-white rounded-full"
              style={{ width: `${(progress / (duration || 1)) * 100}%` }}
            />
            <div 
                className="absolute h-3 w-3 bg-white rounded-full top-1/2 -translate-y-1/2 shadow-md"
                style={{ left: `${(progress / (duration || 1)) * 100}%` }}
            />
        </div>
        <div className="flex justify-between text-xs text-secondary font-medium">
          <span>{formatTime(progress)}</span>
          <span>{formatTime(duration)}</span>
        </div>
      </div>

      {/* Controls */}
      <div className="flex justify-between items-center mb-8">
        <button 
            onClick={toggleShuffle}
            className={`${isShuffle ? 'text-primary' : 'text-secondary hover:text-white'} transition`}
        >
          <Shuffle size={24} />
        </button>

        <button onClick={prevTrack} className="text-white hover:scale-110 transition">
          <SkipBack size={36} fill="currentColor" />
        </button>

        <button 
          onClick={togglePlay} 
          className="w-16 h-16 bg-white rounded-full flex items-center justify-center hover:scale-105 transition text-black"
        >
          {isPlaying ? <Pause size={32} fill="currentColor" /> : <Play size={32} fill="currentColor" className="ml-1" />}
        </button>

        <button onClick={nextTrack} className="text-white hover:scale-110 transition">
          <SkipForward size={36} fill="currentColor" />
        </button>

        <button 
            onClick={toggleRepeat} 
            className={`${playMode !== PlayMode.OFF ? 'text-primary' : 'text-secondary'} transition relative`}
        >
          <Repeat size={24} />
          {playMode === PlayMode.ONE && <span className="absolute text-[8px] font-bold top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-primary">1</span>}
          {playMode === PlayMode.CONTEXT && <div className="absolute -bottom-2 left-1/2 -translate-x-1/2 w-1 h-1 bg-primary rounded-full"></div>}
        </button>
      </div>

      {/* Mobile Volume Control */}
      <div className="flex items-center gap-3">
         <Volume2 size={20} className="text-secondary" />
         <div className="flex-1 h-1 bg-surface-highlight rounded-full relative group">
            <input 
              type="range" 
              min={0} 
              max={1} 
              step={0.01} 
              value={volume}
              onChange={(e) => setVolume(Number(e.target.value))}
              className="absolute w-full h-full opacity-0 cursor-pointer z-10"
            />
            <div 
              className="h-full bg-white rounded-full"
              style={{ width: `${volume * 100}%` }}
            />
         </div>
      </div>

    </div>
  );
};

export interface Track {
  id: string;
  title: string;
  artist: string;
  album: string;
  cover: string; // Keep for track display consistency, usually points to active album cover
  duration: number; // in seconds
  url: string; // audio source
  plays: number;
  genre: string; // New field for recommendations
  explicit?: boolean;
  feat?: string;
  hueq?: string; // ISRC equivalent
  mainArtists?: string[]; // Array of additional main artists
}

export interface DailyChartTrack extends Track {
  dailyPlays: number;
}

export interface Playlist {
  id: string;
  name: string;
  description?: string;
  customCover?: string; // Base64 or URL
  tracks: string[]; // array of track IDs
  isSystem?: boolean; // e.g. "Liked Songs"
  ownerId?: string; // ID of the user who created this playlist

  // New fields for Public/Private feature
  isPublic?: boolean;
  creatorName?: string;
  creatorAvatar?: string;
  savedBy?: string[]; // Array of User IDs who added this playlist to their library
}

export interface Album {
  id: string;
  title: string;
  artist: string;
  covers: string[]; // Changed from single cover to array
  trackIds: string[];
  year: number;
  releaseDate?: string; // ISO string for full date display
  recordLabel?: string;
  type?: ReleaseType;
  mainArtists?: string[]; // Added at album level for better display
}

export interface User {
  id: string;
  username: string;
  password: string; // Stored locally for this prototype
  displayName: string;
  avatar?: string; // Base64
}

export interface AppSettings {
  accentColor: string;
  language: 'English' | 'Russian';
  highQualityAudio: boolean;
  autoPlay: boolean;
  crossfade: number; // seconds
  albumCoverIndexes: Record<string, number>; // Stores user preference for album covers
}

export type ViewState = 
  | { type: 'HOME' }
  | { type: 'SEARCH' }
  | { type: 'LIBRARY' }
  | { type: 'PLAYLIST'; id: string }
  | { type: 'ALBUM'; id: string }
  | { type: 'ARTIST'; id: string }
  | { type: 'CHARTS' };

export enum PlayMode {
  OFF = 'OFF',
  CONTEXT = 'CONTEXT', // Repeat Playlist/Album
  ONE = 'ONE', // Repeat One Track
}

// --- ARTIST HUB TYPES ---

export type ArtistVerificationStatus = 'PENDING' | 'APPROVED' | 'REJECTED';

export interface ArtistAccount {
  id: string; // Unique ID for the account
  artistName: string; // Displays as the Artist Name in app
  username: string; // Login username
  password: string; 
  avatar?: string;
  bio?: string; // Artist Description
  status: ArtistVerificationStatus;
  artistPick?: {
    type: 'TRACK' | 'ALBUM' | 'PLAYLIST';
    id: string;
    image?: string;
    subtitle?: string;
  };
}

export interface ModeratorAccount {
  username: string;
  password: string;
}

export interface DistributionTrack {
  title: string;
  explicit: boolean;
  feat?: string; // Featured artists
  mainArtists?: string[]; // Additional main artists
  genre?: string; // Track specific genre
  fileUrl: string; // Mocked for prototype
  duration: number;
  existingHueq?: string; // If user inputs an existing code
  generatedHueq?: string; // Assigned by system on approval
}

export type ReleaseType = 'Single' | 'Album' | 'EP' | 'Mixtape';

export interface ReleaseRequest {
  id: string;
  artistId: string;
  artistName: string;
  status: 'PENDING' | 'APPROVED' | 'REJECTED' | 'LIVE';
  submissionTime?: string; // ISO String

  // Info
  title: string;
  type: ReleaseType;
  genre: string;
  label: string;
  covers: string[]; // Array of covers
  additionalMainArtists?: string[];

  // Tracks
  tracks: DistributionTrack[];

  // Schedule
  releaseDate: string; // ISO String
  releaseMessage?: string;
}

export interface ProfileEditRequest {
  id: string;
  artistId: string;
  artistName: string;
  newAvatar?: string;
  newBio?: string;
  newArtistPick?: ArtistAccount['artistPick'];
  status: 'PENDING' | 'APPROVED' | 'REJECTED';
}

