                      <div className="flex flex-col gap-2">
                          <label className="font-bold text-sm uppercase text-secondary">Release Time (UTC+3)*</label>
                          <input type="time" value={distTime} onChange={e => setDistTime(e.target.value)} className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none text-white transition-colors"/>
                      </div>
                      <div className="flex flex-col gap-2">
                          <label className="font-bold text-sm uppercase text-secondary">Message to Moderator</label>
                          <textarea value={distMsg} onChange={e => setDistMsg(e.target.value)} className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none h-24 resize-none transition-colors"/>
