                             <div className="flex flex-col gap-1">
                                 <label className="text-xs font-bold text-secondary uppercase">Genre*</label>
                                 <select value={distGenre} onChange={e => setDistGenre(e.target.value)} className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none transition-colors">
                                     {['Pop', 'Rap/Hip-Hop', 'R&B', 'Electronic/Dance', 'Rock', 'Indie'].map(g => <option key={g} value={g}>{g}</option>)}
                                 </select>
                             </div>
                          </div>

                          <input type="text" placeholder={`Label* (Default: ${currentArtist?.artistName})`} value={distLabel} onChange={e => setDistLabel(e.target.value)} className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none transition-colors"/>

                          <div className="flex flex-col gap-1">
                               <label className="text-xs font-bold text-secondary uppercase">Additional Main Artists (Album Level)</label>
                               <div className="flex gap-2">
                                   <input type="text" value={distMainArtistInput} onChange={e => setDistMainArtistInput(e.target.value)} placeholder="Enter artist name" className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none flex-1 transition-colors"/>
                                   <button onClick={() => { if(distMainArtistInput) { setDistMainArtists([...distMainArtists, distMainArtistInput]); setDistMainArtistInput(""); } }} className="bg-surface-highlight px-4 rounded hover:bg-white hover:text-black font-bold transition-colors">Add</button>
                               </div>
                               <div className="flex flex-wrap gap-2 mt-2">
                                   {distMainArtists.map((art, i) => (
                                       <div key={i} className="bg-primary/20 text-primary px-2 py-1 rounded text-xs flex items-center gap-2">
                                           {art} <X size={12} className="cursor-pointer hover:scale-125 transition" onClick={() => setDistMainArtists(distMainArtists.filter((_, idx) => idx !== i))} />
                                       </div>
                                   ))}
                               </div>
                          </div>
                      </div>
                  </div>
              )}

              {distStep === 2 && (
                  <div className="flex flex-col gap-4 animate-slide-in-right">
                      {distTracks.length > 0 && (
                          <div className="flex flex-col gap-3 mb-4">
                              {distTracks.map((track, idx) => (
                                  <div key={idx} className="bg-surface-highlight p-4 rounded flex flex-col gap-2 animate-slide-in-bottom duration-300">
                                      <div className="flex items-center gap-4">
                                          <span className="font-bold text-secondary">{idx + 1}</span>
                                          <div className="flex-1 grid grid-cols-2 gap-4">
                                              <div className="flex flex-col gap-1">
                                                  <label className="text-[10px] uppercase font-bold text-secondary">Title</label>
                                                  <input type="text" value={track.title} onChange={e => updateTrack(idx, 'title', e.target.value)} className="bg-background p-2 rounded text-sm transition-colors focus:border-primary border border-transparent"/>
                                              </div>

                                              {/* Reordered: Additional Main Artists first */}
                                              <div className="flex flex-col gap-1">
                                                  <label className="text-[10px] uppercase font-bold text-secondary">Add. Main Artists (Track)</label>
                                                  <div className="flex gap-1">
                                                     <input type="text" id={`mainArt_${idx}`} className="bg-background p-2 rounded text-sm w-full transition-colors focus:border-primary border border-transparent" placeholder="Add Name"/>
                                                     <button onClick={() => { 
                                                         const el = document.getElementById(`mainArt_${idx}`) as HTMLInputElement;
                                                         addTrackMainArtist(idx, el.value);
                                                         el.value = "";
                                                     }} className="bg-surface-highlight px-2 rounded hover:bg-white hover:text-black transition-colors">+</button>
                                                  </div>
                                                  <div className="flex flex-wrap gap-1 mt-1">
                                                      {track.mainArtists?.map((art, i) => (
                                                          <span key={i} className="text-[10px] bg-white/10 px-1 rounded flex items-center gap-1">{art} <X size={8} onClick={() => removeTrackMainArtist(idx, i)} className="cursor-pointer hover:text-red-500 transition"/></span>
                                                      ))}
                                                  </div>
                                              </div>
                                          </div>

                                          <div className="flex flex-col items-end gap-2">
                                              <label className="flex items-center gap-2 cursor-pointer mt-4">
                                                  <input type="checkbox" checked={track.explicit} onChange={e => updateTrack(idx, 'explicit', e.target.checked)} />
                                                  <span className="text-xs uppercase font-bold text-secondary">E</span>
                                              </label>
                                              <button onClick={() => setDistTracks(distTracks.filter((_, i) => i !== idx))} className="text-red-500 hover:scale-110 transition"><XCircle/></button>
                                          </div>
                                      </div>

                                      <div className="grid grid-cols-3 gap-4 mt-2 border-t border-surface pt-2">
                                          <div>
                                              <label className="text-[10px] uppercase font-bold text-secondary">HUEQ (ISRC)</label>
                                              <div className="flex gap-2">
                                                  <input 
                                                     type="text" 
                                                     placeholder="000XX0" 
                                                     value={track.existingHueq || ""} 
                                                     onChange={e => updateTrack(idx, 'existingHueq', e.target.value)}
                                                     onBlur={e => handleHueqBlur(idx, e.target.value)}
                                                     className="bg-background p-2 rounded text-sm w-full font-mono uppercase transition-colors focus:border-primary border border-transparent"
                                                  />
                                                  <button 
                                                    onClick={() => handleHueqBlur(idx, track.existingHueq || "")}
                                                    className="bg-surface-highlight px-2 rounded hover:bg-white hover:text-black transition-colors"
                                                    title="Check Code"
                                                  >
                                                      <Check size={14}/>
                                                  </button>
                                              </div>
                                          </div>
                                          <div>
                                              <label className="text-[10px] uppercase font-bold text-secondary">Feat.</label>
                                              <input type="text" placeholder="Optional" value={track.feat || ""} onChange={e => updateTrack(idx, 'feat', e.target.value)} className="bg-background p-2 rounded text-sm w-full transition-colors focus:border-primary border border-transparent"/>
                                          </div>
                                          <div>
                                              <label className="text-[10px] uppercase font-bold text-secondary">Genre</label>
                                              <select value={track.genre || distGenre} onChange={e => updateTrack(idx, 'genre', e.target.value)} className="bg-background p-2 rounded text-sm w-full transition-colors focus:border-primary border border-transparent">
                                                  {['Pop', 'Rap/Hip-Hop', 'R&B', 'Electronic/Dance', 'Rock', 'Indie'].map(g => <option key={g} value={g}>{g}</option>)}
                                              </select>
                                          </div>
                                      </div>
                                  </div>
                              ))}
                          </div>
                      )}

                      <div 
                         onClick={() => trackInputRef.current?.click()}
                         className="py-6 border-2 border-dashed border-secondary rounded text-secondary hover:text-white hover:border-white font-bold transition-all duration-300 flex items-center justify-center gap-2 cursor-pointer hover:bg-surface-highlight hover:shadow-lg"
                      >
                          <FileAudio size={24}/> Upload Audio File (Calculates Duration)
                      </div>
                      <input type="file" ref={trackInputRef} className="hidden" accept="audio/*" onChange={handleFileUpload} />
                  </div>
              )}

              {distStep === 3 && (
                  <div className="flex flex-col gap-6 max-w-md mx-auto animate-slide-in-right">
                      <div className="flex flex-col gap-2">
                          <label className="font-bold text-sm uppercase text-secondary">Release Date*</label>
                          <input type="date" value={distDate} onChange={e => setDistDate(e.target.value)} className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none text-white transition-colors"/>
                      </div>
                      <div className="flex flex-col gap-2">
                          <label className="font-bold text-sm uppercase text-secondary">Release Time (UTC+3)*</label>
                          <input type="time" value={distTime} onChange={e => setDistTime(e.target.value)} className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none text-white transition-colors"/>
                      </div>
                      <div className="flex flex-col gap-2">
                          <label className="font-bold text-sm uppercase text-secondary">Message to Moderator</label>
                          <textarea value={distMsg} onChange={e => setDistMsg(e.target.value)} className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none h-24 resize-none transition-colors"/>
                      </div>
                  </div>
              )}
          </div>

          <div className="flex justify-between">
              {distStep > 1 ? <button onClick={() => setDistStep(distStep - 1)} className="px-6 py-3 rounded-full font-bold text-white hover:bg-surface-highlight transition">Back</button> : <div></div>}
              {distStep < 3 ? (
                  <button onClick={handleNextStep} className="px-6 py-3 rounded-full bg-white text-black font-bold hover:scale-105 transition shadow-lg">Next</button>
              ) : (
                  <button onClick={handleSubmitRelease} className="px-6 py-3 rounded-full bg-primary text-black font-bold hover:scale-105 transition shadow-lg hover:shadow-primary/20">Submit Release</button>
              )}
          </div>
      </div>
  );

  return (
    <div className="fixed inset-0 bg-black z-[200] flex items-center justify-center animate-fade-in">
        <button 
          onClick={() => setArtistHubOpen(false)} 
          className="absolute top-4 right-4 text-secondary hover:text-white z-50"
        >
          <X size={32} />
        </button>

        {view === 'AUTH' && renderAuth()}
        {view === 'MOD_DASH' && renderModDash()}
        {view === 'ARTIST_DASH' && renderArtistDash()}
        {view === 'PROFILE_EDIT' && renderProfileEdit()}
        {view === 'ARTIST_PICK' && renderArtistPickSelection()}
        {view === 'DISTRIBUTION' && renderDistributionWizard()}

        {selectedRelease && renderReleaseDetailModal()}
    </div>
  );
};

import React, { useState } from 'react';
import { useStore } from '../context/StoreContext.tsx';
import { Search as SearchIcon, Play, Heart, ListMusic, User, ArrowLeft } from '../components/Icons.tsx';

const formatDuration = (seconds: number) => {
    const min = Math.floor(seconds / 60);
    const sec = Math.floor(seconds % 60);
    return `${min}:${sec.toString().padStart(2, '0')}`;
};

const formatPlays = (plays: number) => {
    return new Intl.NumberFormat('en-US').format(plays);
};

export const Search = () => {
  const { tracks, playlists, playTrack, isLiked, toggleLike, setView, currentUser, existingArtists, artistAccounts, goToArtist, view, albums, goBack } = useStore();
  const [query, setQuery] = useState("");

  const filteredTracks = tracks.filter(t => 
    t.title.toLowerCase().includes(query.toLowerCase()) || 
    t.artist.toLowerCase().includes(query.toLowerCase()) ||
    t.album.toLowerCase().includes(query.toLowerCase())
  );

  // Filter Public Playlists
  const filteredPlaylists = playlists.filter(p => 
    !p.isSystem && 
    p.isPublic &&
    p.name.toLowerCase().includes(query.toLowerCase())
  );

  // Filter Artists
  const filteredArtists = existingArtists.filter(a => a.toLowerCase().includes(query.toLowerCase()));

  // Restricted Genres (Removed Indie, Rock, Jazz)
  const genres = [
    { name: 'Pop', color: 'bg-pink-600' },
    { name: 'Rap/Hip-Hop', color: 'bg-orange-600' },
    { name: 'R&B', color: 'bg-purple-600' },
    { name: 'Electronic/Dance', color: 'bg-teal-600' }
  ];

  const getArtistImage = (name: string) => {
      const acc = artistAccounts.find(a => a.artistName === name);
      if (acc && acc.avatar) return acc.avatar;
      const track = tracks.find(t => t.artist === name);
      return track ? track.cover : null;
  };

  // --- GENRE VIEW ---
  if (view.type === 'GENRE') {
      const genreName = view.id;
      const genreTracks = tracks.filter(t => t.genre === genreName || (t.genre && t.genre.includes(genreName)));

      // Filter albums: Must match genre AND NOT be a Single
      const genreAlbums = albums.filter(a => {
          if (a.type === 'Single') return false; 
          const track = tracks.find(t => t.id === a.trackIds[0]);
          return track && (track.genre === genreName || track.genre?.includes(genreName));
      });

      const genreColor = genres.find(g => g.name === genreName)?.color || 'bg-gray-600';

      return (
          <div className="h-full overflow-y-auto pb-32 relative w-full page-enter">
              <div className={`p-8 ${genreColor} bg-gradient-to-b from-transparent to-background/90 animate-appear`}>
                   <div className="absolute top-4 left-4 z-20">
                      <button onClick={goBack} className="w-8 h-8 bg-black/30 rounded-full flex items-center justify-center text-white"><ArrowLeft size={20}/></button>
                   </div>
                   <h1 className="text-4xl md:text-6xl font-bold mt-8 mb-4">{genreName}</h1>
                   <p className="text-white/80 font-bold">Discover the best {genreName} tracks and releases.</p>
              </div>

              <div className="px-4 md:px-8 py-4 animate-slide-up">

                  {/* Genre Albums */}
                  {genreAlbums.length > 0 && (
                      <div className="mb-8">
                          <h2 className="text-2xl font-bold mb-4">Popular Releases</h2>
                          <div className="flex overflow-x-auto gap-4 pb-4 snap-x no-scrollbar">
                              {genreAlbums.map(album => (
                                  <div 
                                    key={album.id} 
                                    onClick={() => setView({ type: 'ALBUM', id: album.id })}
                                    className="w-[150px] md:w-auto p-3 md:p-4 bg-surface hover:bg-surface-highlight rounded-lg cursor-pointer group snap-start flex-shrink-0 hover-scale"
                                  >
                                      <div className="relative mb-3 md:mb-4 w-full aspect-square">
                                          <img src={album.covers[0]} className="w-full h-full object-cover rounded shadow-lg" />
                                          <div className="absolute bottom-2 right-2 w-12 h-12 bg-primary rounded-full flex items-center justify-center shadow-xl opacity-0 translate-y-2 group-hover:opacity-100 group-hover:translate-y-0 transition-all duration-300">
                                              <Play fill="black" size={24} className="text-black ml-1" />
                                          </div>
                                      </div>
                                      <div className="font-bold truncate text-sm md:text-base">{album.title}</div>
                                      <div className="text-xs md:text-sm text-secondary truncate">{album.artist}</div>
                                  </div>
                              ))}
                          </div>
                      </div>
                  )}

                  {/* Genre Tracks */}
                  <h2 className="text-2xl font-bold mb-4">All Tracks</h2>
                  <div className="flex flex-col gap-2">
                      {genreTracks.length === 0 && <div className="text-secondary">No tracks found in this genre.</div>}
                      {genreTracks.map((track, idx) => (
                          <div 
                             key={track.id} 
                             className="grid grid-cols-[16px_1fr_60px] md:grid-cols-[16px_1fr_100px_60px] items-center gap-4 p-3 rounded hover:bg-surface-highlight group"
                          >
                             <div className="flex items-center justify-center" onClick={() => playTrack(track)}>
                                <div className="text-secondary text-center group-hover:hidden text-sm">{idx + 1}</div>
                                <div className="hidden group-hover:block cursor-pointer"><Play size={16} fill="white"/></div>
                             </div>

                             <div className="flex items-center gap-4 overflow-hidden" onClick={() => playTrack(track)}>
                                <img src={track.cover} className="w-10 h-10 rounded object-cover flex-shrink-0" />
                                <div className="flex flex-col overflow-hidden">
                                  <div className="font-semibold text-white flex items-center gap-2 truncate cursor-pointer hover:underline">
                                      {track.title}
                                      {track.explicit && <span className="text-[8px] border border-secondary text-secondary px-1 rounded bg-surface">E</span>}
                                  </div>
                                  <div className="text-sm text-secondary truncate">{track.artist}</div>
                                </div>
                             </div>

                             <div className="text-secondary text-sm hidden md:block text-right">{formatPlays(track.plays)}</div>

                             <div className="flex items-center gap-4 justify-end">
                                <span className="text-sm text-secondary hidden md:block">{formatDuration(track.duration)}</span>
                                <button onClick={() => toggleLike(track.id)} className={`${isLiked(track.id) ? 'text-primary' : 'text-transparent group-hover:text-secondary hover:text-white'}`}>
                                  <Heart size={18} fill={isLiked(track.id) ? 'currentColor' : 'none'} />
                                </button>
                             </div>
                          </div>
                      ))}
                  </div>
              </div>
          </div>
      );
  }

  // --- SEARCH VIEW ---
  return (
    <div className="p-8 pb-32 bg-background flex-1 overflow-y-auto h-full page-enter">
      <div className="mb-8 relative">
        <SearchIcon className="absolute left-4 top-3.5 text-black" size={24} />
        <input 
          type="text" 
          placeholder="What do you want to listen to?" 
          className="w-full md:w-96 py-3 pl-12 pr-4 rounded-full text-black font-semibold focus:outline-none focus:ring-2 focus:ring-white"
          value={query}
          onChange={e => setQuery(e.target.value)}
          autoFocus
        />
      </div>

      {query ? (
        <div className="flex flex-col gap-8 animate-in fade-in">

           {/* Artists Section */}
           {filteredArtists.length > 0 && (
               <div>
                   <h2 className="text-xl font-bold mb-4">Artists</h2>
                   <div className="flex gap-4 overflow-x-auto pb-2">
                       {filteredArtists.map(artist => (
                           <div key={artist} onClick={() => goToArtist(artist)} className="flex flex-col items-center gap-2 cursor-pointer hover:bg-surface-highlight p-4 rounded-lg transition min-w-[140px]">
                               <div className="w-24 h-24 rounded-full overflow-hidden bg-zinc-800 shadow-lg">
                                   {getArtistImage(artist) ? (
                                       <img src={getArtistImage(artist)!} className="w-full h-full object-cover"/>
                                   ) : (
                                       <User size={48} className="text-secondary m-auto h-full p-4"/>
                                   )}
                               </div>
                               <div className="font-bold text-center">{artist}</div>
                               <div className="text-xs text-secondary bg-surface-highlight px-2 py-1 rounded-full">Artist</div>
                           </div>
                       ))}
                   </div>
               </div>
           )}

           {/* Songs Section */}
           {filteredTracks.length > 0 && (
             <div>
                <h2 className="text-xl font-bold mb-4">Songs</h2>
                <div className="flex flex-col gap-2">
                 {filteredTracks.map(track => (
                   <div 
                     key={track.id} 
                     className="flex items-center justify-between p-3 rounded hover:bg-surface-highlight group"
                   >
                     <div className="flex items-center gap-4 flex-1" onClick={() => playTrack(track)}>
                        <div className="relative w-10 h-10">
                          <img src={track.cover} className="w-full h-full object-cover" />
                          <div className="absolute inset-0 bg-black/50 flex items-center justify-center opacity-0 group-hover:opacity-100">
                            <Play size={16} fill="white" />
                          </div>
                        </div>
                        <div>
                          <div className="font-semibold text-white flex items-center gap-2">
                              {track.title}
                              {track.explicit && <span className="text-[8px] border border-secondary text-secondary px-1 rounded bg-surface">E</span>}
                          </div>
                          <div className="text-sm text-secondary">{track.artist}</div>
                        </div>
                     </div>
                     <div className="flex items-center gap-4">
                        <span className="text-sm text-secondary hidden md:block">{Math.floor(track.duration / 60)}:{(track.duration % 60).toString().padStart(2,'0')}</span>
                        <button onClick={() => toggleLike(track.id)} className={`${isLiked(track.id) ? 'text-primary' : 'text-secondary hover:text-white'}`}>
                          <Heart size={18} fill={isLiked(track.id) ? 'currentColor' : 'none'} />
                        </button>
                     </div>
                   </div>
                 ))}
                </div>
             </div>
           )}

           {/* Public Playlists Section */}
           {filteredPlaylists.length > 0 && (
               <div>
                   <h2 className="text-xl font-bold mb-4">Public Playlists</h2>
                   <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-4">
                       {filteredPlaylists.map(pl => {
                            let cover = pl.customCover;
                            if (!cover && pl.tracks.length > 0) {
                                cover = tracks.find(t => t.id === pl.tracks[0])?.cover;
                            }
                            return (
                                <div 
                                    key={pl.id} 
                                    onClick={() => setView({ type: 'PLAYLIST', id: pl.id })}
                                    className="p-4 bg-surface hover:bg-surface-highlight rounded-lg cursor-pointer transition group hover-scale"
                                >
                                    <div className="aspect-square mb-4 shadow-lg flex items-center justify-center rounded-md overflow-hidden bg-surface-highlight relative">
                                        {cover ? (
                                            <img src={cover} alt={pl.name} className="w-full h-full object-cover" />
                                        ) : (
                                            <ListMusic size={32} className="text-secondary" />
                                        )}
                                        {/* Overlay Play Button */}
                                        <div className="absolute bottom-2 right-2 w-10 h-10 bg-primary rounded-full flex items-center justify-center shadow-xl opacity-0 translate-y-2 group-hover:opacity-100 group-hover:translate-y-0 transition-all duration-300">
                                            <Play fill="black" size={20} className="text-black ml-1" />
                                        </div>
                                    </div>
                                    <h3 className="font-bold truncate text-white">{pl.name}</h3>
                                    <p className="text-sm text-secondary truncate">By {pl.creatorName}</p>
                                </div>
                            );
                       })}
                   </div>
               </div>
           )}

           {filteredTracks.length === 0 && filteredPlaylists.length === 0 && filteredArtists.length === 0 && (
                <div className="text-secondary text-lg text-center mt-10">No results found for "{query}"</div>
           )}
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-2 gap-6 animate-appear">
           {/* Genres Tiles */}
           {genres.map(genre => (
             <div 
               key={genre.name} 
               onClick={() => setView({ type: 'GENRE', id: genre.name })}
               className={`aspect-[2/1] ${genre.color} rounded-lg p-6 font-bold text-3xl md:text-4xl relative overflow-hidden cursor-pointer hover:scale-[1.02] transition shadow-lg group`}
             >
                <span className="relative z-10">{genre.name}</span>
                <div className="absolute -bottom-4 -right-8 w-32 h-32 bg-black/20 rotate-[25deg] rounded-lg group-hover:rotate-[30deg] group-hover:scale-110 transition"></div>
             </div>
           ))}
        </div>
      )}
    </div>
  );
};

import React, { createContext, useContext, useEffect, useRef, useState } from 'react';
import { Track, Playlist, Album, ViewState, PlayMode, User, AppSettings, DailyChartTrack, ArtistAccount, ReleaseRequest, ProfileEditRequest, ModeratorAccount } from '../types.ts';
import { generateInitialData, StorageService } from '../services/data.ts';

interface ArtistStats {
  monthlyPlays: number;
  globalRank: number;
}

interface StoreContextType {
  // Auth
  currentUser: User | null;
  login: (username: string, pass: string) => boolean;
  register: (user: Omit<User, 'id'>) => boolean;
  logout: () => void;
  updateUserProfile: (data: Partial<User>) => { success: boolean; message?: string };

  // Settings
  appSettings: AppSettings;
  updateSettings: (settings: Partial<AppSettings>) => void;

  tracks: Track[];
  albums: Album[];
  playlists: Playlist[]; 
  recommendations: Track[];
  recentlyPlayed: Track[];
  followedArtists: string[];
  currentTrack: Track | null;
  isPlaying: boolean;
  playMode: PlayMode;
  isShuffle: boolean;
  volume: number;
  progress: number;
  duration: number;
  view: ViewState;

  // Daily Chart
  dailyChart: DailyChartTrack[];

  // Cover Management
  getAlbumCover: (albumId: string) => string;
  changeAlbumCover: (albumId: string, direction: 'next' | 'prev') => void;

  // Artist Hub / Moderation
  isArtistHubOpen: boolean;
  setArtistHubOpen: (isOpen: boolean) => void;
  currentArtist: ArtistAccount | null;
  currentModerator: ModeratorAccount | null;

  artistAccounts: ArtistAccount[];
  releaseRequests: ReleaseRequest[];
  profileEditRequests: ProfileEditRequest[];

  hasModerator: boolean;
  existingArtists: string[];

  // Artist Actions
  registerArtist: (data: Omit<ArtistAccount, 'id' | 'status'>) => { success: boolean, message?: string };
  registerModerator: (data: ModeratorAccount) => { success: boolean, message?: string };
  loginArtistOrMod: (username: string, pass: string, type: 'ARTIST' | 'MODERATOR') => { success: boolean, message?: string };
  logoutArtistHub: () => void;
  submitRelease: (release: Omit<ReleaseRequest, 'id' | 'status' | 'artistId' | 'artistName' | 'submissionTime'>) => void;
  submitProfileEdit: (edit: Omit<ProfileEditRequest, 'id' | 'status' | 'artistId' | 'artistName'>) => void;
  deleteRelease: (releaseId: string) => void;

  // Mod Actions
  approveArtist: (id: string) => void;
  rejectArtist: (id: string) => void;
  approveRelease: (id: string) => void;
  rejectRelease: (id: string) => void;
  approveProfileEdit: (id: string) => void;
  rejectProfileEdit: (id: string) => void;

  // HUEQ Helper
  getTrackByHueq: (hueq: string) => Track | undefined;

  // Modal States
  isCreatePlaylistOpen: boolean;
  setCreatePlaylistOpen: (isOpen: boolean) => void;
  playlistIdToEdit: string | null; 
  setPlaylistIdToEdit: (id: string | null) => void;

  isMobilePlayerOpen: boolean;
  setMobilePlayerOpen: (isOpen: boolean) => void;

  isAddToPlaylistOpen: boolean;
  trackIdToAdd: string | null;
  openAddToPlaylist: (trackId: string) => void;
  closeAddToPlaylist: () => void;

  isDeleteModalOpen: boolean;
  playlistToDelete: string | null;
  openDeleteModal: (id: string) => void;
  closeDeleteModal: () => void;
  confirmDeletePlaylist: () => void;

  isProfileModalOpen: boolean;
  setProfileModalOpen: (isOpen: boolean) => void;

  // Actions
  setView: (v: ViewState) => void;
  goToArtist: (artistName: string) => void;
  getArtistStats: (artistName: string) => ArtistStats;
  toggleFollowArtist: (artistName: string) => void;
  isArtistFollowed: (artistName: string) => boolean;
  goBack: () => void;
  playTrack: (track: Track) => void;
  togglePlay: () => void;
  nextTrack: () => void;
  prevTrack: () => void;
