                    <button onClick={goBack} className="w-8 h-8 bg-black/50 rounded-full flex items-center justify-center text-white"><ArrowLeft size={20}/></button>
                 </div>
                 <h1 className="text-3xl md:text-5xl font-bold mt-8 mb-4">Huevify Daily Top 25</h1>
                 <p className="text-white/70">Most played tracks in the last 24h. Updates at 21:00 UTC+3.</p>
            </div>
            <div className="px-4 md:px-8 py-4 animate-slide-up">
               {dailyChart.length === 0 ? (
                   <div className="text-secondary text-center py-10">Chart is calculating... check back later.</div>
               ) : (
                   dailyChart.map((track, idx) => {
                       const allArtists = Array.from(new Set([track.artist, ...(track.mainArtists || [])]));

                       return (
                       <div key={track.id} className="grid grid-cols-[30px_1fr_60px] md:grid-cols-[30px_4fr_2fr_1fr_60px] gap-4 px-2 py-3 rounded hover:bg-surface-highlight group items-center">
                            <div className="flex justify-center text-xl font-bold text-secondary">{idx + 1}</div>
                            <div className="flex items-center gap-3 overflow-hidden">
                                 <img src={track.cover} className="w-10 h-10 rounded object-cover" alt="" />
                                 <div className="flex flex-col overflow-hidden">
                                    <span className="text-white font-medium truncate flex items-center gap-2">
                                        {track.title}
                                        {track.explicit && <span className="text-[8px] border border-secondary text-secondary px-1 rounded bg-surface">E</span>}
                                    </span>
                                    <div className="text-xs text-secondary truncate">
                                        {allArtists.map((a, i) => (
                                            <span key={a}>
                                                {i > 0 && ", "}
                                                <span onClick={(e) => { e.stopPropagation(); goToArtist(a); }} className="hover:underline cursor-pointer">{a}</span>
                                            </span>
                                        ))}
                                    </div>
                                 </div>
                            </div>
                            <span className="text-secondary text-sm hidden md:block truncate">{formatPlays(track.dailyPlays)} daily plays</span>
                            <span className="text-secondary text-sm hidden md:block">{formatDuration(track.duration)}</span>
                            <div className="flex items-center gap-3 justify-end">
                                <button onClick={() => toggleLike(track.id)} className={`${isLiked(track.id) ? 'text-primary' : 'text-transparent group-hover:text-secondary hover:text-white'}`}>
                                    <Heart size={16} fill={isLiked(track.id) ? 'currentColor' : 'none'} />
                                </button>
                                <button onClick={() => playTrack(track)} className="text-white"><Play size={20} fill="white"/></button>
                            </div>
                       </div>
                   )})
               )}
            </div>
        </div>
      );
  }

  // --- ARTIST VIEW ---
  if (view.type === 'ARTIST') {
      const artistName = (view as any).id;
      const artistTracks = tracks.filter(t => t.artist === artistName || t.mainArtists?.includes(artistName));
      const topTracks = [...artistTracks].sort((a, b) => b.plays - a.plays).slice(0, 5);
      const artistAlbums = albums.filter(a => a.artist === artistName);

      const { monthlyPlays, globalRank } = getArtistStats(artistName);

      // Get Bio and Pick if available
      const artistAccount = artistAccounts.find(a => a.artistName === artistName && a.status === 'APPROVED');
      const bio = artistAccount?.bio;
      const pick = artistAccount?.artistPick;

      // Only verify if account exists and is approved
      const isVerified = !!artistAccount;

      const isFollowing = isArtistFollowed(artistName);

      return (
        <div className="h-full overflow-y-auto pb-32 relative w-full page-enter">
            {/* Artist Header */}
            <div 
                className="relative h-[40vh] bg-cover bg-center flex items-end p-8 animate-appear"
                style={{ backgroundImage: `linear-gradient(to bottom, rgba(0,0,0,0.2), #121212), url(${artistAccount?.avatar || (artistTracks[0] ? artistTracks[0].cover : '')})` }}
            >
                <div className="absolute top-4 left-4 z-20">
                    <button onClick={goBack} className="w-8 h-8 bg-black/50 rounded-full flex items-center justify-center text-white"><ArrowLeft size={20}/></button>
                </div>
                <div className="relative z-10 w-full">
                    <div className="flex items-center gap-2 mb-2 text-white">
                        {isVerified && (
                            <div className="bg-blue-600 text-white text-[10px] font-bold px-2 py-1 rounded-full flex items-center gap-1">
                                <span className="w-3 h-3 bg-white rounded-full flex items-center justify-center"><i className="block w-1 h-1 bg-blue-600 rounded-full"></i></span>
                                Verified Artist
                            </div>
                        )}
                    </div>
                    <h1 className="text-5xl md:text-8xl font-bold tracking-tight mb-4 drop-shadow-lg">{artistName}</h1>
                    <p className="text-white font-medium text-lg drop-shadow-md">{formatPlays(monthlyPlays)} monthly plays</p>
                </div>
            </div>

            <div className="px-4 md:px-8 py-6 animate-slide-up">
                <div className="flex items-center gap-4 mb-8">
                    <button onClick={() => topTracks.length && playTrack(topTracks[0])} className="w-14 h-14 bg-primary rounded-full flex items-center justify-center hover:scale-105 transition shadow-lg">
                        <Play size={28} fill="black" className="ml-1 text-black" />
                    </button>

                    {/* Follow Button */}
                    <button 
                        onClick={() => toggleFollowArtist(artistName)}
                        className={`px-6 py-1.5 font-bold text-sm rounded-full uppercase tracking-widest border transition ${isFollowing ? 'border-white text-white hover:bg-white/10' : 'border-secondary text-white hover:border-white'}`}
                    >
                        {isFollowing ? 'Following' : 'Follow'}
                    </button>
                </div>

                <div className="flex flex-col md:flex-row gap-8">
                    {/* Main Content */}
                    <div className="flex-1">

                        {/* Artist Pick */}
                        {pick && (
                            <div className="mb-8">
                                <h2 className="text-2xl font-bold mb-4">Artist Pick</h2>
                                <div 
                                    className="flex items-start gap-4 cursor-pointer hover:bg-surface-highlight p-4 rounded transition group bg-surface"
                                    onClick={() => pick.id && setView({ type: pick.type as any, id: pick.id })}
                                >
                                    <img src={pick.image} className="w-20 h-20 rounded object-cover shadow-lg" />
                                    <div className="flex flex-col justify-center">
                                        <div className="flex items-center gap-2 mb-1">
                                            <div className="w-5 h-5 rounded-full overflow-hidden bg-zinc-800">
                                                <img src={artistAccount?.avatar || pick.image} className="w-full h-full object-cover"/>
                                            </div>
                                            <span className="text-xs text-secondary font-bold">Posted By {artistName}</span>
                                        </div>
                                        <div className="font-bold group-hover:underline text-lg">{pick.subtitle}</div>
                                        <div className="text-sm text-secondary">Latest Release</div>
                                    </div>
                                </div>
                            </div>
                        )}

                        <h2 className="text-2xl font-bold mb-4">Popular</h2>
                        <div className="flex flex-col gap-1 mb-8">
                            {topTracks.map((track, idx) => (
                                <div key={track.id} className="grid grid-cols-[20px_1fr_60px] md:grid-cols-[20px_1fr_60px_60px] items-center gap-4 p-2 rounded hover:bg-surface-highlight group cursor-pointer" onClick={() => playTrack(track)}>
                                    <span className="text-secondary text-sm">{idx + 1}</span>
                                    <div className="flex items-center gap-3">
                                        <img src={track.cover} className="w-10 h-10 rounded object-cover" alt=""/>
                                        <span className="font-medium text-white truncate flex items-center gap-2">
                                            {track.title}
                                            {track.explicit && <span className="text-[8px] border border-secondary text-secondary px-1 rounded bg-surface">E</span>}
                                        </span>
                                    </div>
                                    <span className="text-secondary text-sm hidden md:block">{formatPlays(track.plays)}</span>
                                    <span className="text-secondary text-sm text-right">{formatDuration(track.duration)}</span>
                                </div>
                            ))}
                        </div>

                        <h2 className="text-2xl font-bold mb-4">Discography</h2>
                        <div className="flex overflow-x-auto gap-4 pb-4 md:grid md:grid-cols-4 lg:grid-cols-5">
                            {artistAlbums.map(album => (
                                <div key={album.id} onClick={() => setView({type: 'ALBUM', id: album.id})} className="min-w-[140px] md:min-w-0 p-3 bg-surface hover:bg-surface-highlight rounded-md cursor-pointer hover:scale-[1.02] transition flex-col">
                                    <img src={getAlbumCover(album.id)} className="w-full aspect-square object-cover rounded mb-2 shadow-lg" />
                                    <div className="font-bold truncate text-sm">{album.title}</div>
                                    <div className="text-xs text-secondary">{album.year} • {album.type || 'Album'}</div>
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* About Column */}
                    <div className="w-full md:w-1/3">
                        <h2 className="text-2xl font-bold mb-4">About</h2>
                        <div className="bg-surface rounded-lg overflow-hidden relative group cursor-pointer min-h-[300px] hover:scale-[1.02] transition">
                            {/* Use avatar or fallback to first track cover */}
                            <img 
                                src={artistAccount?.avatar || (topTracks[0]?.cover)} 
                                className="w-full h-full object-cover opacity-60 group-hover:opacity-40 transition absolute inset-0 bg-zinc-800" 
                            />

                            <div className="absolute inset-0 p-6 flex flex-col justify-end z-10">
                                <div className="mb-4">
                                    <div className="text-3xl font-bold text-white mb-2">#{globalRank}</div>
                                    <div className="text-sm font-bold uppercase tracking-widest text-white">in the world</div>
                                </div>
                                <p className="text-white font-medium line-clamp-4 text-sm md:text-base drop-shadow-md">
                                    {bio || `Listen to ${artistName} on Huevify. ${artistName} is verified artist.`}
                                </p>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
      )
  }

  // --- Render Album or Playlist Detail ---
  if (view.type === 'PLAYLIST' || view.type === 'ALBUM') {
    let title = "", subtitle = "", cover = "", description = "", items: any[] = [];
    let year: number | undefined = undefined;
    let fullReleaseDate: string | undefined = undefined;
    let label = "";
    let isPlaylist = view.type === 'PLAYLIST';
    let id = (view as any).id;
    let isLikedSongs = id.startsWith('liked');
    let isHistory = id === 'history';
    let isSystem = false;
    let playlistOwnerId: string | undefined;
    let creatorName: string | undefined;
    let creatorAvatar: string | undefined;
    let releaseType = "Album"; // Default
    let hasMultipleCovers = false;
    let allAlbumArtists: string[] = [];
    let currentAlbumObj: any = null;

    if (isPlaylist) {
      if (isHistory) {
         title = "Recently Played";
         subtitle = `${recentlyPlayed.length} tracks`;
         isSystem = true;
         items = recentlyPlayed;
         if (recentlyPlayed.length > 0) cover = recentlyPlayed[0].cover;
         releaseType = "Playlist";
      } else {
          const pl = playlists.find(p => p.id === id);
          if (!pl) {
             return (
                 <div className="flex flex-col items-center justify-center h-full pb-32">
                     <h2 className="text-2xl font-bold mb-4">Playlist not found</h2>
                     <button onClick={() => setView({type:'HOME'})} className="px-6 py-2 bg-white text-black rounded-full font-bold">Return Home</button>
                 </div>
             );
          }
          title = pl.name;
          subtitle = `Playlist • ${pl.tracks.length} songs`;
          description = pl.description || "";
          isSystem = !!pl.isSystem;
          label = "Huevify User Playlist";
          playlistOwnerId = pl.ownerId;
          creatorName = pl.creatorName;
          creatorAvatar = pl.creatorAvatar;
          releaseType = "Playlist";

          if (isLikedSongs) {
          } else if (pl.customCover) {
              cover = pl.customCover;
          } else {
              cover = pl.tracks.length > 0 ? (tracks.find(t => t.id === pl.tracks[0])?.cover || "") : "";
          }
          items = pl.tracks.map(tid => tracks.find(t => t.id === tid)).filter(Boolean);
      }
    } else {
      const alb = albums.find(a => a.id === id);
      if (!alb) return <div>Not Found</div>;
      title = alb.title;
      currentAlbumObj = alb;

      allAlbumArtists = [alb.artist, ...(alb.mainArtists || [])];

      subtitle = `${alb.type || 'Album'} • ${alb.artist}`;
      if (alb.year) subtitle += ` • ${alb.year}`;
      cover = getAlbumCover(alb.id);
      items = alb.trackIds.map(tid => tracks.find(t => t.id === tid)).filter(Boolean);
      year = alb.year;
      fullReleaseDate = alb.releaseDate;
      label = alb.recordLabel || "Huevify Records";
      releaseType = alb.type || "Album";
      hasMultipleCovers = alb.covers.length > 1;
    }

    const totalDurationSeconds = items.reduce((acc, t) => acc + t.duration, 0);
    const totalMinutes = Math.floor(totalDurationSeconds / 60);
    const totalReleasePlays = items.reduce((acc, t) => acc + t.plays, 0);
    const isOwner = currentUser && playlistOwnerId === currentUser.id;

    // --- Empty Liked Songs View ---
    if (isLikedSongs && items.length === 0) {
        return (
            <div className="h-full flex flex-col items-center justify-center pb-32 relative w-full page-enter p-4 text-center">
                 <div className="absolute top-4 left-4 md:top-6 md:left-6 z-20">
                    <button onClick={goBack} className="w-8 h-8 bg-black/50 hover:bg-black/80 rounded-full flex items-center justify-center text-white transition"><ArrowLeft size={20} /></button>
                 </div>
                 <div className="w-24 h-24 bg-gradient-to-br from-indigo-700 to-blue-300 rounded-full flex items-center justify-center mb-6 shadow-xl">
                    <Heart size={48} fill="white" className="text-white" />
                 </div>
                 <h2 className="text-2xl md:text-4xl font-bold mb-4">Songs you like will appear here</h2>
                 <p className="text-secondary mb-8">Save songs by tapping the heart icon.</p>
                 <button 
                    onClick={() => setView({type:'HOME'})} 
                    className="px-8 py-3 bg-white text-black font-bold rounded-full hover:scale-105 transition"
                 >
                    Return Home
                 </button>
            </div>
        );
    }

    return (
      <div className="h-full overflow-y-auto pb-64 relative w-full page-enter">
        {/* Header */}
        <div className="relative p-6 md:p-8 bg-gradient-to-b from-slate-700 to-background animate-appear">
          {/* Back Button */}
          <div className="absolute top-4 left-4 md:top-6 md:left-6 z-20">
            <button 
              onClick={goBack} 
              className="w-8 h-8 bg-black/50 hover:bg-black/80 rounded-full flex items-center justify-center text-white transition"
            >
              <ArrowLeft size={20} />
            </button>
          </div>

          <div className="flex flex-col items-center text-center md:flex-row md:items-end md:text-left gap-6 mt-8 md:mt-8">
            {/* Cover Art Logic */}
            <div 
                className={`w-48 h-48 md:w-56 md:h-56 shadow-2xl shrink-0 flex items-center justify-center bg-surface-highlight overflow-hidden rounded-md animate-appear relative group ${hasMultipleCovers ? 'cursor-pointer' : ''}`}
                onClick={() => { if(hasMultipleCovers) setCoverPickerOpen(true); }}
            >
                {isLikedSongs ? (
                    <div className="w-full h-full bg-gradient-to-br from-indigo-700 to-blue-300 flex items-center justify-center">
                        <Heart size={64} fill="white" className="text-white" />
                    </div>
                ) : isHistory ? (
                    <div className="w-full h-full bg-surface-highlight flex items-center justify-center">
                        <ListMusic size={64} className="text-secondary" />
                    </div>
                ) : cover ? (
                    <>
                        <img src={cover} alt={title} className="w-full h-full object-cover" />

                        {/* Overlay for multiple covers */}
                        {hasMultipleCovers && (
                             <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center transition">
                                 <span className="text-xs font-bold border border-white px-2 py-1 rounded">CHANGE COVER</span>
                             </div>
                        )}
                    </>
                ) : (
                    <ListMusic size={64} className="text-secondary" />
                )}
            </div>

            <div className="flex flex-col gap-2 w-full md:w-auto animate-appear items-center md:items-start">
              <span className="uppercase text-xs font-bold hidden md:block">
                  {releaseType}
              </span>
              <h1 className="text-3xl md:text-7xl font-bold tracking-tighter leading-tight line-clamp-2">
                  {title}
              </h1>
              {description && <p className="text-secondary/80 text-sm md:text-base font-medium">{description}</p>}

              {!isPlaylist && (
                  <div className="flex flex-wrap justify-center md:justify-start items-center gap-1 font-semibold text-sm md:text-base mt-1 text-white">
                      {allAlbumArtists.map((art, idx) => (
                          <span key={art}>
                              {idx > 0 && ", "}
                              <span onClick={() => goToArtist(art)} className="hover:underline cursor-pointer">{art}</span>
                          </span>
                      ))}
                      {year && <span className="text-secondary"> • {year}</span>}
                  </div>
              )}

              {isPlaylist && !isSystem && creatorName && (
                  <div className="flex items-center gap-2 justify-center md:justify-start mt-2">
                      <div className="w-6 h-6 rounded-full bg-zinc-700 overflow-hidden">
                          {creatorAvatar ? <img src={creatorAvatar} className="w-full h-full object-cover" /> : <User size={16} className="text-white m-1" />}
                      </div>
                      <span className="font-bold text-sm hover:underline cursor-pointer">{creatorName}</span>
                  </div>
              )}
            </div>
          </div>
        </div>

        {/* Action Bar */}
        <div className="px-6 md:px-8 py-4 md:py-6 bg-background/50 backdrop-blur-sm sticky top-0 z-30 flex items-center gap-6 animate-appear">
          <button 
             onClick={() => items.length > 0 && playTrack(items[0])}
             className="w-12 h-12 md:w-14 md:h-14 bg-primary rounded-full flex items-center justify-center hover:scale-105 transition shadow-lg"
          >
            <Play size={24} fill="black" className="ml-1 text-black md:w-7 md:h-7" />
          </button>

          {!isPlaylist && (
             <button onClick={() => toggleAlbumLike(id)} className="hover:scale-105 transition">
                <Heart size={32} fill={isAlbumLiked(id) ? '#1ed760' : 'none'} className={isAlbumLiked(id) ? 'text-primary' : 'text-secondary hover:text-white'} />
             </button>
          )}
        </div>

        {/* List */}
        <div className="px-4 md:px-8 animate-slide-up">
           <div className="hidden md:grid grid-cols-[16px_4fr_2fr_1fr_60px] gap-4 px-4 py-2 border-b border-surface-highlight text-secondary text-sm mb-4">
             <span>#</span>
             <span>Title</span>
             <span>Plays</span>
             <span><ListMusic size={16} /></span>
             <span></span>
           </div>

           {items.map((track, idx) => {
               // Logic: If displaying a track inside an Album View, use the Album's cover, not the Track's canonical cover
               // This allows "reused" tracks via HUEQ to show the correct context-aware cover art
               const displayCover = !isPlaylist ? cover : track.cover;

               const albumArtist = !isPlaylist ? (subtitle.split(' • ')[1] || "") : "";
               const showFeatOnMobile = track.artist !== albumArtist;
               const allTrackArtists = Array.from(new Set([track.artist, ...(track.mainArtists || [])]));

               return (
             <div key={track.id} className="grid grid-cols-[16px_1fr_60px] md:grid-cols-[16px_4fr_2fr_1fr_60px] gap-4 px-2 md:px-4 py-3 rounded hover:bg-surface-highlight group items-center">

               <div className="w-4 flex justify-center">
                   <span className="text-secondary group-hover:hidden text-sm">{idx + 1}</span>
                   <button onClick={() => playTrack(track)} className="hidden group-hover:block text-white"><Play size={12} fill="white"/></button>
               </div>

               <div className="flex items-center gap-3 overflow-hidden">
                 <img src={displayCover} className="w-10 h-10 md:hidden rounded object-cover" alt="" />
                 <div className="flex flex-col overflow-hidden">
                   <span className="text-white font-medium truncate flex items-center gap-2">
                      {track.title} 
                      {track.explicit && <span className="text-[8px] border border-secondary text-secondary px-1 rounded bg-surface">E</span>}
                      <span className="md:hidden text-secondary font-normal">
                          {showFeatOnMobile && track.feat ? ` (feat. ${track.feat})` : ''}
                      </span>
                   </span>
                   <div className="md:hidden text-xs text-secondary truncate mt-0.5">
                      {showFeatOnMobile ? track.artist : ""}
                   </div>
                   <div className="hidden md:block text-secondary text-xs group-hover:text-white truncate">
                       {allTrackArtists.map((a, i) => (
                           <span key={a}>
                               {i > 0 && ", "}
                               <span onClick={(e) => { e.stopPropagation(); goToArtist(a); }} className="hover:underline cursor-pointer">{a}</span>
                           </span>
                       ))}
                   </div>
                 </div>
               </div>

               <span className="text-secondary text-sm hidden md:block truncate">{formatPlays(track.plays)}</span>
               <span className="text-secondary text-sm hidden md:block">{formatDuration(track.duration)}</span>

               <div className="flex items-center gap-3 justify-end">
                 <button onClick={() => toggleLike(track.id)} className={`${isLiked(track.id) ? 'text-primary' : 'text-transparent group-hover:text-secondary hover:text-white'}`}>
                    <Heart size={16} fill={isLiked(track.id) ? 'currentColor' : 'none'} />
                 </button>

                 <button onClick={(e) => { e.stopPropagation(); openAddToPlaylist(track.id); }} className="text-transparent group-hover:text-secondary hover:text-white" title="Add to Playlist">
                    <Plus size={16} />
                 </button>

                 {isPlaylist && !isLikedSongs && !isHistory && isOwner && (
                    <button onClick={() => removeFromPlaylist((view as any).id, track.id)} className="text-transparent group-hover:text-secondary hover:text-red-500">
                      <Trash2 size={16} />
                    </button>
                 )}
               </div>
             </div>
           )})}

           {items.length > 0 && (
             <div className="mt-8 pt-8 border-t border-surface-highlight text-secondary text-sm font-medium pb-8 flex flex-col gap-1">
                 {fullReleaseDate && <p>Released {new Date(fullReleaseDate).toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' })}</p>}
                 {!fullReleaseDate && year && <p>Released {year}</p>}
                 <p>{items.length} songs, {totalMinutes} min</p>
                 <p>{formatPlays(totalReleasePlays)} plays</p>
                 <p className="mt-4 text-[10px] uppercase tracking-widest font-bold">© {label}</p>
             </div>
           )}
        </div>

        {/* Cover Picker Modal */}
        {isCoverPickerOpen && currentAlbumObj && (
            <div className="fixed inset-0 bg-black/80 z-[100] flex items-center justify-center p-4">
                <div className="bg-surface w-full max-w-lg rounded-xl p-6 relative animate-zoom-in">
                    <button onClick={() => setCoverPickerOpen(false)} className="absolute top-4 right-4 text-white"><X size={24}/></button>
                    <h2 className="text-xl font-bold mb-4">Choose Album Cover</h2>
                    <p className="text-sm text-secondary mb-4">Select your preferred artwork for this release.</p>

                    <div className="grid grid-cols-2 md:grid-cols-3 gap-4 max-h-[60vh] overflow-y-auto">
                        {currentAlbumObj.covers.map((c: string, idx: number) => (
                            <div 
                                key={idx} 
                                onClick={() => { changeAlbumCover(currentAlbumObj.id, idx); setCoverPickerOpen(false); }}
                                className="cursor-pointer group relative"
                            >
                                <img src={c} className="w-full aspect-square object-cover rounded shadow-lg group-hover:opacity-80 transition" />
                                <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100">
                                    <span className="bg-primary text-black font-bold text-xs px-2 py-1 rounded">SELECT</span>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        )}

      </div>
    );
  }

  // Fallback
  return null;
};

import React, { useState, useRef, useEffect } from 'react';
import { useStore } from '../context/StoreContext.tsx';
import { 
  X, Mic2, Shield, User, UploadCloud, Calendar, FileAudio, 
  CheckCircle, XCircle, Clock, MoreVertical, Image, Plus,
  Edit, ArrowLeft, Camera, LogOut, ChevronDown, Trash2, ListMusic, Check, Search, Play
} from './Icons.tsx';
import { DistributionTrack, ReleaseType, ReleaseRequest } from '../types.ts';

type HubView = 'AUTH' | 'ARTIST_DASH' | 'MOD_DASH' | 'DISTRIBUTION' | 'PROFILE_EDIT' | 'ARTIST_PICK';

const formatDuration = (seconds: number) => {
    const min = Math.floor(seconds / 60);
    const sec = Math.floor(seconds % 60);
    return `${min}:${sec.toString().padStart(2, '0')}`;
};

export const ArtistHub = () => {
  const { 
    isArtistHubOpen, setArtistHubOpen, currentArtist, currentModerator, 
    loginArtistOrMod, registerArtist, registerModerator, logoutArtistHub, artistAccounts,
    releaseRequests, profileEditRequests, approveArtist, rejectArtist,
    approveRelease, rejectRelease, approveProfileEdit, rejectProfileEdit,
    submitRelease, getArtistStats, submitProfileEdit, hasModerator, existingArtists,
    deleteRelease, getTrackByHueq, tracks, albums, playlists
  } = useStore();

  const [view, setView] = useState<HubView>('AUTH');

  // Auth State
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [role, setRole] = useState<'ARTIST' | 'MODERATOR'>('ARTIST');
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");

  // Artist Registration Logic
  const [artistNameSelection, setArtistNameSelection] = useState("");
  const [isCreatingNewArtist, setIsCreatingNewArtist] = useState(false);
  const [newArtistAlias, setNewArtistAlias] = useState("");

  const [message, setMessage] = useState("");

  // Distribution State
  const [distStep, setDistStep] = useState(1);
  const [distTitle, setDistTitle] = useState("");
  const [distType, setDistType] = useState<ReleaseType>('Single');
  const [distGenre, setDistGenre] = useState("Pop");
  const [distLabel, setDistLabel] = useState("");
  const [distCovers, setDistCovers] = useState<string[]>([]);
  const [distMainArtists, setDistMainArtists] = useState<string[]>([]);
  const [distMainArtistInput, setDistMainArtistInput] = useState("");
  const [distTracks, setDistTracks] = useState<DistributionTrack[]>([]);
  const [distDate, setDistDate] = useState("");
  const [distTime, setDistTime] = useState("00:00");
  const [distMsg, setDistMsg] = useState("");

  // Edit Profile State
  const [editBio, setEditBio] = useState("");

  // Artist Pick State
  const [pickSearch, setPickSearch] = useState("");

  // Release Detail Modal State
  const [selectedRelease, setSelectedRelease] = useState<ReleaseRequest | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const coverInputRef = useRef<HTMLInputElement>(null);
  const trackInputRef = useRef<HTMLInputElement>(null);

  if (!isArtistHubOpen) return null;

  const handleLogin = (e: React.FormEvent) => {
      e.preventDefault();
      setMessage("");
      const res = loginArtistOrMod(username, password, role);
      if (res.success) {
          if (role === 'ARTIST') {
              setView('ARTIST_DASH');
              setEditBio(currentArtist?.bio || "");
          }
          else setView('MOD_DASH');
      } else {
          setMessage(res.message || "Login failed");
      }
  };

  const handleRegister = (e: React.FormEvent) => {
      e.preventDefault();

      if (role === 'MODERATOR') {
          if (hasModerator) {
              setMessage("Moderator registration is closed.");
              return;
          }
          const res = registerModerator({ username, password });
          if (res.success) {
              setMessage("Moderator registered! Please login.");
              setAuthMode('LOGIN');
          } else {
              setMessage(res.message || "Error registering moderator");
          }
          return;
      }

      // Artist Registration
      const finalArtistName = isCreatingNewArtist ? newArtistAlias : artistNameSelection;

      if (!finalArtistName) {
          setMessage("Please select or enter an artist name.");
          return;
      }

      const res = registerArtist({
          artistName: finalArtistName, 
          username, 
          password,
          artistPick: undefined
      });

      if (res.success) {
          setMessage("Registration sent for approval.");
          setAuthMode('LOGIN');
      } else {
          setMessage(res.message || "Error registering");
      }
  };

  // --- Distribution Handlers ---
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          // Convert to Base64 for persistence
          const reader = new FileReader();
          reader.onloadend = () => {
              const base64Audio = reader.result as string;

              // Create temp audio element to get duration
              const audio = new Audio(base64Audio);
              audio.onloadedmetadata = () => {
                  const newTrack: DistributionTrack = {
                      title: file.name.replace(/\.[^/.]+$/, ""),
                      explicit: false,
                      mainArtists: [],
                      genre: distGenre, // Default to release genre
                      duration: audio.duration,
                      fileUrl: base64Audio
                  };
                  setDistTracks(prev => [...prev, newTrack]);
              };
          };
          reader.readAsDataURL(file);
      }
  };

  const updateTrack = (idx: number, field: keyof DistributionTrack, val: any) => {
      setDistTracks(prev => {
          const newTracks = [...prev];
          newTracks[idx] = { ...newTracks[idx], [field]: val };
          return newTracks;
      });
  };

  const addTrackMainArtist = (idx: number, artist: string) => {
      if(!artist) return;
      setDistTracks(prev => {
          const newTracks = [...prev];
          const current = newTracks[idx].mainArtists || [];
          if(!current.includes(artist)) {
              newTracks[idx] = { ...newTracks[idx], mainArtists: [...current, artist] };
          }
          return newTracks;
      });
  };

  const removeTrackMainArtist = (trackIdx: number, artistIdx: number) => {
      setDistTracks(prev => {
          const newTracks = [...prev];
          const current = newTracks[trackIdx].mainArtists || [];
          newTracks[trackIdx].mainArtists = current.filter((_, i) => i !== artistIdx);
          return newTracks;
      });
  };

  const handleHueqBlur = (idx: number, hueq: string) => {
      if (!hueq) return;
      const existing = getTrackByHueq(hueq);

      if (existing) {
          // Bulk update to prevent race conditions
          setDistTracks(prev => {
              const newTracks = [...prev];
              newTracks[idx] = {
                  ...newTracks[idx],
                  title: existing.title,
                  explicit: existing.explicit || false,
                  feat: existing.feat || "",
                  existingHueq: hueq,
                  fileUrl: existing.url,
                  duration: existing.duration,
                  genre: existing.genre, // Sync genre
                  mainArtists: existing.mainArtists || []
              };
              return newTracks;
          });
          alert(`HUEQ Found! Track details auto-filled: ${existing.title}`);
      } else {
          // Keep the HUEQ user typed
          updateTrack(idx, 'existingHueq', hueq);
      }
  };

  const handleNextStep = () => {
      if (distStep === 1) {
          if (!distTitle || !distType || !distGenre || distCovers.length === 0) {
              alert("Please complete all required fields (Title, Type, Genre, Covers) marked with *");
              return;
          }
      }
      if (distStep === 2) {
          if (distTracks.length === 0) {
              alert("Please add at least one track.");
              return;
          }
      }
      setDistStep(prev => prev + 1);
  };

  const handleSubmitRelease = () => {
      if (!distDate || !distTime) {
          alert("Please specify Release Date and Time.");
          return;
      }

      const dateTime = new Date(`${distDate}T${distTime}:00+03:00`);

      submitRelease({
          title: distTitle,
          type: distType,
          genre: distGenre,
          label: distLabel || (currentArtist?.artistName || ""),
          covers: distCovers, // Changed to array
          additionalMainArtists: distMainArtists,
          tracks: distTracks,
          releaseDate: dateTime.toISOString(),
          releaseMessage: distMsg
      });

      alert("Release submitted for approval!");
      setView('ARTIST_DASH');
      // Reset
      setDistStep(1); setDistTitle(""); setDistTracks([]); setDistCovers([]); setDistMsg(""); setDistMainArtists([]);
  };

  const handleCoverUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const files = e.target.files;
      if (files && files.length > 0) {
          Array.from(files).forEach((file: File) => {
              const reader = new FileReader();
              reader.onloadend = () => setDistCovers(prev => [...prev, reader.result as string]);
              reader.readAsDataURL(file);
          });
      }
  };

  const handleProfileUpdate = () => {
      if (!currentArtist) return;
      submitProfileEdit({ newBio: editBio });
      alert("Profile update sent for moderation approval.");
      setView('ARTIST_DASH');
  };

  // --- RENDERERS ---

  const renderAuth = () => (
      <div className="w-full max-w-md bg-surface p-8 rounded-xl shadow-2xl border border-surface-highlight animate-zoom-in">
          <div className="flex justify-center mb-6">
              <div className="w-16 h-16 bg-primary/20 rounded-full flex items-center justify-center animate-bounce">
                  {role === 'ARTIST' ? <Mic2 size={32} className="text-primary" /> : <Shield size={32} className="text-primary" />}
              </div>
          </div>
          <h2 className="text-2xl font-bold text-center mb-6">{authMode === 'LOGIN' ? 'Log in to' : 'Join'} Huevify For {role === 'ARTIST' ? 'Artists' : 'Moderators'}</h2>

          <div className="flex bg-surface-highlight p-1 rounded-full mb-6">
              <button 
                  onClick={() => setRole('ARTIST')} 
                  className={`flex-1 py-2 rounded-full text-sm font-bold transition-all duration-300 ${role === 'ARTIST' ? 'bg-primary text-black shadow-lg' : 'text-secondary hover:text-white'}`}
              >
                  Artist
              </button>

              {(!hasModerator || authMode === 'LOGIN') && (
                  <button 
                      onClick={() => setRole('MODERATOR')}
                      className={`flex-1 py-2 rounded-full text-sm font-bold transition-all duration-300 ${role === 'MODERATOR' ? 'bg-primary text-black shadow-lg' : 'text-secondary hover:text-white'}`}
                  >
                      Moderator
                  </button>
              )}
          </div>

          {message && <div className="bg-red-500/20 text-red-500 p-3 rounded mb-4 text-center text-sm animate-pulse">{message}</div>}

          <form onSubmit={authMode === 'LOGIN' ? handleLogin : handleRegister} className="flex flex-col gap-4">

              {authMode === 'REGISTER' && role === 'ARTIST' && (
                  <div className="flex flex-col gap-2 animate-slide-up">
                      {!isCreatingNewArtist ? (
                          <div className="relative">
                              <select 
                                  value={artistNameSelection}
                                  onChange={(e) => setArtistNameSelection(e.target.value)}
                                  className="w-full bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none appearance-none transition-colors"
                              >
                                  <option value="">Select Artist...</option>
                                  {existingArtists.map(a => <option key={a} value={a}>{a}</option>)}
                              </select>
                              <ChevronDown className="absolute right-3 top-3 text-secondary pointer-events-none" size={20}/>
                          </div>
                      ) : (
                          <input 
                              type="text" 
                              placeholder="New Artist Alias" 
                              value={newArtistAlias} 
                              onChange={e => setNewArtistAlias(e.target.value)}
                              className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none transition-colors"
                          />
                      )}

                      <label className="flex items-center gap-2 cursor-pointer mt-1">
                          <input 
                              type="checkbox" 
                              checked={isCreatingNewArtist}
                              onChange={e => setIsCreatingNewArtist(e.target.checked)}
                          />
                          <span className="text-xs text-secondary">Create new artist</span>
                      </label>
                  </div>
              )}

              <input 
                  type="text" placeholder="Username" value={username} onChange={e => setUsername(e.target.value)}
                  className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none transition-colors"
              />
              <input 
                  type="password" placeholder="Password" value={password} onChange={e => setPassword(e.target.value)}
                  className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none transition-colors"
              />

              <button type="submit" className="bg-primary text-black font-bold py-3 rounded-full hover:scale-105 transition-transform mt-2 shadow-lg hover:shadow-primary/20">
                  {authMode === 'LOGIN' ? 'Log In' : 'Submit Application'}
              </button>
          </form>

          <p className="text-center text-secondary text-sm mt-4">
              {authMode === 'LOGIN' ? "Don't have an account?" : "Already have an account?"} 
              <button onClick={() => { setAuthMode(authMode === 'LOGIN' ? 'REGISTER' : 'LOGIN'); setMessage(""); }} className="text-white font-bold ml-1 hover:underline">
                  {authMode === 'LOGIN' ? 'Sign up' : 'Log in'}
              </button>
          </p>
      </div>
  );

  const renderModDash = () => (
      <div className="w-full h-full flex flex-col p-6 relative overflow-y-auto animate-fade-in">
          <div className="flex justify-between items-center mb-8">
              <h1 className="text-3xl font-bold flex items-center gap-3"><Shield className="text-primary"/> Moderator Dashboard</h1>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 pb-16">
              {/* Artist Requests */}
              <div className="bg-surface rounded-xl p-4 flex flex-col border border-surface-highlight max-h-[500px]">
                  <h3 className="font-bold mb-4 flex items-center gap-2 text-primary"><User size={18}/> Pending Artists</h3>
                  <div className="overflow-y-auto flex-1 flex flex-col gap-3">
                      {artistAccounts.filter(a => a.status === 'PENDING').length === 0 && <span className="text-secondary text-sm">No pending requests</span>}
                      {artistAccounts.filter(a => a.status === 'PENDING').map(a => (
                          <div key={a.id} className="p-3 bg-surface-highlight rounded flex justify-between items-center animate-slide-in-bottom">
                              <div>
                                  <div className="font-bold">{a.artistName}</div>
                                  <div className="text-xs text-secondary">@{a.username}</div>
                              </div>
                              <div className="flex gap-2">
                                  <button onClick={() => approveArtist(a.id)} className="text-green-500 hover:scale-110"><CheckCircle size={20}/></button>
                                  <button onClick={() => rejectArtist(a.id)} className="text-red-500 hover:scale-110"><XCircle size={20}/></button>
                              </div>
                          </div>
                      ))}
                  </div>
              </div>

              {/* Release Requests */}
              <div className="bg-surface rounded-xl p-4 flex flex-col border border-surface-highlight max-h-[500px]">
                  <h3 className="font-bold mb-4 flex items-center gap-2 text-primary"><UploadCloud size={18}/> Pending Releases</h3>
                  <div className="overflow-y-auto flex-1 flex flex-col gap-3">
                      {releaseRequests.filter(r => (r.status === 'PENDING' || r.deletionRequested)).length === 0 && <span className="text-secondary text-sm">No pending releases</span>}
                      {releaseRequests.filter(r => (r.status === 'PENDING' || r.deletionRequested)).map(r => (
                          <div key={r.id} className="p-3 bg-surface-highlight rounded flex gap-3 cursor-pointer hover:bg-zinc-800 transition-colors animate-slide-in-bottom items-start" onClick={() => setSelectedRelease(r)}>
                              <img src={r.covers[0]} className="w-12 h-12 rounded object-cover flex-shrink-0" alt=""/>
                              <div className="flex-1 min-w-0 flex flex-col gap-1">
                                  <div className="flex items-center gap-2">
                                      <div className="font-bold truncate">{r.title}</div>
                                      {r.deletionRequested && <span className="text-[10px] bg-red-500 text-white px-1 rounded font-bold">DELETE REQ</span>}
                                  </div>
                                  <div className="text-xs text-secondary truncate">{r.artistName} • {r.type}</div>
                                  <div className="flex gap-2 justify-end mt-1" onClick={e => e.stopPropagation()}>
                                      {r.deletionRequested ? (
                                           <button onClick={() => approveRelease(r.id)} className="text-red-500 hover:text-white text-[10px] font-bold uppercase border border-red-500 px-2 py-0.5 rounded hover:bg-red-500 transition">Confirm Delete</button>
                                      ) : (
                                          <>
                                            <button onClick={() => approveRelease(r.id)} className="text-green-500 hover:text-white text-[10px] font-bold uppercase border border-green-500 px-2 py-0.5 rounded hover:bg-green-500 transition">Approve</button>
                                            <button onClick={() => rejectRelease(r.id)} className="text-red-500 hover:text-white text-[10px] font-bold uppercase border border-red-500 px-2 py-0.5 rounded hover:bg-red-500 transition">Reject</button>
                                          </>
                                      )}
                                  </div>
                              </div>
                          </div>
                      ))}
                  </div>
              </div>

              {/* Profile Edits */}
              <div className="bg-surface rounded-xl p-4 flex flex-col border border-surface-highlight max-h-[500px]">
                  <h3 className="font-bold mb-4 flex items-center gap-2 text-primary"><Edit size={18}/> Profile Edits</h3>
                  <div className="overflow-y-auto flex-1 flex flex-col gap-3">
                      {profileEditRequests.filter(r => r.status === 'PENDING').length === 0 && <span className="text-secondary text-sm">No pending edits</span>}
                      {profileEditRequests.filter(r => r.status === 'PENDING').map(r => (
                          <div key={r.id} className="p-3 bg-surface-highlight rounded flex flex-col gap-2 animate-slide-in-bottom">
                               <div className="font-bold text-sm">{r.artistName} updates</div>
                               {r.newAvatar && <div className="text-xs text-secondary">New Avatar</div>}
                               {r.newBio && <div className="text-xs text-secondary bg-black/20 p-1 rounded italic line-clamp-2">Bio: {r.newBio}</div>}
                               {r.newArtistPick && <div className="text-xs text-secondary bg-black/20 p-1 rounded italic">New Pick: {r.newArtistPick.subtitle}</div>}
                               <div className="flex gap-2 justify-end">
                                  <button onClick={() => approveProfileEdit(r.id)} className="text-green-500 hover:text-white text-xs font-bold uppercase border border-green-500 px-2 py-1 rounded hover:bg-green-500 transition">Approve</button>
                                  <button onClick={() => rejectProfileEdit(r.id)} className="text-red-500 hover:text-white text-xs font-bold uppercase border border-red-500 px-2 py-1 rounded hover:bg-red-500 transition">Reject</button>
                              </div>
                          </div>
                      ))}
                  </div>
              </div>
          </div>

          {/* Log Out Button */}
          <div className="fixed bottom-6 left-6 md:absolute md:bottom-6 md:left-6 z-50">
              <button 
                  onClick={() => { logoutArtistHub(); setView('AUTH'); }} 
                  className="flex items-center gap-2 px-4 py-2 bg-surface-highlight rounded-full text-secondary hover:text-white hover:bg-red-500 hover:text-white transition font-bold shadow-lg"
              >
                  <LogOut size={18} />
                  Log Out
              </button>
          </div>

          {selectedRelease && (
              <div className="absolute inset-0 bg-black/90 z-50 flex items-center justify-center p-4 animate-fade-in">
                  <div className="bg-surface w-full max-w-lg max-h-[80vh] overflow-y-auto rounded-xl p-6 relative animate-zoom-in">
                      <button onClick={() => setSelectedRelease(null)} className="absolute top-4 right-4 text-white"><X size={24}/></button>
                      <h2 className="text-2xl font-bold mb-4">Release Details</h2>
                      <div className="flex gap-4 mb-4">
                          <img src={selectedRelease.covers[0]} className="w-24 h-24 rounded object-cover flex-shrink-0" />
                          <div className="min-w-0">
                              <div className="font-bold text-xl truncate">{selectedRelease.title}</div>
                              <div className="text-secondary">{selectedRelease.type}</div>
                              <div className="text-secondary text-sm">Status: {selectedRelease.status}</div>
                              {selectedRelease.deletionRequested && <div className="text-red-500 font-bold text-xs uppercase">Deletion Pending</div>}
                          </div>
                      </div>
                      <h3 className="font-bold mb-2">Tracks & HUEQ Codes</h3>
                      <div className="flex flex-col gap-2">
                          {selectedRelease.tracks.map((t, i) => (
                              <div key={i} className="bg-surface-highlight p-2 rounded text-sm flex justify-between items-center">
                                  <span className="truncate mr-2">{i+1}. {t.title}</span>
                                  <span className="text-secondary font-mono bg-black/30 px-2 py-0.5 rounded text-xs flex-shrink-0">
                                      {t.generatedHueq || t.existingHueq || (selectedRelease.status === 'LIVE' ? "Generating..." : "Pending Approval")}
                                  </span>
                              </div>
                          ))}
                      </div>
                  </div>
              </div>
          )}
      </div>
  );

  const renderReleaseDetailModal = () => {
      if (!selectedRelease) return null;

      const allMainArtists = [selectedRelease.artistName, ...(selectedRelease.additionalMainArtists || [])];

      return (
          <div className="absolute inset-0 bg-black/90 z-[250] flex justify-center overflow-y-auto p-4 md:p-12 animate-fade-in">
              <div className="bg-background w-full max-w-4xl min-h-full md:min-h-0 md:rounded-xl relative flex flex-col shadow-2xl border border-surface-highlight animate-zoom-in">
                  <button onClick={() => setSelectedRelease(null)} className="absolute top-4 right-4 z-50 text-secondary hover:text-white bg-black/50 rounded-full p-2 hover:scale-110 transition">
                      <X size={24} />
                  </button>

                  <div className="p-6 md:p-8 bg-gradient-to-b from-surface-highlight to-background">
                      <div className="flex flex-col md:flex-row gap-6 items-center md:items-end text-center md:text-left">
                          <img src={selectedRelease.covers[0]} className="w-48 h-48 md:w-56 md:h-56 shadow-2xl rounded-md object-cover shadow-black/50 flex-shrink-0" />
                          <div className="flex flex-col gap-1 w-full min-w-0">
                              <span className="text-xs font-bold uppercase tracking-wider">{selectedRelease.type}</span>
                              <h1 className="text-2xl md:text-5xl font-bold leading-tight break-words">{selectedRelease.title}</h1>
                              <div className="flex flex-wrap justify-center md:justify-start items-center gap-2 mt-2 text-sm font-semibold">
                                  {allMainArtists.map((artist, i) => (
                                      <span key={i} className="flex items-center gap-1">
                                          {i > 0 && "•"} {artist}
                                      </span>
                                  ))}
                              </div>
                              <div className="text-secondary text-xs mt-1">
                                  {selectedRelease.genre} • {new Date(selectedRelease.releaseDate).getFullYear()} • {formatDuration(selectedRelease.tracks.reduce((a,b) => a + b.duration, 0))}
                              </div>
                          </div>
                      </div>
                  </div>

                  <div className="p-4 md:p-8 flex-1">
                      <div className="grid grid-cols-[16px_1fr_1fr] md:grid-cols-[16px_4fr_2fr_1fr] gap-4 text-secondary text-xs uppercase font-bold border-b border-surface-highlight pb-2 mb-4 px-2">
                          <span>#</span>
                          <span>Title</span>
                          <span className="hidden md:block">HUEQ</span>
                          <span className="text-right"><Clock size={14} className="ml-auto"/></span>
                      </div>

                      <div className="flex flex-col">
                          {selectedRelease.tracks.map((track, i) => (
                              <div key={i} className="grid grid-cols-[16px_1fr_1fr] md:grid-cols-[16px_4fr_2fr_1fr] gap-4 px-2 py-3 rounded hover:bg-surface-highlight items-center group text-sm transition-colors">
                                  <span className="text-secondary">{i + 1}</span>
                                  <div className="flex flex-col min-w-0">
                                      <span className="font-medium text-white flex items-center gap-2 truncate">
                                          {track.title}
                                          {track.explicit && <span className="text-[9px] border border-secondary text-secondary px-1 rounded flex-shrink-0">E</span>}
                                      </span>
                                      <span className="text-xs text-secondary truncate">
                                          {[...(track.mainArtists || [])].filter(Boolean).join(", ")}
                                      </span>
                                  </div>
                                  <span className="hidden md:block font-mono text-xs text-secondary select-all truncate">
                                      {track.generatedHueq || track.existingHueq || "---"}
                                  </span>
                                  <span className="text-right text-secondary">
                                      {formatDuration(track.duration)}
                                  </span>
                              </div>
                          ))}
                      </div>

                      <div className="mt-8 pt-8 border-t border-surface-highlight text-xs text-secondary flex flex-col gap-1">
                          <p>Released: {new Date(selectedRelease.releaseDate).toLocaleString()}</p>
                          <p>© {selectedRelease.label}</p>
                          <p>Reference ID: {selectedRelease.id}</p>
                      </div>
                  </div>
              </div>
          </div>
      );
  };

  const renderArtistDash = () => {
    if (!currentArtist) return null;
