import React, { useState, useRef, useEffect } from 'react';
import { useStore } from '../context/StoreContext.tsx';
import { X, LogOut, User as UserIcon, Settings, ChevronRight, ArrowLeft, Camera, Palette, Globe, Zap, Music2, Moon, Play, Mic2, ShieldAlert } from './Icons.tsx';
import { AppSettings } from '../types.ts';

type ModalView = 'MENU' | 'PROFILE_EDIT' | 'APP_SETTINGS';

const COLORS = [
  '#1ed760', // Green (Default)
  '#ec4899', // Pink (Required 2nd)
  '#ef4444', // Red
  '#f97316', // Orange
  '#f59e0b', // Amber
  '#eab308', // Yellow
  '#84cc16', // Lime
  '#10b981', // Emerald
  '#14b8a6', // Teal
  '#06b6d4', // Cyan
  '#0ea5e9', // Sky
  '#3b82f6', // Blue
  '#6366f1', // Indigo
  '#8b5cf6', // Violet
  '#a855f7', // Purple
  '#d946ef', // Fuchsia
];

export const ProfileModal = () => {
  const { isProfileModalOpen, setProfileModalOpen, currentUser, logout, updateUserProfile, appSettings, updateSettings, setArtistHubOpen } = useStore();
  const [view, setView] = useState<ModalView>('MENU');

  // Edit Profile State
  const [editName, setEditName] = useState("");
  const [editUsername, setEditUsername] = useState("");
  const [editPass, setEditPass] = useState("");
  const [editAvatar, setEditAvatar] = useState<string>("");
  const [editMessage, setEditMessage] = useState<{type: 'error' | 'success', text: string} | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Reset state on open
  useEffect(() => {
      if (isProfileModalOpen && currentUser) {
          setView('MENU');
          setEditName(currentUser.displayName);
          setEditUsername(currentUser.username);
          setEditPass(currentUser.password);
          setEditAvatar(currentUser.avatar || "");
          setEditMessage(null);
      }
  }, [isProfileModalOpen, currentUser]);

  if (!isProfileModalOpen || !currentUser) return null;

  const handleOpenArtistHub = () => {
      setProfileModalOpen(false);
      setArtistHubOpen(true);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setEditAvatar(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveProfile = (e: React.FormEvent) => {
      e.preventDefault();
      if (!editName || !editUsername || !editPass) {
          setEditMessage({ type: 'error', text: 'All fields are required' });
          return;
      }

      const result = updateUserProfile({
          displayName: editName,
          username: editUsername,
          password: editPass,
          avatar: editAvatar || undefined
      });

      if (result.success) {
          setEditMessage({ type: 'success', text: 'Profile updated successfully!' });
          setTimeout(() => setEditMessage(null), 2000);
      } else {
          setEditMessage({ type: 'error', text: result.message || 'Error updating profile' });
      }
  };

  const renderMenu = () => (
    <>
        <div className="flex flex-col items-center mb-6">
            <div className="w-24 h-24 rounded-full bg-surface-highlight mb-4 overflow-hidden border-2 border-primary shadow-lg">
                {currentUser.avatar ? (
                    <img src={currentUser.avatar} alt="Profile" className="w-full h-full object-cover" />
                ) : (
                    <div className="w-full h-full flex items-center justify-center bg-zinc-800">
                        <UserIcon size={40} className="text-secondary" />
                    </div>
                )}
            </div>
            <h2 className="text-2xl font-bold">{currentUser.displayName}</h2>
            <p className="text-secondary text-sm">@{currentUser.username}</p>
        </div>

        <div className="flex flex-col gap-3">
            <button 
                onClick={() => setView('PROFILE_EDIT')}
                className="flex items-center justify-between w-full p-4 rounded bg-surface-highlight/50 hover:bg-surface-highlight transition text-left text-white group"
            >
                <div className="flex items-center gap-3">
                    <UserIcon size={20} className="text-secondary group-hover:text-primary transition-colors" />
                    <span className="font-bold">Edit Profile</span>
                </div>
                <ChevronRight size={16} className="text-secondary" />
            </button>

            <button 
                onClick={() => setView('APP_SETTINGS')}
                className="flex items-center justify-between w-full p-4 rounded bg-surface-highlight/50 hover:bg-surface-highlight transition text-left text-white group"
            >
                <div className="flex items-center gap-3">
                    <Settings size={20} className="text-secondary group-hover:text-primary transition-colors" />
                    <span className="font-bold">App Settings</span>
                </div>
                <ChevronRight size={16} className="text-secondary" />
            </button>

            {/* Huevify For Artists Button */}
            <button 
                onClick={handleOpenArtistHub}
                className="flex items-center justify-between w-full p-4 rounded bg-surface-highlight/50 hover:bg-surface-highlight transition text-left text-white group"
            >
                <div className="flex items-center gap-3">
                    <Mic2 size={20} className="text-secondary group-hover:text-primary transition-colors" />
                    <span className="font-bold">Huevify For Artists</span>
                </div>
                <ChevronRight size={16} className="text-secondary" />
            </button>

            <div className="h-px bg-surface-highlight my-2" />

            <button 
                onClick={logout}
                className="flex items-center gap-3 w-full p-4 rounded hover:bg-red-500/10 transition text-left text-white group"
            >
                <LogOut size={20} className="text-secondary group-hover:text-red-500 transition-colors" />
                <span className="font-bold group-hover:text-red-500 transition-colors">Log out</span>
            </button>
        </div>
    </>
  );

  const renderProfileEdit = () => (
      <>
        <div className="flex items-center gap-4 mb-6">
             <button onClick={() => setView('MENU')} className="text-secondary hover:text-white">
                 <ArrowLeft size={24} />
             </button>
             <h2 className="text-xl font-bold">Edit Profile</h2>
        </div>

        <form onSubmit={handleSaveProfile} className="flex flex-col gap-4 overflow-y-auto max-h-[60vh] px-1">
             {editMessage && (
                 <div className={`p-3 rounded text-sm text-center ${editMessage.type === 'success' ? 'bg-green-500/20 text-green-500' : 'bg-red-500/20 text-red-500'}`}>
                     {editMessage.text}
                 </div>
             )}

             <div className="flex justify-center mb-2">
                <div 
                    onClick={() => fileInputRef.current?.click()}
                    className="w-24 h-24 rounded-full bg-surface-highlight flex items-center justify-center cursor-pointer hover:opacity-80 transition relative overflow-hidden group border-2 border-transparent hover:border-primary"
                >
                    {editAvatar ? (
                        <img src={editAvatar} alt="Avatar" className="w-full h-full object-cover" />
                    ) : (
                        <Camera size={32} className="text-secondary" />
                    )}
                    <div className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition">
                        <span className="text-[10px] font-bold text-white">CHANGE</span>
                    </div>
                </div>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileChange} />
            </div>

            <div className="flex flex-col gap-1">
                <label className="text-xs font-bold text-secondary uppercase">Display Name</label>
                <input 
                    type="text" 
                    value={editName} 
                    onChange={e => setEditName(e.target.value)}
                    className="bg-surface-highlight p-3 rounded text-white focus:outline-none focus:ring-1 focus:ring-primary"
                />
            </div>

            <div className="flex flex-col gap-1">
                <label className="text-xs font-bold text-secondary uppercase">Username</label>
                <input 
                    type="text" 
                    value={editUsername} 
                    onChange={e => setEditUsername(e.target.value)}
                    className="bg-surface-highlight p-3 rounded text-white focus:outline-none focus:ring-1 focus:ring-primary"
                />
            </div>

            <div className="flex flex-col gap-1">
                <label className="text-xs font-bold text-secondary uppercase">Password</label>
                <input 
                    type="password" 
                    value={editPass} 
                    onChange={e => setEditPass(e.target.value)}
                    className="bg-surface-highlight p-3 rounded text-white focus:outline-none focus:ring-1 focus:ring-primary"
                />
            </div>

            <button type="submit" className="mt-4 w-full py-3 bg-white text-black font-bold rounded-full hover:scale-105 transition">
                Save Changes
            </button>
        </form>
      </>
  );

  const renderAppSettings = () => (
      <>
        <div className="flex items-center gap-4 mb-6">
             <button onClick={() => setView('MENU')} className="text-secondary hover:text-white">
                 <ArrowLeft size={24} />
             </button>
             <h2 className="text-xl font-bold">App Settings</h2>
        </div>

        <div className="flex flex-col gap-6 overflow-y-auto max-h-[60vh] px-1 pr-2">

            {/* Accent Color */}
            <div>
                <div className="flex items-center gap-2 mb-3">
                    <Palette size={18} className="text-primary" />
                    <h3 className="font-bold">Accent Color</h3>
                </div>
                <div className="grid grid-cols-8 gap-2">
                    {COLORS.map(color => (
                        <button
                            key={color}
                            onClick={() => updateSettings({ accentColor: color })}
                            className={`w-8 h-8 rounded-full border-2 transition hover:scale-110 ${appSettings.accentColor === color ? 'border-white scale-110' : 'border-transparent'}`}
                            style={{ backgroundColor: color }}
                        />
                    ))}
                </div>
            </div>

            {/* Language */}
            <div>
                <div className="flex items-center gap-2 mb-3">
                    <Globe size={18} className="text-primary" />
                    <h3 className="font-bold">Language</h3>
                </div>
                <select 
                    value={appSettings.language}
                    onChange={(e) => updateSettings({ language: e.target.value as any })}
                    className="w-full bg-surface-highlight text-white p-3 rounded focus:outline-none"
                >
                    <option value="English">English</option>
                    <option value="Russian">Russian (Русский)</option>
                </select>
            </div>

            {/* Features */}
            <div>
                <div className="flex items-center gap-2 mb-3">
                    <Zap size={18} className="text-primary" />
                    <h3 className="font-bold">Playback & Content</h3>
                </div>

                <div className="flex flex-col gap-3">
                    <div className="flex items-center justify-between p-3 bg-surface-highlight rounded">
                        <div className="flex items-center gap-3">
                            <ShieldAlert size={20} className="text-secondary" />
                            <div className="flex flex-col">
                                <span className="font-medium">Allow Explicit Content</span>
                                <span className="text-xs text-secondary">Turn off to hide explicit tracks</span>
                            </div>
                        </div>
                        <label className="relative inline-flex items-center cursor-pointer">
                            <input 
                                type="checkbox" 
                                className="sr-only peer" 
                                checked={appSettings.allowExplicitContent}
                                onChange={e => updateSettings({ allowExplicitContent: e.target.checked })}
                            />
                            <div className="w-11 h-6 bg-zinc-700 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-primary"></div>
                        </label>
                    </div>

                    <div className="flex items-center justify-between p-3 bg-surface-highlight rounded">
                        <div className="flex items-center gap-3">
                            <Play size={20} className="text-secondary" />
                            <span className="font-medium">Auto-play</span>
                        </div>
                        <label className="relative inline-flex items-center cursor-pointer">
                            <input 
                                type="checkbox" 
                                className="sr-only peer" 
                                checked={appSettings.autoPlay}
                                onChange={e => updateSettings({ autoPlay: e.target.checked })}
                            />
                            <div className="w-11 h-6 bg-zinc-700 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-primary"></div>
                        </label>
                    </div>
                </div>
            </div>

        </div>
      </>
  );

  return (
    <div className="fixed inset-0 bg-black/80 z-[100] flex items-center justify-center p-4">
      <div className="bg-surface w-full max-w-sm rounded-lg p-6 relative shadow-2xl border border-surface-highlight animate-in fade-in zoom-in duration-200">

        <button 
            onClick={() => setProfileModalOpen(false)}
            className="absolute top-4 right-4 text-secondary hover:text-white z-10"
        >
            <X size={24} />
        </button>

        {view === 'MENU' && renderMenu()}
        {view === 'PROFILE_EDIT' && renderProfileEdit()}
        {view === 'APP_SETTINGS' && renderAppSettings()}

      </div>
    </div>
  );
};

import React from 'react';
import { StoreProvider, useStore } from './context/StoreContext.tsx';
import { Sidebar } from './components/Sidebar.tsx';
import { Player } from './components/Player.tsx';
import { MobileNav } from './components/MobileNav.tsx';
import { FullScreenPlayer } from './components/FullScreenPlayer.tsx';
import { CreatePlaylistModal } from './components/CreatePlaylistModal.tsx';
import { AddToPlaylistModal } from './components/AddToPlaylistModal.tsx';
import { DeletePlaylistModal } from './components/DeletePlaylistModal.tsx';
import { ProfileModal } from './components/ProfileModal.tsx';
import { ArtistHub } from './components/ArtistHub.tsx';
import { Auth } from './components/Auth.tsx';
import { Home } from './pages/Home.tsx';
import { Search } from './pages/Search.tsx';
import { Library } from './pages/Library.tsx';

const MainView = () => {
  const { view } = useStore();

  const renderContent = () => {
    switch (view.type) {
      case 'HOME': return <Home />;
      case 'SEARCH': return <Search />;
      case 'GENRE': return <Search />;
      case 'LIBRARY': return <Library />;
      case 'PLAYLIST': return <Library />;
      case 'ALBUM': return <Library />;
      case 'ARTIST': return <Library />;
      case 'CHARTS': return <Library />;
      default: return <Home />;
    }
  };

  return (
    <div className="flex-1 flex flex-col bg-background min-h-0 overflow-hidden relative">
      {renderContent()}
    </div>
  );
};

const AppContent = () => {
    const { currentUser } = useStore();

    if (!currentUser) {
        return <Auth />;
    }

    return (
        <div className="flex h-screen w-full bg-black text-white font-sans overflow-hidden">
        <Sidebar />
        <main className="flex-1 flex flex-col h-full overflow-hidden relative">
           <div className="h-16 w-full absolute top-0 left-0 bg-gradient-to-b from-black/20 to-transparent z-20 pointer-events-none" />
           <MainView />
           <MobileNav />
        </main>

        {/* Modals and Overlays moved outside of main to ensure correct stacking context */}
        <Player />
        <FullScreenPlayer />
        <CreatePlaylistModal />
        <AddToPlaylistModal />
        <DeletePlaylistModal />
        <ProfileModal />
        <ArtistHub />
      </div>
    );
};

export default function App() {
  return (
    <StoreProvider>
      <AppContent />
    </StoreProvider>
  );
}

import React from 'react';
import { 
  Home, Search, Library, PlusSquare, Heart, Play, Pause, 
  SkipBack, SkipForward, Repeat, Shuffle, Volume2, ListMusic, Trash2, Mic2,
  ArrowLeft, Plus, ChevronDown, Image, X, Check, Edit, MoreHorizontal,
  User, LogOut, Settings, Camera, Upload, Palette, Globe, Zap, ChevronRight, ChevronLeft, Music2, Moon,
  Shield, UploadCloud, Calendar, FileAudio, CheckCircle, XCircle, Clock, MoreVertical, ShieldAlert
} from 'lucide-react';

export { 
  Home, Search, Library, PlusSquare, Heart, Play, Pause, 
  SkipBack, SkipForward, Repeat, Shuffle, Volume2, ListMusic, Trash2, Mic2,
  ArrowLeft, Plus, ChevronDown, Image, X, Check, Edit, MoreHorizontal,
  User, LogOut, Settings, Camera, Upload, Palette, Globe, Zap, ChevronRight, ChevronLeft, Music2, Moon,
  Shield, UploadCloud, Calendar, FileAudio, CheckCircle, XCircle, Clock, MoreVertical, ShieldAlert
};

import React, { useState, useRef, useEffect } from 'react';
import { useStore } from '../context/StoreContext.tsx';
import { 
  X, Mic2, Shield, User, UploadCloud, Calendar, FileAudio, 
  CheckCircle, XCircle, Clock, MoreVertical, Image, Plus,
  Edit, ArrowLeft, Camera, LogOut, ChevronDown, Trash2, ListMusic, Check, Search, Play
} from './Icons.tsx';
import { DistributionTrack, ReleaseType, ReleaseRequest } from '../types.ts';

type HubView = 'AUTH' | 'ARTIST_DASH' | 'MOD_DASH' | 'DISTRIBUTION' | 'PROFILE_EDIT' | 'ARTIST_PICK';

const formatDuration = (seconds: number) => {
    const min = Math.floor(seconds / 60);
    const sec = Math.floor(seconds % 60);
    return `${min}:${sec.toString().padStart(2, '0')}`;
};

export const ArtistHub = () => {
  const { 
    isArtistHubOpen, setArtistHubOpen, currentArtist, currentModerator, 
    loginArtistOrMod, registerArtist, registerModerator, logoutArtistHub, artistAccounts,
    releaseRequests, profileEditRequests, approveArtist, rejectArtist,
    approveRelease, rejectRelease, approveProfileEdit, rejectProfileEdit,
    submitRelease, getArtistStats, submitProfileEdit, hasModerator, existingArtists,
    deleteRelease, getTrackByHueq, tracks, albums, playlists
  } = useStore();

  const [view, setView] = useState<HubView>('AUTH');

  // Auth State
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [role, setRole] = useState<'ARTIST' | 'MODERATOR'>('ARTIST');
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");

  // Artist Registration Logic
  const [artistNameSelection, setArtistNameSelection] = useState("");
  const [isCreatingNewArtist, setIsCreatingNewArtist] = useState(false);
  const [newArtistAlias, setNewArtistAlias] = useState("");

  const [message, setMessage] = useState("");

  // Distribution State
  const [distStep, setDistStep] = useState(1);
  const [distTitle, setDistTitle] = useState("");
  const [distType, setDistType] = useState<ReleaseType>('Single');
  const [distGenre, setDistGenre] = useState("Pop");
  const [distLabel, setDistLabel] = useState("");
  const [distCovers, setDistCovers] = useState<string[]>([]);
  const [distMainArtists, setDistMainArtists] = useState<string[]>([]);
  const [distMainArtistInput, setDistMainArtistInput] = useState("");
  const [distTracks, setDistTracks] = useState<DistributionTrack[]>([]);
  const [distDate, setDistDate] = useState("");
  const [distTime, setDistTime] = useState("00:00");
  const [distMsg, setDistMsg] = useState("");

  // Edit Profile State
  const [editBio, setEditBio] = useState("");

  // Artist Pick State
  const [pickSearch, setPickSearch] = useState("");

  // Release Detail Modal State
  const [selectedRelease, setSelectedRelease] = useState<ReleaseRequest | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const coverInputRef = useRef<HTMLInputElement>(null);
  const trackInputRef = useRef<HTMLInputElement>(null);

  // Initialize view based on login state
  useEffect(() => {
      if (isArtistHubOpen) {
          if (currentArtist) setView('ARTIST_DASH');
          else if (currentModerator) setView('MOD_DASH');
          else setView('AUTH');
      }
  }, [isArtistHubOpen, currentArtist, currentModerator]);

  if (!isArtistHubOpen) return null;

  const handleLogin = (e: React.FormEvent) => {
      e.preventDefault();
      setMessage("");
      const res = loginArtistOrMod(username, password, role);
      if (res.success) {
          if (role === 'ARTIST') {
              setView('ARTIST_DASH');
              setEditBio(currentArtist?.bio || "");
          }
          else setView('MOD_DASH');
      } else {
          setMessage(res.message || "Login failed");
      }
  };

  const handleRegister = (e: React.FormEvent) => {
      e.preventDefault();

      if (role === 'MODERATOR') {
          if (hasModerator) {
              setMessage("Moderator registration is closed.");
              return;
          }
          const res = registerModerator({ username, password });
          if (res.success) {
              setMessage("Moderator registered! Please login.");
              setAuthMode('LOGIN');
          } else {
              setMessage(res.message || "Error registering moderator");
          }
          return;
      }

      // Artist Registration
      const finalArtistName = isCreatingNewArtist ? newArtistAlias : artistNameSelection;

      if (!finalArtistName) {
          setMessage("Please select or enter an artist name.");
          return;
      }

      const res = registerArtist({
          artistName: finalArtistName, 
          username, 
          password,
          artistPick: undefined
      });

      if (res.success) {
          setMessage("Registration sent for approval.");
          setAuthMode('LOGIN');
      } else {
          setMessage(res.message || "Error registering");
      }
  };

  // --- Distribution Handlers ---
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          // Convert to Base64 for persistence
          const reader = new FileReader();
          reader.onloadend = () => {
              const base64Audio = reader.result as string;

              // Create temp audio element to get duration
              const audio = new Audio(base64Audio);
              audio.onloadedmetadata = () => {
                  const newTrack: DistributionTrack = {
                      title: file.name.replace(/\.[^/.]+$/, ""),
                      explicit: false,
                      mainArtists: [],
                      genre: distGenre, // Default to release genre
                      duration: audio.duration,
                      fileUrl: base64Audio
                  };
                  setDistTracks(prev => [...prev, newTrack]);
              };
          };
          reader.readAsDataURL(file);
      }
  };

  const updateTrack = (idx: number, field: keyof DistributionTrack, val: any) => {
      setDistTracks(prev => {
          const newTracks = [...prev];
          newTracks[idx] = { ...newTracks[idx], [field]: val };
          return newTracks;
      });
  };

  const handleHueqBlur = (idx: number, hueq: string) => {
      if (!hueq) return;
      const existing = getTrackByHueq(hueq);

      if (existing) {
          setDistTracks(prev => {
              const newTracks = [...prev];
              newTracks[idx] = {
                  ...newTracks[idx],
                  title: existing.title,
                  explicit: existing.explicit || false,
                  feat: existing.feat || "",
                  existingHueq: hueq,
                  fileUrl: existing.url,
                  duration: existing.duration,
                  genre: existing.genre, // Sync genre
                  mainArtists: existing.mainArtists || []
              };
              return newTracks;
          });
          alert(`HUEQ Found! Track details auto-filled: ${existing.title}`);
      } else {
          updateTrack(idx, 'existingHueq', hueq);
      }
  };

  const handleNextStep = () => {
      if (distStep === 1) {
          if (!distTitle || !distType || !distGenre || distCovers.length === 0) {
              alert("Please complete all required fields (Title, Type, Genre, Covers) marked with *");
              return;
          }
      }
      if (distStep === 2) {
          if (distTracks.length === 0) {
              alert("Please add at least one track.");
              return;
          }
      }
      setDistStep(prev => prev + 1);
  };

  const handleSubmitRelease = () => {
      if (!distDate || !distTime) {
          alert("Please specify Release Date and Time.");
          return;
      }

      const dateTime = new Date(`${distDate}T${distTime}:00+03:00`);

      submitRelease({
          title: distTitle,
          type: distType,
          genre: distGenre,
          label: distLabel || (currentArtist?.artistName || ""),
          covers: distCovers, // Changed to array
          additionalMainArtists: distMainArtists,
          tracks: distTracks,
          releaseDate: dateTime.toISOString(),
          releaseMessage: distMsg
      });

      alert("Release submitted for approval!");
      setView('ARTIST_DASH');
      // Reset
      setDistStep(1); setDistTitle(""); setDistTracks([]); setDistCovers([]); setDistMsg(""); setDistMainArtists([]);
  };

  const handleCoverUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const files = e.target.files;
      if (files && files.length > 0) {
          Array.from(files).forEach((file: File) => {
              const reader = new FileReader();
              reader.onloadend = () => setDistCovers(prev => [...prev, reader.result as string]);
              reader.readAsDataURL(file);
          });
      }
  };

  const handleProfileUpdate = () => {
      if (!currentArtist) return;
      submitProfileEdit({ newBio: editBio });
      alert("Profile update sent for moderation approval.");
      setView('ARTIST_DASH');
  };

  // --- RENDERERS ---

  const renderAuth = () => (
      <div className="w-full max-w-md bg-surface p-8 rounded-xl shadow-2xl border border-surface-highlight animate-zoom-in">
          <div className="flex justify-center mb-6">
              <div className="w-16 h-16 bg-primary/20 rounded-full flex items-center justify-center animate-bounce">
                  {role === 'ARTIST' ? <Mic2 size={32} className="text-primary" /> : <Shield size={32} className="text-primary" />}
              </div>
          </div>
          <h2 className="text-2xl font-bold text-center mb-6">{authMode === 'LOGIN' ? 'Log in to' : 'Join'} Huevify For {role === 'ARTIST' ? 'Artists' : 'Moderators'}</h2>

          <div className="flex bg-surface-highlight p-1 rounded-full mb-6">
              <button 
                  onClick={() => setRole('ARTIST')} 
                  className={`flex-1 py-2 rounded-full text-sm font-bold transition-all duration-300 ${role === 'ARTIST' ? 'bg-primary text-black shadow-lg' : 'text-secondary hover:text-white'}`}
              >
                  Artist
              </button>

              {(!hasModerator || authMode === 'LOGIN') && (
                  <button 
                      onClick={() => setRole('MODERATOR')}
                      className={`flex-1 py-2 rounded-full text-sm font-bold transition-all duration-300 ${role === 'MODERATOR' ? 'bg-primary text-black shadow-lg' : 'text-secondary hover:text-white'}`}
                  >
                      Moderator
                  </button>
              )}
          </div>

          {message && <div className="bg-red-500/20 text-red-500 p-3 rounded mb-4 text-center text-sm animate-pulse">{message}</div>}

          <form onSubmit={authMode === 'LOGIN' ? handleLogin : handleRegister} className="flex flex-col gap-4">

              {authMode === 'REGISTER' && role === 'ARTIST' && (
                  <div className="flex flex-col gap-2 animate-slide-up">
                      {!isCreatingNewArtist ? (
                          <div className="relative">
                              <select 
                                  value={artistNameSelection}
                                  onChange={(e) => setArtistNameSelection(e.target.value)}
                                  className="w-full bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none appearance-none transition-colors"
                              >
                                  <option value="">Select Artist...</option>
                                  {existingArtists.map(a => <option key={a} value={a}>{a}</option>)}
                              </select>
                              <ChevronDown className="absolute right-3 top-3 text-secondary pointer-events-none" size={20}/>
                          </div>
                      ) : (
                          <input 
                              type="text" 
                              placeholder="New Artist Alias" 
                              value={newArtistAlias} 
                              onChange={e => setNewArtistAlias(e.target.value)}
                              className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none transition-colors"
                          />
                      )}

                      <label className="flex items-center gap-2 cursor-pointer mt-1">
                          <input 
                              type="checkbox" 
                              checked={isCreatingNewArtist}
                              onChange={e => setIsCreatingNewArtist(e.target.checked)}
                          />
                          <span className="text-xs text-secondary">Create new artist</span>
                      </label>
                  </div>
              )}

              <input 
                  type="text" placeholder="Username" value={username} onChange={e => setUsername(e.target.value)}
                  className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none transition-colors"
              />
              <input 
                  type="password" placeholder="Password" value={password} onChange={e => setPassword(e.target.value)}
                  className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none transition-colors"
              />

              <button type="submit" className="bg-primary text-black font-bold py-3 rounded-full hover:scale-105 transition-transform mt-2 shadow-lg hover:shadow-primary/20">
                  {authMode === 'LOGIN' ? 'Log In' : 'Submit Application'}
              </button>
          </form>

          <p className="text-center text-secondary text-sm mt-4">
              {authMode === 'LOGIN' ? "Don't have an account?" : "Already have an account?"} 
              <button onClick={() => { setAuthMode(authMode === 'LOGIN' ? 'REGISTER' : 'LOGIN'); setMessage(""); }} className="text-white font-bold ml-1 hover:underline">
                  {authMode === 'LOGIN' ? 'Sign up' : 'Log in'}
              </button>
          </p>
      </div>
  );

  const renderModDash = () => (
      <div className="w-full h-full flex flex-col p-6 relative overflow-y-auto animate-fade-in pb-24">
          <div className="flex justify-between items-center mb-8">
              <h1 className="text-3xl font-bold flex items-center gap-3"><Shield className="text-primary"/> Moderator Dashboard</h1>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {/* Artist Requests */}
              <div className="bg-surface rounded-xl p-4 flex flex-col border border-surface-highlight max-h-[500px]">
                  <h3 className="font-bold mb-4 flex items-center gap-2 text-primary"><User size={18}/> Pending Artists</h3>
                  <div className="overflow-y-auto flex-1 flex flex-col gap-3">
                      {artistAccounts.filter(a => a.status === 'PENDING').length === 0 && <span className="text-secondary text-sm">No pending requests</span>}
                      {artistAccounts.filter(a => a.status === 'PENDING').map(a => (
                          <div key={a.id} className="p-3 bg-surface-highlight rounded flex justify-between items-center animate-slide-in-bottom">
                              <div>
                                  <div className="font-bold">{a.artistName}</div>
                                  <div className="text-xs text-secondary">@{a.username}</div>
                              </div>
                              <div className="flex gap-2">
                                  <button onClick={() => approveArtist(a.id)} className="text-green-500 hover:scale-110"><CheckCircle size={20}/></button>
                                  <button onClick={() => rejectArtist(a.id)} className="text-red-500 hover:scale-110"><XCircle size={20}/></button>
                              </div>
                          </div>
                      ))}
                  </div>
              </div>

              {/* Release Requests */}
              <div className="bg-surface rounded-xl p-4 flex flex-col border border-surface-highlight max-h-[500px]">
                  <h3 className="font-bold mb-4 flex items-center gap-2 text-primary"><UploadCloud size={18}/> Pending Releases</h3>
                  <div className="overflow-y-auto flex-1 flex flex-col gap-3">
                      {releaseRequests.filter(r => (r.status === 'PENDING' || r.deletionRequested)).length === 0 && <span className="text-secondary text-sm">No pending releases</span>}
                      {releaseRequests.filter(r => (r.status === 'PENDING' || r.deletionRequested)).map(r => (
                          <div key={r.id} className="p-3 bg-surface-highlight rounded flex gap-3 cursor-pointer hover:bg-zinc-800 transition-colors animate-slide-in-bottom items-start" onClick={() => setSelectedRelease(r)}>
                              <img src={r.covers[0]} className="w-12 h-12 rounded object-cover flex-shrink-0" alt=""/>
                              <div className="flex-1 min-w-0 flex flex-col gap-1">
                                  <div className="flex items-center gap-2">
                                      <div className="font-bold truncate">{r.title}</div>
                                      {r.deletionRequested && <span className="text-[10px] bg-red-500 text-white px-1 rounded font-bold">DELETE REQ</span>}
                                  </div>
                                  <div className="text-xs text-secondary truncate">{r.artistName} • {r.type}</div>
                                  <div className="flex gap-2 justify-end mt-1" onClick={e => e.stopPropagation()}>
                                      {r.deletionRequested ? (
                                           <button onClick={() => approveRelease(r.id)} className="text-red-500 hover:text-white text-[10px] font-bold uppercase border border-red-500 px-2 py-0.5 rounded hover:bg-red-500 transition">Confirm Delete</button>
                                      ) : (
                                          <>
                                            <button onClick={() => approveRelease(r.id)} className="text-green-500 hover:text-white text-[10px] font-bold uppercase border border-green-500 px-2 py-0.5 rounded hover:bg-green-500 transition">Approve</button>
                                            <button onClick={() => rejectRelease(r.id)} className="text-red-500 hover:text-white text-[10px] font-bold uppercase border border-red-500 px-2 py-0.5 rounded hover:bg-red-500 transition">Reject</button>
                                          </>
                                      )}
                                  </div>
                              </div>
                          </div>
                      ))}
                  </div>
              </div>

              {/* Profile Edits */}
              <div className="bg-surface rounded-xl p-4 flex flex-col border border-surface-highlight max-h-[500px]">
                  <h3 className="font-bold mb-4 flex items-center gap-2 text-primary"><Edit size={18}/> Profile Edits</h3>
                  <div className="overflow-y-auto flex-1 flex flex-col gap-3">
                      {profileEditRequests.filter(r => r.status === 'PENDING').length === 0 && <span className="text-secondary text-sm">No pending edits</span>}
                      {profileEditRequests.filter(r => r.status === 'PENDING').map(r => (
                          <div key={r.id} className="p-3 bg-surface-highlight rounded flex flex-col gap-2 animate-slide-in-bottom">
                               <div className="font-bold text-sm">{r.artistName} updates</div>
                               {r.newAvatar && <div className="text-xs text-secondary">New Avatar</div>}
                               {r.newBio && <div className="text-xs text-secondary bg-black/20 p-1 rounded italic line-clamp-2">Bio: {r.newBio}</div>}
                               {r.newArtistPick && <div className="text-xs text-secondary bg-black/20 p-1 rounded italic">New Pick: {r.newArtistPick.subtitle}</div>}
                               <div className="flex gap-2 justify-end">
                                  <button onClick={() => approveProfileEdit(r.id)} className="text-green-500 hover:text-white text-xs font-bold uppercase border border-green-500 px-2 py-1 rounded hover:bg-green-500 transition">Approve</button>
                                  <button onClick={() => rejectProfileEdit(r.id)} className="text-red-500 hover:text-white text-xs font-bold uppercase border border-red-500 px-2 py-1 rounded hover:bg-red-500 transition">Reject</button>
                              </div>
                          </div>
                      ))}
                  </div>
              </div>
          </div>

          <div className="absolute bottom-6 left-6">
              <button 
                  onClick={() => { logoutArtistHub(); setView('AUTH'); }} 
                  className="flex items-center gap-2 px-4 py-2 bg-surface-highlight rounded-full text-secondary hover:text-white hover:bg-red-500 hover:text-white transition font-bold shadow-lg"
              >
                  <LogOut size={18} />
                  Log Out
              </button>
          </div>
      </div>
  );

  const renderDistribution = () => (
      <div className="w-full max-w-4xl bg-surface p-8 rounded-xl shadow-2xl border border-surface-highlight animate-zoom-in relative max-h-[90vh] overflow-y-auto">
          <button onClick={() => setView('ARTIST_DASH')} className="absolute top-8 left-8 text-secondary hover:text-white"><ArrowLeft size={24}/></button>
          <h2 className="text-3xl font-bold text-center mb-8">New Release</h2>

          {/* Progress Steps */}
          <div className="flex justify-center gap-4 mb-8">
              {[1, 2, 3].map(s => (
                  <div key={s} className={`w-3 h-3 rounded-full ${distStep >= s ? 'bg-primary' : 'bg-surface-highlight'}`} />
              ))}
          </div>

          {distStep === 1 && (
              <div className="flex flex-col gap-6 animate-slide-in-right">
                  <h3 className="text-xl font-bold">Step 1: Release Info</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      <div className="flex flex-col gap-4">
                          <input type="text" placeholder="Release Title *" value={distTitle} onChange={e => setDistTitle(e.target.value)} className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none" />
                          <select value={distType} onChange={e => setDistType(e.target.value as any)} className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none">
                              <option value="Single">Single</option>
                              <option value="EP">EP</option>
                              <option value="Album">Album</option>
                          </select>
                          <input type="text" placeholder="Genre *" value={distGenre} onChange={e => setDistGenre(e.target.value)} className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none" />
                          <input type="text" placeholder="Record Label" value={distLabel} onChange={e => setDistLabel(e.target.value)} className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none" />
                      </div>
                      <div className="flex flex-col gap-4">
                          <div className="border-2 border-dashed border-surface-highlight rounded-lg p-8 flex flex-col items-center justify-center text-center hover:border-primary transition cursor-pointer relative overflow-hidden" onClick={() => coverInputRef.current?.click()}>
                              {distCovers.length > 0 ? (
                                  <div className="grid grid-cols-2 gap-2 w-full">
                                      {distCovers.map((c, i) => <img key={i} src={c} className="w-full aspect-square object-cover rounded shadow"/>)}
                                  </div>
                              ) : (
                                  <>
                                      <Image size={48} className="text-secondary mb-4"/>
                                      <span className="text-secondary text-sm font-bold">Upload Covers *</span>
                                  </>
                              )}
                              <input type="file" multiple ref={coverInputRef} className="hidden" accept="image/*" onChange={handleCoverUpload} />
                          </div>

                          {/* Main Artists */}
                          <div>
                              <label className="text-xs text-secondary font-bold uppercase mb-2 block">Additional Main Artists</label>
                              <div className="flex gap-2">
                                  <input type="text" value={distMainArtistInput} onChange={e => setDistMainArtistInput(e.target.value)} className="flex-1 bg-background p-2 rounded border border-surface-highlight text-sm" placeholder="Artist Name" />
                                  <button onClick={() => { if(distMainArtistInput) { setDistMainArtists([...distMainArtists, distMainArtistInput]); setDistMainArtistInput(""); } }} className="bg-surface-highlight p-2 rounded hover:bg-white hover:text-black"><Plus size={20}/></button>
                              </div>
                              <div className="flex flex-wrap gap-2 mt-2">
                                  {distMainArtists.map((a, i) => (
                                      <span key={i} className="bg-primary/20 text-primary px-2 py-1 rounded text-xs flex items-center gap-1">
                                          {a} <button onClick={() => setDistMainArtists(distMainArtists.filter((_, idx) => idx !== i))}><X size={12}/></button>
                                      </span>
                                  ))}
                              </div>
                          </div>
                      </div>
                  </div>
              </div>
          )}

          {distStep === 2 && (
              <div className="flex flex-col gap-6 animate-slide-in-right">
                  <h3 className="text-xl font-bold">Step 2: Tracks</h3>

                  <div className="flex justify-end">
                      <button onClick={() => fileInputRef.current?.click()} className="flex items-center gap-2 bg-white text-black px-4 py-2 rounded-full font-bold hover:scale-105 transition">
                          <Plus size={18}/> Add Track (Upload Audio)
                      </button>
                      <input type="file" ref={fileInputRef} className="hidden" accept="audio/*" onChange={handleFileUpload} />
                  </div>

                  <div className="flex flex-col gap-4 max-h-[300px] overflow-y-auto">
                      {distTracks.map((track, i) => (
                          <div key={i} className="bg-surface-highlight p-4 rounded flex flex-col gap-3">
                              <div className="flex justify-between items-start">
                                  <div className="flex items-center gap-3">
                                      <div className="w-8 h-8 bg-zinc-800 rounded flex items-center justify-center text-xs font-bold text-secondary">{i+1}</div>
                                      <input 
                                          type="text" 
                                          value={track.title} 
                                          onChange={e => updateTrack(i, 'title', e.target.value)}
                                          className="bg-transparent border-b border-secondary/50 focus:border-white focus:outline-none font-bold text-lg w-full"
                                          placeholder="Track Title"
                                      />
                                  </div>
                                  <button onClick={() => setDistTracks(distTracks.filter((_, idx) => idx !== i))} className="text-red-500 hover:text-red-400"><Trash2 size={20}/></button>
                              </div>

                              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                  <div className="flex items-center gap-2">
                                      <input 
                                          type="text" 
                                          value={track.existingHueq || ""} 
                                          onChange={e => updateTrack(i, 'existingHueq', e.target.value)}
                                          onBlur={e => handleHueqBlur(i, e.target.value)}
                                          placeholder="HUEQ Code (Optional)"
                                          className="bg-black/20 p-2 rounded text-sm w-full font-mono text-secondary focus:text-white focus:outline-none border border-transparent focus:border-primary"
                                      />
                                  </div>
                                  <div className="flex items-center gap-4">
                                      <label className="flex items-center gap-2 cursor-pointer">
                                          <input type="checkbox" checked={track.explicit} onChange={e => updateTrack(i, 'explicit', e.target.checked)} className="rounded text-primary focus:ring-0"/>
                                          <span className="text-xs font-bold uppercase text-secondary">Explicit</span>
                                      </label>
                                      <div className="text-xs text-secondary bg-black/20 px-2 py-1 rounded">{formatDuration(track.duration)}</div>
                                  </div>
                              </div>
                          </div>
                      ))}
                      {distTracks.length === 0 && <div className="text-center text-secondary py-8 border-2 border-dashed border-surface-highlight rounded">No tracks added yet.</div>}
                  </div>
              </div>
          )}

          {distStep === 3 && (
              <div className="flex flex-col gap-6 animate-slide-in-right">
                  <h3 className="text-xl font-bold">Step 3: Schedule</h3>
                  <div className="flex flex-col gap-4 max-w-md mx-auto w-full">
                      <div className="flex flex-col gap-1">
                          <label className="text-xs font-bold text-secondary uppercase">Release Date *</label>
                          <input type="date" value={distDate} onChange={e => setDistDate(e.target.value)} className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none calendar-dark" />
                      </div>
                      <div className="flex flex-col gap-1">
                          <label className="text-xs font-bold text-secondary uppercase">Release Time *</label>
                          <input type="time" value={distTime} onChange={e => setDistTime(e.target.value)} className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none" />
                      </div>
                      <div className="flex flex-col gap-1">
                          <label className="text-xs font-bold text-secondary uppercase">Message to Moderators</label>
                          <textarea value={distMsg} onChange={e => setDistMsg(e.target.value)} className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none h-24 resize-none" placeholder="Optional notes..."></textarea>
                      </div>
                  </div>
              </div>
          )}

          <div className="flex justify-between mt-8 pt-8 border-t border-surface-highlight">
              {distStep > 1 ? (
                  <button onClick={() => setDistStep(distStep - 1)} className="px-6 py-2 rounded-full font-bold text-white hover:bg-white/10 transition">Back</button>
              ) : <div></div>}

              {distStep < 3 ? (
                  <button onClick={handleNextStep} className="px-8 py-2 rounded-full font-bold bg-white text-black hover:scale-105 transition">Next</button>
              ) : (
                  <button onClick={handleSubmitRelease} className="px-8 py-2 rounded-full font-bold bg-primary text-black hover:scale-105 transition shadow-lg shadow-primary/20">Submit Release</button>
              )}
          </div>
      </div>
  );

  const renderProfileEdit = () => (
      <div className="w-full max-w-lg bg-surface p-8 rounded-xl shadow-2xl border border-surface-highlight animate-zoom-in relative">
          <button onClick={() => setView('ARTIST_DASH')} className="absolute top-6 left-6 text-secondary hover:text-white"><ArrowLeft size={24}/></button>
          <h2 className="text-2xl font-bold text-center mb-6">Edit Artist Profile</h2>

          <div className="flex flex-col gap-4">
              <div className="flex flex-col gap-1">
                  <label className="text-xs font-bold text-secondary uppercase">Biography</label>
                  <textarea 
                      value={editBio} 
                      onChange={e => setEditBio(e.target.value)} 
                      className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none h-40 resize-none"
                      placeholder="Tell your story..."
                  />
              </div>
              <button onClick={handleProfileUpdate} className="bg-white text-black font-bold py-3 rounded-full hover:scale-105 transition mt-2">Submit Changes</button>
          </div>
      </div>
  );

  const renderArtistPick = () => {
      const results = !pickSearch ? [] : [
          ...tracks.filter(t => t.title.toLowerCase().includes(pickSearch.toLowerCase())).map(t => ({...t, type: 'TRACK'})),
          ...albums.filter(a => a.title.toLowerCase().includes(pickSearch.toLowerCase())).map(a => ({...a, type: 'ALBUM'})),
      ].slice(0, 10);

      const handlePick = (item: any) => {
          if (!currentArtist) return;
          const pick = {
              type: item.type,
              id: item.id,
              image: item.cover || (item.covers ? item.covers[0] : ""),
              subtitle: item.title
          };
          submitProfileEdit({ newArtistPick: pick as any });
          alert("Artist Pick updated (pending approval)");
          setView('ARTIST_DASH');
      };

      return (
          <div className="w-full max-w-lg bg-surface p-8 rounded-xl shadow-2xl border border-surface-highlight animate-zoom-in relative">
              <button onClick={() => setView('ARTIST_DASH')} className="absolute top-6 left-6 text-secondary hover:text-white"><ArrowLeft size={24}/></button>
              <h2 className="text-2xl font-bold text-center mb-6">Select Artist Pick</h2>

              <div className="relative mb-6">
                  <Search size={20} className="absolute left-3 top-3 text-secondary"/>
                  <input 
                      type="text" 
                      value={pickSearch} 
                      onChange={e => setPickSearch(e.target.value)} 
                      placeholder="Search for a track or album..." 
                      className="w-full bg-background pl-10 pr-4 py-3 rounded-full border border-surface-highlight focus:border-primary focus:outline-none"
                      autoFocus
                  />
              </div>

              <div className="flex flex-col gap-2 max-h-[400px] overflow-y-auto">
                  {results.map((item: any) => (
                      <div key={item.id} onClick={() => handlePick(item)} className="flex items-center gap-3 p-2 hover:bg-surface-highlight rounded cursor-pointer">
                          <img src={item.cover || (item.covers ? item.covers[0] : "")} className="w-10 h-10 rounded object-cover"/>
                          <div className="flex-1 min-w-0">
                              <div className="font-bold truncate">{item.title}</div>
                              <div className="text-xs text-secondary">{item.type} • {item.artist}</div>
                          </div>
                      </div>
                  ))}
                  {pickSearch && results.length === 0 && <div className="text-center text-secondary">No results found.</div>}
              </div>
          </div>
      );
  };

  const renderReleaseDetailModal = () => {
      if (!selectedRelease) return null;

      const allMainArtists = [selectedRelease.artistName, ...(selectedRelease.additionalMainArtists || [])];

      return (
          <div className="absolute inset-0 bg-black/90 z-[250] flex justify-center overflow-y-auto p-4 md:p-12 animate-fade-in">
              <div className="bg-background w-full max-w-4xl min-h-full md:min-h-0 md:rounded-xl relative flex flex-col shadow-2xl border border-surface-highlight animate-zoom-in">
                  <button onClick={() => setSelectedRelease(null)} className="absolute top-4 right-4 z-50 text-secondary hover:text-white bg-black/50 rounded-full p-2 hover:scale-110 transition">
                      <X size={24} />
                  </button>

                  <div className="p-6 md:p-8 bg-gradient-to-b from-surface-highlight to-background">
                      <div className="flex flex-col md:flex-row gap-6 items-center md:items-end text-center md:text-left">
                          <img src={selectedRelease.covers[0]} className="w-48 h-48 md:w-56 md:h-56 shadow-2xl rounded-md object-cover shadow-black/50 flex-shrink-0" />
                          <div className="flex flex-col gap-1 w-full min-w-0">
                              <span className="text-xs font-bold uppercase tracking-wider">{selectedRelease.type}</span>
                              <h1 className="text-2xl md:text-5xl font-bold leading-tight break-words">{selectedRelease.title}</h1>
                              <div className="flex flex-wrap justify-center md:justify-start items-center gap-2 mt-2 text-sm font-semibold">
                                  {allMainArtists.map((artist, i) => (
                                      <span key={i} className="flex items-center gap-1">
                                          {i > 0 && "•"} {artist}
                                      </span>
                                  ))}
                              </div>
                              <div className="text-secondary text-xs mt-1">
                                  {selectedRelease.genre} • {new Date(selectedRelease.releaseDate).getFullYear()} • {formatDuration(selectedRelease.tracks.reduce((a,b) => a + b.duration, 0))}
                              </div>
                          </div>
                      </div>
                  </div>

                  <div className="p-4 md:p-8 flex-1">
                      <div className="grid grid-cols-[16px_1fr_1fr] md:grid-cols-[16px_4fr_2fr_1fr] gap-4 text-secondary text-xs uppercase font-bold border-b border-surface-highlight pb-2 mb-4 px-2">
                          <span>#</span>
                          <span>Title</span>
                          <span className="hidden md:block">HUEQ</span>
                          <span className="text-right"><Clock size={14} className="ml-auto"/></span>
                      </div>

                      <div className="flex flex-col">
                          {selectedRelease.tracks.map((track, i) => (
                              <div key={i} className="grid grid-cols-[16px_1fr_1fr] md:grid-cols-[16px_4fr_2fr_1fr] gap-4 px-2 py-3 rounded hover:bg-surface-highlight items-center group text-sm transition-colors">
                                  <span className="text-secondary">{i + 1}</span>
                                  <div className="flex flex-col min-w-0">
                                      <span className="font-medium text-white flex items-center gap-2 truncate">
                                          {track.title}
                                          {track.explicit && <span className="text-[9px] border border-secondary text-secondary px-1 rounded flex-shrink-0">E</span>}
                                      </span>
                                      <span className="text-xs text-secondary truncate">
                                          {[...(track.mainArtists || [])].filter(Boolean).join(", ")}
                                      </span>
                                  </div>
                                  <span className="hidden md:block font-mono text-xs text-secondary select-all truncate">
                                      {track.generatedHueq || track.existingHueq || "---"}
                                  </span>
                                  <span className="text-right text-secondary">
                                      {formatDuration(track.duration)}
                                  </span>
                              </div>
                          ))}
                      </div>

                      <div className="mt-8 pt-8 border-t border-surface-highlight text-xs text-secondary flex flex-col gap-1">
                          <p>Released: {new Date(selectedRelease.releaseDate).toLocaleString()}</p>
                          <p>© {selectedRelease.label}</p>
                          <p>Reference ID: {selectedRelease.id}</p>
                      </div>
                  </div>
              </div>
          </div>
      );
  };

  const renderArtistDash = () => {
    if (!currentArtist) return null;
    const myReleases = releaseRequests.filter(r => r.artistId === currentArtist.id);
    const stats = getArtistStats(currentArtist.artistName);

    return (
        <div className="w-full h-full flex flex-col p-6 relative overflow-y-auto animate-fade-in pb-24">
            <div className="flex justify-between items-center mb-8">
                <div className="flex items-center gap-4">
                    <div className="w-16 h-16 rounded-full overflow-hidden bg-zinc-800 shadow-lg">
                        {currentArtist.avatar ? <img src={currentArtist.avatar} className="w-full h-full object-cover" /> : <User size={32} className="text-secondary m-auto h-full" />}
                    </div>
                    <div>
                        <h1 className="text-3xl font-bold flex items-center gap-2">{currentArtist.artistName} <CheckCircle size={20} className="text-blue-500" fill="white" /></h1>
                        <p className="text-secondary text-sm">Artist Dashboard</p>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
                <button onClick={() => setView('DISTRIBUTION')} className="bg-primary text-black p-4 rounded-xl flex flex-col items-center justify-center gap-2 hover:scale-105 transition font-bold h-32 shadow-lg hover:shadow-primary/20">
                    <UploadCloud size={32}/>
                    Upload New Release
                </button>
                <button onClick={() => setView('PROFILE_EDIT')} className="bg-surface border border-surface-highlight p-4 rounded-xl flex flex-col items-center justify-center gap-2 hover:bg-surface-highlight transition font-bold h-32 hover:scale-105">
                    <Edit size={32} className="text-secondary"/>
                    Edit Profile
                </button>
                <button onClick={() => setView('ARTIST_PICK')} className="bg-surface border border-surface-highlight p-4 rounded-xl flex flex-col items-center justify-center gap-2 hover:bg-surface-highlight transition font-bold h-32 hover:scale-105">
                    <ListMusic size={32} className="text-secondary"/>
                    Select Artist Pick
                </button>
            </div>

            <h2 className="text-2xl font-bold mb-4">My Releases</h2>

            {/* Desktop Table */}
            <div className="hidden md:block flex-1 overflow-y-auto bg-surface rounded-xl border border-surface-highlight max-h-[400px]">
                <table className="w-full text-left border-collapse">
                    <thead className="bg-surface-highlight text-secondary text-xs uppercase font-bold sticky top-0">
                        <tr>
                            <th className="p-4">Release</th>
                            <th className="p-4">Type</th>
                            <th className="p-4">Date</th>
                            <th className="p-4">Status</th>
                            <th className="p-4 text-right">Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        {myReleases.length === 0 && (
                            <tr>
                                <td colSpan={5} className="p-8 text-center text-secondary">You haven't uploaded any releases yet.</td>
                            </tr>
                        )}
                        {myReleases.map(r => (
                            <tr key={r.id} className="border-b border-surface-highlight hover:bg-white/5 transition cursor-pointer" onClick={() => setSelectedRelease(r)}>
                                <td className="p-4 flex items-center gap-3">
                                    <img src={r.covers[0]} className="w-10 h-10 rounded object-cover shadow-sm flex-shrink-0" />
                                    <span className="font-bold">{r.title}</span>
                                </td>
                                <td className="p-4 text-sm text-secondary">{r.type}</td>
                                <td className="p-4 text-sm text-secondary">{new Date(r.releaseDate).toLocaleDateString()}</td>
                                <td className="p-4">
                                    <span className={`px-2 py-1 rounded text-xs font-bold uppercase ${
                                        r.status === 'LIVE' ? 'bg-green-500/20 text-green-500' :
                                        r.status === 'APPROVED' ? 'bg-blue-500/20 text-blue-500' :
                                        r.status === 'REJECTED' ? 'bg-red-500/20 text-red-500' :
                                        'bg-yellow-500/20 text-yellow-500'
                                    }`}>
                                        {r.deletionRequested ? "DELETION PENDING" : r.status}
                                    </span>
                                </td>
                                <td className="p-4 text-right">
                                    <button onClick={(e) => { e.stopPropagation(); deleteRelease(r.id); }} className="text-secondary hover:text-red-500 transition hover:scale-110">
                                        <Trash2 size={18}/>
                                    </button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            {/* Mobile List */}
            <div className="md:hidden flex flex-col gap-3 pb-20">
                {myReleases.length === 0 && <div className="text-center text-secondary">No releases yet.</div>}
                {myReleases.map(r => (
                    <div key={r.id} className="bg-surface p-4 rounded-lg flex items-center gap-4 cursor-pointer active:scale-95 transition items-start" onClick={() => setSelectedRelease(r)}>
                        <img src={r.covers[0]} className="w-16 h-16 rounded object-cover shadow-sm flex-shrink-0" />
                        <div className="flex-1 min-w-0">
                            <div className="font-bold text-lg truncate">{r.title}</div>
                            <div className="text-sm text-secondary truncate">{r.type} • {new Date(r.releaseDate).toLocaleDateString()}</div>
                            <div className={`text-xs font-bold mt-1 uppercase ${
                                r.status === 'LIVE' ? 'text-green-500' :
                                r.status === 'APPROVED' ? 'text-blue-500' :
                                r.status === 'REJECTED' ? 'text-red-500' :
                                'text-yellow-500'
                            }`}>{r.deletionRequested ? "DELETION PENDING" : r.status}</div>
                        </div>
                        <button onClick={(e) => { e.stopPropagation(); deleteRelease(r.id); }} className="text-secondary hover:text-red-500">
                            <Trash2 size={20}/>
                        </button>
                    </div>
                ))}
            </div>

             {/* Log Out Button */}
            <div className="fixed bottom-6 left-6 md:absolute md:bottom-6 md:left-6 z-50">
                <button 
                    onClick={() => { logoutArtistHub(); setView('AUTH'); }} 
                    className="flex items-center gap-2 px-4 py-2 bg-surface-highlight rounded-full text-secondary hover:text-white hover:bg-red-500 hover:text-white transition font-bold shadow-lg"
                >
                    <LogOut size={18} />
                    Log Out
                </button>
            </div>
        </div>
    );
  };

  return (
    <div className="fixed inset-0 bg-background z-[200] overflow-y-auto animate-in fade-in">
       {/* Close Button */}
       <button 
          onClick={() => setArtistHubOpen(false)} 
          className="absolute top-6 right-6 z-50 text-secondary hover:text-white bg-black/50 rounded-full p-2"
       >
          <X size={32} />
       </button>

       <div className="min-h-full flex flex-col items-center justify-center p-4">
           {view === 'AUTH' && renderAuth()}
           {view === 'ARTIST_DASH' && renderArtistDash()}
           {view === 'MOD_DASH' && renderModDash()}
           {view === 'DISTRIBUTION' && renderDistribution()}
           {view === 'PROFILE_EDIT' && renderProfileEdit()}
           {view === 'ARTIST_PICK' && renderArtistPick()}
       </div>

       {renderReleaseDetailModal()}
    </div>
  );
};

export interface Track {
  id: string;
  title: string;
  artist: string;
  album: string;
  cover: string; // Keep for track display consistency, usually points to active album cover
  duration: number; // in seconds
  url: string; // audio source
  plays: number;
  genre: string; // New field for recommendations
  explicit?: boolean;
  feat?: string;
  hueq?: string; // ISRC equivalent
  mainArtists?: string[]; // Array of additional main artists
}

export interface DailyChartTrack extends Track {
  dailyPlays: number;
}

export interface Playlist {
  id: string;
  name: string;
  description?: string;
  customCover?: string; // Base64 or URL
  tracks: string[]; // array of track IDs
  isSystem?: boolean; // e.g. "Liked Songs"
  ownerId?: string; // ID of the user who created this playlist

  // New fields for Public/Private feature
  isPublic?: boolean;
  creatorName?: string;
  creatorAvatar?: string;
  savedBy?: string[]; // Array of User IDs who added this playlist to their library
}

export interface Album {
  id: string;
  title: string;
  artist: string;
  covers: string[]; // Changed from single cover to array
  trackIds: string[];
  year: number;
  releaseDate?: string; // ISO string for full date display
  recordLabel?: string;
  type?: ReleaseType;
  mainArtists?: string[]; // Added at album level for better display
}

export interface User {
  id: string;
  username: string;
  password: string; // Stored locally for this prototype
  displayName: string;
  avatar?: string; // Base64
}

export interface AppSettings {
  accentColor: string;
  language: 'English' | 'Russian';
  allowExplicitContent: boolean; // Replaced High Quality Audio
  autoPlay: boolean;
  crossfade: number; // seconds
  albumCoverIndexes: Record<string, number>; // Stores user preference for album covers
}

export type ViewState = 
  | { type: 'HOME' }
  | { type: 'SEARCH' }
  | { type: 'LIBRARY' }
  | { type: 'PLAYLIST'; id: string }
  | { type: 'ALBUM'; id: string }
  | { type: 'ARTIST'; id: string }
  | { type: 'CHARTS' }
  | { type: 'GENRE'; id: string };

export enum PlayMode {
  OFF = 'OFF',
  CONTEXT = 'CONTEXT', // Repeat Playlist/Album
  ONE = 'ONE', // Repeat One Track
}

// --- ARTIST HUB TYPES ---

export type ArtistVerificationStatus = 'PENDING' | 'APPROVED' | 'REJECTED';

export interface ArtistAccount {
  id: string; // Unique ID for the account
  artistName: string; // Displays as the Artist Name in app
  username: string; // Login username
  password: string; 
  avatar?: string;
  bio?: string; // Artist Description
  status: ArtistVerificationStatus;
  artistPick?: {
    type: 'TRACK' | 'ALBUM' | 'PLAYLIST';
    id: string;
    image?: string;
    subtitle?: string;
  };
}

export interface ModeratorAccount {
  username: string;
  password: string;
}

export interface DistributionTrack {
  title: string;
  explicit: boolean;
  feat?: string; // Featured artists
  mainArtists?: string[]; // Additional main artists
  genre?: string; // Track specific genre
  fileUrl: string; // Mocked for prototype
  duration: number;
  existingHueq?: string; // If user inputs an existing code
  generatedHueq?: string; // Assigned by system on approval
}

export type ReleaseType = 'Single' | 'Album' | 'EP' | 'Mixtape';

export interface ReleaseRequest {
  id: string;
  artistId: string;
  artistName: string;
  status: 'PENDING' | 'APPROVED' | 'REJECTED' | 'LIVE';
  submissionTime?: string; // ISO String
  deletionRequested?: boolean; // New: For moderation deletion flow

  // Info
  title: string;
  type: ReleaseType;
  genre: string;
  label: string;
  covers: string[]; // Array of covers
  additionalMainArtists?: string[];

  // Tracks
  tracks: DistributionTrack[];

  // Schedule
  releaseDate: string; // ISO String
  releaseMessage?: string;
}

export interface ProfileEditRequest {
  id: string;
  artistId: string;
  artistName: string;
  newAvatar?: string;
  newBio?: string;
  newArtistPick?: ArtistAccount['artistPick'];
  status: 'PENDING' | 'APPROVED' | 'REJECTED';
}

export interface AppNotification {
  id: string;
  message: string;
  type: 'error' | 'success' | 'info';
}

import React, { createContext, useContext, useEffect, useRef, useState } from 'react';
import { Track, Playlist, Album, ViewState, PlayMode, User, AppSettings, DailyChartTrack, ArtistAccount, ReleaseRequest, ProfileEditRequest, ModeratorAccount, AppNotification } from '../types.ts';
import { generateInitialData, StorageService } from '../services/data.ts';

interface ArtistStats {
  monthlyPlays: number;
  globalRank: number;
}

interface StoreContextType {
  // Auth
  currentUser: User | null;
  login: (username: string, pass: string) => boolean;
  register: (user: Omit<User, 'id'>) => boolean;
  logout: () => void;
  updateUserProfile: (data: Partial<User>) => { success: boolean; message?: string };

  // Settings
  appSettings: AppSettings;
  updateSettings: (settings: Partial<AppSettings>) => void;

  tracks: Track[];
  albums: Album[];
  playlists: Playlist[]; 
  likedPlaylistId: string; // Helper for dynamic ID
  recommendations: Track[];
  recentlyPlayed: Track[];
  followedArtists: string[];
  currentTrack: Track | null;
  isPlaying: boolean;
  playMode: PlayMode;
  isShuffle: boolean;
  volume: number;
  progress: number;
  duration: number;
  view: ViewState;

  // Notification
  notifications: AppNotification[];
  showNotification: (message: string, type?: 'error' | 'success' | 'info') => void;
  dismissNotification: (id: string) => void;

  // Daily Chart
  dailyChart: DailyChartTrack[];

  // Cover Management
  getAlbumCover: (albumId: string) => string;
  changeAlbumCover: (albumId: string, index: number) => void;

  // Artist Hub / Moderation
  isArtistHubOpen: boolean;
  setArtistHubOpen: (isOpen: boolean) => void;
  currentArtist: ArtistAccount | null;
  currentModerator: ModeratorAccount | null;

  artistAccounts: ArtistAccount[];
  releaseRequests: ReleaseRequest[];
  profileEditRequests: ProfileEditRequest[];

  hasModerator: boolean;
  existingArtists: string[];

  // Artist Actions
  registerArtist: (data: Omit<ArtistAccount, 'id' | 'status'>) => { success: boolean, message?: string };
  registerModerator: (data: ModeratorAccount) => { success: boolean, message?: string };
  loginArtistOrMod: (username: string, pass: string, type: 'ARTIST' | 'MODERATOR') => { success: boolean, message?: string };
  logoutArtistHub: () => void;
  submitRelease: (release: Omit<ReleaseRequest, 'id' | 'status' | 'artistId' | 'artistName' | 'submissionTime'>) => void;
  submitProfileEdit: (edit: Omit<ProfileEditRequest, 'id' | 'status' | 'artistId' | 'artistName'>) => void;
  deleteRelease: (releaseId: string) => void;

  // Mod Actions
  approveArtist: (id: string) => void;
  rejectArtist: (id: string) => void;
  approveRelease: (id: string) => void;
  rejectRelease: (id: string) => void;
  approveProfileEdit: (id: string) => void;
  rejectProfileEdit: (id: string) => void;

  // HUEQ Helper
  getTrackByHueq: (hueq: string) => Track | undefined;

  // Modal States
  isCreatePlaylistOpen: boolean;
  setCreatePlaylistOpen: (isOpen: boolean) => void;
  playlistIdToEdit: string | null; 
  setPlaylistIdToEdit: (id: string | null) => void;

  isMobilePlayerOpen: boolean;
  setMobilePlayerOpen: (isOpen: boolean) => void;

  isAddToPlaylistOpen: boolean;
  trackIdToAdd: string | null;
  openAddToPlaylist: (trackId: string) => void;
  closeAddToPlaylist: () => void;

  isDeleteModalOpen: boolean;
  playlistToDelete: string | null;
  openDeleteModal: (id: string) => void;
  closeDeleteModal: () => void;
  confirmDeletePlaylist: () => void;

  isProfileModalOpen: boolean;
  setProfileModalOpen: (isOpen: boolean) => void;

  // Actions
  setView: (v: ViewState) => void;
  goToArtist: (artistName: string) => void;
  getArtistStats: (artistName: string) => ArtistStats;
  toggleFollowArtist: (artistName: string) => void;
  isArtistFollowed: (artistName: string) => boolean;
  goBack: () => void;
  playTrack: (track: Track) => void;
  togglePlay: () => void;
  nextTrack: () => void;
  prevTrack: () => void;
  seek: (time: number) => void;
  setVolume: (vol: number) => void;
  toggleRepeat: () => void;
  toggleShuffle: () => void;

  createPlaylist: (name: string, description?: string, cover?: string, isPublic?: boolean) => void;
  editPlaylist: (id: string, name: string, description?: string, cover?: string, isPublic?: boolean) => void;
  deletePlaylist: (id: string) => void; 
  addToPlaylist: (playlistId: string, trackId: string) => void;
  removeFromPlaylist: (playlistId: string, trackId: string) => void;
  togglePlaylistSave: (playlistId: string) => void; 

  toggleLike: (trackId: string) => void;
  isLiked: (trackId: string) => boolean;
  toggleAlbumLike: (albumId: string) => void;
  isAlbumLiked: (albumId: string) => boolean;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

// Helper to generate HUEQ: 000XX0
const generateHUEQ = (): string => {
    const randomDigit = () => Math.floor(Math.random() * 10);
    const randomChar = () => String.fromCharCode(65 + Math.floor(Math.random() * 26)); // A-Z
    return `${randomDigit()}${randomDigit()}${randomDigit()}${randomChar()}${randomChar()}${randomDigit()}`;
};

export const StoreProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  // --- Auth State ---
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  // --- Settings State ---
  const [appSettings, setAppSettingsState] = useState<AppSettings>({
    accentColor: '#1ed760',
    language: 'English',
    allowExplicitContent: true, // Default to true
    autoPlay: true,
    crossfade: 0,
    albumCoverIndexes: {}
  });

  // --- Data State ---
  const [tracks, setTracks] = useState<Track[]>([]);
  const [albums, setAlbums] = useState<Album[]>([]);
  const [playlists, setPlaylists] = useState<Playlist[]>([]);
  const [recommendations, setRecommendations] = useState<Track[]>([]);
  const [recentlyPlayed, setRecentlyPlayed] = useState<Track[]>([]);
  const [likedAlbumIds, setLikedAlbumIds] = useState<string[]>([]);
  const [followedArtists, setFollowedArtists] = useState<string[]>([]);

  const [dailyChart, setDailyChart] = useState<DailyChartTrack[]>([]);
  const [notifications, setNotifications] = useState<AppNotification[]>([]);

  // --- Artist Hub State ---
  const [isArtistHubOpen, setArtistHubOpen] = useState(false);
  const [currentArtist, setCurrentArtist] = useState<ArtistAccount | null>(null);
  const [currentModerator, setCurrentModerator] = useState<ModeratorAccount | null>(null);
  const [artistAccounts, setArtistAccounts] = useState<ArtistAccount[]>([]);
  const [releaseRequests, setReleaseRequests] = useState<ReleaseRequest[]>([]);
  const [profileEditRequests, setProfileEditRequests] = useState<ProfileEditRequest[]>([]);
  const [hasModerator, setHasModerator] = useState(false);
  const [existingArtists, setExistingArtists] = useState<string[]>([]);

  // --- Player State ---
  const [currentTrack, setCurrentTrack] = useState<Track | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [playMode, setPlayMode] = useState<PlayMode>(PlayMode.OFF);
  const [isShuffle, setIsShuffle] = useState(false);
  const [volume, setVolumeState] = useState(0.5);
  const [progress, setProgress] = useState(0);
  const [duration, setDuration] = useState(0);
  const [hasCountedListen, setHasCountedListen] = useState(false);

  // --- UI State ---
  const [view, setViewInternal] = useState<ViewState>({ type: 'HOME' });
  const [history, setHistory] = useState<ViewState[]>([]);

  // Modals
  const [isCreatePlaylistOpen, setCreatePlaylistOpen] = useState(false);
  const [playlistIdToEdit, setPlaylistIdToEdit] = useState<string | null>(null);
  const [isMobilePlayerOpen, setMobilePlayerOpen] = useState(false);
  const [isAddToPlaylistOpen, setAddToPlaylistOpen] = useState(false);
  const [trackIdToAdd, setTrackIdToAdd] = useState<string | null>(null);
  const [isProfileModalOpen, setProfileModalOpen] = useState(false);

  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [playlistToDelete, setPlaylistToDelete] = useState<string | null>(null);

  // --- Refs ---
  const audioRef = useRef<HTMLAudioElement>(new Audio());
  const cumulativeTimeRef = useRef(0);
  const lastTimeRef = useRef(0);

  // Helper ID
  const likedPlaylistId = currentUser ? `liked_${currentUser.id}` : 'liked';

  const showNotification = (message: string, type: 'error' | 'success' | 'info' = 'info') => {
      const id = Date.now().toString();
      setNotifications(prev => [...prev, { id, message, type }]);
      setTimeout(() => dismissNotification(id), 5000);
  };

  const dismissNotification = (id: string) => {
      setNotifications(prev => prev.filter(n => n.id !== id));
  };

  // --- Automated Play Count System ---
  useEffect(() => {
    const interval = setInterval(() => {
        const now = new Date();
        if (now.getMinutes() === 30) {
             const currentHour = now.getHours();
             const lastUpdateHour = StorageService.load('huevify_last_play_update_hour', -1);

             if (lastUpdateHour !== currentHour) {
                 setTracks(prevTracks => {
                     const updated = prevTracks.map(t => {
                         let add = 0;
                         if (t.plays <= 10000) {
                             add = Math.floor(Math.random() * 1000) + 1;
                         } else if (t.plays <= 50000) {
                             add = Math.floor(Math.random() * 9900) + 100;
                         } else {
                             add = Math.floor(Math.random() * 24000) + 1000;
                         }
                         return { ...t, plays: t.plays + add };
                     });
                     const playCounts = updated.reduce((acc, t) => ({ ...acc, [t.id]: t.plays }), {});
                     StorageService.save('huevify_plays', playCounts);
                     return updated;
                 });
                 StorageService.save('huevify_last_play_update_hour', currentHour);
             }
        }
    }, 10000); 
    return () => clearInterval(interval);
  }, []); 

  // --- Logic to Refresh Library (Merge Static + Dynamic Data) ---
  const refreshLibrary = (requests: ReleaseRequest[]) => {
      const { tracks: initialTracks, albums: initialAlbums } = generateInitialData();
      const storedPlays = StorageService.load<Record<string, number>>('huevify_plays', {});

      let mergedTracks = [...initialTracks];
      let mergedAlbums = [...initialAlbums];
      const artistSet = new Set(initialAlbums.map(a => a.artist));

      requests.forEach(req => {
          const isLive = req.status === 'LIVE';
          const isApprovedAndDue = req.status === 'APPROVED' && new Date(req.releaseDate).getTime() <= Date.now();

          if (isLive || isApprovedAndDue) {
              artistSet.add(req.artistName);
              if (req.additionalMainArtists) {
                  req.additionalMainArtists.forEach(a => artistSet.add(a));
              }

              const albumId = `dist_alb_${req.id}`;
              if (!mergedAlbums.find(a => a.id === albumId)) {
                  const newAlbum: Album = {
                      id: albumId,
                      title: req.title,
                      artist: req.artistName,
                      covers: req.covers.length > 0 ? req.covers : ["https://picsum.photos/300"],
                      trackIds: [],
                      year: new Date(req.releaseDate).getFullYear(),
                      releaseDate: req.releaseDate, 
                      recordLabel: req.label,
                      type: req.type,
                      mainArtists: req.additionalMainArtists || [] 
                  };

                  req.tracks.forEach((t, idx) => {
                      let trackId: string;
                      let existingTrack: Track | undefined;

                      if (t.existingHueq) {
                           existingTrack = mergedTracks.find(mt => mt.hueq === t.existingHueq);
                      }

                      if (existingTrack) {
                          trackId = existingTrack.id;
                          const trackIndex = mergedTracks.findIndex(tr => tr.id === trackId);
                          if (trackIndex !== -1) {
                              mergedTracks[trackIndex] = {
                                  ...mergedTracks[trackIndex],
                                  genre: t.genre || req.genre || mergedTracks[trackIndex].genre,
                                  explicit: t.explicit,
                              };
                          }
                      } else {
                          trackId = `dist_trk_${req.id}_${idx}`;
                          const releaseLevelArtists = req.additionalMainArtists || [];
                          const trackLevelArtists = t.mainArtists || [];
                          const combinedMainArtists = Array.from(new Set([...releaseLevelArtists, ...trackLevelArtists]));

                          mergedTracks.push({
                              id: trackId,
                              title: t.title,
                              artist: req.artistName,
                              album: req.title,
                              cover: req.covers[0], 
                              duration: t.duration, 
                              url: t.fileUrl, 
                              plays: 0,
                              genre: t.genre || req.genre,
                              explicit: t.explicit,
                              feat: t.feat,
                              hueq: t.generatedHueq || t.existingHueq,
                              mainArtists: combinedMainArtists
                          });
                      }

                      newAlbum.trackIds.push(trackId);
                  });
                  mergedAlbums.push(newAlbum);
              }
          }
      });

      const tracksWithPlays = mergedTracks.map(t => ({
          ...t,
          plays: storedPlays[t.id] !== undefined ? storedPlays[t.id] : t.plays
      }));

      setTracks(tracksWithPlays);
      setAlbums(mergedAlbums);
      setExistingArtists(Array.from(artistSet));
  };

  // --- Initialization & User Switching ---
  useEffect(() => {
    // 1. Load User
    const sessionUser = StorageService.load<User | null>('huevify_current_user', null);
    if (sessionUser) setCurrentUser(sessionUser);

    // 2. Load Global Data
    const savedArtistAccounts = StorageService.load<ArtistAccount[]>('huevify_artist_accounts', []);
    setArtistAccounts(savedArtistAccounts);

    const savedReleaseRequests = StorageService.load<ReleaseRequest[]>('huevify_release_requests', []);
    setReleaseRequests(savedReleaseRequests);

    const savedProfileRequests = StorageService.load<ProfileEditRequest[]>('huevify_profile_requests', []);
    setProfileEditRequests(savedProfileRequests);

    const mod = StorageService.load<ModeratorAccount | null>('huevify_moderator', null);
    setHasModerator(!!mod);

    // Initial Lib Refresh
    refreshLibrary(savedReleaseRequests);

    audioRef.current.volume = 0.5;
  }, []);

  // --- Load User-Specific Data when currentUser changes ---
  useEffect(() => {
      if (currentUser) {
          // Load Settings per user
          const userSettings = StorageService.load<AppSettings | null>(`huevify_settings_${currentUser.id}`, null);
          if (userSettings) {
              setAppSettingsState({
                  ...userSettings,
                  albumCoverIndexes: userSettings.albumCoverIndexes || {}
              });
          } else {
              // Default settings
              setAppSettingsState({
                accentColor: '#1ed760',
                language: 'English',
                allowExplicitContent: true,
                autoPlay: true,
                crossfade: 0,
                albumCoverIndexes: {}
              });
          }

          // Load Recent per user
          const userRecent = StorageService.load<Track[]>(`huevify_recent_${currentUser.id}`, []);
          setRecentlyPlayed(userRecent);

          // Load Followed/Liked per user (Already separated by key)
          const storedLikedAlbums = StorageService.load<string[]>(`huevify_liked_albums_${currentUser.id}`, []);
          setLikedAlbumIds(storedLikedAlbums);

          const storedFollowedArtists = StorageService.load<string[]>(`huevify_followed_artists_${currentUser.id}`, []);
          setFollowedArtists(storedFollowedArtists);

      } else {
          // Reset if no user
          setRecentlyPlayed([]);
          setLikedAlbumIds([]);
          setFollowedArtists([]);
      }
  }, [currentUser]);

  // --- Release Scheduler Check ---
  useEffect(() => {
      const checkReleases = () => {
          const now = new Date();
          let changed = false;
          const updatedRequests = releaseRequests.map(req => {
              if (req.status === 'APPROVED' && new Date(req.releaseDate).getTime() <= now.getTime()) {
                  changed = true;
                  return { ...req, status: 'LIVE' as const };
              }
              return req;
          });

          if (changed) {
              setReleaseRequests(updatedRequests);
              StorageService.save('huevify_release_requests', updatedRequests);
              refreshLibrary(updatedRequests);
          }
      };

      const interval = setInterval(checkReleases, 60000); 
      return () => clearInterval(interval);
  }, [releaseRequests]);


  // --- Artist Hub Methods ---

  const registerArtist = (data: Omit<ArtistAccount, 'id' | 'status'>): { success: boolean, message?: string } => {
      if (artistAccounts.some(a => a.username === data.username)) return { success: false, message: "Username taken" };

      const newArtist: ArtistAccount = {
          ...data,
          id: `art_${Date.now()}`,
          status: 'PENDING'
      };
      const updated = [...artistAccounts, newArtist];
      setArtistAccounts(updated);
      StorageService.save('huevify_artist_accounts', updated);
      return { success: true };
  };

  const registerModerator = (data: ModeratorAccount): { success: boolean, message?: string } => {
      if (hasModerator) return { success: false, message: "Moderator already exists" };
      StorageService.save('huevify_moderator', data);
      setHasModerator(true);
      setCurrentModerator(data);
      return { success: true };
  };

  const loginArtistOrMod = (username: string, pass: string, type: 'ARTIST' | 'MODERATOR'): { success: boolean, message?: string } => {
      if (type === 'MODERATOR') {
          const mod = StorageService.load<ModeratorAccount | null>('huevify_moderator', null);
          if (mod && username === mod.username && pass === mod.password) {
              setCurrentModerator(mod);
              return { success: true };
          }
          return { success: false, message: "Invalid moderator credentials" };
      } else {
          const artist = artistAccounts.find(a => a.username === username && a.password === pass);
          if (!artist) return { success: false, message: "Invalid credentials" };
          if (artist.status === 'PENDING') return { success: false, message: "Account pending approval" };
          if (artist.status === 'REJECTED') return { success: false, message: "Account rejected" };

          setCurrentArtist(artist);
          return { success: true };
      }
  };

  const logoutArtistHub = () => {
      setCurrentArtist(null);
      setCurrentModerator(null);
  };

  const deleteRelease = (releaseId: string) => {
      const release = releaseRequests.find(r => r.id === releaseId);
      if (!release) return;

      if (release.status === 'LIVE' || release.status === 'APPROVED') {
          const updated = releaseRequests.map(r => r.id === releaseId ? { ...r, deletionRequested: true } : r);
          setReleaseRequests(updated);
          StorageService.save('huevify_release_requests', updated);
          showNotification("Deletion requested. Pending moderator approval.", "info");
      } else {
          const updated = releaseRequests.filter(r => r.id !== releaseId);
          setReleaseRequests(updated);
          StorageService.save('huevify_release_requests', updated);
          refreshLibrary(updated);

          // Cleanup Recently Played (Simple check)
          if (currentUser) {
              const newRecent = recentlyPlayed.filter(t => !t.id.includes(releaseId)); 
              setRecentlyPlayed(newRecent);
              StorageService.save(`huevify_recent_${currentUser.id}`, newRecent);
          }
          showNotification("Release deleted from drafts.", "success");
      }
  };

  const submitRelease = (releaseData: Omit<ReleaseRequest, 'id' | 'status' | 'artistId' | 'artistName' | 'submissionTime'>) => {
      if (!currentArtist) return;
      const newRelease: ReleaseRequest = {
          ...releaseData,
          id: `rel_${Date.now()}`,
          artistId: currentArtist.id,
          artistName: currentArtist.artistName,
          status: 'PENDING',
          submissionTime: new Date().toISOString()
      };
      const updated = [...releaseRequests, newRelease];
      setReleaseRequests(updated);
      StorageService.save('huevify_release_requests', updated);
  };

  const submitProfileEdit = (editData: Omit<ProfileEditRequest, 'id' | 'status' | 'artistId' | 'artistName'>) => {
      if (!currentArtist) return;
      const newReq: ProfileEditRequest = {
          ...editData,
          id: `pe_${Date.now()}`,
          artistId: currentArtist.id,
          artistName: currentArtist.artistName,
          status: 'PENDING'
      };
      const updated = [...profileEditRequests, newReq];
      setProfileEditRequests(updated);
      StorageService.save('huevify_profile_requests', updated);
  };

  const approveArtist = (id: string) => {
      const updated = artistAccounts.map(a => a.id === id ? { ...a, status: 'APPROVED' as const } : a);
      setArtistAccounts(updated);
      StorageService.save('huevify_artist_accounts', updated);
  };
  const rejectArtist = (id: string) => {
      const updated = artistAccounts.map(a => a.id === id ? { ...a, status: 'REJECTED' as const } : a);
      setArtistAccounts(updated);
      StorageService.save('huevify_artist_accounts', updated);
  };

  const approveRelease = (id: string) => {
      const existingReq = releaseRequests.find(r => r.id === id);
      if (!existingReq) return;

      if (existingReq.deletionRequested) {
          const updated = releaseRequests.filter(r => r.id !== id);
          setReleaseRequests(updated);
          StorageService.save('huevify_release_requests', updated);
          refreshLibrary(updated);
          return;
      }

      const tracksWithHueqs = existingReq.tracks.map(t => {
          if (t.existingHueq) return t; 
          return { ...t, generatedHueq: generateHUEQ() }; 
      });

      const updatedRequests = releaseRequests.map(r => 
          r.id === id 
            ? { ...r, status: 'APPROVED' as const, tracks: tracksWithHueqs } 
            : r
      );

      setReleaseRequests(updatedRequests);
      StorageService.save('huevify_release_requests', updatedRequests);

      const req = updatedRequests.find(r => r.id === id);
      if (req && new Date(req.releaseDate).getTime() <= Date.now()) {
          refreshLibrary(updatedRequests);
      }
  };
  const rejectRelease = (id: string) => {
      // If it's a deletion request rejection, we just cancel the deletion request
      const req = releaseRequests.find(r => r.id === id);
      if (req && req.deletionRequested) {
          const updated = releaseRequests.map(r => r.id === id ? { ...r, deletionRequested: false } : r);
          setReleaseRequests(updated);
          StorageService.save('huevify_release_requests', updated);
          showNotification("Deletion rejected. Release remains live.", "info");
      } else {
          // Normal rejection of a new release
          const updated = releaseRequests.map(r => r.id === id ? { ...r, status: 'REJECTED' as const, deletionRequested: false } : r);
          setReleaseRequests(updated);
          StorageService.save('huevify_release_requests', updated);
          showNotification("Release rejected.", "info");
      }
  };

  const approveProfileEdit = (id: string) => {
      const req = profileEditRequests.find(r => r.id === id);
      if (!req) return;

      const updatedAccounts = artistAccounts.map(a => {
          if (a.id === req.artistId) {
              return {
                  ...a,
                  avatar: req.newAvatar || a.avatar,
                  bio: req.newBio || a.bio,
                  artistPick: req.newArtistPick || a.artistPick
              };
          }
          return a;
      });
      setArtistAccounts(updatedAccounts);
      StorageService.save('huevify_artist_accounts', updatedAccounts);

      const updatedReqs = profileEditRequests.map(r => r.id === id ? { ...r, status: 'APPROVED' as const } : r);
      setProfileEditRequests(updatedReqs);
      StorageService.save('huevify_profile_requests', updatedReqs);
  };
  const rejectProfileEdit = (id: string) => {
      const updatedReqs = profileEditRequests.map(r => r.id === id ? { ...r, status: 'REJECTED' as const } : r);
      setProfileEditRequests(updatedReqs);
      StorageService.save('huevify_profile_requests', updatedReqs);
  };

  const getTrackByHueq = (hueq: string): Track | undefined => {
      return tracks.find(t => t.hueq === hueq);
  };

  // --- Existing Logic (Daily Chart, etc.) ---
  useEffect(() => {
    if (tracks.length === 0) return;

    const processDailyChart = () => {
        const now = new Date();
        const lastUpdateStr = StorageService.load<string | null>('huevify_last_chart_update', null);
        const playSnapshot = StorageService.load<Record<string, number>>('huevify_chart_snapshot', {});

        let threshold = new Date();
        threshold.setUTCHours(18, 0, 0, 0); 

        if (now.getTime() < threshold.getTime()) {
            threshold.setDate(threshold.getDate() - 1);
        }

        const lastUpdateDate = lastUpdateStr ? new Date(lastUpdateStr) : new Date(0);

        if (lastUpdateDate.getTime() < threshold.getTime()) {
            const currentPlaysMap = tracks.reduce((acc, t) => ({...acc, [t.id]: t.plays}), {} as Record<string, number>);

            const chartData: DailyChartTrack[] = tracks.map(t => {
                const prevPlays = playSnapshot[t.id] || 0;
                const dailyDelta = Math.max(0, t.plays - prevPlays);
                return { ...t, dailyPlays: dailyDelta };
            });

            const sorted = chartData.sort((a, b) => b.dailyPlays - a.dailyPlays).slice(0, 25);
            setDailyChart(sorted);
            StorageService.save('huevify_daily_chart', sorted);

            StorageService.save('huevify_chart_snapshot', currentPlaysMap);
            StorageService.save('huevify_last_chart_update', now.toISOString());
        } else {
            const savedChart = StorageService.load<DailyChartTrack[]>('huevify_daily_chart', []);
            setDailyChart(savedChart);
        }
    };

    processDailyChart();
    const interval = setInterval(processDailyChart, 60000);
    return () => clearInterval(interval);

  }, [tracks]);

  // --- Album Cover Logic ---
  const getAlbumCover = (albumId: string): string => {
      const album = albums.find(a => a.id === albumId);
      if (!album || !album.covers || album.covers.length === 0) return "";
      // albumCoverIndexes is loaded from user-specific settings
      const index = appSettings.albumCoverIndexes[albumId] || 0;
      return album.covers[index] || album.covers[0];
  };

  const changeAlbumCover = (albumId: string, index: number) => {
      updateSettings({
          albumCoverIndexes: {
              ...appSettings.albumCoverIndexes,
              [albumId]: index
          }
      });
  };

  // --- Settings Injection Effect ---
  useEffect(() => {
    const color = appSettings.accentColor;
    const styleId = 'huevify-theme-override';
    let styleTag = document.getElementById(styleId);
    if (!styleTag) {
        styleTag = document.createElement('style');
        styleTag.id = styleId;
        document.head.appendChild(styleTag);
    }
    styleTag.innerHTML = `
        .text-primary { color: ${color} !important; }
        .bg-primary { background-color: ${color} !important; }
        .border-primary { border-color: ${color} !important; }
        .accent-primary { accent-color: ${color} !important; }
        .group:hover .group-hover\\:text-primary { color: ${color} !important; }
        .group:hover .group-hover\\:bg-primary { background-color: ${color} !important; }
        .selection\\:bg-primary::selection { background-color: ${color} !important; }
        .range-slider::-webkit-slider-thumb:hover { background-color: ${color} !important; }
    `;
  }, [appSettings.accentColor]);

  // --- Playlist Loading & Account Isolation ---
  useEffect(() => {
    let allPlaylists = StorageService.load<Playlist[]>('huevify_playlists', []);

    // Create unique Liked playlist per user
    if (currentUser) {
        const likedId = `liked_${currentUser.id}`;
        if (!allPlaylists.find(p => p.id === likedId)) {
            const likedPl: Playlist = { 
                id: likedId, 
                name: 'Liked Songs', 
                tracks: [], 
                isSystem: true, 
                description: 'Your favorite tracks',
                ownerId: currentUser.id
            };
            allPlaylists = [likedPl, ...allPlaylists];
            StorageService.save('huevify_playlists', allPlaylists);
        }
    }
    setPlaylists(allPlaylists);
  }, [currentUser]); 

  // --- Settings Methods ---
  const updateSettings = (newSettings: Partial<AppSettings>) => {
      if (!currentUser) return;
      setAppSettingsState(prev => {
          const updated = { ...prev, ...newSettings };
          // Save to user-specific key
          StorageService.save(`huevify_settings_${currentUser.id}`, updated);
          return updated;
      });
  };

  const updateUserProfile = (data: Partial<User>): { success: boolean; message?: string } => {
      if (!currentUser) return { success: false, message: "Not logged in" };
      const users = StorageService.load<User[]>('huevify_users', []);
      if (data.username && data.username !== currentUser.username) {
          if (users.some(u => u.username === data.username)) {
              return { success: false, message: "Username already taken" };
          }
      }
      const updatedUser = { ...currentUser, ...data };
      const updatedUsersList = users.map(u => u.id === currentUser.id ? updatedUser : u);
      StorageService.save('huevify_users', updatedUsersList);
      StorageService.save('huevify_current_user', updatedUser);
      setCurrentUser(updatedUser);
      if (data.displayName || data.avatar) {
          const allPlaylists = StorageService.load<Playlist[]>('huevify_playlists', []);
          const updatedPlaylists = allPlaylists.map(p => {
              if (p.ownerId === currentUser.id) {
                  return { 
                      ...p, 
                      creatorName: data.displayName || p.creatorName,
                      creatorAvatar: data.avatar || p.creatorAvatar
                  };
              }
              return p;
          });
          StorageService.save('huevify_playlists', updatedPlaylists);
          setPlaylists(updatedPlaylists);
      }
      return { success: true };
  };

  // --- Auth Methods ---
  const login = (username: string, pass: string): boolean => {
    const users = StorageService.load<User[]>('huevify_users', []);
    const user = users.find(u => u.username === username && u.password === pass);
    if (user) {
        setCurrentUser(user);
        StorageService.save('huevify_current_user', user);
        return true;
    }
    return false;
  };

  const register = (newUser: Omit<User, 'id'>): boolean => {
      const users = StorageService.load<User[]>('huevify_users', []);
      if (users.some(u => u.username === newUser.username)) {
          return false; // User exists
      }
      const user: User = { ...newUser, id: `user_${Date.now()}` };
      const updatedUsers = [...users, user];
      StorageService.save('huevify_users', updatedUsers);
      setCurrentUser(user);
      StorageService.save('huevify_current_user', user);
      return true;
  };

  const logout = () => {
      setCurrentUser(null);
      StorageService.save('huevify_current_user', null);
      setProfileModalOpen(false);
      setIsPlaying(false);
      audioRef.current.pause();
      setCurrentTrack(null);
      setViewInternal({ type: 'HOME' });
  };

  // --- Logic for Recs ---
  useEffect(() => {
    if (tracks.length === 0 || !currentUser) return;
    const genreScores: Record<string, number> = {};
    // Use dynamic liked ID
    const likedId = `liked_${currentUser.id}`;
    const likedPlaylist = playlists.find(p => p.id === likedId);
    const likedIds = likedPlaylist ? likedPlaylist.tracks : [];

    tracks.forEach(t => {
      let score = 0;
      if (likedIds.includes(t.id)) score += 50;
      if (t.plays > 0) score += Math.log(t.plays) * 2;
      if (score > 0) {
        genreScores[t.genre] = (genreScores[t.genre] || 0) + score;
      }
    });
    const topGenres = Object.entries(genreScores).sort(([, a], [, b]) => b - a).slice(0, 3).map(([g]) => g);
    const targetGenres = topGenres.length > 0 ? topGenres : tracks.map(t => t.genre);
    const candidates = tracks.filter(t => targetGenres.includes(t.genre) && !likedIds.includes(t.id));
    // Filter explicit if needed
    const filteredCandidates = appSettings.allowExplicitContent ? candidates : candidates.filter(t => !t.explicit);
    const shuffled = [...filteredCandidates].sort(() => 0.5 - Math.random()).slice(0, 6);
    setRecommendations(shuffled);
  }, [tracks, playlists, currentUser, appSettings.allowExplicitContent]);

  useEffect(() => {
    if (tracks.length > 0) {
      const playCounts = tracks.reduce((acc, t) => ({ ...acc, [t.id]: t.plays }), {});
      StorageService.save('huevify_plays', playCounts);
    }
  }, [tracks]);

  useEffect(() => {
    if(currentUser) {
        StorageService.save(`huevify_liked_albums_${currentUser.id}`, likedAlbumIds);
    }
  }, [likedAlbumIds, currentUser]);

  useEffect(() => {
    if(currentUser) {
        StorageService.save(`huevify_followed_artists_${currentUser.id}`, followedArtists);
    }
  }, [followedArtists, currentUser]);

  // --- Navigation ---
  const setView = (newView: ViewState) => {
    if (JSON.stringify(view) !== JSON.stringify(newView)) {
      setHistory(prev => [...prev, view]);
      setViewInternal(newView);
    }
    setMobilePlayerOpen(false);
  };

  const goToArtist = (artistName: string) => {
    setView({ type: 'ARTIST', id: artistName });
    setMobilePlayerOpen(false);
  }

  const goBack = () => {
    if (history.length > 0) {
      const prev = history[history.length - 1];
      setHistory(h => h.slice(0, -1));
      setViewInternal(prev);
    } else {
      setViewInternal({ type: 'HOME' });
    }
  };

  const getArtistStats = (artistName: string): ArtistStats => {
    const artistPlayMap: Record<string, number> = {};
    tracks.forEach(t => { 
        const primary = t.artist;
        if (primary) artistPlayMap[primary] = (artistPlayMap[primary] || 0) + t.plays;

        if (t.mainArtists) {
            t.mainArtists.forEach(ma => {
                artistPlayMap[ma] = (artistPlayMap[ma] || 0) + t.plays;
            });
        }
    });

    const sortedArtists = Object.entries(artistPlayMap).sort(([, a], [, b]) => b - a);
    const rankIndex = sortedArtists.findIndex(([name]) => name === artistName);
    const totalPlays = artistPlayMap[artistName] || 0;

    return { monthlyPlays: totalPlays, globalRank: rankIndex === -1 ? 999 : rankIndex + 1 };
  };

  const toggleFollowArtist = (artistName: string) => {
    setFollowedArtists(prev => prev.includes(artistName) ? prev.filter(a => a !== artistName) : [...prev, artistName]);
  };
  const isArtistFollowed = (artistName: string) => followedArtists.includes(artistName);

  // --- Player Logic ---
  useEffect(() => {
    cumulativeTimeRef.current = 0;
    lastTimeRef.current = 0;
    setHasCountedListen(false);
  }, [currentTrack]);

  useEffect(() => {
    const audio = audioRef.current;
    const handleTimeUpdate = () => {
      const now = audio.currentTime;
      setProgress(now);
      const diff = now - lastTimeRef.current;
      if (diff > 0 && diff < 1.5) cumulativeTimeRef.current += diff;
      lastTimeRef.current = now;
      if (cumulativeTimeRef.current > 30 && !hasCountedListen && currentTrack) handleListenCount(currentTrack);
    };
    const handleEnded = () => {
      if (playMode === PlayMode.ONE) { 
          audio.currentTime = 0; 
          cumulativeTimeRef.current = 0; 
          setHasCountedListen(false);
          audio.play(); 
      }
      else if (appSettings.autoPlay) { nextTrack(); } 
      else { setIsPlaying(false); audioRef.current.pause(); }
    };
    const handleLoadedMetadata = () => setDuration(audio.duration);
    audio.addEventListener('timeupdate', handleTimeUpdate);
    audio.addEventListener('ended', handleEnded);
    audio.addEventListener('loadedmetadata', handleLoadedMetadata);
    return () => {
      audio.removeEventListener('timeupdate', handleTimeUpdate);
      audio.removeEventListener('ended', handleEnded);
      audio.removeEventListener('loadedmetadata', handleLoadedMetadata);
    };
  }, [currentTrack, hasCountedListen, playMode, tracks, isShuffle, appSettings.autoPlay]);

  const handleListenCount = (track: Track) => {
    const addedPlays = Math.floor(100 + Math.random() * 9900); 
    setTracks(prev => prev.map(t => t.id === track.id ? { ...t, plays: t.plays + addedPlays } : t));
    setHasCountedListen(true);
  };

  const playTrack = (track: Track) => {
    // 1. Check if track is Explicit and allowed
    if (track.explicit && !appSettings.allowExplicitContent) {
        showNotification("Content not available. Turn on 'Allow Explicit Content' in settings.", "error");
        return;
    }

    // 2. Check if track is actually live (Deleted tracks check)
    // We check if the track ID exists in the current 'tracks' array
    const isLive = tracks.find(t => t.id === track.id);
    if (!isLive) {
        showNotification("This track is no longer available.", "error");
        return;
    }

    // Save to User Specific Recent
    if (currentUser) {
        setRecentlyPlayed(prev => {
            const filtered = prev.filter(t => t.id !== track.id);
            const newHistory = [track, ...filtered].slice(0, 10);
            StorageService.save(`huevify_recent_${currentUser.id}`, newHistory);
            return newHistory;
        });
    }

    if (currentTrack?.id === track.id) { togglePlay(); return; }
    setCurrentTrack(track);
    audioRef.current.src = track.url;
    audioRef.current.play().then(() => setIsPlaying(true)).catch(e => console.error("Audio play failed", e));
  };

  const togglePlay = () => {
    if (audioRef.current.paused) { audioRef.current.play(); setIsPlaying(true); }
    else { audioRef.current.pause(); setIsPlaying(false); }
  };
  const setVolume = (vol: number) => { setVolumeState(vol); audioRef.current.volume = vol; };
  const seek = (time: number) => { audioRef.current.currentTime = time; lastTimeRef.current = time; setProgress(time); };

  const getQueue = (): Track[] => {
    if (view.type === 'PLAYLIST' && (view as any).id === 'history') {
        // Filter explicit content from history queue as well
        if (!appSettings.allowExplicitContent) {
            return recentlyPlayed.filter(t => !t.explicit);
        }
        return recentlyPlayed;
    }
    // Filter explicit content from queue if needed
    if (!appSettings.allowExplicitContent) {
        return tracks.filter(t => !t.explicit);
    }
    return tracks; 
  };
  const nextTrack = () => {
    const queue = getQueue();
    if (isShuffle) { playTrack(queue[Math.floor(Math.random() * queue.length)]); return; }
    const idx = queue.findIndex(t => t.id === currentTrack?.id);
    if (idx !== -1 && idx < queue.length - 1) playTrack(queue[idx + 1]);
    else if (playMode === PlayMode.CONTEXT) playTrack(queue[0]);
    else { setIsPlaying(false); audioRef.current.pause(); audioRef.current.currentTime = 0; }
  };
  const prevTrack = () => {
    if (audioRef.current.currentTime > 3) { audioRef.current.currentTime = 0; lastTimeRef.current = 0; return; }
    const queue = getQueue();
    const idx = queue.findIndex(t => t.id === currentTrack?.id);
    if (idx > 0) playTrack(queue[idx - 1]); else playTrack(queue[queue.length - 1]);
  };
  const toggleRepeat = () => {
    if (playMode === PlayMode.OFF) setPlayMode(PlayMode.CONTEXT);
    else if (playMode === PlayMode.CONTEXT) setPlayMode(PlayMode.ONE);
    else setPlayMode(PlayMode.OFF);
  };
  const toggleShuffle = () => setIsShuffle(!isShuffle);

  const syncPlaylists = (newGlobalPlaylists: Playlist[]) => {
      StorageService.save('huevify_playlists', newGlobalPlaylists);
      setPlaylists(newGlobalPlaylists);
  };
  const createPlaylist = (name: string, description?: string, cover?: string, isPublic: boolean = false) => {
    if (!currentUser) return;
    const newPl: Playlist = { id: `pl_${Date.now()}`, name, description: description || "", customCover: cover, tracks: [], ownerId: currentUser.id, creatorName: currentUser.displayName, creatorAvatar: currentUser.avatar, isPublic: isPublic, savedBy: [] };
    const all = [...playlists]; 
    syncPlaylists([...all, newPl]);
  };
  const editPlaylist = (id: string, name: string, description?: string, cover?: string, isPublic?: boolean) => {
    const all = [...playlists];
    const updated = all.map(p => { if (p.id === id) { return { ...p, name, description, customCover: cover, isPublic: isPublic !== undefined ? isPublic : p.isPublic }; } return p; });
    syncPlaylists(updated);
  };
  const openDeleteModal = (id: string) => { setPlaylistToDelete(id); setIsDeleteModalOpen(true); };
  const closeDeleteModal = () => { setIsDeleteModalOpen(false); setPlaylistToDelete(null); };
  const confirmDeletePlaylist = () => { if (!playlistToDelete) return; const id = playlistToDelete; if (view.type === 'PLAYLIST' && (view as any).id === id) setViewInternal({ type: 'LIBRARY' }); const all = [...playlists]; const updated = all.filter(p => p.id !== id); syncPlaylists(updated); closeDeleteModal(); };
  const deletePlaylist = (id: string) => openDeleteModal(id);
  const addToPlaylist = (playlistId: string, trackId: string) => { 
      const updated = playlists.map(p => { 
          if (p.id === playlistId && !p.tracks.includes(trackId)) {
              return { ...p, tracks: [...p.tracks, trackId] }; 
          }
          return p; 
      }); 
      syncPlaylists(updated); 
  };
  const removeFromPlaylist = (playlistId: string, trackId: string) => { 
      const updated = playlists.map(p => { 
          if (p.id === playlistId) {
              return { ...p, tracks: p.tracks.filter(id => id !== trackId) }; 
          }
          return p; 
      }); 
      syncPlaylists(updated); 
  };
  const togglePlaylistSave = (playlistId: string) => { if (!currentUser) return; const updated = playlists.map(p => { if (p.id === playlistId) { const saved = p.savedBy || []; const isSaved = saved.includes(currentUser.id); return { ...p, savedBy: isSaved ? saved.filter(id => id !== currentUser.id) : [...saved, currentUser.id] }; } return p; }); syncPlaylists(updated); };

  // Account Isolated Likes
  const toggleLike = (trackId: string) => { 
      if (!currentUser) return;
      const likedId = `liked_${currentUser.id}`;
      const likedPl = playlists.find(p => p.id === likedId); 
      if (!likedPl) return; 
      if (likedPl.tracks.includes(trackId)) removeFromPlaylist(likedId, trackId); 
      else addToPlaylist(likedId, trackId); 
  };
  const isLiked = (trackId: string) => { 
      if (!currentUser) return false;
      const likedId = `liked_${currentUser.id}`;
      const likedPl = playlists.find(p => p.id === likedId); 
      return likedPl ? likedPl.tracks.includes(trackId) : false; 
  };

  const toggleAlbumLike = (albumId: string) => { setLikedAlbumIds(prev => prev.includes(albumId) ? prev.filter(id => id !== albumId) : [...prev, albumId]); };
  const isAlbumLiked = (albumId: string) => likedAlbumIds.includes(albumId);
  const openAddToPlaylist = (trackId: string) => { setTrackIdToAdd(trackId); setAddToPlaylistOpen(true); };
  const closeAddToPlaylist = () => { setAddToPlaylistOpen(false); setTrackIdToAdd(null); };

  return (
    <StoreContext.Provider value={{
      currentUser, login, register, logout, updateUserProfile,
      appSettings, updateSettings, dailyChart,
      getAlbumCover, changeAlbumCover,
      isArtistHubOpen, setArtistHubOpen, currentArtist, currentModerator, artistAccounts,
      registerArtist, registerModerator, loginArtistOrMod, logoutArtistHub, submitRelease, submitProfileEdit, deleteRelease,
      approveArtist, rejectArtist, approveRelease, rejectRelease, approveProfileEdit, rejectProfileEdit,
      releaseRequests, profileEditRequests, hasModerator, existingArtists, getTrackByHueq,
      tracks, albums, playlists, recommendations, recentlyPlayed, followedArtists, currentTrack, isPlaying, playMode, isShuffle, volume, progress, duration, view,
      isCreatePlaylistOpen, setCreatePlaylistOpen, playlistIdToEdit, setPlaylistIdToEdit,
      isMobilePlayerOpen, setMobilePlayerOpen,
      isAddToPlaylistOpen, trackIdToAdd, openAddToPlaylist, closeAddToPlaylist,
      isDeleteModalOpen, playlistToDelete, openDeleteModal, closeDeleteModal, confirmDeletePlaylist,
      isProfileModalOpen, setProfileModalOpen, likedPlaylistId, notifications, showNotification, dismissNotification,
      setView, goToArtist, getArtistStats, toggleFollowArtist, isArtistFollowed, goBack, playTrack, togglePlay, nextTrack, prevTrack, seek, setVolume, toggleRepeat, toggleShuffle,
      createPlaylist, editPlaylist, deletePlaylist, addToPlaylist, removeFromPlaylist, togglePlaylistSave, toggleLike, isLiked,
      toggleAlbumLike, isAlbumLiked
    }}>
      {children}
    </StoreContext.Provider>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { useStore } from '../context/StoreContext.tsx';
import { 
  X, Mic2, Shield, User, UploadCloud, Calendar, FileAudio, 
  CheckCircle, XCircle, Clock, MoreVertical, Image, Plus,
  Edit, ArrowLeft, Camera, LogOut, ChevronDown, Trash2, ListMusic, Check, Search, Play, BarChart2
} from './Icons.tsx';
import { DistributionTrack, ReleaseType, ReleaseRequest } from '../types.ts';

type HubView = 'AUTH' | 'ARTIST_DASH' | 'MOD_DASH' | 'DISTRIBUTION' | 'PROFILE_EDIT' | 'ARTIST_PICK';

const formatDuration = (seconds: number) => {
    const min = Math.floor(seconds / 60);
    const sec = Math.floor(seconds % 60);
    return `${min}:${sec.toString().padStart(2, '0')}`;
};

export const ArtistHub = () => {
  const { 
    isArtistHubOpen, setArtistHubOpen, currentArtist, currentModerator, 
    loginArtistOrMod, registerArtist, registerModerator, logoutArtistHub, artistAccounts,
    releaseRequests, profileEditRequests, approveArtist, rejectArtist,
    approveRelease, rejectRelease, approveProfileEdit, rejectProfileEdit,
    submitRelease, getArtistStats, submitProfileEdit, hasModerator, existingArtists,
    deleteRelease, getTrackByHueq, tracks, albums, playlists, showNotification
  } = useStore();

  const [view, setView] = useState<HubView>('AUTH');

  // Auth State
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [role, setRole] = useState<'ARTIST' | 'MODERATOR'>('ARTIST');
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");

  // Artist Registration Logic
  const [artistNameSelection, setArtistNameSelection] = useState("");
  const [isCreatingNewArtist, setIsCreatingNewArtist] = useState(false);
  const [newArtistAlias, setNewArtistAlias] = useState("");

  const [message, setMessage] = useState("");

  // Distribution State
  const [distStep, setDistStep] = useState(1);
  const [distTitle, setDistTitle] = useState("");
  const [distType, setDistType] = useState<ReleaseType>('Single');
  const [distGenre, setDistGenre] = useState("Pop");
  const [distLabel, setDistLabel] = useState("");
  const [distCovers, setDistCovers] = useState<string[]>([]);
  const [distMainArtists, setDistMainArtists] = useState<string[]>([]);
  const [distMainArtistInput, setDistMainArtistInput] = useState("");
  const [distTracks, setDistTracks] = useState<DistributionTrack[]>([]);
  const [distDate, setDistDate] = useState("");
  const [distTime, setDistTime] = useState("00:00");
  const [distMsg, setDistMsg] = useState("");

  // Edit Profile State
  const [editBio, setEditBio] = useState("");
  const [editAvatar, setEditAvatar] = useState("");

  // Artist Pick State
  const [pickSearch, setPickSearch] = useState("");

  // Release Detail Modal State
  const [selectedRelease, setSelectedRelease] = useState<ReleaseRequest | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const coverInputRef = useRef<HTMLInputElement>(null);
  const avatarInputRef = useRef<HTMLInputElement>(null);

  // Initialize view based on login state
  useEffect(() => {
      if (isArtistHubOpen) {
          if (currentArtist) {
              setView('ARTIST_DASH');
              setEditBio(currentArtist.bio || "");
              setEditAvatar(currentArtist.avatar || "");
          }
          else if (currentModerator) setView('MOD_DASH');
          else setView('AUTH');
      }
  }, [isArtistHubOpen, currentArtist, currentModerator]);

  if (!isArtistHubOpen) return null;

  const handleLogin = (e: React.FormEvent) => {
      e.preventDefault();
      setMessage("");
      const res = loginArtistOrMod(username, password, role);
      if (res.success) {
          if (role === 'ARTIST') {
              setView('ARTIST_DASH');
          }
          else setView('MOD_DASH');
          showNotification("Welcome back!", "success");
      } else {
          setMessage(res.message || "Login failed");
      }
  };

  const handleRegister = (e: React.FormEvent) => {
      e.preventDefault();

      if (role === 'MODERATOR') {
          if (hasModerator) {
              setMessage("Moderator registration is closed.");
              return;
          }
          const res = registerModerator({ username, password });
          if (res.success) {
              setMessage("Moderator registered! Please login.");
              setAuthMode('LOGIN');
          } else {
              setMessage(res.message || "Error registering moderator");
          }
          return;
      }

      // Artist Registration
      const finalArtistName = isCreatingNewArtist ? newArtistAlias : artistNameSelection;

      if (!finalArtistName) {
          setMessage("Please select or enter an artist name.");
          return;
      }

      const res = registerArtist({
          artistName: finalArtistName, 
          username, 
          password,
          artistPick: undefined
      });

      if (res.success) {
          setMessage("Registration sent for approval.");
          setAuthMode('LOGIN');
      } else {
          setMessage(res.message || "Error registering");
      }
  };

  // --- Distribution Handlers ---
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          // Convert to Base64 for persistence
          const reader = new FileReader();
          reader.onloadend = () => {
              const base64Audio = reader.result as string;

              // Create temp audio element to get duration
              const audio = new Audio(base64Audio);
              audio.onloadedmetadata = () => {
                  const newTrack: DistributionTrack = {
                      title: file.name.replace(/\.[^/.]+$/, ""),
                      explicit: false,
                      mainArtists: [],
                      genre: distGenre, // Default to release genre
                      duration: audio.duration,
                      fileUrl: base64Audio
                  };
                  setDistTracks(prev => [...prev, newTrack]);
              };
          };
          reader.readAsDataURL(file);
      }
  };

  const updateTrack = (idx: number, field: keyof DistributionTrack, val: any) => {
      setDistTracks(prev => {
          const newTracks = [...prev];
          newTracks[idx] = { ...newTracks[idx], [field]: val };
          return newTracks;
      });
  };

  const handleHueqBlur = (idx: number, hueq: string) => {
      if (!hueq) return;
      const existing = getTrackByHueq(hueq);

      if (existing) {
          setDistTracks(prev => {
              const newTracks = [...prev];
              newTracks[idx] = {
                  ...newTracks[idx],
                  title: existing.title,
                  explicit: existing.explicit || false,
                  feat: existing.feat || "",
                  existingHueq: hueq,
                  fileUrl: existing.url,
                  duration: existing.duration,
                  genre: existing.genre, // Sync genre
                  mainArtists: existing.mainArtists || []
              };
              return newTracks;
          });
          showNotification(`HUEQ Found! Track details auto-filled: ${existing.title}`, "success");
      } else {
          updateTrack(idx, 'existingHueq', hueq);
      }
  };

  const handleNextStep = () => {
      if (distStep === 1) {
          if (!distTitle || !distType || !distGenre || distCovers.length === 0) {
              showNotification("Please complete all required fields (Title, Type, Genre, Covers)", "error");
              return;
          }
      }
      if (distStep === 2) {
          if (distTracks.length === 0) {
              showNotification("Please add at least one track.", "error");
              return;
          }
      }
      setDistStep(prev => prev + 1);
  };

  const handleSubmitRelease = () => {
      if (!distDate || !distTime) {
          showNotification("Please specify Release Date and Time.", "error");
          return;
      }

      const dateTime = new Date(`${distDate}T${distTime}:00+03:00`);

      submitRelease({
          title: distTitle,
          type: distType,
          genre: distGenre,
          label: distLabel || (currentArtist?.artistName || ""),
          covers: distCovers, // Changed to array
          additionalMainArtists: distMainArtists,
          tracks: distTracks,
          releaseDate: dateTime.toISOString(),
          releaseMessage: distMsg
      });

      showNotification("Release submitted for approval!", "success");
