        <CreatePlaylistModal />
        <AddToPlaylistModal />
        <DeletePlaylistModal />
        <ProfileModal />
        <ArtistHub />
        <NotificationOverlay />
      </div>
    );
};

export default function App() {
  return (
    <StoreProvider>
      <AppContent />
    </StoreProvider>
  );
}

