    autoPlay: true,
    crossfade: 0,
    albumCoverIndexes: {}
  });

  // --- Data State ---
  const [tracks, setTracks] = useState<Track[]>([]);
  const [albums, setAlbums] = useState<Album[]>([]);
  const [playlists, setPlaylists] = useState<Playlist[]>([]);
  const [recommendations, setRecommendations] = useState<Track[]>([]);
  const [recentlyPlayed, setRecentlyPlayed] = useState<Track[]>([]);
  const [likedAlbumIds, setLikedAlbumIds] = useState<string[]>([]);
  const [followedArtists, setFollowedArtists] = useState<string[]>([]);

  const [dailyChart, setDailyChart] = useState<DailyChartTrack[]>([]);
  const [notifications, setNotifications] = useState<AppNotification[]>([]);

  // --- Artist Hub State ---
  const [isArtistHubOpen, setArtistHubOpen] = useState(false);
  const [currentArtist, setCurrentArtist] = useState<ArtistAccount | null>(null);
  const [currentModerator, setCurrentModerator] = useState<ModeratorAccount | null>(null);
  const [artistAccounts, setArtistAccounts] = useState<ArtistAccount[]>([]);
  const [releaseRequests, setReleaseRequests] = useState<ReleaseRequest[]>([]);
  const [profileEditRequests, setProfileEditRequests] = useState<ProfileEditRequest[]>([]);
  const [hasModerator, setHasModerator] = useState(false);
  const [existingArtists, setExistingArtists] = useState<string[]>([]);
  // Store deleted legacy IDs to hide them
  const [deletedLegacyIds, setDeletedLegacyIds] = useState<string[]>([]);

  // --- Player State ---
  const [currentTrack, setCurrentTrack] = useState<Track | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [playMode, setPlayMode] = useState<PlayMode>(PlayMode.OFF);
  const [isShuffle, setIsShuffle] = useState(false);
  const [volume, setVolumeState] = useState(0.5);
  const [progress, setProgress] = useState(0);
  const [duration, setDuration] = useState(0);
  const [hasCountedListen, setHasCountedListen] = useState(false);

  // --- UI State ---
  const [view, setViewInternal] = useState<ViewState>({ type: 'HOME' });
  const [history, setHistory] = useState<ViewState[]>([]);

  // Modals
  const [isCreatePlaylistOpen, setCreatePlaylistOpen] = useState(false);
  const [playlistIdToEdit, setPlaylistIdToEdit] = useState<string | null>(null);
  const [isMobilePlayerOpen, setMobilePlayerOpen] = useState(false);
  const [isAddToPlaylistOpen, setAddToPlaylistOpen] = useState(false);
  const [trackIdToAdd, setTrackIdToAdd] = useState<string | null>(null);
  const [isProfileModalOpen, setProfileModalOpen] = useState(false);

  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [playlistToDelete, setPlaylistToDelete] = useState<string | null>(null);

  // --- Refs ---
  const audioRef = useRef<HTMLAudioElement>(new Audio());
  const cumulativeTimeRef = useRef(0);
  const lastTimeRef = useRef(0);
  // Real-time Sync Channel
  const broadcastChannelRef = useRef<BroadcastChannel | null>(null);

  // Helper ID
  const likedPlaylistId = currentUser ? `liked_${currentUser.id}` : 'liked';

  const showNotification = (message: string, type: 'error' | 'success' | 'info' = 'info') => {
      const id = Date.now().toString();
      setNotifications(prev => [...prev, { id, message, type }]);
      setTimeout(() => dismissNotification(id), 5000);
  };

  const dismissNotification = (id: string) => {
      setNotifications(prev => prev.filter(n => n.id !== id));
  };

  // --- Broadcast Channel for Cross-Tab Syncing ---
  useEffect(() => {
      try {
          if (typeof BroadcastChannel !== 'undefined') {
              broadcastChannelRef.current = new BroadcastChannel('huevify_sync');

              broadcastChannelRef.current.onmessage = (event) => {
                  try {
                      const { type } = event.data;
                      // When another tab updates data, reload from local storage
                      if (type === 'PLAYLISTS_UPDATE') {
                          setPlaylists(StorageService.load<Playlist[]>('huevify_playlists', []));
                      }
                      if (type === 'TRACKS_UPDATE') {
                          const requests = StorageService.load<ReleaseRequest[]>('huevify_release_requests', []);
                          const storedPlays = StorageService.load<Record<string, number>>('huevify_plays', {});
                          refreshLibrary(requests, storedPlays);
                      }
                      if (type === 'ARTIST_DATA_UPDATE') {
                          setArtistAccounts(StorageService.load<ArtistAccount[]>('huevify_artist_accounts', []));
                          setReleaseRequests(StorageService.load<ReleaseRequest[]>('huevify_release_requests', []));
                          setProfileEditRequests(StorageService.load<ProfileEditRequest[]>('huevify_profile_requests', []));
                          setDeletedLegacyIds(StorageService.load<string[]>('huevify_deleted_legacy', []));

                          const requests = StorageService.load<ReleaseRequest[]>('huevify_release_requests', []);
                          const storedPlays = StorageService.load<Record<string, number>>('huevify_plays', {});
                          refreshLibrary(requests, storedPlays);
                      }
                      if (type === 'SETTINGS_UPDATE' && currentUser) {
                          const userSettings = StorageService.load<AppSettings | null>(`huevify_settings_${currentUser.id}`, null);
                          if (userSettings) setAppSettingsState(prev => ({ ...prev, ...userSettings }));
                      }
                  } catch (err) {
                      console.error("Sync error:", err);
                  }
              };
          }
      } catch (e) {
          console.warn("BroadcastChannel not supported in this browser.", e);
      }

      return () => {
          broadcastChannelRef.current?.close();
      };
  }, [currentUser]);

  const notifySync = (type: 'PLAYLISTS_UPDATE' | 'TRACKS_UPDATE' | 'ARTIST_DATA_UPDATE' | 'SETTINGS_UPDATE') => {
      try {
          broadcastChannelRef.current?.postMessage({ type });
      } catch (e) {
          console.error("Failed to notify sync", e);
      }
  };

  // --- Automated Play Count System ---
  useEffect(() => {
    const interval = setInterval(() => {
        const now = new Date();
        if (now.getMinutes() === 30) {
             const currentHour = now.getHours();
             const lastUpdateHour = StorageService.load('huevify_last_play_update_hour', -1);

             if (lastUpdateHour !== currentHour) {
                 setTracks(prevTracks => {
                     const updated = prevTracks.map(t => {
                         let add = 0;
                         if (t.plays <= 10000) {
                             add = Math.floor(Math.random() * 1000) + 1;
                         } else if (t.plays <= 50000) {
                             add = Math.floor(Math.random() * 9900) + 100;
                         } else {
                             add = Math.floor(Math.random() * 24000) + 1000;
                         }
                         return { ...t, plays: t.plays + add };
                     });
                     const playCounts = updated.reduce((acc, t) => ({ ...acc, [t.id]: t.plays }), {});
                     StorageService.save('huevify_plays', playCounts);
                     notifySync('TRACKS_UPDATE');
                     return updated;
                 });
                 StorageService.save('huevify_last_play_update_hour', currentHour);
             }
        }
    }, 10000); 
    return () => clearInterval(interval);
  }, []); 

  // --- Logic to Refresh Library (Merge Static + Dynamic Data) ---
  const refreshLibrary = (requests: ReleaseRequest[], storedPlays?: Record<string, number>) => {
      try {
          const { tracks: initialTracks, albums: initialAlbums } = generateInitialData();
          const plays = storedPlays || StorageService.load<Record<string, number>>('huevify_plays', {});
          const deletedLegacy = StorageService.load<string[]>('huevify_deleted_legacy', []);

          let mergedTracks = initialTracks.filter(t => !deletedLegacy.includes(t.album)); // Filter tracks if album is hidden
          let mergedAlbums = initialAlbums.filter(a => !deletedLegacy.includes(a.id));

          const artistSet = new Set(mergedAlbums.map(a => a.artist));

          requests.forEach(req => {
              // Safety check for malformed requests
              if (!req || !req.tracks) return;

              const isLive = req.status === 'LIVE';
              const isApprovedAndDue = req.status === 'APPROVED' && new Date(req.releaseDate).getTime() <= Date.now();

              if (isLive || isApprovedAndDue) {
                  artistSet.add(req.artistName);
                  if (req.additionalMainArtists) {
                      req.additionalMainArtists.forEach(a => artistSet.add(a));
                  }

                  const albumId = req.id.startsWith('a') ? req.id : `dist_alb_${req.id}`; // Reuse ID if it's a legacy edit override

                  // If this dynamic request overrides a legacy ID, remove the legacy one first
                  const existingIndex = mergedAlbums.findIndex(a => a.id === albumId);

                  const newAlbum: Album = {
                      id: albumId,
                      title: req.title,
                      artist: req.artistName,
                      covers: req.covers.length > 0 ? req.covers : ["https://picsum.photos/300"],
                      trackIds: [],
                      year: new Date(req.releaseDate).getFullYear(),
                      releaseDate: req.releaseDate, 
                      recordLabel: req.label,
                      type: req.type,
                      mainArtists: req.additionalMainArtists || [] 
                  };

                  const newTracksForThisAlbum: Track[] = [];

                  req.tracks.forEach((t, idx) => {
                      let trackId: string;
                      let existingTrack: Track | undefined;

                      if (t.existingHueq) {
                           existingTrack = mergedTracks.find(mt => mt.hueq === t.existingHueq);
                      }

                      if (existingTrack) {
                          trackId = existingTrack.id;
                          const trackIndex = mergedTracks.findIndex(tr => tr.id === trackId);
                          if (trackIndex !== -1) {
                              mergedTracks[trackIndex] = {
                                  ...mergedTracks[trackIndex],
                                  title: t.title,
                                  artist: t.artist || req.artistName, // Support override
                                  genre: t.genre || req.genre || mergedTracks[trackIndex].genre,
                                  explicit: t.explicit,
                              };
                          }
                      } else {
                          trackId = `dist_trk_${req.id}_${idx}`;
                          const releaseLevelArtists = req.additionalMainArtists || [];
                          const trackLevelArtists = t.mainArtists || [];
                          const combinedMainArtists = Array.from(new Set([...releaseLevelArtists, ...trackLevelArtists]));

                          newTracksForThisAlbum.push({
                              id: trackId,
                              title: t.title,
                              artist: t.artist || req.artistName, // Support override
                              album: req.title,
                              cover: req.covers[0], 
                              duration: t.duration, 
                              url: t.fileUrl, 
                              plays: 0,
                              genre: t.genre || req.genre,
                              explicit: t.explicit,
                              feat: t.feat,
                              hueq: t.generatedHueq || t.existingHueq,
                              mainArtists: combinedMainArtists
                          });
                      }

                      newAlbum.trackIds.push(trackId);
                  });

                  if (existingIndex !== -1) {
                      mergedAlbums[existingIndex] = newAlbum;
                      mergedTracks.push(...newTracksForThisAlbum);
                  } else {
                      mergedAlbums.push(newAlbum);
                      mergedTracks.push(...newTracksForThisAlbum);
                  }
              }
          });

          // Unique Tracks (Prevent duplicates if refresh called multiple times awkwardly)
          const uniqueTracks = Array.from(new Map(mergedTracks.map(item => [item.id, item])).values());

          const tracksWithPlays = uniqueTracks.map(t => ({
              ...t,
              plays: plays[t.id] !== undefined ? plays[t.id] : t.plays
          }));

          setTracks(tracksWithPlays);
          setAlbums(mergedAlbums);
          setExistingArtists(Array.from(artistSet));
      } catch (e) {
          console.error("Failed to refresh library", e);
          // Fallback to initial data if everything fails
          const { tracks: fallbackTracks } = generateInitialData();
          setTracks(fallbackTracks);
      }
  };

  // --- Initialization & User Switching ---
  useEffect(() => {
    try {
        // 1. Load User
        const sessionUser = StorageService.load<User | null>('huevify_current_user', null);
        if (sessionUser) setCurrentUser(sessionUser);

        // 2. Load Global Data
        const savedArtistAccounts = StorageService.load<ArtistAccount[]>('huevify_artist_accounts', []);
        setArtistAccounts(savedArtistAccounts);

        const savedReleaseRequests = StorageService.load<ReleaseRequest[]>('huevify_release_requests', []);
        setReleaseRequests(savedReleaseRequests);

        const savedProfileRequests = StorageService.load<ProfileEditRequest[]>('huevify_profile_requests', []);
        setProfileEditRequests(savedProfileRequests);

        const savedDeletedLegacy = StorageService.load<string[]>('huevify_deleted_legacy', []);
        setDeletedLegacyIds(savedDeletedLegacy);

        const mod = StorageService.load<ModeratorAccount | null>('huevify_moderator', null);
        setHasModerator(!!mod);

        // Initial Lib Refresh
        refreshLibrary(savedReleaseRequests);

        audioRef.current.volume = 0.5;
    } catch (e) {
        console.error("Initialization failed", e);
    }

    // Artificial delay to prevent "Logged out" flash, ensured to run
    setTimeout(() => {
        setIsInitialized(true);
    }, 500);
  }, []);

  // --- Load User-Specific Data when currentUser changes ---
  useEffect(() => {
      if (currentUser) {
          try {
              // Load Settings per user
              const userSettings = StorageService.load<AppSettings | null>(`huevify_settings_${currentUser.id}`, null);
              if (userSettings) {
                  setAppSettingsState({
                      ...userSettings,
                      albumCoverIndexes: userSettings.albumCoverIndexes || {}
                  });
              } else {
                  // Default settings
                  setAppSettingsState({
                    accentColor: '#1ed760',
                    language: 'English',
                    allowExplicitContent: true,
                    autoPlay: true,
                    crossfade: 0,
                    albumCoverIndexes: {}
                  });
              }

              // Load Recent per user
              const userRecent = StorageService.load<Track[]>(`huevify_recent_${currentUser.id}`, []);
              setRecentlyPlayed(userRecent);

              // Load Followed/Liked per user (Already separated by key)
              const storedLikedAlbums = StorageService.load<string[]>(`huevify_liked_albums_${currentUser.id}`, []);
              setLikedAlbumIds(storedLikedAlbums);

              const storedFollowedArtists = StorageService.load<string[]>(`huevify_followed_artists_${currentUser.id}`, []);
              setFollowedArtists(storedFollowedArtists);
          } catch(e) {
              console.error("Failed to load user specific data", e);
          }

      } else {
          // Reset if no user
          setRecentlyPlayed([]);
          setLikedAlbumIds([]);
          setFollowedArtists([]);
      }
  }, [currentUser]);

  // --- Release Scheduler Check ---
  useEffect(() => {
      const checkReleases = () => {
          try {
              const now = new Date();
              let changed = false;
              const updatedRequests = releaseRequests.map(req => {
                  if (req.status === 'APPROVED' && new Date(req.releaseDate).getTime() <= now.getTime()) {
                      changed = true;
                      return { ...req, status: 'LIVE' as const };
                  }
                  return req;
              });

              if (changed) {
                  setReleaseRequests(updatedRequests);
                  StorageService.save('huevify_release_requests', updatedRequests);
                  notifySync('ARTIST_DATA_UPDATE');
                  refreshLibrary(updatedRequests);
              }
          } catch (e) {
              console.error("Scheduler check failed", e);
          }
      };

      const interval = setInterval(checkReleases, 60000); 
      return () => clearInterval(interval);
  }, [releaseRequests]);


  // --- Artist Hub Methods ---

  const registerArtist = (data: Omit<ArtistAccount, 'id' | 'status'>): { success: boolean, message?: string } => {
      if (artistAccounts.some(a => a.username === data.username)) return { success: false, message: "Username taken" };

      const newArtist: ArtistAccount = {
          ...data,
          id: `art_${Date.now()}`,
          status: 'PENDING'
      };
      const updated = [...artistAccounts, newArtist];
      setArtistAccounts(updated);
      StorageService.save('huevify_artist_accounts', updated);
      notifySync('ARTIST_DATA_UPDATE');
      return { success: true };
  };

  const registerModerator = (data: ModeratorAccount): { success: boolean, message?: string } => {
      if (hasModerator) return { success: false, message: "Moderator already exists" };
      StorageService.save('huevify_moderator', data);
      setHasModerator(true);
      setCurrentModerator(data);
      // No sync needed for mod creation really
      return { success: true };
  };

  const loginArtistOrMod = (username: string, pass: string, type: 'ARTIST' | 'MODERATOR'): { success: boolean, message?: string } => {
      if (type === 'MODERATOR') {
          const mod = StorageService.load<ModeratorAccount | null>('huevify_moderator', null);
          if (mod && username === mod.username && pass === mod.password) {
              setCurrentModerator(mod);
              return { success: true };
          }
          return { success: false, message: "Invalid moderator credentials" };
      } else {
          const artist = artistAccounts.find(a => a.username === username && a.password === pass);
          if (!artist) return { success: false, message: "Invalid credentials" };
          if (artist.status === 'PENDING') return { success: false, message: "Account pending approval" };
          if (artist.status === 'REJECTED') return { success: false, message: "Account rejected" };

          setCurrentArtist(artist);
          return { success: true };
      }
  };

  const logoutArtistHub = () => {
      setCurrentArtist(null);
      setCurrentModerator(null);
  };

  const deleteArtistAccount = (artistId: string) => {
      const updated = artistAccounts.filter(a => a.id !== artistId);
      setArtistAccounts(updated);
      StorageService.save('huevify_artist_accounts', updated);
      notifySync('ARTIST_DATA_UPDATE');
      showNotification("Artist account deleted (Access Revoked). Artist content remains live.", "info");
  };

  const deleteRelease = (releaseId: string) => {
      // Check if it's a legacy release
      if (releaseId.startsWith('a') && !releaseId.includes('dist_')) {
          const updatedDeleted = [...deletedLegacyIds, releaseId];
          setDeletedLegacyIds(updatedDeleted);
          StorageService.save('huevify_deleted_legacy', updatedDeleted);
          notifySync('ARTIST_DATA_UPDATE');
          refreshLibrary(releaseRequests);
          showNotification("Legacy release hidden from platform.", "success");
          return;
      }

      const release = releaseRequests.find(r => r.id === releaseId);
      if (!release) return;

      if (release.status === 'LIVE' || release.status === 'APPROVED') {
          const updated = releaseRequests.map(r => r.id === releaseId ? { ...r, deletionRequested: true } : r);
          setReleaseRequests(updated);
          StorageService.save('huevify_release_requests', updated);
          notifySync('ARTIST_DATA_UPDATE');
          showNotification("Deletion requested. Pending moderator approval.", "info");
      } else {
          const updated = releaseRequests.filter(r => r.id !== releaseId);
          setReleaseRequests(updated);
          StorageService.save('huevify_release_requests', updated);
          notifySync('ARTIST_DATA_UPDATE');
          refreshLibrary(updated);

          // Cleanup Recently Played (Simple check)
          if (currentUser) {
              const newRecent = recentlyPlayed.filter(t => !t.id.includes(releaseId)); 
              setRecentlyPlayed(newRecent);
              StorageService.save(`huevify_recent_${currentUser.id}`, newRecent);
          }
          showNotification("Release deleted from drafts.", "success");
      }
  };

  const submitRelease = (
      releaseData: Omit<ReleaseRequest, 'id' | 'status' | 'artistId' | 'artistName' | 'submissionTime'>,
      overrideArtist?: { artistId: string, artistName: string }
  ) => {
      const artistId = overrideArtist ? overrideArtist.artistId : currentArtist?.id;
      const artistName = overrideArtist ? overrideArtist.artistName : currentArtist?.artistName;

      if (!artistId || !artistName) return;

      const newRelease: ReleaseRequest = {
          ...releaseData,
          id: `rel_${Date.now()}`,
          artistId: artistId,
          artistName: artistName,
          status: 'PENDING',
          submissionTime: new Date().toISOString()
      };

      // Auto-approve if moderator is uploading
      if (overrideArtist) {
          newRelease.status = 'APPROVED';
          // Check if date is in past, if so make LIVE
          if (new Date(newRelease.releaseDate).getTime() <= Date.now()) {
              newRelease.status = 'LIVE';
          }
      }

      const updated = [...releaseRequests, newRelease];
      setReleaseRequests(updated);
      StorageService.save('huevify_release_requests', updated);
      notifySync('ARTIST_DATA_UPDATE');

      if (newRelease.status === 'LIVE' || newRelease.status === 'APPROVED') {
          refreshLibrary(updated);
      }
  };

  const updateReleaseRequest = (id: string, data: Partial<ReleaseRequest>) => {
      // Check if updating a "legacy" ID that doesn't exist in requests yet (Migration scenario)
      if (id.startsWith('a') && !releaseRequests.find(r => r.id === id)) {
          // This is a legacy album being "edited". We need to create a new Request for it with the legacy ID
          // to overwrite the static data in refreshLibrary
          const newRequest: ReleaseRequest = {
              ...data as ReleaseRequest, // Data contains the full form state
              id: id, // Keep legacy ID to override
              status: 'LIVE', // Directly live if mod edits legacy
              submissionTime: new Date().toISOString()
          };
          const updated = [...releaseRequests, newRequest];
          setReleaseRequests(updated);
          StorageService.save('huevify_release_requests', updated);
          notifySync('ARTIST_DATA_UPDATE');
          refreshLibrary(updated);
          return;
      }

      const updated = releaseRequests.map(r => r.id === id ? { ...r, ...data } : r);
      setReleaseRequests(updated);
      StorageService.save('huevify_release_requests', updated);
      notifySync('ARTIST_DATA_UPDATE');

      // If it's live or approved, we need to refresh the library to reflect changes
      const req = updated.find(r => r.id === id);
      if (req && (req.status === 'LIVE' || req.status === 'APPROVED')) {
          refreshLibrary(updated);
      }
  };

  const submitProfileEdit = (editData: Omit<ProfileEditRequest, 'id' | 'status' | 'artistId' | 'artistName'>) => {
      if (!currentArtist) return;
      const newReq: ProfileEditRequest = {
          ...editData,
          id: `pe_${Date.now()}`,
          artistId: currentArtist.id,
          artistName: currentArtist.artistName,
          status: 'PENDING'
      };
      const updated = [...profileEditRequests, newReq];
      setProfileEditRequests(updated);
      StorageService.save('huevify_profile_requests', updated);
      notifySync('ARTIST_DATA_UPDATE');
  };

  const approveArtist = (id: string) => {
      const updated = artistAccounts.map(a => a.id === id ? { ...a, status: 'APPROVED' as const } : a);
      setArtistAccounts(updated);
      StorageService.save('huevify_artist_accounts', updated);
      notifySync('ARTIST_DATA_UPDATE');
  };
  const rejectArtist = (id: string) => {
      const updated = artistAccounts.map(a => a.id === id ? { ...a, status: 'REJECTED' as const } : a);
      setArtistAccounts(updated);
      StorageService.save('huevify_artist_accounts', updated);
      notifySync('ARTIST_DATA_UPDATE');
  };

  const approveRelease = (id: string) => {
      const existingReq = releaseRequests.find(r => r.id === id);
      if (!existingReq) return;

      if (existingReq.deletionRequested) {
          const updated = releaseRequests.filter(r => r.id !== id);
          setReleaseRequests(updated);
          StorageService.save('huevify_release_requests', updated);
          refreshLibrary(updated);
          notifySync('ARTIST_DATA_UPDATE');
          return;
      }

      const tracksWithHueqs = existingReq.tracks.map(t => {
          if (t.existingHueq) return t; 
          return { ...t, generatedHueq: generateHUEQ() }; 
      });

      const updatedRequests = releaseRequests.map(r => 
          r.id === id 
            ? { ...r, status: 'APPROVED' as const, tracks: tracksWithHueqs } 
            : r
      );

      setReleaseRequests(updatedRequests);
      StorageService.save('huevify_release_requests', updatedRequests);
      notifySync('ARTIST_DATA_UPDATE');

      const req = updatedRequests.find(r => r.id === id);
      if (req && new Date(req.releaseDate).getTime() <= Date.now()) {
          refreshLibrary(updatedRequests);
      }
  };
  const rejectRelease = (id: string) => {
      // If it's a deletion request rejection, we just cancel the deletion request
      const req = releaseRequests.find(r => r.id === id);
      if (req && req.deletionRequested) {
          const updated = releaseRequests.map(r => r.id === id ? { ...r, deletionRequested: false } : r);
          setReleaseRequests(updated);
          StorageService.save('huevify_release_requests', updated);
          showNotification("Deletion rejected. Release remains live.", "info");
      } else {
          // Normal rejection of a new release
          const updated = releaseRequests.map(r => r.id === id ? { ...r, status: 'REJECTED' as const, deletionRequested: false } : r);
          setReleaseRequests(updated);
          StorageService.save('huevify_release_requests', updated);
          showNotification("Release rejected.", "info");
      }
      notifySync('ARTIST_DATA_UPDATE');
  };

  const approveProfileEdit = (id: string) => {
      const req = profileEditRequests.find(r => r.id === id);
      if (!req) return;

      const updatedAccounts = artistAccounts.map(a => {
          if (a.id === req.artistId) {
              return {
                  ...a,
                  avatar: req.newAvatar || a.avatar,
                  bio: req.newBio || a.bio,
                  artistPick: req.newArtistPick || a.artistPick
              };
          }
          return a;
      });
      setArtistAccounts(updatedAccounts);
      StorageService.save('huevify_artist_accounts', updatedAccounts);

      const updatedReqs = profileEditRequests.map(r => r.id === id ? { ...r, status: 'APPROVED' as const } : r);
      setProfileEditRequests(updatedReqs);
      StorageService.save('huevify_profile_requests', updatedReqs);
      notifySync('ARTIST_DATA_UPDATE');
  };
  const rejectProfileEdit = (id: string) => {
      const updatedReqs = profileEditRequests.map(r => r.id === id ? { ...r, status: 'REJECTED' as const } : r);
      setProfileEditRequests(updatedReqs);
      StorageService.save('huevify_profile_requests', updatedReqs);
      notifySync('ARTIST_DATA_UPDATE');
  };

  const getTrackByHueq = (hueq: string): Track | undefined => {
      return tracks.find(t => t.hueq === hueq);
  };

  // --- Existing Logic (Daily Chart, etc.) ---
  useEffect(() => {
    if (tracks.length === 0) return;

    const processDailyChart = () => {
        const now = new Date();
        const lastUpdateStr = StorageService.load<string | null>('huevify_last_chart_update', null);
        const playSnapshot = StorageService.load<Record<string, number>>('huevify_chart_snapshot', {});

        let threshold = new Date();
        threshold.setUTCHours(18, 0, 0, 0); 

        if (now.getTime() < threshold.getTime()) {
            threshold.setDate(threshold.getDate() - 1);
        }

        const lastUpdateDate = lastUpdateStr ? new Date(lastUpdateStr) : new Date(0);

        if (lastUpdateDate.getTime() < threshold.getTime()) {
            const currentPlaysMap = tracks.reduce((acc, t) => ({...acc, [t.id]: t.plays}), {});

            const chartData: DailyChartTrack[] = tracks.map(t => {
                const prevPlays = playSnapshot[t.id] || 0;
                const dailyDelta = Math.max(0, t.plays - prevPlays);
                return { ...t, dailyPlays: dailyDelta };
            });

            const sorted = chartData.sort((a, b) => b.dailyPlays - a.dailyPlays).slice(0, 25);
            setDailyChart(sorted);
            StorageService.save('huevify_daily_chart', sorted);

            StorageService.save('huevify_chart_snapshot', currentPlaysMap);
            StorageService.save('huevify_last_chart_update', now.toISOString());
        } else {
            const savedChart = StorageService.load<DailyChartTrack[]>('huevify_daily_chart', []);
            setDailyChart(savedChart);
        }
    };

    processDailyChart();
    const interval = setInterval(processDailyChart, 60000);
    return () => clearInterval(interval);

  }, [tracks]);

  // --- Album Cover Logic ---
  const getAlbumCover = (albumId: string): string => {
      const album = albums.find(a => a.id === albumId);
      if (!album || !album.covers || album.covers.length === 0) return "";
      // albumCoverIndexes is loaded from user-specific settings
      const index = appSettings.albumCoverIndexes[albumId] || 0;
      return album.covers[index] || album.covers[0];
  };

  const getTrackCover = (track: Track): string => {
      // Find the album associated with this track to check for a preferred cover
      const album = albums.find(a => a.title === track.album);
      if (album) {
          return getAlbumCover(album.id);
      }
      return track.cover;
  };

  const changeAlbumCover = (albumId: string, index: number) => {
      updateSettings({
          albumCoverIndexes: {
              ...appSettings.albumCoverIndexes,
              [albumId]: index
          }
      });
  };

  // --- Settings Injection Effect ---
  useEffect(() => {
    const color = appSettings.accentColor;
    const styleId = 'huevify-theme-override';
    let styleTag = document.getElementById(styleId);
    if (!styleTag) {
        styleTag = document.createElement('style');
        styleTag.id = styleId;
        document.head.appendChild(styleTag);
    }
    styleTag.innerHTML = `
        .text-primary { color: ${color} !important; }
        .bg-primary { background-color: ${color} !important; }
        .border-primary { border-color: ${color} !important; }
        .accent-primary { accent-color: ${color} !important; }
        .group:hover .group-hover\\:text-primary { color: ${color} !important; }
        .group:hover .group-hover\\:bg-primary { background-color: ${color} !important; }
        .selection\\:bg-primary::selection { background-color: ${color} !important; }
        .range-slider::-webkit-slider-thumb:hover { background-color: ${color} !important; }
    `;
  }, [appSettings.accentColor]);

  // --- Playlist Loading & Account Isolation ---
  useEffect(() => {
    let allPlaylists = StorageService.load<Playlist[]>('huevify_playlists', []);

    // Create unique Liked playlist per user
    if (currentUser) {
        const likedId = `liked_${currentUser.id}`;
        // Only create if it doesn't exist AND we are filtering by exact ID later
        if (!allPlaylists.find(p => p.id === likedId)) {
            const likedPl: Playlist = { 
                id: likedId, 
                name: 'Liked Songs', 
                tracks: [], 
                isSystem: true, 
                description: 'Your favorite tracks',
                ownerId: currentUser.id
            };
            allPlaylists = [likedPl, ...allPlaylists];
            StorageService.save('huevify_playlists', allPlaylists);
        }
    }
    setPlaylists(allPlaylists);
  }, [currentUser]); 

  // --- Settings Methods ---
  const updateSettings = (newSettings: Partial<AppSettings>) => {
      if (!currentUser) return;
      setAppSettingsState(prev => {
          const updated = { ...prev, ...newSettings };
          // Save to user-specific key
          StorageService.save(`huevify_settings_${currentUser.id}`, updated);
          notifySync('SETTINGS_UPDATE');
          return updated;
      });
  };

  const updateUserProfile = (data: Partial<User>): { success: boolean; message?: string } => {
      if (!currentUser) return { success: false, message: "Not logged in" };
      const users = StorageService.load<User[]>('huevify_users', []);
      if (data.username && data.username !== currentUser.username) {
          if (users.some(u => u.username === data.username)) {
              return { success: false, message: "Username already taken" };
          }
      }
      const updatedUser = { ...currentUser, ...data };
      const updatedUsersList = users.map(u => u.id === currentUser.id ? updatedUser : u);
      StorageService.save('huevify_users', updatedUsersList);
      StorageService.save('huevify_current_user', updatedUser);
      setCurrentUser(updatedUser);
      if (data.displayName || data.avatar) {
          const allPlaylists = StorageService.load<Playlist[]>('huevify_playlists', []);
          const updatedPlaylists = allPlaylists.map(p => {
              if (p.ownerId === currentUser.id) {
                  return { 
                      ...p, 
                      creatorName: data.displayName || p.creatorName,
                      creatorAvatar: data.avatar || p.creatorAvatar
                  };
              }
              return p;
          });
          StorageService.save('huevify_playlists', updatedPlaylists);
          setPlaylists(updatedPlaylists);
          notifySync('PLAYLISTS_UPDATE');
      }
      return { success: true };
  };

  // --- Auth Methods ---
  const login = (username: string, pass: string): boolean => {
    const users = StorageService.load<User[]>('huevify_users', []);
    const user = users.find(u => u.username === username && u.password === pass);
    if (user) {
        setCurrentUser(user);
        StorageService.save('huevify_current_user', user);
        return true;
    }
    return false;
  };

  const register = (newUser: Omit<User, 'id'>): boolean => {
      const users = StorageService.load<User[]>('huevify_users', []);
      if (users.some(u => u.username === newUser.username)) {
          return false; // User exists
      }
      const user: User = { ...newUser, id: `user_${Date.now()}` };
      const updatedUsers = [...users, user];
      StorageService.save('huevify_users', updatedUsers);
      setCurrentUser(user);
      StorageService.save('huevify_current_user', user);
      return true;
  };

  const logout = () => {
      setCurrentUser(null);
      StorageService.save('huevify_current_user', null);
      setProfileModalOpen(false);
      setIsPlaying(false);
      audioRef.current.pause();
      setCurrentTrack(null);
      setViewInternal({ type: 'HOME' });
  };

  // --- Logic for Recs ---
  useEffect(() => {
    if (tracks.length === 0 || !currentUser) return;
    const genreScores: Record<string, number> = {};
    // Use dynamic liked ID
    const likedId = `liked_${currentUser.id}`;
    const likedPlaylist = playlists.find(p => p.id === likedId);
    const likedIds = likedPlaylist ? likedPlaylist.tracks : [];

    tracks.forEach(t => {
      let score = 0;
      if (likedIds.includes(t.id)) score += 50;
      if (t.plays > 0) score += Math.log(t.plays) * 2;
      if (score > 0) {
        genreScores[t.genre] = (genreScores[t.genre] || 0) + score;
      }
    });
    const topGenres = Object.entries(genreScores).sort(([, a], [, b]) => b - a).slice(0, 3).map(([g]) => g);
    const targetGenres = topGenres.length > 0 ? topGenres : tracks.map(t => t.genre);
    const candidates = tracks.filter(t => targetGenres.includes(t.genre) && !likedIds.includes(t.id));
    // Filter explicit if needed
    const filteredCandidates = appSettings.allowExplicitContent ? candidates : candidates.filter(t => !t.explicit);
    const shuffled = [...filteredCandidates].sort(() => 0.5 - Math.random()).slice(0, 6);
    setRecommendations(shuffled);
  }, [tracks, playlists, currentUser, appSettings.allowExplicitContent]);

  useEffect(() => {
    if (tracks.length > 0) {
      const playCounts = tracks.reduce((acc, t) => ({ ...acc, [t.id]: t.plays }), {});
      StorageService.save('huevify_plays', playCounts);
    }
  }, [tracks]);

  useEffect(() => {
    if(currentUser) {
        StorageService.save(`huevify_liked_albums_${currentUser.id}`, likedAlbumIds);
    }
  }, [likedAlbumIds, currentUser]);

  useEffect(() => {
    if(currentUser) {
        StorageService.save(`huevify_followed_artists_${currentUser.id}`, followedArtists);
    }
  }, [followedArtists, currentUser]);

  // --- Navigation ---
  const setView = (newView: ViewState) => {
    if (JSON.stringify(view) !== JSON.stringify(newView)) {
      setHistory(prev => [...prev, view]);
      setViewInternal(newView);
    }
    setMobilePlayerOpen(false);
  };

  const goToArtist = (artistName: string) => {
    setView({ type: 'ARTIST', id: artistName });
    setMobilePlayerOpen(false);
  }

  const goBack = () => {
    if (history.length > 0) {
      const prev = history[history.length - 1];
      setHistory(h => h.slice(0, -1));
      setViewInternal(prev);
    } else {
      setViewInternal({ type: 'HOME' });
    }
  };

  const getArtistStats = (artistName: string): ArtistStats => {
    const artistPlayMap: Record<string, number> = {};
    tracks.forEach(t => { 
        const primary = t.artist;
        if (primary) artistPlayMap[primary] = (artistPlayMap[primary] || 0) + t.plays;

        if (t.mainArtists) {
            t.mainArtists.forEach(ma => {
                artistPlayMap[ma] = (artistPlayMap[ma] || 0) + t.plays;
            });
        }
    });

    const sortedArtists = Object.entries(artistPlayMap).sort(([, a], [, b]) => b - a);
    const rankIndex = sortedArtists.findIndex(([name]) => name === artistName);
    const totalPlays = artistPlayMap[artistName] || 0;

    return { monthlyPlays: totalPlays, globalRank: rankIndex === -1 ? 999 : rankIndex + 1 };
  };

  const toggleFollowArtist = (artistName: string) => {
    setFollowedArtists(prev => prev.includes(artistName) ? prev.filter(a => a !== artistName) : [...prev, artistName]);
  };
  const isArtistFollowed = (artistName: string) => followedArtists.includes(artistName);

  // --- Player Logic ---
  useEffect(() => {
    cumulativeTimeRef.current = 0;
    lastTimeRef.current = 0;
    setHasCountedListen(false);
  }, [currentTrack]);

  useEffect(() => {
    const audio = audioRef.current;
    const handleTimeUpdate = () => {
      const now = audio.currentTime;
      setProgress(now);
      const diff = now - lastTimeRef.current;

      // Accumulate listen time if playing normally (not scrubbing fast)
      if (diff > 0 && diff < 1.5) {
          cumulativeTimeRef.current += diff;
      }
      lastTimeRef.current = now;

      // Count play ONLY if active listen > 30s AND hasn't counted for this specific track instance yet
      if (cumulativeTimeRef.current > 30 && !hasCountedListen && currentTrack) {
          handleListenCount(currentTrack);
      }
    };
    const handleEnded = () => {
      if (playMode === PlayMode.ONE) { 
          audio.currentTime = 0; 
          // Logic: If user repeats ONE, it counts as a new listen for the next loop
          cumulativeTimeRef.current = 0; 
          setHasCountedListen(false);
          audio.play(); 
      }
      else if (appSettings.autoPlay) { nextTrack(); } 
      else { setIsPlaying(false); audioRef.current.pause(); }
    };
    const handleLoadedMetadata = () => setDuration(audio.duration);
    audio.addEventListener('timeupdate', handleTimeUpdate);
    audio.addEventListener('ended', handleEnded);
    audio.addEventListener('loadedmetadata', handleLoadedMetadata);
    return () => {
      audio.removeEventListener('timeupdate', handleTimeUpdate);
      audio.removeEventListener('ended', handleEnded);
      audio.removeEventListener('loadedmetadata', handleLoadedMetadata);
    };
  }, [currentTrack, hasCountedListen, playMode, tracks, isShuffle, appSettings.autoPlay]);

  const handleListenCount = (track: Track) => {
    const addedPlays = Math.floor(100 + Math.random() * 9900); 
    setTracks(prev => {
        const updated = prev.map(t => t.id === track.id ? { ...t, plays: t.plays + addedPlays } : t);
        const playCounts = updated.reduce((acc, t) => ({ ...acc, [t.id]: t.plays }), {});
        StorageService.save('huevify_plays', playCounts);
        notifySync('TRACKS_UPDATE');
        return updated;
    });
    setHasCountedListen(true);
  };

  const playTrack = (track: Track) => {
    // 1. Check if track is Explicit and allowed
    if (track.explicit && !appSettings.allowExplicitContent) {
        showNotification("Content not available. Turn on 'Allow Explicit Content' in settings.", "error");
        return;
    }

    // 2. Check if track is actually live (Deleted tracks check)
    const isLive = tracks.find(t => t.id === track.id);
    if (!isLive) {
        showNotification("This track is no longer available.", "error");
        return;
    }

    // Save to User Specific Recent
    if (currentUser) {
        setRecentlyPlayed(prev => {
            const filtered = prev.filter(t => t.id !== track.id);
            const newHistory = [track, ...filtered].slice(0, 10);
            StorageService.save(`huevify_recent_${currentUser.id}`, newHistory);
            return newHistory;
        });
    }

    if (currentTrack?.id === track.id) { togglePlay(); return; }

    // New Track Logic
    setCurrentTrack(track);
    setHasCountedListen(false); // Reset listen count for new track
    cumulativeTimeRef.current = 0; // Reset time accumulator

    audioRef.current.src = track.url;
    audioRef.current.play().then(() => setIsPlaying(true)).catch(e => console.error("Audio play failed", e));
  };

  const togglePlay = () => {
    if (audioRef.current.paused) { audioRef.current.play(); setIsPlaying(true); }
    else { audioRef.current.pause(); setIsPlaying(false); }
  };
  const setVolume = (vol: number) => { setVolumeState(vol); audioRef.current.volume = vol; };
  const seek = (time: number) => { audioRef.current.currentTime = time; lastTimeRef.current = time; setProgress(time); };

  const getQueue = (): Track[] => {
    if (view.type === 'PLAYLIST' && (view as any).id === 'history') {
        if (!appSettings.allowExplicitContent) {
            return recentlyPlayed.filter(t => !t.explicit);
        }
        return recentlyPlayed;
    }
    if (!appSettings.allowExplicitContent) {
        return tracks.filter(t => !t.explicit);
    }
    return tracks; 
  };
  const nextTrack = () => {
    const queue = getQueue();
    if (isShuffle) { playTrack(queue[Math.floor(Math.random() * queue.length)]); return; }
    const idx = queue.findIndex(t => t.id === currentTrack?.id);
    if (idx !== -1 && idx < queue.length - 1) playTrack(queue[idx + 1]);
    else if (playMode === PlayMode.CONTEXT) playTrack(queue[0]);
    else { setIsPlaying(false); audioRef.current.pause(); audioRef.current.currentTime = 0; }
  };
  const prevTrack = () => {
    if (audioRef.current.currentTime > 3) { audioRef.current.currentTime = 0; lastTimeRef.current = 0; return; }
    const queue = getQueue();
    const idx = queue.findIndex(t => t.id === currentTrack?.id);
    if (idx > 0) playTrack(queue[idx - 1]); else playTrack(queue[queue.length - 1]);
  };
  const toggleRepeat = () => {
    if (playMode === PlayMode.OFF) setPlayMode(PlayMode.CONTEXT);
    else if (playMode === PlayMode.CONTEXT) setPlayMode(PlayMode.ONE);
    else setPlayMode(PlayMode.OFF);
  };
  const toggleShuffle = () => setIsShuffle(!isShuffle);

  const syncPlaylists = (newGlobalPlaylists: Playlist[]) => {
      StorageService.save('huevify_playlists', newGlobalPlaylists);
      setPlaylists(newGlobalPlaylists);
      notifySync('PLAYLISTS_UPDATE');
  };
  const createPlaylist = (name: string, description?: string, cover?: string, isPublic: boolean = false) => {
    if (!currentUser) return;
    const newPl: Playlist = { id: `pl_${Date.now()}`, name, description: description || "", customCover: cover, tracks: [], ownerId: currentUser.id, creatorName: currentUser.displayName, creatorAvatar: currentUser.avatar, isPublic: isPublic, savedBy: [] };
    const all = [...playlists]; 
    syncPlaylists([...all, newPl]);
  };
  const editPlaylist = (id: string, name: string, description?: string, cover?: string, isPublic?: boolean) => {
    const all = [...playlists];
    const updated = all.map(p => { if (p.id === id) { return { ...p, name, description, customCover: cover, isPublic: isPublic !== undefined ? isPublic : p.isPublic }; } return p; });
    syncPlaylists(updated);
  };
  const openDeleteModal = (id: string) => { setPlaylistToDelete(id); setIsDeleteModalOpen(true); };
  const closeDeleteModal = () => { setIsDeleteModalOpen(false); setPlaylistToDelete(null); };
  const confirmDeletePlaylist = () => { if (!playlistToDelete) return; const id = playlistToDelete; if (view.type === 'PLAYLIST' && (view as any).id === id) setViewInternal({ type: 'LIBRARY' }); const all = [...playlists]; const updated = all.filter(p => p.id !== id); syncPlaylists(updated); closeDeleteModal(); };
  const deletePlaylist = (id: string) => openDeleteModal(id);
  const addToPlaylist = (playlistId: string, trackId: string) => { 
      const updated = playlists.map(p => { 
          if (p.id === playlistId && !p.tracks.includes(trackId)) {
              return { ...p, tracks: [...p.tracks, trackId] }; 
          }
          return p; 
      }); 
      syncPlaylists(updated); 
  };
  const removeFromPlaylist = (playlistId: string, trackId: string) => { 
      const updated = playlists.map(p => { 
          if (p.id === playlistId) {
              return { ...p, tracks: p.tracks.filter(id => id !== trackId) }; 
          }
          return p; 
      }); 
      syncPlaylists(updated); 
  };
  const togglePlaylistSave = (playlistId: string) => { if (!currentUser) return; const updated = playlists.map(p => { if (p.id === playlistId) { const saved = p.savedBy || []; const isSaved = saved.includes(currentUser.id); return { ...p, savedBy: isSaved ? saved.filter(id => id !== currentUser.id) : [...saved, currentUser.id] }; } return p; }); syncPlaylists(updated); };

  // Account Isolated Likes
  const toggleLike = (trackId: string) => { 
      if (!currentUser) return;
      const likedId = `liked_${currentUser.id}`;
      const likedPl = playlists.find(p => p.id === likedId); 
      if (!likedPl) return; 
      if (likedPl.tracks.includes(trackId)) removeFromPlaylist(likedId, trackId); 
      else addToPlaylist(likedId, trackId); 
  };
  const isLiked = (trackId: string) => { 
      if (!currentUser) return false;
      const likedId = `liked_${currentUser.id}`;
      const likedPl = playlists.find(p => p.id === likedId); 
      return likedPl ? likedPl.tracks.includes(trackId) : false; 
  };

  const toggleAlbumLike = (albumId: string) => { setLikedAlbumIds(prev => prev.includes(albumId) ? prev.filter(id => id !== albumId) : [...prev, albumId]); };
  const isAlbumLiked = (albumId: string) => likedAlbumIds.includes(albumId);
  const openAddToPlaylist = (trackId: string) => { setTrackIdToAdd(trackId); setAddToPlaylistOpen(true); };
  const closeAddToPlaylist = () => { setAddToPlaylistOpen(false); setTrackIdToAdd(null); };

  if (!isInitialized && currentUser) {
      return (
          <div className="flex h-screen w-full bg-black items-center justify-center flex-col gap-4">
              <div className="w-20 h-20 bg-primary/20 rounded-full flex items-center justify-center animate-pulse">
                  <div className="text-4xl font-bold text-primary">H</div>
              </div>
              <div className="text-secondary text-sm animate-pulse">Loading Library...</div>
          </div>
      );
  }

  return (
    <StoreContext.Provider value={{
      currentUser, login, register, logout, updateUserProfile,
      appSettings, updateSettings, dailyChart,
      getAlbumCover, changeAlbumCover, getTrackCover,
      isArtistHubOpen, setArtistHubOpen, currentArtist, currentModerator, artistAccounts,
      registerArtist, registerModerator, loginArtistOrMod, logoutArtistHub, submitRelease, submitProfileEdit, deleteRelease, updateReleaseRequest, deleteArtistAccount,
      approveArtist, rejectArtist, approveRelease, rejectRelease, approveProfileEdit, rejectProfileEdit,
      releaseRequests, profileEditRequests, hasModerator, existingArtists, getTrackByHueq,
      tracks, albums, playlists, recommendations, recentlyPlayed, followedArtists, currentTrack, isPlaying, playMode, isShuffle, volume, progress, duration, view,
      isCreatePlaylistOpen, setCreatePlaylistOpen, playlistIdToEdit, setPlaylistIdToEdit,
      isMobilePlayerOpen, setMobilePlayerOpen,
      isAddToPlaylistOpen, trackIdToAdd, openAddToPlaylist, closeAddToPlaylist,
      isDeleteModalOpen, playlistToDelete, openDeleteModal, closeDeleteModal, confirmDeletePlaylist,
      isProfileModalOpen, setProfileModalOpen, likedPlaylistId, notifications, showNotification, dismissNotification,
      setView, goToArtist, getArtistStats, toggleFollowArtist, isArtistFollowed, goBack, playTrack, togglePlay, nextTrack, prevTrack, seek, setVolume, toggleRepeat, toggleShuffle,
      createPlaylist, editPlaylist, deletePlaylist, addToPlaylist, removeFromPlaylist, togglePlaylistSave, toggleLike, isLiked,
      toggleAlbumLike, isAlbumLiked
    }}>
      {children}
    </StoreContext.Provider>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { useStore } from '../context/StoreContext.tsx';
import { 
  X, Mic2, Shield, User, UploadCloud, Calendar, FileAudio, 
  CheckCircle, XCircle, Clock, MoreVertical, Image, Plus,
  Edit, ArrowLeft, Camera, LogOut, ChevronDown, Trash2, ListMusic, Check, Search, Play, BarChart2, Globe, Database, Key
} from './Icons.tsx';
import { DistributionTrack, ReleaseType, ReleaseRequest } from '../types.ts';

type HubView = 'AUTH' | 'ARTIST_DASH' | 'MOD_DASH' | 'DISTRIBUTION' | 'PROFILE_EDIT' | 'ARTIST_PICK' | 'MOD_CREDENTIALS' | 'MOD_ALL_RELEASES';

const formatDuration = (seconds: number) => {
    const min = Math.floor(seconds / 60);
    const sec = Math.floor(seconds % 60);
    return `${min}:${sec.toString().padStart(2, '0')}`;
};

export const ArtistHub = () => {
  const { 
    isArtistHubOpen, setArtistHubOpen, currentArtist, currentModerator, 
    loginArtistOrMod, registerArtist, registerModerator, logoutArtistHub, artistAccounts,
    releaseRequests, profileEditRequests, approveArtist, rejectArtist,
    approveRelease, rejectRelease, approveProfileEdit, rejectProfileEdit,
    submitRelease, updateReleaseRequest, getArtistStats, submitProfileEdit, hasModerator, existingArtists,
    deleteRelease, getTrackByHueq, tracks, albums, playlists, showNotification, deleteArtistAccount
  } = useStore();

  const [view, setView] = useState<HubView>('AUTH');

  // Auth State
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [role, setRole] = useState<'ARTIST' | 'MODERATOR'>('ARTIST');
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");

  // Artist Registration Logic
  const [artistNameSelection, setArtistNameSelection] = useState("");
  const [isCreatingNewArtist, setIsCreatingNewArtist] = useState(false);
  const [newArtistAlias, setNewArtistAlias] = useState("");

  const [message, setMessage] = useState("");

  // Distribution State
  const [distStep, setDistStep] = useState(1);
  const [distTitle, setDistTitle] = useState("");
  const [distArtistName, setDistArtistName] = useState(""); // For Mods to override
  const [distType, setDistType] = useState<ReleaseType>('Single');
  const [distGenre, setDistGenre] = useState("Pop");
  const [distLabel, setDistLabel] = useState("");
  const [distCovers, setDistCovers] = useState<string[]>([]);
  const [distMainArtists, setDistMainArtists] = useState<string[]>([]);
  const [distMainArtistInput, setDistMainArtistInput] = useState("");
  const [distTracks, setDistTracks] = useState<DistributionTrack[]>([]);

  // Editing Mode
  const [isEditing, setIsEditing] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  // Track Tag Inputs (Step 2)
  const [trackArtistInputs, setTrackArtistInputs] = useState<Record<number, string>>({});

  const [distDate, setDistDate] = useState("");
  const [distTime, setDistTime] = useState("00:00");
  const [distMsg, setDistMsg] = useState("");

  // Edit Profile State
  const [editBio, setEditBio] = useState("");
  const [editAvatar, setEditAvatar] = useState("");

  // Artist Pick State
  const [pickSearch, setPickSearch] = useState("");

  // Release Detail Modal State
  const [selectedRelease, setSelectedRelease] = useState<ReleaseRequest | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const coverInputRef = useRef<HTMLInputElement>(null);
  const avatarInputRef = useRef<HTMLInputElement>(null);

  // Initialize view based on login state
  useEffect(() => {
      if (isArtistHubOpen) {
          if (currentArtist) {
              setView('ARTIST_DASH');
              setEditBio(currentArtist.bio || "");
              setEditAvatar(currentArtist.avatar || "");
          }
          else if (currentModerator) setView('MOD_DASH');
          else setView('AUTH');
      }
  }, [isArtistHubOpen, currentArtist, currentModerator]);

  if (!isArtistHubOpen) return null;

  const handleLogin = (e: React.FormEvent) => {
      e.preventDefault();
      setMessage("");
      const res = loginArtistOrMod(username, password, role);
      if (res.success) {
          if (role === 'ARTIST') {
              setView('ARTIST_DASH');
          }
          else setView('MOD_DASH');
          showNotification("Welcome back!", "success");
      } else {
          setMessage(res.message || "Login failed");
      }
  };

  const handleRegister = (e: React.FormEvent) => {
      e.preventDefault();

      if (role === 'MODERATOR') {
          if (hasModerator) {
              setMessage("Moderator registration is closed.");
              return;
          }
          const res = registerModerator({ username, password });
          if (res.success) {
              setMessage("Moderator registered! Please login.");
              setAuthMode('LOGIN');
          } else {
              setMessage(res.message || "Error registering moderator");
          }
          return;
      }

      // Artist Registration
      const finalArtistName = isCreatingNewArtist ? newArtistAlias : artistNameSelection;

      if (!finalArtistName) {
          setMessage("Please select or enter an artist name.");
          return;
      }

      const res = registerArtist({
          artistName: finalArtistName, 
          username, 
          password,
          artistPick: undefined
      });

      if (res.success) {
          setMessage("Registration sent for approval.");
          setAuthMode('LOGIN');
      } else {
          setMessage(res.message || "Error registering");
      }
  };

  // --- Distribution Handlers ---
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          // Convert to Base64 for persistence
          const reader = new FileReader();
          reader.onloadend = () => {
              const base64Audio = reader.result as string;

              // Create temp audio element to get duration
              const audio = new Audio(base64Audio);
              audio.onloadedmetadata = () => {
                  const newTrack: DistributionTrack = {
                      title: file.name.replace(/\.[^/.]+$/, ""),
                      explicit: false,
                      mainArtists: [],
                      genre: distGenre, // Default to release genre
                      duration: audio.duration,
                      fileUrl: base64Audio
                  };
                  setDistTracks(prev => [...prev, newTrack]);
              };
          };
          reader.readAsDataURL(file);
      }
  };

  const updateTrack = (idx: number, field: keyof DistributionTrack, val: any) => {
      setDistTracks(prev => {
          const newTracks = [...prev];
          newTracks[idx] = { ...newTracks[idx], [field]: val };
          return newTracks;
      });
  };

  // Track Artist Tag Handlers
  const addTrackArtist = (trackIdx: number) => {
      const name = trackArtistInputs[trackIdx];
      if (!name) return;

      setDistTracks(prev => {
          const newTracks = [...prev];
          const currentArtists = newTracks[trackIdx].mainArtists || [];
          newTracks[trackIdx] = { 
              ...newTracks[trackIdx], 
              mainArtists: [...currentArtists, name] 
          };
          return newTracks;
      });

      setTrackArtistInputs(prev => ({ ...prev, [trackIdx]: "" }));
  };

  const removeTrackArtist = (trackIdx: number, artistToRemove: string) => {
      setDistTracks(prev => {
          const newTracks = [...prev];
          const currentArtists = newTracks[trackIdx].mainArtists || [];
          newTracks[trackIdx] = { 
              ...newTracks[trackIdx], 
              mainArtists: currentArtists.filter(a => a !== artistToRemove) 
          };
          return newTracks;
      });
  };

  const handleHueqBlur = (idx: number, hueq: string) => {
      if (!hueq) return;
      const existing = getTrackByHueq(hueq);

      if (existing) {
          setDistTracks(prev => {
              const newTracks = [...prev];
              newTracks[idx] = {
                  ...newTracks[idx],
                  title: existing.title,
                  explicit: existing.explicit || false,
                  feat: existing.feat || "",
                  existingHueq: hueq,
                  fileUrl: existing.url,
                  duration: existing.duration,
                  genre: existing.genre, // Sync genre
                  mainArtists: existing.mainArtists || []
              };
              return newTracks;
          });
          showNotification(`HUEQ Found! Track details auto-filled: ${existing.title}`, "success");
      } else {
          updateTrack(idx, 'existingHueq', hueq);
      }
  };

  const handleNextStep = () => {
      if (distStep === 1) {
          if (!distTitle || !distType || !distGenre || distCovers.length === 0) {
              showNotification("Please complete all required fields (Title, Type, Genre, Covers)", "error");
              return;
          }
          if (currentModerator && !distArtistName) {
              showNotification("Artist Name is required for Moderator uploads.", "error");
              return;
          }
      }
      if (distStep === 2) {
          if (distTracks.length === 0) {
              showNotification("Please add at least one track.", "error");
              return;
          }
      }
      setDistStep(prev => prev + 1);
  };

  const handleSubmitRelease = () => {
      if (!distDate || !distTime) {
          showNotification("Please specify Release Date and Time.", "error");
          return;
      }

      const dateTime = new Date(`${distDate}T${distTime}:00+03:00`);

      // Determine Artist Identity
      const overrideArtist = currentModerator ? { 
          artistId: isEditing && editingId && !editingId.startsWith('a') ? (releaseRequests.find(r => r.id === editingId)?.artistId || `va_${Date.now()}`) : `va_${Date.now()}`,
          artistName: distArtistName || "Various Artists" 
      } : undefined;

      const payload = {
          title: distTitle,
          type: distType,
          genre: distGenre,
          label: distLabel || (currentArtist?.artistName || distArtistName || "Independent"),
          covers: distCovers, 
          additionalMainArtists: distMainArtists,
          tracks: distTracks,
          releaseDate: dateTime.toISOString(),
          releaseMessage: distMsg
      };

      if (isEditing && editingId) {
          updateReleaseRequest(editingId, {
              ...payload,
              // If mod is editing, allow updating artist name/id
              artistName: overrideArtist?.artistName || releaseRequests.find(r => r.id === editingId)?.artistName || ""
          });
          showNotification("Release updated successfully.", "success");
      } else {
          submitRelease(payload, overrideArtist);
          showNotification("Release submitted!", "success");
      }

      // Navigate back
      if (currentModerator) {
          setView('MOD_ALL_RELEASES');
      } else {
          setView('ARTIST_DASH');
      }

      resetDistForm();
  };

  const resetDistForm = () => {
      setDistStep(1); 
      setDistTitle(""); 
      setDistArtistName("");
      setDistTracks([]); 
      setDistCovers([]); 
      setDistMsg(""); 
      setDistMainArtists([]); 
      setTrackArtistInputs({});
      setIsEditing(false);
      setEditingId(null);
  };

  const handleCoverUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const files = e.target.files;
      if (files && files.length > 0) {
          Array.from(files).forEach((file: File) => {
              const reader = new FileReader();
              reader.onloadend = () => setDistCovers(prev => [...prev, reader.result as string]);
              reader.readAsDataURL(file);
          });
      }
  };

  const handleAvatarUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setEditAvatar(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleProfileUpdate = () => {
      if (!currentArtist) return;
      submitProfileEdit({ newBio: editBio, newAvatar: editAvatar });
      showNotification("Profile update sent for moderation approval.", "success");
      setView('ARTIST_DASH');
  };

  const handleEditRelease = (release: any) => {
      setIsEditing(true);
      setEditingId(release.id);

      setDistTitle(release.title);
      setDistType(release.type);
      setDistGenre(release.genre);
      setDistLabel(release.label || release.recordLabel || "");
      setDistCovers(release.covers);
      setDistMainArtists(release.additionalMainArtists || release.mainArtists || []);
      setDistTracks(release.tracks || []);

      // If mod, allow editing artist name
      if (currentModerator) {
          setDistArtistName(release.artistName || release.artist);
      }

      // Date Time parsing
      const dateObj = release.releaseDate ? new Date(release.releaseDate) : new Date();
      // Simple ISO to yyyy-MM-dd
      setDistDate(dateObj.toISOString().split('T')[0]);
      // Simple time
      setDistTime(dateObj.toTimeString().slice(0, 5));

      setDistMsg(release.releaseMessage || "");

      setDistStep(1);
      setView('DISTRIBUTION');
  };

  // --- RENDERERS ---

  const renderAuth = () => (
      <div className="w-full max-w-md bg-surface p-8 rounded-xl shadow-2xl border border-surface-highlight animate-zoom-in">
          <div className="flex justify-center mb-6">
              <div className="w-16 h-16 bg-primary/20 rounded-full flex items-center justify-center animate-bounce">
                  {role === 'ARTIST' ? <Mic2 size={32} className="text-primary" /> : <Shield size={32} className="text-primary" />}
              </div>
          </div>
          <h2 className="text-2xl font-bold text-center mb-6">{authMode === 'LOGIN' ? 'Log in to' : 'Join'} Huevify For {role === 'ARTIST' ? 'Artists' : 'Moderators'}</h2>

          <div className="flex bg-surface-highlight p-1 rounded-full mb-6">
              <button 
                  onClick={() => setRole('ARTIST')} 
                  className={`flex-1 py-2 rounded-full text-sm font-bold transition-all duration-300 ${role === 'ARTIST' ? 'bg-primary text-black shadow-lg' : 'text-secondary hover:text-white'}`}
              >
                  Artist
              </button>

              {(!hasModerator || authMode === 'LOGIN') && (
                  <button 
                      onClick={() => setRole('MODERATOR')}
                      className={`flex-1 py-2 rounded-full text-sm font-bold transition-all duration-300 ${role === 'MODERATOR' ? 'bg-primary text-black shadow-lg' : 'text-secondary hover:text-white'}`}
                  >
                      Moderator
                  </button>
              )}
          </div>

          {message && <div className="bg-red-500/20 text-red-500 p-3 rounded mb-4 text-center text-sm animate-pulse">{message}</div>}

          <form onSubmit={authMode === 'LOGIN' ? handleLogin : handleRegister} className="flex flex-col gap-4">

              {authMode === 'REGISTER' && role === 'ARTIST' && (
                  <div className="flex flex-col gap-2 animate-slide-up">
                      {!isCreatingNewArtist ? (
                          <div className="relative">
                              <select 
                                  value={artistNameSelection}
                                  onChange={(e) => setArtistNameSelection(e.target.value)}
                                  className="w-full bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none appearance-none transition-colors"
                              >
                                  <option value="">Select Artist...</option>
                                  {existingArtists.map(a => <option key={a} value={a}>{a}</option>)}
                              </select>
                              <ChevronDown className="absolute right-3 top-3 text-secondary pointer-events-none" size={20}/>
                          </div>
                      ) : (
                          <input 
                              type="text" 
                              placeholder="New Artist Alias" 
                              value={newArtistAlias} 
                              onChange={e => setNewArtistAlias(e.target.value)}
                              className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none transition-colors"
                          />
                      )}

                      <label className="flex items-center gap-2 cursor-pointer mt-1">
                          <input 
                              type="checkbox" 
                              checked={isCreatingNewArtist}
                              onChange={e => setIsCreatingNewArtist(e.target.checked)}
                          />
                          <span className="text-xs text-secondary">Create new artist</span>
                      </label>
                  </div>
              )}

              <input 
                  type="text" placeholder="Username" value={username} onChange={e => setUsername(e.target.value)}
                  className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none transition-colors"
              />
              <input 
                  type="password" placeholder="Password" value={password} onChange={e => setPassword(e.target.value)}
                  className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none transition-colors"
              />

              <button type="submit" className="bg-primary text-black font-bold py-3 rounded-full hover:scale-105 transition-transform mt-2 shadow-lg hover:shadow-primary/20">
                  {authMode === 'LOGIN' ? 'Log In' : 'Submit Application'}
              </button>
          </form>

          <p className="text-center text-secondary text-sm mt-4">
              {authMode === 'LOGIN' ? "Don't have an account?" : "Already have an account?"} 
              <button onClick={() => { setAuthMode(authMode === 'LOGIN' ? 'REGISTER' : 'LOGIN'); setMessage(""); }} className="text-white font-bold ml-1 hover:underline">
                  {authMode === 'LOGIN' ? 'Sign up' : 'Log in'}
              </button>
          </p>
      </div>
  );

  const renderModCredentials = () => (
      <div className="w-full h-full flex flex-col p-6 relative overflow-y-auto animate-fade-in pb-24">
          <div className="flex items-center gap-4 mb-8">
               <button onClick={() => setView('MOD_DASH')} className="text-secondary hover:text-white"><ArrowLeft size={24}/></button>
               <h1 className="text-3xl font-bold flex items-center gap-3"><Key className="text-primary"/> Artist Credentials</h1>
          </div>

          <div className="bg-surface rounded-xl border border-surface-highlight overflow-hidden">
              <table className="w-full text-left border-collapse">
                  <thead className="bg-surface-highlight text-secondary text-xs uppercase font-bold">
                      <tr>
                          <th className="p-4">Artist Name</th>
                          <th className="p-4">Username</th>
                          <th className="p-4">Password</th>
                          <th className="p-4">Status</th>
                          <th className="p-4 text-right">Delete</th>
                      </tr>
                  </thead>
                  <tbody>
                      {artistAccounts.map(a => (
                          <tr key={a.id} className="border-b border-surface-highlight hover:bg-white/5 transition">
                              <td className="p-4 font-bold">{a.artistName}</td>
                              <td className="p-4 text-sm font-mono">{a.username}</td>
                              <td className="p-4 text-sm font-mono text-red-400">{a.password}</td>
                              <td className="p-4"><span className="text-xs font-bold uppercase">{a.status}</span></td>
                              <td className="p-4 text-right">
                                  <button onClick={() => deleteArtistAccount(a.id)} className="text-secondary hover:text-red-500 transition">
                                      <Trash2 size={18}/>
                                  </button>
                              </td>
                          </tr>
                      ))}
                  </tbody>
              </table>
          </div>
      </div>
  );

  const renderModAllReleases = () => {
      // Combine releaseRequests (dynamic) AND albums (legacy/hardcoded)
      // Filter out any legacy albums that have a matching ID in releaseRequests to avoid dupes (handled in StoreContext, but for display safely)

      const legacyAlbumsAsReleases = albums.filter(a => !releaseRequests.find(r => r.id === a.id)).map(a => ({
          id: a.id, // Keep original ID (e.g., 'a1')
          title: a.title,
          artistName: a.artist,
          type: a.type || 'Album',
          releaseDate: a.releaseDate || new Date(a.year, 0, 1).toISOString(),
          status: 'LIVE' as const,
          covers: a.covers,
          label: a.recordLabel,
          tracks: a.trackIds.map(tid => {
              const t = tracks.find(tr => tr.id === tid);
              return {
                  title: t?.title || "",
                  explicit: t?.explicit || false,
                  duration: t?.duration || 0,
                  mainArtists: t?.mainArtists || [],
                  fileUrl: "",
                  artist: t?.artist // Include track artist
              };
          })
      }));

      const allDisplayReleases = [...releaseRequests, ...legacyAlbumsAsReleases].sort((a,b) => new Date(b.releaseDate).getTime() - new Date(a.releaseDate).getTime());

      return (
      <div className="w-full h-full flex flex-col p-6 relative overflow-y-auto animate-fade-in pb-24">
          <div className="flex items-center gap-4 mb-8">
               <button onClick={() => setView('MOD_DASH')} className="text-secondary hover:text-white"><ArrowLeft size={24}/></button>
               <h1 className="text-3xl font-bold flex items-center gap-3"><Database className="text-primary"/> All Releases Manager</h1>
          </div>

          <div className="bg-surface rounded-xl border border-surface-highlight overflow-hidden">
             <table className="w-full text-left border-collapse">
                    <thead className="bg-surface-highlight text-secondary text-xs uppercase font-bold sticky top-0">
                        <tr>
                            <th className="p-4">Release</th>
                            <th className="p-4">Artist</th>
                            <th className="p-4">Type</th>
                            <th className="p-4">Date</th>
                            <th className="p-4">Status</th>
                            <th className="p-4 text-right">Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        {allDisplayReleases.length === 0 && (
                            <tr><td colSpan={6} className="p-8 text-center text-secondary">No releases found.</td></tr>
                        )}
                        {allDisplayReleases.map((r: any, idx) => (
                            <tr key={idx} className="border-b border-surface-highlight hover:bg-white/5 transition cursor-pointer" onClick={() => setSelectedRelease(r)}>
                                <td className="p-4 flex items-center gap-3">
                                    <img src={r.covers[0]} className="w-10 h-10 rounded object-cover shadow-sm flex-shrink-0" />
                                    <span className="font-bold">{r.title}</span>
                                </td>
                                <td className="p-4 font-bold text-sm">{r.artistName}</td>
                                <td className="p-4 text-sm text-secondary">{r.type}</td>
                                <td className="p-4 text-sm text-secondary">{new Date(r.releaseDate).toLocaleDateString()}</td>
                                <td className="p-4">
                                    <span className={`px-2 py-1 rounded text-xs font-bold uppercase ${
                                        r.status === 'LIVE' ? 'bg-green-500/20 text-green-500' :
                                        r.status === 'APPROVED' ? 'bg-blue-500/20 text-blue-500' :
                                        r.status === 'REJECTED' ? 'bg-red-500/20 text-red-500' :
                                        'bg-yellow-500/20 text-yellow-500'
                                    }`}>
                                        {r.deletionRequested ? "DELETION PENDING" : r.status}
                                    </span>
                                </td>
                                <td className="p-4 text-right">
                                    <div className="flex justify-end gap-3" onClick={e => e.stopPropagation()}>
                                        <button onClick={() => handleEditRelease(r)} className="text-secondary hover:text-white transition">
                                            <Edit size={18}/>
                                        </button>
                                        <button onClick={() => deleteRelease(r.id)} className="text-secondary hover:text-red-500 transition">
                                            <Trash2 size={18}/>
                                        </button>
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
          </div>
      </div>
      );
  };

  const renderModDash = () => (
      <div className="w-full h-full flex flex-col p-6 relative overflow-y-auto animate-fade-in pb-24">
          <div className="flex justify-between items-center mb-8">
              <h1 className="text-3xl font-bold flex items-center gap-3"><Shield className="text-primary"/> Moderator Dashboard</h1>
          </div>

          {/* Quick Actions Grid for Mod */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
               <button onClick={() => { resetDistForm(); setView('DISTRIBUTION'); }} className="bg-primary text-black p-6 rounded-xl flex flex-col items-center justify-center gap-2 hover:scale-105 transition font-bold h-32 shadow-lg hover:shadow-primary/20 w-full">
                    <UploadCloud size={32}/>
                    Upload Release
                </button>
                <button onClick={() => setView('MOD_ALL_RELEASES')} className="bg-surface border border-surface-highlight p-6 rounded-xl flex flex-col items-center justify-center gap-2 hover:bg-surface-highlight transition font-bold h-32 hover:scale-105 w-full">
                    <Database size={32} className="text-secondary"/>
                    Manage All Releases
                </button>
                <button onClick={() => setView('MOD_CREDENTIALS')} className="bg-surface border border-surface-highlight p-6 rounded-xl flex flex-col items-center justify-center gap-2 hover:bg-surface-highlight transition font-bold h-32 hover:scale-105 w-full">
                    <Key size={32} className="text-secondary"/>
                    Artist Credentials
                </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {/* Artist Requests */}
              <div className="bg-surface rounded-xl p-4 flex flex-col border border-surface-highlight max-h-[500px]">
                  <h3 className="font-bold mb-4 flex items-center gap-2 text-primary"><User size={18}/> Pending Artists</h3>
                  <div className="overflow-y-auto flex-1 flex flex-col gap-3">
                      {artistAccounts.filter(a => a.status === 'PENDING').length === 0 && <span className="text-secondary text-sm">No pending requests</span>}
                      {artistAccounts.filter(a => a.status === 'PENDING').map(a => (
                          <div key={a.id} className="p-3 bg-surface-highlight rounded flex justify-between items-center animate-slide-in-bottom">
                              <div>
                                  <div className="font-bold">{a.artistName}</div>
                                  <div className="text-xs text-secondary">@{a.username}</div>
                              </div>
                              <div className="flex gap-2">
                                  <button onClick={() => approveArtist(a.id)} className="text-green-500 hover:scale-110"><CheckCircle size={20}/></button>
                                  <button onClick={() => rejectArtist(a.id)} className="text-red-500 hover:scale-110"><XCircle size={20}/></button>
                              </div>
                          </div>
                      ))}
                  </div>
              </div>

              {/* Release Requests */}
              <div className="bg-surface rounded-xl p-4 flex flex-col border border-surface-highlight max-h-[500px]">
                  <h3 className="font-bold mb-4 flex items-center gap-2 text-primary"><UploadCloud size={18}/> Pending Releases</h3>
                  <div className="overflow-y-auto flex-1 flex flex-col gap-3">
                      {releaseRequests.filter(r => (r.status === 'PENDING' || r.deletionRequested)).length === 0 && <span className="text-secondary text-sm">No pending releases</span>}
                      {releaseRequests.filter(r => (r.status === 'PENDING' || r.deletionRequested)).map(r => (
                          <div key={r.id} className="p-3 bg-surface-highlight rounded flex gap-3 cursor-pointer hover:bg-zinc-800 transition-colors animate-slide-in-bottom items-start" onClick={() => setSelectedRelease(r)}>
                              <img src={r.covers[0]} className="w-12 h-12 rounded object-cover flex-shrink-0" alt=""/>
                              <div className="flex-1 min-w-0 flex flex-col gap-1">
                                  <div className="flex items-center gap-2">
                                      <div className="font-bold truncate">{r.title}</div>
                                      {r.deletionRequested && <span className="text-[10px] bg-red-500 text-white px-1 rounded font-bold">DELETE REQ</span>}
                                  </div>
                                  <div className="text-xs text-secondary truncate">{r.artistName} • {r.type}</div>
                                  <div className="flex gap-2 justify-end mt-1" onClick={e => e.stopPropagation()}>
                                      {r.deletionRequested ? (
                                           <>
                                             <button onClick={() => approveRelease(r.id)} className="text-red-500 hover:text-white text-[10px] font-bold uppercase border border-red-500 px-2 py-0.5 rounded hover:bg-red-500 transition">Confirm Delete</button>
                                             {/* Reject Deletion Button */}
                                             <button onClick={() => rejectRelease(r.id)} className="text-blue-500 hover:text-white text-[10px] font-bold uppercase border border-blue-500 px-2 py-0.5 rounded hover:bg-blue-500 transition">Reject Del</button>
                                           </>
                                      ) : (
                                          <>
                                            <button onClick={() => approveRelease(r.id)} className="text-green-500 hover:text-white text-[10px] font-bold uppercase border border-green-500 px-2 py-0.5 rounded hover:bg-green-500 transition">Approve</button>
                                            <button onClick={() => rejectRelease(r.id)} className="text-red-500 hover:text-white text-[10px] font-bold uppercase border border-red-500 px-2 py-0.5 rounded hover:bg-red-500 transition">Reject</button>
                                          </>
                                      )}
                                  </div>
                              </div>
                          </div>
                      ))}
                  </div>
              </div>

              {/* Profile Edits */}
              <div className="bg-surface rounded-xl p-4 flex flex-col border border-surface-highlight max-h-[500px]">
