                                <td className="p-4 text-right">
                                    <div className="flex justify-end gap-3" onClick={e => e.stopPropagation()}>
                                        <button onClick={() => handleEditRelease(r)} className="text-secondary hover:text-white transition hover:scale-110">
                                            <Edit size={18}/>
                                        </button>

                                        {/* Only allow deletion for non-legacy tracks for simplicity in prototype, or requests */}
                                        {r.id.startsWith('rel_') && (
                                            <button onClick={() => deleteRelease(r.id)} className="text-secondary hover:text-red-500 transition hover:scale-110">
                                                <Trash2 size={18}/>
                                            </button>
                                        )}
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            {/* Mobile List */}
            <div className="md:hidden flex flex-col gap-3 pb-20">
                {myReleases.length === 0 && <div className="text-center text-secondary">No releases yet.</div>}
                {myReleases.map((r, idx) => (
                    <div key={idx} className="bg-surface p-4 rounded-lg flex items-center gap-4 cursor-pointer active:scale-95 transition items-start" onClick={() => setSelectedRelease(r)}>
                        <div className="w-16 h-16 shrink-0">
                            <img src={r.covers[0]} className="w-full h-full rounded object-cover shadow-sm" />
                        </div>
                        <div className="flex-1 min-w-0">
                            <div className="font-bold text-lg truncate">{r.title}</div>
                            <div className="text-sm text-secondary truncate">{r.type} • {new Date(r.releaseDate).toLocaleDateString()}</div>
                            <div className={`text-xs font-bold mt-1 uppercase ${
                                r.status === 'LIVE' ? 'text-green-500' :
                                r.status === 'APPROVED' ? 'text-blue-500' :
                                r.status === 'REJECTED' ? 'text-red-500' :
                                'text-yellow-500'
                            }`}>{r.deletionRequested ? "DELETION PENDING" : r.status}</div>
                        </div>
                        <div className="flex flex-col gap-2">
                            <button onClick={(e) => { e.stopPropagation(); handleEditRelease(r); }} className="text-secondary hover:text-white">
                                <Edit size={20}/>
                            </button>
                            {r.id.startsWith('rel_') && (
                                <button onClick={(e) => { e.stopPropagation(); deleteRelease(r.id); }} className="text-secondary hover:text-red-500">
                                    <Trash2 size={20}/>
                                </button>
                            )}
                        </div>
                    </div>
                ))}
            </div>

             {/* Log Out Button */}
            <div className="fixed bottom-6 left-6 md:absolute md:bottom-6 md:left-6 z-50">
                <button 
                    onClick={() => { logoutArtistHub(); setView('AUTH'); }} 
                    className="flex items-center gap-2 px-4 py-2 bg-surface-highlight rounded-full text-secondary hover:text-white hover:bg-red-500 hover:text-white transition font-bold shadow-lg"
                >
                    <LogOut size={18} />
                    Log Out
                </button>
            </div>
        </div>
    );
  };

export interface Track {
  id: string;
  title: string;
  artist: string;
  album: string;
  cover: string; // Keep for track display consistency, usually points to active album cover
  duration: number; // in seconds
  url: string; // audio source
  plays: number;
  genre: string; // New field for recommendations
  explicit?: boolean;
  feat?: string;
  hueq?: string; // ISRC equivalent
  mainArtists?: string[]; // Array of additional main artists
}

export interface DailyChartTrack extends Track {
  dailyPlays: number;
}

export interface Playlist {
  id: string;
  name: string;
  description?: string;
  customCover?: string; // Base64 or URL
  tracks: string[]; // array of track IDs
  isSystem?: boolean; // e.g. "Liked Songs"
  ownerId?: string; // ID of the user who created this playlist

  // New fields for Public/Private feature
  isPublic?: boolean;
  creatorName?: string;
  creatorAvatar?: string;
  savedBy?: string[]; // Array of User IDs who added this playlist to their library
}

export interface Album {
  id: string;
  title: string;
  artist: string;
  covers: string[]; // Changed from single cover to array
  trackIds: string[];
  year: number;
  releaseDate?: string; // ISO string for full date display
  recordLabel?: string;
  type?: ReleaseType;
  mainArtists?: string[]; // Added at album level for better display
}

export interface User {
  id: string;
  username: string;
  password: string; // Stored locally for this prototype
  displayName: string;
  avatar?: string; // Base64
}

export interface AppSettings {
  accentColor: string;
  language: 'English' | 'Russian';
  allowExplicitContent: boolean; // Replaced High Quality Audio
  autoPlay: boolean;
  crossfade: number; // seconds
  albumCoverIndexes: Record<string, number>; // Stores user preference for album covers
}

export type ViewState = 
  | { type: 'HOME' }
  | { type: 'SEARCH' }
  | { type: 'LIBRARY' }
  | { type: 'PLAYLIST'; id: string }
  | { type: 'ALBUM'; id: string }
  | { type: 'ARTIST'; id: string }
  | { type: 'CHARTS' }
  | { type: 'GENRE'; id: string };

