                          <label className="text-xs font-bold text-secondary uppercase">Message to Moderators</label>
                          <textarea value={distMsg} onChange={e => setDistMsg(e.target.value)} className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none h-24 resize-none" placeholder="Optional notes..."></textarea>
                      </div>
                  </div>
              </div>
          )}

          <div className="flex justify-between mt-8 pt-8 border-t border-surface-highlight">
              {distStep > 1 ? (
                  <button onClick={() => setDistStep(distStep - 1)} className="px-6 py-2 rounded-full font-bold text-white hover:bg-white/10 transition">Back</button>
              ) : <div></div>}

              {distStep < 3 ? (
                  <button onClick={handleNextStep} className="px-8 py-2 rounded-full font-bold bg-white text-black hover:scale-105 transition">Next</button>
              ) : (
                  <button onClick={handleSubmitRelease} className="px-8 py-2 rounded-full font-bold bg-primary text-black hover:scale-105 transition shadow-lg shadow-primary/20">
                      {isEditing ? 'Update Release' : 'Submit Release'}
                  </button>
              )}
          </div>
      </div>
  );

  const renderArtistDash = () => {
    if (!currentArtist) return null;

    // Filter pending releases (exclude those that are LIVE to avoid duplication with liveAlbums)
    const pendingReleases = releaseRequests.filter(r => r.artistId === currentArtist.id && r.status !== 'LIVE');

    // Convert static albums to "Live" release format for display
    const liveAlbums = albums
        .filter(a => a.artist === currentArtist.artistName)
        .map(a => ({
            id: a.id,
            artistId: currentArtist.id,
            artistName: a.artist,
            status: 'LIVE' as const,
            title: a.title,
            type: (a.type || 'Album') as ReleaseType,
            genre: 'Pop', // Default for legacy
            label: a.recordLabel || "",
            covers: a.covers,
            additionalMainArtists: a.mainArtists,
            tracks: a.trackIds.map(tid => {
                const t = tracks.find(tr => tr.id === tid);
                return {
                    title: t?.title || "",
                    explicit: t?.explicit || false,
                    duration: t?.duration || 0,
                    mainArtists: t?.mainArtists || [],
                    feat: t?.feat,
                    existingHueq: t?.hueq,
                    fileUrl: ""
                };
            }),
            releaseDate: a.releaseDate || new Date(a.year, 0, 1).toISOString(),
            submissionTime: new Date().toISOString(),
            deletionRequested: false
        }));

    const myReleases = [...pendingReleases, ...liveAlbums];
    const stats = getArtistStats(currentArtist.artistName);

    return (
        <div className="w-full h-full flex flex-col p-6 relative overflow-y-auto animate-fade-in pb-8">
            <div className="flex justify-between items-center mb-8 shrink-0">
                <div className="flex items-center gap-4">
                    <div className="w-16 h-16 rounded-full overflow-hidden bg-zinc-800 shadow-lg">
                        {currentArtist.avatar ? <img src={currentArtist.avatar} className="w-full h-full object-cover" /> : <User size={32} className="text-secondary m-auto h-full" />}
                    </div>
                    <div>
                        <h1 className="text-3xl font-bold flex items-center gap-2">{currentArtist.artistName} <CheckCircle size={20} className="text-blue-500" fill="white" /></h1>
                        <p className="text-secondary text-sm">Artist Dashboard</p>
                    </div>
                </div>
            </div>

            {/* Stats */}
            <div className="grid grid-cols-2 gap-4 mb-8 shrink-0">
                <div className="bg-surface border border-surface-highlight p-4 rounded-xl flex items-center gap-4">
                    <div className="w-12 h-12 bg-primary/20 rounded-full flex items-center justify-center">
                        <BarChart2 size={24} className="text-primary"/>
                    </div>
                    <div>
                        <div className="text-2xl font-bold">{stats.monthlyPlays.toLocaleString()}</div>
                        <div className="text-xs text-secondary uppercase font-bold">Monthly Plays</div>
                    </div>
                </div>
                <div className="bg-surface border border-surface-highlight p-4 rounded-xl flex items-center gap-4">
                    <div className="w-12 h-12 bg-primary/20 rounded-full flex items-center justify-center">
                        <Globe size={24} className="text-primary"/>
                    </div>
                    <div>
                        <div className="text-2xl font-bold">#{stats.globalRank}</div>
                        <div className="text-xs text-secondary uppercase font-bold">Global Rank</div>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8 w-full shrink-0">
                <button onClick={() => { resetDistForm(); setView('DISTRIBUTION'); }} className="bg-primary text-black p-6 rounded-xl flex flex-col items-center justify-center gap-2 hover:scale-105 transition font-bold h-32 shadow-lg hover:shadow-primary/20 w-full">
                    <UploadCloud size={32}/>
                    Upload New Release
                </button>
                <button onClick={() => setView('PROFILE_EDIT')} className="bg-surface border border-surface-highlight p-6 rounded-xl flex flex-col items-center justify-center gap-2 hover:bg-surface-highlight transition font-bold h-32 hover:scale-105 w-full">
                    <Edit size={32} className="text-secondary"/>
                    Edit Profile
                </button>
                <button onClick={() => setView('ARTIST_PICK')} className="bg-surface border border-surface-highlight p-6 rounded-xl flex flex-col items-center justify-center gap-2 hover:bg-surface-highlight transition font-bold h-32 hover:scale-105 w-full">
                    <ListMusic size={32} className="text-secondary"/>
                    Select Artist Pick
                </button>
            </div>

            <h2 className="text-2xl font-bold mb-4 shrink-0">My Releases</h2>

            {/* Desktop Table */}
            <div className="hidden md:block flex-1 overflow-y-auto bg-surface rounded-xl border border-surface-highlight max-h-[400px]">
                <table className="w-full text-left border-collapse">
                    <thead className="bg-surface-highlight text-secondary text-xs uppercase font-bold sticky top-0 z-10">
                        <tr>
                            <th className="p-4 bg-surface-highlight">Release</th>
                            <th className="p-4 bg-surface-highlight">Type</th>
                            <th className="p-4 bg-surface-highlight">Date</th>
                            <th className="p-4 bg-surface-highlight">Status</th>
                            <th className="p-4 bg-surface-highlight text-right">Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        {myReleases.length === 0 && (
                            <tr>
                                <td colSpan={5} className="p-8 text-center text-secondary">You haven't uploaded any releases yet.</td>
                            </tr>
                        )}
                        {myReleases.map((r, idx) => (
                            <tr key={idx} className="border-b border-surface-highlight hover:bg-white/5 transition cursor-pointer" onClick={() => setSelectedRelease(r)}>
                                <td className="p-4 flex items-center gap-3">
                                    <img src={r.covers[0]} className="w-10 h-10 rounded object-cover shadow-sm flex-shrink-0" />
                                    <span className="font-bold">{r.title}</span>
                                </td>
                                <td className="p-4 text-sm text-secondary">{r.type}</td>
                                <td className="p-4 text-sm text-secondary">{new Date(r.releaseDate).toLocaleDateString()}</td>
                                <td className="p-4">
                                    <span className={`px-2 py-1 rounded text-xs font-bold uppercase ${
                                        r.status === 'LIVE' ? 'bg-green-500/20 text-green-500' :
                                        r.status === 'APPROVED' ? 'bg-blue-500/20 text-blue-500' :
                                        r.status === 'REJECTED' ? 'bg-red-500/20 text-red-500' :
                                        'bg-yellow-500/20 text-yellow-500'
                                    }`}>
                                        {r.deletionRequested ? "DELETION PENDING" : r.status}
                                    </span>
                                </td>
                                <td className="p-4 text-right">
                                    <div className="flex justify-end gap-3" onClick={e => e.stopPropagation()}>
                                        <button onClick={() => handleEditRelease(r)} className="text-secondary hover:text-white transition hover:scale-110">
                                            <Edit size={18}/>
                                        </button>

                                        {/* Only allow deletion for non-legacy tracks for simplicity in prototype, or requests */}
                                        {r.id.startsWith('rel_') && (
                                            <button onClick={() => deleteRelease(r.id)} className="text-secondary hover:text-red-500 transition hover:scale-110">
                                                <Trash2 size={18}/>
                                            </button>
                                        )}
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            {/* Mobile List */}
            <div className="md:hidden flex flex-col gap-3 pb-20">
                {myReleases.length === 0 && <div className="text-center text-secondary">No releases yet.</div>}
                {myReleases.map((r, idx) => (
                    <div key={idx} className="bg-surface p-4 rounded-lg flex items-center gap-4 cursor-pointer active:scale-95 transition items-start" onClick={() => setSelectedRelease(r)}>
                        <div className="w-16 h-16 shrink-0">
                            <img src={r.covers[0]} className="w-full h-full rounded object-cover shadow-sm" />
                        </div>
                        <div className="flex-1 min-w-0">
                            <div className="font-bold text-lg truncate">{r.title}</div>
                            <div className="text-sm text-secondary truncate">{r.type} • {new Date(r.releaseDate).toLocaleDateString()}</div>
                            <div className={`text-xs font-bold mt-1 uppercase ${
                                r.status === 'LIVE' ? 'text-green-500' :
                                r.status === 'APPROVED' ? 'text-blue-500' :
                                r.status === 'REJECTED' ? 'text-red-500' :
                                'text-yellow-500'
                            }`}>{r.deletionRequested ? "DELETION PENDING" : r.status}</div>
                        </div>
                        <div className="flex flex-col gap-2">
                            <button onClick={(e) => { e.stopPropagation(); handleEditRelease(r); }} className="text-secondary hover:text-white">
                                <Edit size={20}/>
                            </button>
                            {r.id.startsWith('rel_') && (
                                <button onClick={(e) => { e.stopPropagation(); deleteRelease(r.id); }} className="text-secondary hover:text-red-500">
                                    <Trash2 size={20}/>
                                </button>
                            )}
                        </div>
                    </div>
                ))}
            </div>

             {/* Log Out Button */}
            <div className="mt-auto pt-8">
                <button 
                    onClick={() => { logoutArtistHub(); setView('AUTH'); }} 
                    className="flex items-center gap-2 px-4 py-2 bg-surface-highlight rounded-full text-secondary hover:text-white hover:bg-red-500 hover:text-white transition font-bold shadow-lg"
                >
                    <LogOut size={18} />
                    Log Out
                </button>
            </div>
        </div>
    );
  };

  const renderProfileEditForm = () => (
      <div className="w-full max-w-md bg-surface p-8 rounded-xl shadow-2xl border border-surface-highlight animate-zoom-in relative">
          <button onClick={() => setView('ARTIST_DASH')} className="absolute top-4 left-4 text-secondary hover:text-white"><ArrowLeft size={24}/></button>
          <h2 className="text-2xl font-bold text-center mb-6">Edit Artist Profile</h2>

          <div className="flex flex-col gap-6">
              <div className="flex justify-center">
                  <div 
                      onClick={() => avatarInputRef.current?.click()}
                      className="w-32 h-32 rounded-full bg-surface-highlight flex items-center justify-center cursor-pointer hover:opacity-80 transition relative overflow-hidden group border-2 border-transparent hover:border-primary"
                  >
                      {editAvatar ? (
                          <img src={editAvatar} alt="Avatar" className="w-full h-full object-cover" />
                      ) : (
                          <Camera size={40} className="text-secondary" />
                      )}
                      <div className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition">
                          <span className="text-xs font-bold text-white uppercase">Change</span>
                      </div>
                  </div>
                  <input type="file" ref={avatarInputRef} className="hidden" accept="image/*" onChange={handleAvatarUpload} />
              </div>

              <div className="flex flex-col gap-2">
                  <label className="text-xs font-bold text-secondary uppercase">Artist Bio</label>
                  <textarea 
                      value={editBio} 
                      onChange={e => setEditBio(e.target.value)}
                      className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none resize-none h-32 text-white"
                      placeholder="Tell fans about yourself..."
                  />
              </div>

              <button 
                  onClick={handleProfileUpdate}
                  className="bg-primary text-black font-bold py-3 rounded-full hover:scale-105 transition shadow-lg shadow-primary/20"
              >
                  Submit Changes
              </button>
          </div>
      </div>
  );

  const renderArtistPickSelector = () => {
      // Combined search for Tracks and Albums
      const searchResults = [
          ...tracks.filter(t => t.title.toLowerCase().includes(pickSearch.toLowerCase()) || t.artist.toLowerCase().includes(pickSearch.toLowerCase())).map(t => ({ type: 'TRACK', data: t })),
          ...albums.filter(a => a.title.toLowerCase().includes(pickSearch.toLowerCase()) || a.artist.toLowerCase().includes(pickSearch.toLowerCase())).map(a => ({ type: 'ALBUM', data: a }))
      ].slice(0, 20);

      const handleSelectPick = (item: any) => {
          const type = item.type;
          const data = item.data;

          let pickData;
          if (type === 'TRACK') {
              pickData = {
                  type: 'TRACK',
                  id: data.id,
                  image: getTrackCover(data),
                  subtitle: data.title
              };
          } else {
              pickData = {
                  type: 'ALBUM',
                  id: data.id,
                  image: data.covers[0],
                  subtitle: data.title
              };
          }

          submitProfileEdit({ newArtistPick: pickData as any });
          showNotification("Artist Pick updated (Pending Approval)", "success");
          setView('ARTIST_DASH');
      };

      return (
          <div className="w-full max-w-2xl bg-surface p-6 rounded-xl shadow-2xl border border-surface-highlight animate-zoom-in relative flex flex-col h-[80vh]">
              <div className="flex items-center gap-4 mb-6">
                  <button onClick={() => setView('ARTIST_DASH')} className="text-secondary hover:text-white"><ArrowLeft size={24}/></button>
                  <h2 className="text-2xl font-bold">Select Artist Pick</h2>
              </div>

              <div className="relative mb-6">
                  <Search className="absolute left-3 top-3 text-secondary" size={20} />
                  <input 
                      type="text" 
                      placeholder="Search for a track or album..." 
                      value={pickSearch}
                      onChange={e => setPickSearch(e.target.value)}
                      className="w-full bg-background pl-10 pr-4 py-3 rounded-full border border-surface-highlight focus:border-primary focus:outline-none text-white"
                      autoFocus
                  />
              </div>

              <div className="flex-1 overflow-y-auto flex flex-col gap-2">
                  {searchResults.map((item: any, idx) => {
                      const img = item.type === 'TRACK' ? getTrackCover(item.data) : item.data.covers[0];
                      const title = item.data.title;
                      const sub = item.type === 'TRACK' ? item.data.artist : item.data.artist + ' • Album';

                      return (
                          <div key={idx} onClick={() => handleSelectPick(item)} className="flex items-center gap-3 p-2 hover:bg-surface-highlight rounded cursor-pointer group">
                              <img src={img} className="w-12 h-12 rounded object-cover" />
                              <div className="flex-1">
                                  <div className="font-bold text-white">{title}</div>
                                  <div className="text-xs text-secondary">{sub}</div>
                              </div>
                              <button className="px-3 py-1 bg-white text-black text-xs font-bold rounded-full opacity-0 group-hover:opacity-100 transition">SELECT</button>
                          </div>
                      );
                  })}
              </div>
          </div>
      );
  };

  const renderReleaseDetailModal = () => {
      if (!selectedRelease) return null;

      return (
          <div className="fixed inset-0 bg-black/80 z-[250] flex items-center justify-center p-4">
              <div className="bg-surface w-full max-w-2xl rounded-xl p-6 relative shadow-2xl border border-surface-highlight animate-zoom-in max-h-[90vh] overflow-y-auto">
                  <button onClick={() => setSelectedRelease(null)} className="absolute top-4 right-4 text-secondary hover:text-white"><X size={24}/></button>

                  <div className="flex gap-6 mb-6">
                      <img src={selectedRelease.covers[0]} className="w-32 h-32 rounded-lg shadow-lg object-cover" />
                      <div>
                          <h2 className="text-2xl font-bold mb-1">{selectedRelease.title}</h2>
                          <p className="text-secondary">{selectedRelease.artistName}</p>
                          <div className="flex gap-2 mt-2 text-xs font-bold uppercase">
                              <span className="bg-surface-highlight px-2 py-1 rounded border border-white/10">{selectedRelease.type}</span>
                              <span className="bg-surface-highlight px-2 py-1 rounded border border-white/10">{selectedRelease.genre}</span>
                              <span className={`px-2 py-1 rounded border border-white/10 ${
                                  selectedRelease.status === 'LIVE' ? 'bg-green-500/20 text-green-500' :
                                  selectedRelease.status === 'APPROVED' ? 'bg-blue-500/20 text-blue-500' :
                                  selectedRelease.status === 'REJECTED' ? 'bg-red-500/20 text-red-500' :
                                  'bg-yellow-500/20 text-yellow-500'
                              }`}>
                                  {selectedRelease.deletionRequested ? "DELETION PENDING" : selectedRelease.status}
                              </span>
                          </div>
                          <p className="text-xs text-secondary mt-2">Release Date: {new Date(selectedRelease.releaseDate).toLocaleString()}</p>
                      </div>
                  </div>

                  <h3 className="font-bold mb-3 border-b border-surface-highlight pb-2">Tracklist & HUEQ Codes</h3>
                  <div className="flex flex-col gap-2">
                      {selectedRelease.tracks.map((t, i) => (
                          <div key={i} className="flex justify-between items-center p-2 hover:bg-surface-highlight rounded">
                              <div className="flex items-center gap-3">
                                  <span className="text-secondary text-sm w-4">{i+1}</span>
                                  <div>
                                      <div className="font-bold text-sm">{t.title}</div>
                                      <div className="text-xs text-secondary">{formatDuration(t.duration)} • {t.explicit ? 'Explicit' : 'Clean'}</div>
                                  </div>
                              </div>
                              <div className="text-right">
                                  <div className="text-xs font-mono bg-black/40 px-2 py-1 rounded text-primary">
                                      {t.generatedHueq || t.existingHueq || "PENDING"}
                                  </div>
                                  <div className="text-[10px] text-secondary mt-0.5">HUEQ</div>
                              </div>
                          </div>
                      ))}
                  </div>

                  {selectedRelease.releaseMessage && (
                      <div className="mt-6 bg-surface-highlight p-4 rounded border border-white/5">
                          <h4 className="text-xs font-bold uppercase text-secondary mb-1">Message from Artist</h4>
                          <p className="text-sm italic">{selectedRelease.releaseMessage}</p>
                      </div>
                  )}
              </div>
          </div>
      );
  };

  return (
    <div className="fixed inset-0 bg-black z-[200] animate-fade-in flex flex-col">
        <button 
            onClick={() => setArtistHubOpen(false)} 
            className="absolute top-4 right-4 text-secondary hover:text-white z-[60]"
        >
            <X size={24} />
        </button>

        {view === 'AUTH' && (
            <div className="flex items-center justify-center flex-1">
                {renderAuth()}
            </div>
        )}
        {view === 'ARTIST_DASH' && renderArtistDash()}
        {view === 'MOD_DASH' && renderModDash()}
        {view === 'DISTRIBUTION' && (
            <div className="flex items-center justify-center flex-1 overflow-hidden p-4">
                {renderDistribution()}
            </div>
        )}
        {view === 'PROFILE_EDIT' && (
            <div className="flex items-center justify-center flex-1 overflow-hidden p-4">
                {renderProfileEditForm()}
            </div>
        )}
        {view === 'ARTIST_PICK' && (
            <div className="flex items-center justify-center flex-1 overflow-hidden p-4">
                {renderArtistPickSelector()}
            </div>
        )}
        {view === 'MOD_CREDENTIALS' && renderModCredentials()}
        {view === 'MOD_ALL_RELEASES' && renderModAllReleases()}

        {/* Overlays */}
        {selectedRelease && renderReleaseDetailModal()}
    </div>
  );
};

import React, { createContext, useContext, useEffect, useRef, useState } from 'react';
import { Track, Playlist, Album, ViewState, PlayMode, User, AppSettings, DailyChartTrack, ArtistAccount, ReleaseRequest, ProfileEditRequest, ModeratorAccount, AppNotification } from '../types.ts';
import { generateInitialData, StorageService } from '../services/data.ts';

interface ArtistStats {
  monthlyPlays: number;
  globalRank: number;
}

interface StoreContextType {
  // Auth
  currentUser: User | null;
  login: (username: string, pass: string) => boolean;
  register: (user: Omit<User, 'id'>) => boolean;
  logout: () => void;
  updateUserProfile: (data: Partial<User>) => { success: boolean; message?: string };

  // Settings
  appSettings: AppSettings;
  updateSettings: (settings: Partial<AppSettings>) => void;

  tracks: Track[];
  albums: Album[];
  playlists: Playlist[]; 
  likedPlaylistId: string; // Helper for dynamic ID
  recommendations: Track[];
  recentlyPlayed: Track[];
  followedArtists: string[];
  currentTrack: Track | null;
  isPlaying: boolean;
  playMode: PlayMode;
  isShuffle: boolean;
  volume: number;
  progress: number;
  duration: number;
  view: ViewState;

  // Notification
  notifications: AppNotification[];
  showNotification: (message: string, type?: 'error' | 'success' | 'info') => void;
  dismissNotification: (id: string) => void;

  // Daily Chart
  dailyChart: DailyChartTrack[];

  // Cover Management
  getAlbumCover: (albumId: string) => string;
  getTrackCover: (track: Track) => string;
  changeAlbumCover: (albumId: string, index: number) => void;

  // Artist Hub / Moderation
  isArtistHubOpen: boolean;
  setArtistHubOpen: (isOpen: boolean) => void;
  currentArtist: ArtistAccount | null;
  currentModerator: ModeratorAccount | null;

  artistAccounts: ArtistAccount[];
  releaseRequests: ReleaseRequest[];
  profileEditRequests: ProfileEditRequest[];

  hasModerator: boolean;
  existingArtists: string[];

  // Artist Actions
  registerArtist: (data: Omit<ArtistAccount, 'id' | 'status'>) => { success: boolean, message?: string };
  registerModerator: (data: ModeratorAccount) => { success: boolean, message?: string };
  loginArtistOrMod: (username: string, pass: string, type: 'ARTIST' | 'MODERATOR') => { success: boolean, message?: string };
  logoutArtistHub: () => void;
  submitRelease: (
      release: Omit<ReleaseRequest, 'id' | 'status' | 'artistId' | 'artistName' | 'submissionTime'>,
      overrideArtist?: { artistId: string, artistName: string }
  ) => void;
  updateReleaseRequest: (id: string, data: Partial<ReleaseRequest>) => void;
  submitProfileEdit: (edit: Omit<ProfileEditRequest, 'id' | 'status' | 'artistId' | 'artistName'>) => void;
  deleteRelease: (releaseId: string) => void;
  deleteArtistAccount: (artistId: string) => void;
  changeArtistPassword: (newPass: string) => void;
  changeModeratorPassword: (newPass: string) => void;

  // Mod Actions
  approveArtist: (id: string) => void;
  rejectArtist: (id: string) => void;
  approveRelease: (id: string) => void;
  rejectRelease: (id: string) => void;
  approveProfileEdit: (id: string) => void;
  rejectProfileEdit: (id: string) => void;

  // HUEQ Helper
  getTrackByHueq: (hueq: string) => Track | undefined;

  // Modal States
  isCreatePlaylistOpen: boolean;
  setCreatePlaylistOpen: (isOpen: boolean) => void;
  playlistIdToEdit: string | null; 
  setPlaylistIdToEdit: (id: string | null) => void;

  isMobilePlayerOpen: boolean;
  setMobilePlayerOpen: (isOpen: boolean) => void;

  isAddToPlaylistOpen: boolean;
  trackIdToAdd: string | null;
  openAddToPlaylist: (trackId: string) => void;
  closeAddToPlaylist: () => void;

  isDeleteModalOpen: boolean;
  playlistToDelete: string | null;
  openDeleteModal: (id: string) => void;
  closeDeleteModal: () => void;
  confirmDeletePlaylist: () => void;

  isProfileModalOpen: boolean;
  setProfileModalOpen: (isOpen: boolean) => void;

  // Actions
  setView: (v: ViewState) => void;
  goToArtist: (artistName: string) => void;
  getArtistStats: (artistName: string) => ArtistStats;
  toggleFollowArtist: (artistName: string) => void;
  isArtistFollowed: (artistName: string) => boolean;
  goBack: () => void;
  playTrack: (track: Track) => void;
  togglePlay: () => void;
  nextTrack: () => void;
  prevTrack: () => void;
  seek: (time: number) => void;
  setVolume: (vol: number) => void;
  toggleRepeat: () => void;
  toggleShuffle: () => void;

  createPlaylist: (name: string, description?: string, cover?: string, isPublic?: boolean) => void;
  editPlaylist: (id: string, name: string, description?: string, cover?: string, isPublic?: boolean) => void;
  deletePlaylist: (id: string) => void; 
  addToPlaylist: (playlistId: string, trackId: string) => void;
  removeFromPlaylist: (playlistId: string, trackId: string) => void;
  togglePlaylistSave: (playlistId: string) => void; 

  toggleLike: (trackId: string) => void;
  isLiked: (trackId: string) => boolean;
  toggleAlbumLike: (albumId: string) => void;
  isAlbumLiked: (albumId: string) => boolean;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

export const useStore = () => {
  const context = useContext(StoreContext);
  if (context === undefined) {
    throw new Error('useStore must be used within a StoreProvider');
  }
  return context;
};

// Helper to generate HUEQ: 000XX0
const generateHUEQ = (): string => {
    const randomDigit = () => Math.floor(Math.random() * 10);
    const randomChar = () => String.fromCharCode(65 + Math.floor(Math.random() * 26)); // A-Z
    return `${randomDigit()}${randomDigit()}${randomDigit()}${randomChar()}${randomChar()}${randomDigit()}`;
};

export const StoreProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  // --- Auth State ---
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);

  // --- Settings State ---
  const [appSettings, setAppSettingsState] = useState<AppSettings>({
    accentColor: '#1ed760',
    language: 'English',
    allowExplicitContent: true, // Default to true
    autoPlay: true,
    crossfade: 0,
    albumCoverIndexes: {}
  });

  // --- Data State ---
  const [tracks, setTracks] = useState<Track[]>([]);
  const [albums, setAlbums] = useState<Album[]>([]);
  const [playlists, setPlaylists] = useState<Playlist[]>([]);
  const [recommendations, setRecommendations] = useState<Track[]>([]);
  const [recentlyPlayed, setRecentlyPlayed] = useState<Track[]>([]);
  const [likedAlbumIds, setLikedAlbumIds] = useState<string[]>([]);
  const [followedArtists, setFollowedArtists] = useState<string[]>([]);

  const [dailyChart, setDailyChart] = useState<DailyChartTrack[]>([]);
  const [notifications, setNotifications] = useState<AppNotification[]>([]);

  // --- Artist Hub State ---
  const [isArtistHubOpen, setArtistHubOpen] = useState(false);
  const [currentArtist, setCurrentArtist] = useState<ArtistAccount | null>(null);
  const [currentModerator, setCurrentModerator] = useState<ModeratorAccount | null>(null);
  const [artistAccounts, setArtistAccounts] = useState<ArtistAccount[]>([]);
  const [releaseRequests, setReleaseRequests] = useState<ReleaseRequest[]>([]);
  const [profileEditRequests, setProfileEditRequests] = useState<ProfileEditRequest[]>([]);
  const [hasModerator, setHasModerator] = useState(false);
  const [existingArtists, setExistingArtists] = useState<string[]>([]);
  // Legacy deletions
  const [deletedLegacyIds, setDeletedLegacyIds] = useState<string[]>([]);

  // --- Player State ---
  const [currentTrack, setCurrentTrack] = useState<Track | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [playMode, setPlayMode] = useState<PlayMode>(PlayMode.OFF);
  const [isShuffle, setIsShuffle] = useState(false);
  const [volume, setVolumeState] = useState(0.5);
  const [progress, setProgress] = useState(0);
  const [duration, setDuration] = useState(0);
  const [hasCountedListen, setHasCountedListen] = useState(false);

  // --- UI State ---
  const [view, setViewInternal] = useState<ViewState>({ type: 'HOME' });
  const [history, setHistory] = useState<ViewState[]>([]);

  // Modals
  const [isCreatePlaylistOpen, setCreatePlaylistOpen] = useState(false);
  const [playlistIdToEdit, setPlaylistIdToEdit] = useState<string | null>(null);
  const [isMobilePlayerOpen, setMobilePlayerOpen] = useState(false);
  const [isAddToPlaylistOpen, setAddToPlaylistOpen] = useState(false);
  const [trackIdToAdd, setTrackIdToAdd] = useState<string | null>(null);
  const [isProfileModalOpen, setProfileModalOpen] = useState(false);

  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [playlistToDelete, setPlaylistToDelete] = useState<string | null>(null);

  // --- Refs ---
  const audioRef = useRef<HTMLAudioElement>(new Audio());
  const cumulativeTimeRef = useRef(0);
  const lastTimeRef = useRef(0);
  // Real-time Sync Channel
  const broadcastChannelRef = useRef<BroadcastChannel | null>(null);

  // Helper ID
  const likedPlaylistId = currentUser ? `liked_${currentUser.id}` : 'liked';

  const showNotification = (message: string, type: 'error' | 'success' | 'info' = 'info') => {
      const id = Date.now().toString();
      setNotifications(prev => [...prev, { id, message, type }]);
      setTimeout(() => dismissNotification(id), 5000);
  };

  const dismissNotification = (id: string) => {
      setNotifications(prev => prev.filter(n => n.id !== id));
  };

  // --- Broadcast Channel for Cross-Tab Syncing ---
  useEffect(() => {
      try {
          if (typeof BroadcastChannel !== 'undefined') {
              broadcastChannelRef.current = new BroadcastChannel('huevify_sync');

              broadcastChannelRef.current.onmessage = (event) => {
                  try {
                      const { type } = event.data;
                      // When another tab updates data, reload from local storage
                      if (type === 'PLAYLISTS_UPDATE') {
                          setPlaylists(StorageService.load<Playlist[]>('huevify_playlists', []));
                      }
                      if (type === 'TRACKS_UPDATE') {
                          const requests = StorageService.load<ReleaseRequest[]>('huevify_release_requests', []);
                          const storedPlays = StorageService.load<Record<string, number>>('huevify_plays', {});
                          refreshLibrary(requests, storedPlays);
                      }
                      if (type === 'ARTIST_DATA_UPDATE') {
                          setArtistAccounts(StorageService.load<ArtistAccount[]>('huevify_artist_accounts', []));
                          setReleaseRequests(StorageService.load<ReleaseRequest[]>('huevify_release_requests', []));
                          setProfileEditRequests(StorageService.load<ProfileEditRequest[]>('huevify_profile_requests', []));
                          setDeletedLegacyIds(StorageService.load<string[]>('huevify_deleted_legacy', []));

                          const requests = StorageService.load<ReleaseRequest[]>('huevify_release_requests', []);
                          const storedPlays = StorageService.load<Record<string, number>>('huevify_plays', {});
                          refreshLibrary(requests, storedPlays);
                      }
                      if (type === 'SETTINGS_UPDATE' && currentUser) {
                          const userSettings = StorageService.load<AppSettings | null>(`huevify_settings_${currentUser.id}`, null);
                          if (userSettings) setAppSettingsState(prev => ({ ...prev, ...userSettings }));
                      }
                  } catch (err) {
                      console.error("Sync error:", err);
                  }
              };
          }
      } catch (e) {
          console.warn("BroadcastChannel not supported in this browser.", e);
      }

      return () => {
          broadcastChannelRef.current?.close();
      };
  }, [currentUser]);

  const notifySync = (type: 'PLAYLISTS_UPDATE' | 'TRACKS_UPDATE' | 'ARTIST_DATA_UPDATE' | 'SETTINGS_UPDATE') => {
      try {
          broadcastChannelRef.current?.postMessage({ type });
      } catch (e) {
          console.error("Failed to notify sync", e);
      }
  };

  // --- Automated Play Count System ---
  useEffect(() => {
    const interval = setInterval(() => {
        const now = new Date();
        if (now.getMinutes() === 30) {
             const currentHour = now.getHours();
             const lastUpdateHour = StorageService.load('huevify_last_play_update_hour', -1);

             if (lastUpdateHour !== currentHour) {
                 setTracks(prevTracks => {
                     const updated = prevTracks.map(t => {
                         let add = 0;
                         if (t.plays <= 10000) {
                             add = Math.floor(Math.random() * 1000) + 1;
                         } else if (t.plays <= 50000) {
                             add = Math.floor(Math.random() * 9900) + 100;
                         } else {
                             add = Math.floor(Math.random() * 24000) + 1000;
                         }
                         return { ...t, plays: t.plays + add };
                     });
                     const playCounts = updated.reduce((acc, t) => ({ ...acc, [t.id]: t.plays }), {});
                     StorageService.save('huevify_plays', playCounts);
                     notifySync('TRACKS_UPDATE');
                     return updated;
                 });
                 StorageService.save('huevify_last_play_update_hour', currentHour);
             }
        }
    }, 10000); 
    return () => clearInterval(interval);
  }, []); 

  // --- Logic to Refresh Library (Merge Static + Dynamic Data) ---
  const refreshLibrary = (requests: ReleaseRequest[], storedPlays?: Record<string, number>) => {
      try {
          const { tracks: initialTracks, albums: initialAlbums } = generateInitialData();
          const plays = storedPlays || StorageService.load<Record<string, number>>('huevify_plays', {});
          const deletedLegacy = StorageService.load<string[]>('huevify_deleted_legacy', []);

          // Filter out deleted legacy albums
          let mergedTracks = initialTracks.filter(t => !deletedLegacy.includes(t.album) && !deletedLegacy.some(id => t.id.startsWith(id))); 
          let mergedAlbums = initialAlbums.filter(a => !deletedLegacy.includes(a.id));

          const artistSet = new Set(mergedAlbums.map(a => a.artist));

          requests.forEach(req => {
              // Safety check for malformed requests
              if (!req || !req.tracks) return;

              const isLive = req.status === 'LIVE';
              const isApprovedAndDue = req.status === 'APPROVED' && new Date(req.releaseDate).getTime() <= Date.now();

              if (isLive || isApprovedAndDue) {
                  artistSet.add(req.artistName);
                  if (req.additionalMainArtists) {
                      req.additionalMainArtists.forEach(a => artistSet.add(a));
                  }

                  // Use ID from request. If it starts with 'a', it overrides a legacy album.
                  const albumId = req.id.startsWith('a') ? req.id : `dist_alb_${req.id}`;

                  // Check if overriding existing album
                  const existingAlbumIndex = mergedAlbums.findIndex(a => a.id === albumId);

                  const newAlbum: Album = {
                      id: albumId,
                      title: req.title,
                      artist: req.artistName,
                      covers: req.covers.length > 0 ? req.covers : ["https://picsum.photos/300"],
                      trackIds: [],
                      year: new Date(req.releaseDate).getFullYear(),
                      releaseDate: req.releaseDate, 
                      recordLabel: req.label,
                      type: req.type,
                      mainArtists: req.additionalMainArtists || [] 
                  };

                  const newTracksForThisAlbum: Track[] = [];

                  req.tracks.forEach((t, idx) => {
                      let trackId: string;
                      let existingTrack: Track | undefined;

                      if (t.existingHueq) {
                           existingTrack = mergedTracks.find(mt => mt.hueq === t.existingHueq);
                      }

                      // If we are overriding a legacy album, we should try to match tracks by index or ID if possible
                      // But for simplicity in this prototype, we'll just generate new track IDs based on the request
                      // UNLESS the request is specifically editing a legacy album, in which case we might want to preserve track IDs? 
                      // For now, simpler to treat the 'edit' as a full replace of the album's track list.

                      if (existingTrack) {
                          trackId = existingTrack.id;
                          const trackIndex = mergedTracks.findIndex(tr => tr.id === trackId);
                          if (trackIndex !== -1) {
                              mergedTracks[trackIndex] = {
                                  ...mergedTracks[trackIndex],
                                  title: t.title,
                                  artist: t.artist || req.artistName, // Use track override or release artist
                                  genre: t.genre || req.genre || mergedTracks[trackIndex].genre,
                                  explicit: t.explicit,
                              };
                          }
                      } else {
                          trackId = `dist_trk_${req.id}_${idx}`;
                          const releaseLevelArtists = req.additionalMainArtists || [];
                          const trackLevelArtists = t.mainArtists || [];
                          const combinedMainArtists = Array.from(new Set([...releaseLevelArtists, ...trackLevelArtists]));

                          newTracksForThisAlbum.push({
                              id: trackId,
                              title: t.title,
                              artist: t.artist || req.artistName, // Use track override or release artist
                              album: req.title,
                              cover: req.covers[0], 
                              duration: t.duration, 
                              url: t.fileUrl, 
                              plays: 0,
                              genre: t.genre || req.genre,
                              explicit: t.explicit,
                              feat: t.feat,
                              hueq: t.generatedHueq || t.existingHueq,
                              mainArtists: combinedMainArtists
                          });
                      }

                      newAlbum.trackIds.push(trackId);
                  });

                  if (existingAlbumIndex !== -1) {
                      mergedAlbums[existingAlbumIndex] = newAlbum;
                      // When replacing an album, we should really remove its old tracks from the mergedTracks list to avoid dupes/orphans
                      // However, finding them simply by ID is tricky if they were legacy 't1' style.
                      // For prototype: we just add the new tracks. Visuals will use the new Album which points to new Tracks.
                      // Old tracks might float in 'All Songs' if searching, but won't be linked to the album.
                      mergedTracks.push(...newTracksForThisAlbum);
                  } else {
                      mergedAlbums.push(newAlbum);
                      mergedTracks.push(...newTracksForThisAlbum);
                  }
              }
          });

          // Unique Tracks (Prevent duplicates if refresh called multiple times awkwardly)
          const uniqueTracks = Array.from(new Map(mergedTracks.map(item => [item.id, item])).values());

          const tracksWithPlays = uniqueTracks.map(t => ({
              ...t,
              plays: plays[t.id] !== undefined ? plays[t.id] : t.plays
          }));

          setTracks(tracksWithPlays);
          setAlbums(mergedAlbums);
          setExistingArtists(Array.from(artistSet));
      } catch (e) {
          console.error("Failed to refresh library", e);
          // Fallback to initial data if everything fails
          const { tracks: fallbackTracks } = generateInitialData();
          setTracks(fallbackTracks);
      }
  };

  // --- Initialization & User Switching ---
  useEffect(() => {
    try {
        // 1. Load User
        const sessionUser = StorageService.load<User | null>('huevify_current_user', null);
        if (sessionUser) setCurrentUser(sessionUser);

        // 2. Load Global Data
        const savedArtistAccounts = StorageService.load<ArtistAccount[]>('huevify_artist_accounts', []);
        setArtistAccounts(savedArtistAccounts);

        const savedReleaseRequests = StorageService.load<ReleaseRequest[]>('huevify_release_requests', []);
        setReleaseRequests(savedReleaseRequests);

        const savedProfileRequests = StorageService.load<ProfileEditRequest[]>('huevify_profile_requests', []);
        setProfileEditRequests(savedProfileRequests);

        const savedDeletedLegacy = StorageService.load<string[]>('huevify_deleted_legacy', []);
        setDeletedLegacyIds(savedDeletedLegacy);

        const mod = StorageService.load<ModeratorAccount | null>('huevify_moderator', null);
        setHasModerator(!!mod);

        // Initial Lib Refresh
        refreshLibrary(savedReleaseRequests);

        audioRef.current.volume = 0.5;
    } catch (e) {
        console.error("Initialization failed", e);
    }

    // Artificial delay to prevent "Logged out" flash, ensured to run
    setTimeout(() => {
        setIsInitialized(true);
    }, 500);
  }, []);

  // --- Load User-Specific Data when currentUser changes ---
  useEffect(() => {
      if (currentUser) {
          try {
              // Load Settings per user
              const userSettings = StorageService.load<AppSettings | null>(`huevify_settings_${currentUser.id}`, null);
              if (userSettings) {
                  setAppSettingsState({
                      ...userSettings,
                      albumCoverIndexes: userSettings.albumCoverIndexes || {}
                  });
              } else {
                  // Default settings
                  setAppSettingsState({
                    accentColor: '#1ed760',
                    language: 'English',
                    allowExplicitContent: true,
                    autoPlay: true,
                    crossfade: 0,
                    albumCoverIndexes: {}
                  });
              }

              // Load Recent per user
              const userRecent = StorageService.load<Track[]>(`huevify_recent_${currentUser.id}`, []);
              setRecentlyPlayed(userRecent);

              // Load Followed/Liked per user (Already separated by key)
              const storedLikedAlbums = StorageService.load<string[]>(`huevify_liked_albums_${currentUser.id}`, []);
              setLikedAlbumIds(storedLikedAlbums);

              const storedFollowedArtists = StorageService.load<string[]>(`huevify_followed_artists_${currentUser.id}`, []);
              setFollowedArtists(storedFollowedArtists);
          } catch(e) {
              console.error("Failed to load user specific data", e);
          }

      } else {
          // Reset if no user
          setRecentlyPlayed([]);
          setLikedAlbumIds([]);
          setFollowedArtists([]);
      }
  }, [currentUser]);

  // --- Release Scheduler Check ---
  useEffect(() => {
      const checkReleases = () => {
          try {
              const now = new Date();
              let changed = false;
              const updatedRequests = releaseRequests.map(req => {
                  if (req.status === 'APPROVED' && new Date(req.releaseDate).getTime() <= now.getTime()) {
                      changed = true;
                      return { ...req, status: 'LIVE' as const };
                  }
                  return req;
              });

              if (changed) {
                  setReleaseRequests(updatedRequests);
                  StorageService.save('huevify_release_requests', updatedRequests);
                  notifySync('ARTIST_DATA_UPDATE');
                  refreshLibrary(updatedRequests);
              }
          } catch (e) {
              console.error("Scheduler check failed", e);
          }
      };

      const interval = setInterval(checkReleases, 60000); 
      return () => clearInterval(interval);
  }, [releaseRequests]);


  // --- Artist Hub Methods ---

  const registerArtist = (data: Omit<ArtistAccount, 'id' | 'status'>): { success: boolean, message?: string } => {
      if (artistAccounts.some(a => a.username === data.username)) return { success: false, message: "Username taken" };

      const newArtist: ArtistAccount = {
          ...data,
          id: `art_${Date.now()}`,
          status: 'PENDING'
      };
      const updated = [...artistAccounts, newArtist];
      setArtistAccounts(updated);
      StorageService.save('huevify_artist_accounts', updated);
      notifySync('ARTIST_DATA_UPDATE');
      return { success: true };
  };

  const registerModerator = (data: ModeratorAccount): { success: boolean, message?: string } => {
      if (hasModerator) return { success: false, message: "Moderator already exists" };
      StorageService.save('huevify_moderator', data);
      setHasModerator(true);
      setCurrentModerator(data);
      // No sync needed for mod creation really
      return { success: true };
  };

  const loginArtistOrMod = (username: string, pass: string, type: 'ARTIST' | 'MODERATOR'): { success: boolean, message?: string } => {
      if (type === 'MODERATOR') {
          const mod = StorageService.load<ModeratorAccount | null>('huevify_moderator', null);
          if (mod && username === mod.username && pass === mod.password) {
              setCurrentModerator(mod);
              return { success: true };
          }
          return { success: false, message: "Invalid moderator credentials" };
      } else {
          const artist = artistAccounts.find(a => a.username === username && a.password === pass);
          if (!artist) return { success: false, message: "Invalid credentials" };
          if (artist.status === 'PENDING') return { success: false, message: "Account pending approval" };
          if (artist.status === 'REJECTED') return { success: false, message: "Account rejected" };

          setCurrentArtist(artist);
          return { success: true };
      }
  };

  const logoutArtistHub = () => {
      setCurrentArtist(null);
      setCurrentModerator(null);
  };

  const deleteArtistAccount = (artistId: string) => {
      const updated = artistAccounts.filter(a => a.id !== artistId);
      setArtistAccounts(updated);
      StorageService.save('huevify_artist_accounts', updated);
      notifySync('ARTIST_DATA_UPDATE');
      showNotification("Artist account deleted (Access Revoked). Artist content remains live.", "info");
  };

  const changeArtistPassword = (newPass: string) => {
      if (!currentArtist) return;
      const updated = artistAccounts.map(a => a.id === currentArtist.id ? { ...a, password: newPass } : a);
      setArtistAccounts(updated);
      StorageService.save('huevify_artist_accounts', updated);
      notifySync('ARTIST_DATA_UPDATE');
      // Update session
      setCurrentArtist({ ...currentArtist, password: newPass });
      showNotification("Password changed successfully.", "success");
  };

  const changeModeratorPassword = (newPass: string) => {
      if (!currentModerator) return;
      const updatedMod = { ...currentModerator, password: newPass };
      StorageService.save('huevify_moderator', updatedMod);
      setCurrentModerator(updatedMod);
      showNotification("Moderator password changed successfully.", "success");
  };

  const deleteRelease = (releaseId: string) => {
      // Check if it's a legacy release
      if (releaseId.startsWith('a') && !releaseId.includes('dist_')) {
          const updatedDeleted = [...deletedLegacyIds, releaseId];
          setDeletedLegacyIds(updatedDeleted);
          StorageService.save('huevify_deleted_legacy', updatedDeleted);
          notifySync('ARTIST_DATA_UPDATE');
          refreshLibrary(releaseRequests);
          showNotification("Legacy release hidden from platform.", "success");
          return;
      }

      const release = releaseRequests.find(r => r.id === releaseId);
      if (!release) return;

      if (release.status === 'LIVE' || release.status === 'APPROVED') {
          const updated = releaseRequests.map(r => r.id === releaseId ? { ...r, deletionRequested: true } : r);
          setReleaseRequests(updated);
          StorageService.save('huevify_release_requests', updated);
          notifySync('ARTIST_DATA_UPDATE');
          showNotification("Deletion requested. Pending moderator approval.", "info");
      } else {
          const updated = releaseRequests.filter(r => r.id !== releaseId);
          setReleaseRequests(updated);
          StorageService.save('huevify_release_requests', updated);
          notifySync('ARTIST_DATA_UPDATE');
          refreshLibrary(updated);

          // Cleanup Recently Played (Simple check)
          if (currentUser) {
              const newRecent = recentlyPlayed.filter(t => !t.id.includes(releaseId)); 
              setRecentlyPlayed(newRecent);
              StorageService.save(`huevify_recent_${currentUser.id}`, newRecent);
          }
          showNotification("Release deleted from drafts.", "success");
      }
  };

  const submitRelease = (
      releaseData: Omit<ReleaseRequest, 'id' | 'status' | 'artistId' | 'artistName' | 'submissionTime'>,
      overrideArtist?: { artistId: string, artistName: string }
  ) => {
      const artistId = overrideArtist ? overrideArtist.artistId : currentArtist?.id;
      const artistName = overrideArtist ? overrideArtist.artistName : currentArtist?.artistName;

      if (!artistId || !artistName) return;

      const newRelease: ReleaseRequest = {
          ...releaseData,
          id: `rel_${Date.now()}`,
          artistId: artistId,
          artistName: artistName,
          status: 'PENDING',
          submissionTime: new Date().toISOString()
      };

      // Auto-approve if moderator is uploading
      if (overrideArtist) {
          newRelease.status = 'APPROVED';
          // Check if date is in past, if so make LIVE
          if (new Date(newRelease.releaseDate).getTime() <= Date.now()) {
              newRelease.status = 'LIVE';
          }
      }

      const updated = [...releaseRequests, newRelease];
      setReleaseRequests(updated);
      StorageService.save('huevify_release_requests', updated);
      notifySync('ARTIST_DATA_UPDATE');

      if (newRelease.status === 'LIVE' || newRelease.status === 'APPROVED') {
          refreshLibrary(updated);
      }
  };

  const updateReleaseRequest = (id: string, data: Partial<ReleaseRequest>) => {
      // Check if updating a "legacy" ID that doesn't exist in requests yet (Migration scenario)
      if (id.startsWith('a') && !releaseRequests.find(r => r.id === id)) {
          // This is a legacy album being "edited". We need to create a new Request for it with the legacy ID
          // to overwrite the static data in refreshLibrary
          const newRequest: ReleaseRequest = {
              ...data as ReleaseRequest, // Data contains the full form state
              id: id, // Keep legacy ID to override
              status: 'LIVE', // Directly live if mod edits legacy
              submissionTime: new Date().toISOString()
          };
          const updated = [...releaseRequests, newRequest];
          setReleaseRequests(updated);
          StorageService.save('huevify_release_requests', updated);
          notifySync('ARTIST_DATA_UPDATE');
          refreshLibrary(updated);
          return;
      }

      const updated = releaseRequests.map(r => r.id === id ? { ...r, ...data } : r);
      setReleaseRequests(updated);
      StorageService.save('huevify_release_requests', updated);
      notifySync('ARTIST_DATA_UPDATE');

      // If it's live or approved, we need to refresh the library to reflect changes
      const req = updated.find(r => r.id === id);
      if (req && (req.status === 'LIVE' || req.status === 'APPROVED')) {
          refreshLibrary(updated);
      }
  };

  const submitProfileEdit = (editData: Omit<ProfileEditRequest, 'id' | 'status' | 'artistId' | 'artistName'>) => {
      if (!currentArtist) return;
      const newReq: ProfileEditRequest = {
          ...editData,
          id: `pe_${Date.now()}`,
          artistId: currentArtist.id,
          artistName: currentArtist.artistName,
          status: 'PENDING'
      };
      const updated = [...profileEditRequests, newReq];
      setProfileEditRequests(updated);
      StorageService.save('huevify_profile_requests', updated);
      notifySync('ARTIST_DATA_UPDATE');
  };

  const approveArtist = (id: string) => {
