                                                  className="w-full bg-transparent font-bold focus:outline-none border-b border-transparent focus:border-primary placeholder-secondary/50"
                                                  placeholder="Track Title"
                                              />
                                          </div>
                                          <div className="flex items-center gap-2">
                                              <label className="flex items-center gap-2 cursor-pointer bg-black/30 px-2 py-1 rounded">
                                                  <span className="text-xs font-bold uppercase text-secondary">Explicit</span>
                                                  <input type="checkbox" checked={track.explicit} onChange={e => updateTrack(idx, 'explicit', e.target.checked)} className="accent-primary"/>
                                              </label>
                                              <button onClick={() => {
                                                  const newTracks = distTracks.filter((_, i) => i !== idx);
                                                  setDistTracks(newTracks);
                                              }} className="text-secondary hover:text-red-500 p-1"><X size={20}/></button>
                                          </div>
                                      </div>

                                      {/* Advanced Track Options */}
                                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                           {/* HUEQ Input */}
                                           <div className="flex items-center gap-2 bg-black/20 p-2 rounded">
                                                <span className="text-[10px] font-bold text-secondary uppercase w-12">HUEQ</span>
                                                <input 
                                                    type="text" 
                                                    placeholder="Existing HUEQ (Optional)" 
                                                    value={track.existingHueq || ""}
                                                    onBlur={(e) => handleHueqBlur(idx, e.target.value)}
                                                    onChange={(e) => updateTrack(idx, 'existingHueq', e.target.value)}
                                                    className="bg-transparent text-xs w-full focus:outline-none font-mono text-primary"
                                                />
                                           </div>

                                           {/* Featured Artists */}
                                           <div className="flex flex-col gap-2 bg-black/20 p-2 rounded">
                                                <div className="flex items-center gap-2">
                                                    <span className="text-[10px] font-bold text-secondary uppercase w-12">Feat.</span>
                                                    <input 
                                                        type="text"
                                                        value={track.feat || ""}
                                                        onChange={(e) => updateTrack(idx, 'feat', e.target.value)}
                                                        className="bg-transparent text-xs w-full focus:outline-none"
                                                        placeholder="Featured Artist(s)"
                                                    />
                                                </div>
                                           </div>
                                      </div>

                                      {/* Main Artists Tagging */}
                                      <div className="bg-black/20 p-2 rounded">
                                            <div className="flex flex-wrap gap-2 mb-2">
                                                <span className="text-[10px] font-bold text-secondary uppercase self-center mr-2">Main Artists:</span>
                                                {(track.mainArtists || []).map(ma => (
                                                    <span key={ma} className="bg-primary/20 text-primary text-xs px-2 py-1 rounded-full flex items-center gap-1">
                                                        {ma}
                                                        <button onClick={() => removeTrackArtist(idx, ma)}><X size={12}/></button>
                                                    </span>
                                                ))}
                                            </div>
                                            <div className="flex gap-2">
                                                <input 
                                                    type="text" 
                                                    placeholder="Add another main artist..." 
                                                    value={trackArtistInputs[idx] || ""}
                                                    onChange={e => setTrackArtistInputs(prev => ({...prev, [idx]: e.target.value}))}
                                                    onKeyDown={e => e.key === 'Enter' && addTrackArtist(idx)}
                                                    className="bg-transparent text-xs flex-1 focus:outline-none border-b border-white/10 focus:border-primary"
                                                />
                                                <button onClick={() => addTrackArtist(idx)} className="text-primary hover:text-white"><Plus size={16}/></button>
                                            </div>
                                      </div>

                                      {/* Ordering Controls */}
                                      <div className="absolute left-[-30px] top-0 bottom-0 flex flex-col justify-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                          <button onClick={() => moveTrack(idx, 'up')} className="p-1 hover:text-white text-secondary" disabled={idx === 0}><ChevronUp size={20}/></button>
                                          <button onClick={() => moveTrack(idx, 'down')} className="p-1 hover:text-white text-secondary" disabled={idx === distTracks.length - 1}><ChevronDown size={20}/></button>
                                      </div>
                                  </div>
                              ))}

                              {distTracks.length === 0 && (
                                  <div className="text-center text-secondary py-10 border-2 border-dashed border-surface-highlight rounded-xl">
                                      No tracks added yet. Upload audio to begin.
                                  </div>
                              )}
                          </div>
                      </div>
                  )}

                  {/* STEP 3: Review */}
                  {distStep === 3 && (
                      <div className="flex flex-col gap-6 animate-slide-in-right">
                          <h2 className="text-2xl font-bold text-center mb-4">Review Release</h2>

                          <div className="bg-surface-highlight rounded-xl p-6 flex gap-6">
                               <img src={distCovers[0]} className="w-40 h-40 rounded shadow-xl object-cover" />
                               <div className="flex flex-col justify-center gap-2">
                                   <div className="text-sm text-secondary uppercase font-bold">{distType}</div>
                                   <h3 className="text-3xl font-bold">{distTitle}</h3>
                                   <div className="text-lg text-secondary">{currentArtist?.artistName || distArtistName}</div>
                                   <div className="text-sm text-secondary">{new Date(distDate).toLocaleDateString()} • {distTracks.length} Tracks</div>
                                   <div className="text-xs text-secondary mt-2">Label: {distLabel || currentArtist?.artistName || distArtistName}</div>
                               </div>
                          </div>

                          <div className="bg-surface-highlight rounded-xl p-6">
                              <h4 className="font-bold border-b border-white/10 pb-2 mb-4 text-secondary uppercase text-sm">Tracklist</h4>
                              <div className="flex flex-col gap-2">
                                  {distTracks.map((t, i) => (
                                      <div key={i} className="flex justify-between items-center py-2 border-b border-white/5 last:border-0">
                                          <div className="flex items-center gap-4">
                                              <span className="text-secondary w-6">{i+1}</span>
                                              <span className="font-medium">{t.title}</span>
                                              {t.explicit && <span className="text-[8px] border border-secondary text-secondary px-1 rounded">E</span>}
                                          </div>
                                          <span className="text-secondary text-sm">{formatDuration(t.duration)}</span>
                                      </div>
                                  ))}
                              </div>
                          </div>

                          <div className="flex flex-col gap-2">
                              <label className="text-xs font-bold text-secondary uppercase">Submission Message (Optional)</label>
                              <textarea 
                                  value={distMsg} 
                                  onChange={e => setDistMsg(e.target.value)}
                                  className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none resize-none h-20"
                                  placeholder="Notes for moderators..."
                              />
                          </div>
                      </div>
                  )}

              </div>

              {/* Navigation Buttons */}
              <div className="mt-6 pt-6 border-t border-surface-highlight flex justify-between">
                  {distStep > 1 ? (
                      <button onClick={() => setDistStep(prev => prev - 1)} className="px-6 py-3 rounded-full font-bold hover:bg-surface-highlight transition">Back</button>
                  ) : (
                      <div></div>
                  )}

                  {distStep < 3 ? (
                      <button onClick={handleNextStep} className="bg-white text-black px-8 py-3 rounded-full font-bold hover:scale-105 transition shadow-lg">Next</button>
                  ) : (
                      <button onClick={handleSubmitRelease} className="bg-primary text-black px-8 py-3 rounded-full font-bold hover:scale-105 transition shadow-lg shadow-primary/20">Submit Release</button>
                  )}
              </div>
          </div>
      );
  };

  return (
    <div className="fixed inset-0 bg-black z-[200] animate-fade-in flex flex-col">
        <button 
            onClick={() => setArtistHubOpen(false)} 
            className="absolute top-4 right-4 text-secondary hover:text-white z-[60]"
        >
            <X size={24} />
        </button>

        {view === 'AUTH' && renderAuth()}
        {view === 'ARTIST_DASH' && renderArtistDash()}
        {view === 'MOD_DASH' && renderModDash()}
        {view === 'DISTRIBUTION' && (
            <div className="flex items-center justify-center flex-1 overflow-hidden p-4">
                {renderDistribution()}
            </div>
        )}
        {view === 'PROFILE_EDIT' && (
            <div className="flex items-center justify-center flex-1 overflow-hidden p-4">
                {renderProfileEditForm()}
            </div>
        )}
        {view === 'ARTIST_PICK' && (
            <div className="flex items-center justify-center flex-1 overflow-hidden p-4">
                {renderArtistPickSelector()}
            </div>
        )}
        {view === 'MOD_CREDENTIALS' && renderModCredentials()}
        {view === 'MOD_ALL_RELEASES' && renderModAllReleases()}
        {view === 'MOD_SETTINGS' && (
            <div className="flex items-center justify-center flex-1 overflow-hidden p-4">
                {renderModSettings()}
            </div>
        )}

        {/* Overlays */}
        {selectedRelease && renderReleaseDetailModal()}
    </div>
  );
};

