                {searchResults.map((item: any) => {
                   const image = item.type === 'TRACK' ? getTrackCover(item) : getAlbumCover(item.id);
                   const subtitle = item.type === 'TRACK' ? item.artist : (item.year ? `Album • ${item.year}` : 'Album');

                   return (
                       <div 
                           key={`${item.type}_${item.id}`}
                           onClick={() => {
