                                          <div className="text-xs text-secondary bg-black/20 px-2 py-1 rounded">{formatDuration(track.duration)}</div>
                                      </div>
                                  </div>

                                  <div className="flex flex-col gap-2">
                                      <select 
                                        value={track.genre} 
