  // Cover Management
  getAlbumCover: (albumId: string) => string;
  getTrackCover: (track: Track) => string;
  changeAlbumCover: (albumId: string, index: number) => void;

  // Artist Hub / Moderation
  isArtistHubOpen: boolean;
