                   </span>

                   {/* Mobile Artist & Plays Display */}
                   <div className="md:hidden text-xs text-secondary truncate mt-0.5 flex items-center gap-1">
                      <span className="truncate">{showFeatOnMobile ? track.artist : (allTrackArtists.join(', '))}</span>
                      <span>•</span>
                      <span>{formatPlays(track.plays)}</span>
                   </div>

                   <div className="hidden md:block text-secondary text-xs group-hover:text-white truncate">
                       {allTrackArtists.map((a, i) => (
                           <span key={a}>
                               {i > 0 && ", "}
                               <span onClick={(e) => { e.stopPropagation(); goToArtist(a); }} className="hover:underline cursor-pointer">{a}</span>
                           </span>
                       ))}
                   </div>
                 </div>
               </div>

               <span className="text-secondary text-sm hidden md:block truncate">{formatPlays(track.plays)}</span>
               <span className="text-secondary text-sm hidden md:block">{formatDuration(track.duration)}</span>

               <div className="flex items-center gap-3 justify-end">
                 <button onClick={() => toggleLike(track.id)} className={`${isLiked(track.id) ? 'text-primary' : 'text-transparent group-hover:text-secondary hover:text-white'}`}>
                    <Heart size={16} fill={isLiked(track.id) ? 'currentColor' : 'none'} />
                 </button>

                 <button onClick={(e) => { e.stopPropagation(); openAddToPlaylist(track.id); }} className="text-transparent group-hover:text-secondary hover:text-white" title={t('addToPlaylist')}>
                    <Plus size={16} />
                 </button>

                 {isPlaylist && !isLikedSongs && !isHistory && isOwner && (
                    <button onClick={() => removeFromPlaylist((view as any).id, track.id)} className="text-transparent group-hover:text-secondary hover:text-red-500">
                      <Trash2 size={16} />
                    </button>
                 )}
               </div>
             </div>
           )})}

           {items.length > 0 && (
             <div className="mt-8 pt-8 border-t border-surface-highlight text-secondary text-sm font-medium pb-8 flex flex-col gap-1">
                 {fullReleaseDate && <p>{t('released')} {new Date(fullReleaseDate).toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' })}</p>}
                 {!fullReleaseDate && year && <p>{t('released')} {year}</p>}
                 <p>{items.length} {t('songs')}, {totalMinutes} {t('min')}</p>
                 <p>{formatPlays(totalReleasePlays)} {t('plays')}</p>
                 <p className="mt-4 text-[10px] uppercase tracking-widest font-bold">© {label}</p>
             </div>
           )}
        </div>

        {/* Cover Picker Modal */}
        {isCoverPickerOpen && currentAlbumObj && (
            <div className="fixed inset-0 bg-black/80 z-[100] flex items-center justify-center p-4">
                <div className="bg-surface w-full max-w-lg rounded-xl p-6 relative animate-zoom-in">
                    <button onClick={() => setCoverPickerOpen(false)} className="absolute top-4 right-4 text-white"><X size={24}/></button>
                    <h2 className="text-xl font-bold mb-4">{t('chooseCover')}</h2>
                    <p className="text-sm text-secondary mb-4">Select your preferred artwork for this release.</p>

                    <div className="grid grid-cols-2 md:grid-cols-3 gap-4 max-h-[60vh] overflow-y-auto">
                        {currentAlbumObj.covers.map((c: string, idx: number) => (
                            <div 
                                key={idx} 
                                onClick={() => { changeAlbumCover(currentAlbumObj.id, idx); setCoverPickerOpen(false); }}
                                className="cursor-pointer group relative"
                            >
                                <img src={c} className="w-full aspect-square object-cover rounded shadow-lg group-hover:opacity-80 transition" />
                                <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100">
                                    <span className="bg-primary text-black font-bold text-xs px-2 py-1 rounded">{t('select')}</span>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        )}

      </div>
    );
  }

  // Fallback
  return null;
};

import React from 'react';
import { useStore } from '../context/StoreContext';
import { Play, Pause, SkipBack, SkipForward, Repeat, Shuffle, Volume2, Heart, Plus } from './Icons';
import { PlayMode } from '../types';

const formatTime = (seconds: number) => {
  if (!seconds) return "0:00";
  const mins = Math.floor(seconds / 60);
  const secs = Math.floor(seconds % 60);
  return `${mins}:${secs.toString().padStart(2, '0')}`;
};

export const Player = () => {
  const { 
    currentTrack, isPlaying, togglePlay, nextTrack, prevTrack, 
    progress, duration, seek, volume, setVolume, playMode, toggleRepeat,
    isLiked, toggleLike, setMobilePlayerOpen, isShuffle, toggleShuffle,
    openAddToPlaylist, goToArtist, getTrackCover, t
  } = useStore();

  if (!currentTrack) {
    return (
      <div className="fixed bottom-16 md:bottom-0 w-full h-16 md:h-24 bg-surface border-t border-surface-highlight flex items-center justify-center text-secondary text-sm z-50">
        {t('selectTrack')}
      </div>
    );
  }

  const allArtists = Array.from(new Set([currentTrack.artist, ...(currentTrack.mainArtists || [])]));
  const cover = getTrackCover(currentTrack);

  return (
    // On mobile: bottom-16 (above nav), height-16. On desktop: bottom-0, height-24.
    <div className="fixed bottom-16 md:bottom-0 left-0 w-full h-16 md:h-24 bg-surface border-t border-surface-highlight px-4 flex items-center justify-between z-50 transition-all">

      {/* Track Info - Clickable on mobile to open full player */}
      <div 
        className="flex items-center w-full md:w-1/4 md:min-w-[180px] overflow-hidden cursor-pointer md:cursor-default"
        onClick={() => {
            if (window.innerWidth < 768) {
                setMobilePlayerOpen(true);
            }
        }}
      >
        <img src={cover} alt="Cover" className="h-10 w-10 md:h-14 md:w-14 rounded shadow mr-3 md:mr-4 flex-shrink-0" />
        <div className="flex flex-col overflow-hidden mr-2 md:mr-4 flex-1">
          <span className="text-sm font-semibold text-white truncate hover:underline cursor-pointer">{currentTrack.title}</span>
          <div className="text-xs text-secondary truncate">
              {allArtists.map((a, i) => (
                  <span key={a}>
                      {i > 0 && ", "}
                      <span 
                        onClick={(e) => { e.stopPropagation(); goToArtist(a); }} 
                        className="hover:text-white hover:underline cursor-pointer"
                      >
                          {a}
                      </span>
                  </span>
              ))}
          </div>
        </div>
        <button 
          onClick={(e) => { e.stopPropagation(); toggleLike(currentTrack.id); }} 
          className={`hidden md:block hover:scale-105 transition mr-2 ${isLiked(currentTrack.id) ? 'text-primary' : 'text-secondary hover:text-white'}`}
        >
          <Heart size={20} fill={isLiked(currentTrack.id) ? 'currentColor' : 'none'} />
        </button>
        <button 
          onClick={(e) => { e.stopPropagation(); openAddToPlaylist(currentTrack.id); }} 
          className="hidden md:block hover:scale-105 transition text-secondary hover:text-white"
        >
          <Plus size={20} />
        </button>
      </div>

      {/* Controls (Desktop Centered) */}
      <div className="flex flex-col items-center w-auto md:w-2/4 max-w-2xl md:static absolute right-4 md:right-auto">
        <div className="flex items-center gap-4 md:gap-6 mb-0 md:mb-2">
           {/* Hide extra controls on mobile */}
          <button 
             onClick={toggleShuffle}
             className={`hidden md:block transition ${isShuffle ? 'text-primary' : 'text-secondary hover:text-white'}`}
          >
            <Shuffle size={20} />
          </button>
          <button onClick={prevTrack} className="hidden md:block text-secondary hover:text-white transition">
            <SkipBack size={24} fill="currentColor" />
          </button>

          <button 
            onClick={(e) => { e.stopPropagation(); togglePlay(); }} 
            className="w-8 h-8 md:w-8 md:h-8 bg-white rounded-full flex items-center justify-center hover:scale-105 transition text-black"
          >
            {isPlaying ? <Pause size={20} fill="currentColor" /> : <Play size={20} fill="currentColor" className="ml-1" />}
          </button>

          <button onClick={nextTrack} className="text-secondary hover:text-white transition ml-2 md:ml-0">
            <SkipForward size={24} fill="currentColor" />
          </button>
          <button 
            onClick={toggleRepeat} 
            className={`hidden md:block transition relative ${playMode !== PlayMode.OFF ? 'text-primary' : 'text-secondary hover:text-white'}`}
          >
            <Repeat size={20} />
            {playMode === PlayMode.ONE && <span className="absolute text-[8px] font-bold top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-primary">1</span>}
            {playMode === PlayMode.CONTEXT && <div className="absolute -bottom-2 left-1/2 -translate-x-1/2 w-1 h-1 bg-primary rounded-full"></div>}
          </button>
        </div>

        {/* Progress Bar (Hidden on Mobile) */}
        <div className="hidden md:flex items-center w-full gap-2 text-xs text-secondary">
          <span>{formatTime(progress)}</span>
          <div className="flex-1 h-1 bg-surface-highlight rounded-full relative group">
             <input
                type="range"
                min={0}
                max={duration || 100}
                value={progress}
                onChange={(e) => seek(Number(e.target.value))}
                className="absolute w-full h-full opacity-0 cursor-pointer z-10"
              />
              <div 
                className="h-full bg-white rounded-full group-hover:bg-primary transition-colors"
                style={{ width: `${(progress / (duration || 1)) * 100}%` }}
              />
          </div>
          <span>{formatTime(duration)}</span>
        </div>
      </div>

      {/* Volume (Hidden on Mobile) */}
      <div className="hidden md:flex items-center justify-end w-1/4 min-w-[150px] gap-2">
        <Volume2 size={20} className="text-secondary" />
        <div className="w-24 h-1 bg-surface-highlight rounded-full relative group">
            <input 
              type="range" 
              min={0} 
              max={1} 
              step={0.01} 
              value={volume}
              onChange={(e) => setVolume(Number(e.target.value))}
              className="absolute w-full h-full opacity-0 cursor-pointer z-10"
            />
            <div 
              className="h-full bg-white rounded-full group-hover:bg-primary transition-colors"
              style={{ width: `${volume * 100}%` }}
            />
        </div>
      </div>

      {/* Mobile progress bar (Simple overlay on top of player) */}
      <div className="absolute top-0 left-0 w-full h-[2px] bg-transparent md:hidden pointer-events-none">
        <div className="h-full bg-primary" style={{ width: `${(progress / (duration || 1)) * 100}%` }} />
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { useStore } from '../context/StoreContext.tsx';
import { X, Image } from './Icons.tsx';

export const CreatePlaylistModal = () => {
  const { 
    isCreatePlaylistOpen, setCreatePlaylistOpen, createPlaylist, editPlaylist,
    playlistIdToEdit, playlists, t 
  } = useStore();

  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [cover, setCover] = useState<string | null>(null);
  const [isPublic, setIsPublic] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isCreatePlaylistOpen) {
      if (playlistIdToEdit) {
        const pl = playlists.find(p => p.id === playlistIdToEdit);
        if (pl) {
            setName(pl.name);
            setDescription(pl.description || "");
            setCover(pl.customCover || null);
            setIsPublic(!!pl.isPublic);
        }
      } else {
        // Reset for Create mode
        setName("");
        setDescription("");
        setCover(null);
        setIsPublic(false);
      }
    }
  }, [isCreatePlaylistOpen, playlistIdToEdit, playlists]);

  if (!isCreatePlaylistOpen) return null;

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setCover(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSave = () => {
    if (!name.trim()) return alert("Name is required");

    if (playlistIdToEdit) {
        editPlaylist(playlistIdToEdit, name, description, cover || undefined, isPublic);
    } else {
        createPlaylist(name, description, cover || undefined, isPublic);
    }

    setCreatePlaylistOpen(false);
  };

  return (
    <div className="fixed inset-0 bg-black/80 z-[70] flex items-center justify-center p-4">
      <div className="bg-surface w-full max-w-md rounded-lg p-6 relative shadow-2xl border border-surface-highlight animate-in fade-in zoom-in duration-200">
        <button 
          onClick={() => setCreatePlaylistOpen(false)} 
          className="absolute top-4 right-4 text-secondary hover:text-white"
        >
          <X size={24} />
        </button>

        <h2 className="text-2xl font-bold mb-6 text-center">{playlistIdToEdit ? t('editPlaylist') : t('createPlaylist')}</h2>

        <div className="flex flex-col gap-6">
          {/* Cover Upload Area */}
          <div className="flex justify-center">
            <div 
              onClick={() => fileInputRef.current?.click()}
              className="w-40 h-40 bg-surface-highlight rounded shadow-inner flex flex-col items-center justify-center cursor-pointer hover:bg-[#333] transition relative overflow-hidden group"
            >
              {cover ? (
                <img src={cover} alt="Preview" className="w-full h-full object-cover" />
              ) : (
                <>
                  <Image size={48} className="text-secondary mb-2" />
                  <span className="text-xs text-secondary font-bold">{t('choosePhoto')}</span>
                </>
              )}

              {/* Hover overlay */}
              <div className="absolute inset-0 bg-black/50 flex items-center justify-center opacity-0 group-hover:opacity-100 transition">
                 <span className="text-white font-bold">{t('edit')}</span>
              </div>
            </div>
            <input 
              type="file" 
              ref={fileInputRef} 
              className="hidden" 
              accept="image/*" 
              onChange={handleFileChange}
            />
          </div>

          <div className="flex flex-col gap-4">
            <input 
              type="text" 
              placeholder={t('playlistName')}
              value={name}
              onChange={(e) => setName(e.target.value)}
              className="bg-surface-highlight text-white p-3 rounded focus:outline-none focus:ring-1 focus:ring-white font-bold"
            />
            <textarea 
              placeholder={t('description')}
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              className="bg-surface-highlight text-white p-3 rounded focus:outline-none focus:ring-1 focus:ring-white resize-none h-24 text-sm"
            />
          </div>

          <div className="flex items-center gap-3 bg-surface-highlight p-3 rounded">
              <input 
                type="checkbox" 
                id="public-check"
                checked={isPublic}
                onChange={e => setIsPublic(e.target.checked)}
                className="w-5 h-5 accent-primary cursor-pointer"
              />
              <div className="flex flex-col">
                  <label htmlFor="public-check" className="font-bold text-sm cursor-pointer select-none">{t('publicPlaylist')}</label>
                  <span className="text-xs text-secondary">{t('publicDesc')}</span>
              </div>
          </div>

          <div className="flex justify-end">
            <button 
              onClick={handleSave}
              className="bg-white text-black font-bold py-3 px-8 rounded-full hover:scale-105 transition"
            >
              {t('save')}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

