                        <BarChart2 size={24} className="text-primary"/>
                    </div>
                    <div>
                        <div className="text-2xl font-bold">{stats.monthlyPlays.toLocaleString()}</div>
                        <div className="text-xs text-secondary uppercase font-bold">{t('monthlyPlays')}</div>
                    </div>
                </div>
