                                           <input type="text" value={track.title} onChange={e => updateTrack(idx, 'title', e.target.value)} className="bg-background p-2 rounded text-sm focus:outline-none focus:border-primary border border-transparent"/>
                                       </div>

                                       {/* HUEQ Input */}
                                       <div className="flex flex-col gap-1">
                                            <label className="text-[10px] font-bold text-secondary uppercase flex items-center gap-1">
                                                HUEQ (ISRC) <span className="text-[8px] bg-white/10 px-1 rounded text-white/50">OPTIONAL</span>
                                            </label>
                                            <div className="relative">
                                                <input 
                                                    type="text" 
                                                    value={track.existingHueq || ""} 
                                                    onChange={e => updateTrack(idx, 'existingHueq', e.target.value)}
                                                    onBlur={e => handleHueqBlur(idx, e.target.value)}
                                                    placeholder="Existing Code"
                                                    className="bg-background p-2 rounded text-sm focus:outline-none focus:border-primary border border-transparent w-full font-mono uppercase"
                                                />
                                                {track.fileUrl && track.existingHueq && (
                                                    <div className="absolute right-2 top-2 text-green-500"><CheckCircle size={16}/></div>
                                                )}
                                            </div>
                                       </div>

                                       <div className="flex flex-col gap-1">
                                            <label className="text-[10px] font-bold text-secondary uppercase">Feat. Artist (Optional)</label>
                                            <input type="text" value={track.feat || ""} onChange={e => updateTrack(idx, 'feat', e.target.value)} className="bg-background p-2 rounded text-sm focus:outline-none focus:border-primary border border-transparent"/>
                                       </div>

                                       {/* Track Level Main Artist */}
                                       <div className="flex flex-col gap-1">
                                           <label className="text-[10px] font-bold text-secondary uppercase">Add Main Artist (Optional)</label>
                                           <div className="flex gap-2">
                                               <input 
                                                    type="text" 
                                                    value={trackArtistInputs[idx] || ""} 
                                                    onChange={e => setTrackArtistInputs(prev => ({ ...prev, [idx]: e.target.value }))}
                                                    className="bg-background p-2 rounded text-sm focus:outline-none focus:border-primary border border-transparent flex-1"
                                               />
                                               <button onClick={() => addTrackArtist(idx)} className="bg-white/10 px-3 rounded hover:bg-white/20"><Plus size={16}/></button>
                                           </div>
                                           {track.mainArtists && track.mainArtists.length > 0 && (
                                               <div className="flex flex-wrap gap-1 mt-1">
                                                   {track.mainArtists.map(ma => (
                                                       <span key={ma} className="bg-primary/20 text-primary text-[10px] px-1 rounded flex items-center gap-1">
                                                           {ma} <X size={10} className="cursor-pointer" onClick={() => removeTrackArtist(idx, ma)}/>
                                                       </span>
                                                   ))}
                                               </div>
                                           )}
                                       </div>
                                   </div>

                                   <div className="flex items-center gap-4">
                                       <label className="flex items-center gap-2 cursor-pointer bg-black/20 px-3 py-2 rounded">
                                           <input type="checkbox" checked={track.explicit} onChange={e => updateTrack(idx, 'explicit', e.target.checked)} className="accent-primary"/>
                                           <span className="text-xs font-bold text-white uppercase">{t('explicit')}</span>
                                       </label>
                                       <span className="text-xs text-secondary font-mono">{formatDuration(track.duration)}</span>
                                   </div>
                               </div>
                           ))}
                      </div>
                  </div>
              )}

              {distStep === 3 && (
                  <div className="flex flex-col gap-6 max-w-lg mx-auto">
                      <div className="flex gap-4">
                          <div className="flex-1 flex flex-col gap-1">
                              <label className="text-xs font-bold text-secondary uppercase">{t('releaseDate')}</label>
                              <div className="relative">
                                  <input type="date" value={distDate} onChange={e => setDistDate(e.target.value)} className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none w-full"/>
                                  <Calendar className="absolute right-3 top-3 text-secondary pointer-events-none" size={20}/>
                              </div>
                          </div>
                          <div className="flex-1 flex flex-col gap-1">
                              <label className="text-xs font-bold text-secondary uppercase">{t('releaseTime')}</label>
                              <div className="relative">
                                  <input type="time" value={distTime} onChange={e => setDistTime(e.target.value)} className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none w-full"/>
                                  <Clock className="absolute right-3 top-3 text-secondary pointer-events-none" size={20}/>
                              </div>
                          </div>
                      </div>

                      <div className="flex flex-col gap-1">
                           <label className="text-xs font-bold text-secondary uppercase">{t('msgToMods')}</label>
                           <textarea value={distMsg} onChange={e => setDistMsg(e.target.value)} placeholder="Notes about samples, clearance, etc." className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none h-32 resize-none"/>
                      </div>

                      <div className="bg-surface-highlight p-4 rounded text-sm text-secondary">
                          <p>By submitting, you confirm you have rights to this content.</p>
                      </div>
                  </div>
              )}
          </div>

          <div className="flex justify-between mt-8 pt-4 border-t border-surface-highlight">
              {distStep > 1 ? (
                  <button onClick={() => setDistStep(prev => prev - 1)} className="px-6 py-2 rounded-full font-bold border border-secondary text-secondary hover:text-white hover:border-white transition">{t('back')}</button>
              ) : <div></div>}

              {distStep < 3 ? (
                  <button onClick={handleNextStep} className="px-6 py-2 rounded-full font-bold bg-white text-black hover:scale-105 transition">{t('next')}</button>
              ) : (
                  <button onClick={handleSubmitRelease} className="px-8 py-2 rounded-full font-bold bg-primary text-black hover:scale-105 transition shadow-lg shadow-primary/20">{isEditing ? t('updateRelease') : t('submitRelease')}</button>
              )}
          </div>
      </div>
  );

  const renderArtistDash = () => {
      if (!currentArtist) return null;
      const stats = getArtistStats(currentArtist.artistName);
      const myReleases = releaseRequests.filter(r => r.artistId === currentArtist.id).sort((a,b) => new Date(b.submissionTime || 0).getTime() - new Date(a.submissionTime || 0).getTime());

      return (
          <div className="w-full h-full flex flex-col p-6 relative overflow-y-auto animate-fade-in pb-8">
              <div className="flex justify-between items-center mb-8 shrink-0">
                  <h1 className="text-3xl font-bold flex items-center gap-3"><Mic2 className="text-primary"/> {t('artistDash')}</h1>
                  <div className="flex gap-4">
                      <div className="flex flex-col items-end">
                          <span className="text-xl font-bold">{currentArtist.artistName}</span>
                          <span className="text-xs text-secondary">{t('status')}: {currentArtist.status}</span>
                      </div>
                      <img src={currentArtist.avatar || "https://via.placeholder.com/150"} className="w-12 h-12 rounded-full object-cover border-2 border-primary" />
                  </div>
              </div>

              {/* Stats Cards */}
              <div className="grid grid-cols-2 gap-4 mb-8 shrink-0">
                  <div className="bg-surface p-4 rounded-xl border border-surface-highlight flex flex-col items-center justify-center gap-2">
                      <span className="text-3xl font-bold">{stats.monthlyPlays.toLocaleString()}</span>
                      <span className="text-xs text-secondary uppercase tracking-widest">{t('monthlyPlays')}</span>
                  </div>
                  <div className="bg-surface p-4 rounded-xl border border-surface-highlight flex flex-col items-center justify-center gap-2">
                      <span className="text-3xl font-bold">#{stats.globalRank}</span>
                      <span className="text-xs text-secondary uppercase tracking-widest">Global Rank</span>
                  </div>
              </div>

              {/* Quick Actions */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-8 shrink-0">
                   <button onClick={() => { resetDistForm(); setView('DISTRIBUTION'); }} className="bg-primary text-black p-4 rounded-xl flex items-center justify-center gap-2 hover:scale-105 transition font-bold shadow-lg hover:shadow-primary/20">
                        <UploadCloud size={20}/>
                        {t('uploadNew')}
                   </button>
                   <button onClick={() => setView('PROFILE_EDIT')} className="bg-surface border border-surface-highlight p-4 rounded-xl flex items-center justify-center gap-2 hover:bg-surface-highlight transition font-bold hover:scale-105">
                        <User size={20} className="text-secondary"/>
                        {t('editProfile')}
                   </button>
                   <button onClick={() => setView('ARTIST_PICK')} className="bg-surface border border-surface-highlight p-4 rounded-xl flex items-center justify-center gap-2 hover:bg-surface-highlight transition font-bold hover:scale-105">
                        <CheckCircle size={20} className="text-secondary"/>
                        {t('artistPick')}
                   </button>
              </div>

              {/* Releases List */}
              <div className="bg-surface rounded-xl p-6 flex flex-col border border-surface-highlight flex-1 min-h-[300px]">
                  <h3 className="font-bold mb-4 flex items-center gap-2 text-primary"><ListMusic size={18}/> {t('myReleases')}</h3>
                  <div className="overflow-y-auto flex-1 flex flex-col gap-3">
                      {myReleases.length === 0 && <span className="text-secondary text-sm text-center py-10">{t('noReleases')}</span>}
                      {myReleases.map(r => (
                          <div key={r.id} className="p-3 bg-surface-highlight rounded flex gap-3 items-center group cursor-pointer hover:bg-zinc-800 transition" onClick={() => handleEditRelease(r)}>
                              <img src={r.covers[0]} className="w-12 h-12 rounded object-cover flex-shrink-0" alt=""/>
                              <div className="flex-1 min-w-0">
                                  <div className="flex items-center gap-2">
                                      <div className="font-bold truncate">{r.title}</div>
                                      {r.deletionRequested && <span className="text-[10px] bg-red-500 text-white px-1 rounded font-bold">{t('deleteReq')}</span>}
                                  </div>
                                  <div className="text-xs text-secondary truncate">{r.type} • {new Date(r.releaseDate).toLocaleDateString()}</div>
                              </div>
                              <div className="flex flex-col items-end gap-1">
                                  <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase ${
                                      r.status === 'LIVE' ? 'bg-green-500/20 text-green-500' :
                                      r.status === 'APPROVED' ? 'bg-blue-500/20 text-blue-500' :
                                      r.status === 'REJECTED' ? 'bg-red-500/20 text-red-500' :
                                      'bg-yellow-500/20 text-yellow-500'
                                  }`}>
                                      {r.status}
                                  </span>
                                  <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition" onClick={e => e.stopPropagation()}>
                                      {r.status !== 'LIVE' && r.status !== 'APPROVED' && (
                                          <button onClick={() => deleteRelease(r.id)} className="text-secondary hover:text-red-500" title={t('delete')}>
                                              <Trash2 size={16} />
                                          </button>
                                      )}
                                      {(r.status === 'LIVE' || r.status === 'APPROVED') && !r.deletionRequested && (
                                          <button onClick={() => deleteRelease(r.id)} className="text-secondary hover:text-red-500" title={t('deleteReq')}>
                                              <Trash2 size={16} />
                                          </button>
                                      )}
                                  </div>
                              </div>
                          </div>
                      ))}
                  </div>
              </div>

              <div className="mt-8">
                  <button 
                      onClick={() => { logoutArtistHub(); setView('AUTH'); }} 
                      className="flex items-center gap-2 px-4 py-2 bg-surface-highlight rounded-full text-secondary hover:text-white hover:bg-red-500 hover:text-white transition font-bold shadow-lg"
                  >
                      <LogOut size={18} />
                      {t('logout')}
                  </button>
              </div>
          </div>
      );
  };

  const renderProfileEditForm = () => (
      <div className="w-full max-w-md bg-surface p-8 rounded-xl shadow-2xl border border-surface-highlight animate-zoom-in relative">
          <button onClick={() => setView('ARTIST_DASH')} className="absolute top-8 left-8 text-secondary hover:text-white"><ArrowLeft size={24}/></button>
          <h2 className="text-2xl font-bold text-center mb-6">{t('editProfile')}</h2>

          <div className="flex flex-col gap-6">
               <div className="flex justify-center mb-2">
                    <div 
                        onClick={() => avatarInputRef.current?.click()}
                        className="w-32 h-32 rounded-full bg-surface-highlight flex items-center justify-center cursor-pointer hover:opacity-80 transition relative overflow-hidden group border-4 border-surface"
                    >
                        {editAvatar ? (
                            <img src={editAvatar} className="w-full h-full object-cover" />
                        ) : (
                            <Camera size={40} className="text-secondary" />
                        )}
                        <div className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition">
                            <span className="text-xs font-bold text-white uppercase">{t('upload')}</span>
                        </div>
                    </div>
                    <input type="file" ref={avatarInputRef} className="hidden" accept="image/*" onChange={handleAvatarUpload} />
               </div>

               <div className="flex flex-col gap-1">
                   <label className="text-xs font-bold text-secondary uppercase">{t('bio')}</label>
                   <textarea value={editBio} onChange={e => setEditBio(e.target.value)} className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none h-32 resize-none"/>
               </div>

               <div className="flex flex-col gap-1">
                   <label className="text-xs font-bold text-secondary uppercase">{t('changePass')}</label>
                   <input type="password" value={editNewPassword} onChange={e => setEditNewPassword(e.target.value)} placeholder={t('newPass')} className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none"/>
               </div>

               <button onClick={handleProfileUpdate} className="bg-white text-black font-bold py-3 rounded-full hover:scale-105 transition mt-2">{t('submitChanges')}</button>
          </div>
      </div>
  );

  const renderArtistPickSelector = () => {
      // Search Logic
      const searchResults = tracks.filter(t => t.title.toLowerCase().includes(pickSearch.toLowerCase()) || t.album.toLowerCase().includes(pickSearch.toLowerCase())).slice(0, 5);

      const handleSelectPick = (item: any, type: 'TRACK' | 'ALBUM' | 'PLAYLIST') => {
          submitProfileEdit({
              newArtistPick: {
                  type,
                  id: item.id,
                  image: type === 'TRACK' ? getTrackCover(item) : type === 'ALBUM' ? getAlbumCover(item.id) : item.customCover,
                  subtitle: type === 'TRACK' ? item.title : item.title || item.name
              }
          });
          showNotification("Artist Pick Updated (Pending Approval)", "success");
          setView('ARTIST_DASH');
      };

      return (
          <div className="w-full max-w-lg bg-surface p-8 rounded-xl shadow-2xl border border-surface-highlight animate-zoom-in relative h-[70vh] flex flex-col">
              <button onClick={() => setView('ARTIST_DASH')} className="absolute top-8 left-8 text-secondary hover:text-white"><ArrowLeft size={24}/></button>
              <h2 className="text-2xl font-bold text-center mb-6">{t('artistPick')}</h2>

              <div className="relative mb-6">
                  <input 
                      type="text" 
                      placeholder={t('searchTrackAlbum')}
                      value={pickSearch}
                      onChange={e => setPickSearch(e.target.value)}
                      className="w-full bg-background p-3 pl-10 rounded border border-surface-highlight focus:border-primary focus:outline-none"
                  />
                  <Search className="absolute left-3 top-3 text-secondary" size={20}/>
              </div>

              <div className="flex-1 overflow-y-auto flex flex-col gap-2">
                  {searchResults.map(item => (
                      <div key={item.id} className="p-3 bg-surface-highlight rounded flex items-center justify-between group">
                          <div className="flex items-center gap-3">
                              <img src={getTrackCover(item)} className="w-10 h-10 rounded object-cover" />
                              <div className="flex flex-col">
                                  <span className="font-bold">{item.title}</span>
                                  <span className="text-xs text-secondary">{item.artist}</span>
                              </div>
                          </div>
                          <button 
                              onClick={() => handleSelectPick(item, 'TRACK')}
                              className="px-3 py-1 bg-white text-black text-xs font-bold rounded-full hover:scale-105 transition"
                          >
                              {t('select')}
                          </button>
                      </div>
                  ))}
                  {albums.filter(a => a.title.toLowerCase().includes(pickSearch.toLowerCase())).slice(0, 3).map(a => (
                      <div key={a.id} className="p-3 bg-surface-highlight rounded flex items-center justify-between group">
                           <div className="flex items-center gap-3">
                              <img src={a.covers[0]} className="w-10 h-10 rounded object-cover" />
                              <div className="flex flex-col">
                                  <span className="font-bold">{a.title}</span>
                                  <span className="text-xs text-secondary">Album • {a.artist}</span>
                              </div>
                          </div>
                          <button 
                              onClick={() => handleSelectPick(a, 'ALBUM')}
                              className="px-3 py-1 bg-white text-black text-xs font-bold rounded-full hover:scale-105 transition"
                          >
                              {t('select')}
                          </button>
                      </div>
                  ))}
              </div>
          </div>
      );
  };

  return (
    <div className="fixed inset-0 bg-black z-[200] animate-fade-in flex flex-col">
        <button 
            onClick={() => setArtistHubOpen(false)} 
            className="absolute top-4 right-4 text-secondary hover:text-white z-[60]"
        >
            <X size={24} />
        </button>

        {view === 'AUTH' && renderAuth()}
        {view === 'ARTIST_DASH' && renderArtistDash()}
        {view === 'MOD_DASH' && renderModDash()}
        {view === 'DISTRIBUTION' && (
            <div className="flex items-center justify-center flex-1 overflow-hidden p-4">
                {renderDistribution()}
            </div>
        )}
        {view === 'PROFILE_EDIT' && (
            <div className="flex items-center justify-center flex-1 overflow-hidden p-4">
                {renderProfileEditForm()}
            </div>
        )}
        {view === 'ARTIST_PICK' && (
            <div className="flex items-center justify-center flex-1 overflow-hidden p-4">
                {renderArtistPickSelector()}
            </div>
        )}
        {view === 'MOD_CREDENTIALS' && renderModCredentials()}
        {view === 'MOD_ALL_RELEASES' && renderModAllReleases()}
        {view === 'MOD_ALL_TRACKS' && renderModAllTracks()}
        {view === 'MOD_SETTINGS' && (
            <div className="flex items-center justify-center flex-1 overflow-hidden p-4">
                {renderModSettings()}
            </div>
        )}

        {/* Overlays */}
        {selectedRelease && renderReleaseDetailModal()}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { useStore } from '../context/StoreContext.tsx';
import { 
  X, Mic2, Shield, User, UploadCloud, Calendar, FileAudio, 
  CheckCircle, XCircle, Clock, MoreVertical, Image, Plus,
  Edit, ArrowLeft, Camera, LogOut, ChevronDown, Trash2, ListMusic, Check, Search, Play, BarChart2, Globe, Database, Key, Settings, ChevronUp
} from './Icons.tsx';
import { DistributionTrack, ReleaseType, ReleaseRequest } from '../types.ts';

type HubView = 'AUTH' | 'ARTIST_DASH' | 'MOD_DASH' | 'DISTRIBUTION' | 'PROFILE_EDIT' | 'ARTIST_PICK' | 'MOD_CREDENTIALS' | 'MOD_ALL_RELEASES' | 'MOD_SETTINGS' | 'MOD_ALL_TRACKS';

const formatDuration = (seconds: number) => {
    const min = Math.floor(seconds / 60);
    const sec = Math.floor(seconds % 60);
    return `${min}:${sec.toString().padStart(2, '0')}`;
};

export const ArtistHub = () => {
  const { 
    isArtistHubOpen, setArtistHubOpen, currentArtist, currentModerator, 
    loginArtistOrMod, registerArtist, registerModerator, logoutArtistHub, artistAccounts,
    releaseRequests, profileEditRequests, approveArtist, rejectArtist,
    approveRelease, rejectRelease, approveProfileEdit, rejectProfileEdit,
    submitRelease, updateReleaseRequest, getArtistStats, submitProfileEdit, hasModerator, existingArtists,
    deleteRelease, getTrackByHueq, tracks, albums, playlists, showNotification, deleteArtistAccount, getTrackCover, getAlbumCover,
    changeArtistPassword, changeModeratorPassword, deleteLegacyTrack, t
  } = useStore();

  const [view, setView] = useState<HubView>('AUTH');

  // Auth State
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [role, setRole] = useState<'ARTIST' | 'MODERATOR'>('ARTIST');
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");

  // Artist Registration Logic
  const [artistNameSelection, setArtistNameSelection] = useState("");
  const [isCreatingNewArtist, setIsCreatingNewArtist] = useState(false);
  const [newArtistAlias, setNewArtistAlias] = useState("");

  const [message, setMessage] = useState("");

  // Distribution State
  const [distStep, setDistStep] = useState(1);
  const [distTitle, setDistTitle] = useState("");
  const [distArtistName, setDistArtistName] = useState(""); // For Mods to override
  const [distType, setDistType] = useState<ReleaseType>('Single');
  const [distGenre, setDistGenre] = useState("Pop");
  const [distLabel, setDistLabel] = useState("");
  const [distCovers, setDistCovers] = useState<string[]>([]);
  const [distMainArtists, setDistMainArtists] = useState<string[]>([]);
  const [distMainArtistInput, setDistMainArtistInput] = useState("");
  const [distTracks, setDistTracks] = useState<DistributionTrack[]>([]);

  // Editing Mode
  const [isEditing, setIsEditing] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  // Track Tag Inputs (Step 2)
  const [trackArtistInputs, setTrackArtistInputs] = useState<Record<number, string>>({});

  const [distDate, setDistDate] = useState("");
  const [distTime, setDistTime] = useState("00:00");
  const [distMsg, setDistMsg] = useState("");

  // Edit Profile State
  const [editBio, setEditBio] = useState("");
  const [editAvatar, setEditAvatar] = useState("");
  const [editNewPassword, setEditNewPassword] = useState("");

  // Mod Settings State
  const [modNewPassword, setModNewPassword] = useState("");

  // Artist Pick State
  const [pickSearch, setPickSearch] = useState("");

  // Release Detail Modal State
  const [selectedRelease, setSelectedRelease] = useState<ReleaseRequest | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const coverInputRef = useRef<HTMLInputElement>(null);
  const avatarInputRef = useRef<HTMLInputElement>(null);

  // Initialize view based on login state
  useEffect(() => {
      if (isArtistHubOpen) {
          if (currentArtist) {
              setView('ARTIST_DASH');
              setEditBio(currentArtist.bio || "");
              setEditAvatar(currentArtist.avatar || "");
              setEditNewPassword("");
          }
          else if (currentModerator) {
              setView('MOD_DASH');
              setModNewPassword("");
          }
          else setView('AUTH');
      }
  }, [isArtistHubOpen, currentArtist, currentModerator]);

  if (!isArtistHubOpen) return null;

  const handleLogin = (e: React.FormEvent) => {
      e.preventDefault();
      setMessage("");
      const res = loginArtistOrMod(username, password, role);
      if (res.success) {
          if (role === 'ARTIST') {
              setView('ARTIST_DASH');
          }
          else setView('MOD_DASH');
          showNotification(t('welcomeBack'), "success");
      } else {
          setMessage(res.message || t('invalidCreds'));
      }
  };

  const handleRegister = (e: React.FormEvent) => {
      e.preventDefault();

      if (role === 'MODERATOR') {
          if (hasModerator) {
              setMessage(t('modExists'));
              return;
          }
          const res = registerModerator({ username, password });
          if (res.success) {
              setMessage("Moderator registered! Please login.");
              setAuthMode('LOGIN');
          } else {
              setMessage(res.message || "Error registering moderator");
          }
          return;
      }

      // Artist Registration
      const finalArtistName = isCreatingNewArtist ? newArtistAlias : artistNameSelection;

      if (!finalArtistName) {
          setMessage(t('fillAll'));
          return;
      }

      const res = registerArtist({
          artistName: finalArtistName, 
          username, 
          password,
          artistPick: undefined
      });

      if (res.success) {
          setMessage(t('regSent'));
          setAuthMode('LOGIN');
      } else {
          setMessage(res.message || "Error registering");
      }
  };

  // --- Distribution Handlers ---
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          // Convert to Base64 for persistence
          const reader = new FileReader();
          reader.onloadend = () => {
              const base64Audio = reader.result as string;

              // Create temp audio element to get duration
              const audio = new Audio(base64Audio);
              audio.onloadedmetadata = () => {
                  const newTrack: DistributionTrack = {
                      title: file.name.replace(/\.[^/.]+$/, ""),
                      explicit: false,
                      mainArtists: [],
                      genre: distGenre, // Default to release genre
                      duration: audio.duration,
                      fileUrl: base64Audio
                  };
                  setDistTracks(prev => [...prev, newTrack]);
              };
          };
          reader.readAsDataURL(file);
      }
  };

  const updateTrack = (idx: number, field: keyof DistributionTrack, val: any) => {
      setDistTracks(prev => {
          const newTracks = [...prev];
          newTracks[idx] = { ...newTracks[idx], [field]: val };
          return newTracks;
      });
  };

  const moveTrack = (index: number, direction: 'up' | 'down') => {
      if (direction === 'up' && index > 0) {
          setDistTracks(prev => {
              const newTracks = [...prev];
              [newTracks[index], newTracks[index - 1]] = [newTracks[index - 1], newTracks[index]];
              return newTracks;
          });
      } else if (direction === 'down' && index < distTracks.length - 1) {
          setDistTracks(prev => {
              const newTracks = [...prev];
              [newTracks[index], newTracks[index + 1]] = [newTracks[index + 1], newTracks[index]];
              return newTracks;
          });
      }
  };

  // Track Artist Tag Handlers
  const addTrackArtist = (trackIdx: number) => {
      const name = trackArtistInputs[trackIdx];
      if (!name) return;

      setDistTracks(prev => {
          const newTracks = [...prev];
          const currentArtists = newTracks[trackIdx].mainArtists || [];
          newTracks[trackIdx] = { 
              ...newTracks[trackIdx], 
              mainArtists: [...currentArtists, name] 
          };
          return newTracks;
      });

      setTrackArtistInputs(prev => ({ ...prev, [trackIdx]: "" }));
  };

  const removeTrackArtist = (trackIdx: number, artistToRemove: string) => {
      setDistTracks(prev => {
          const newTracks = [...prev];
          const currentArtists = newTracks[trackIdx].mainArtists || [];
          newTracks[trackIdx] = { 
              ...newTracks[trackIdx], 
              mainArtists: currentArtists.filter(a => a !== artistToRemove) 
          };
          return newTracks;
      });
  };

  const handleHueqBlur = (idx: number, hueq: string) => {
      if (!hueq) return;
      const existing = getTrackByHueq(hueq);

      if (existing) {
          setDistTracks(prev => {
              const newTracks = [...prev];
              newTracks[idx] = {
                  ...newTracks[idx],
                  title: existing.title,
                  explicit: existing.explicit || false,
                  feat: existing.feat || "",
                  existingHueq: hueq,
                  fileUrl: existing.url,
                  duration: existing.duration,
                  genre: existing.genre, // Sync genre
                  mainArtists: existing.mainArtists || []
              };
              return newTracks;
          });
          showNotification(`HUEQ Found! Track details auto-filled: ${existing.title}`, "success");
      } else {
          updateTrack(idx, 'existingHueq', hueq);
      }
  };

  const handleNextStep = () => {
      if (distStep === 1) {
          if (!distTitle || !distType || !distGenre || distCovers.length === 0) {
              showNotification(t('completeFields'), "error");
              return;
          }
          if (currentModerator && !distArtistName) {
              showNotification(t('artistNameReq'), "error");
              return;
          }
      }
      if (distStep === 2) {
          if (distTracks.length === 0) {
              showNotification(t('addOneTrack'), "error");
              return;
          }
      }
      setDistStep(prev => prev + 1);
  };

  const handleSubmitRelease = () => {
      if (!distDate || !distTime) {
          showNotification(t('specifyDate'), "error");
          return;
      }

      const dateTime = new Date(`${distDate}T${distTime}:00+03:00`);

      // Determine Artist Identity
      const overrideArtist = currentModerator ? { 
          artistId: isEditing && editingId && !editingId.startsWith('a') ? (releaseRequests.find(r => r.id === editingId)?.artistId || `va_${Date.now()}`) : `va_${Date.now()}`,
          artistName: distArtistName || "Various Artists" 
      } : undefined;

      const payload = {
          title: distTitle,
          type: distType,
          genre: distGenre,
          label: distLabel || (currentArtist?.artistName || distArtistName || "Independent"),
          covers: distCovers, 
          additionalMainArtists: distMainArtists,
          tracks: distTracks,
          releaseDate: dateTime.toISOString(),
          releaseMessage: distMsg
      };

      if (isEditing && editingId) {
          updateReleaseRequest(editingId, {
              ...payload,
              // If mod is editing, allow updating artist name/id
              artistName: overrideArtist?.artistName || releaseRequests.find(r => r.id === editingId)?.artistName || ""
