import React, { useState, useRef, useEffect } from 'react';
import { useStore } from '../context/StoreContext';
import { 
    X, UploadCloud, ListMusic, Calendar, CheckCircle, XCircle, 
    MoreVertical, LogOut, ChevronRight, ArrowLeft, Plus, Trash2, 
    Shield, User, Lock, Search, FileAudio, Music2, Edit, Key
} from './Icons';
import { ReleaseRequest, Track, ArtistAccount, DistributionTrack } from '../types';

const formatDuration = (seconds: number) => {
  if (!seconds) return "0:00";
  const mins = Math.floor(seconds / 60);
  const secs = Math.floor(seconds % 60);
  return `${mins}:${secs.toString().padStart(2, '0')}`;
};

type HubView = 'AUTH' | 'ARTIST_DASH' | 'MOD_DASH';
type ArtistView = 'OVERVIEW' | 'UPLOAD' | 'RELEASES' | 'PROFILE' | 'SETTINGS';
type ModView = 'PENDING_ARTISTS' | 'PENDING_RELEASES' | 'PROFILE_EDITS' | 'MANAGE';

export const ArtistHub = () => {
    const { 
        isArtistHubOpen, setArtistHubOpen, currentArtist, currentModerator,
        loginArtistOrMod, registerArtist, registerModerator, logoutArtistHub,
        releaseRequests, submitRelease, updateReleaseRequest, deleteRelease,
        artistAccounts, approveArtist, rejectArtist,
        approveRelease, rejectRelease,
        profileEditRequests, approveProfileEdit, rejectProfileEdit,
        submitProfileEdit,
        hasModerator, existingArtists,
        changeArtistPassword, changeModeratorPassword,
        deleteArtistAccount, deleteLegacyTrack,
        t
    } = useStore();

    // Global State
    const [activeView, setActiveView] = useState<HubView>('AUTH');

    // Auth State
    const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
    const [authType, setAuthType] = useState<'ARTIST' | 'MODERATOR'>('ARTIST');
    const [username, setUsername] = useState("");
    const [password, setPassword] = useState("");
    const [artistName, setArtistName] = useState("");
    const [authError, setAuthError] = useState("");

    // Dash State
    const [dashView, setDashView] = useState<ArtistView>('OVERVIEW');
    const [modDashView, setModDashView] = useState<ModView>('PENDING_RELEASES');

    // Upload Form State
    const [uploadStep, setUploadStep] = useState(1);
    const [releaseTitle, setReleaseTitle] = useState("");
    const [releaseType, setReleaseType] = useState("Single");
    const [releaseGenre, setReleaseGenre] = useState("Pop");
    const [releaseLabel, setReleaseLabel] = useState("");
    const [releaseDate, setReleaseDate] = useState("");
    const [releaseTime, setReleaseTime] = useState("00:00");
    const [releaseCovers, setReleaseCovers] = useState<string[]>([]);
    const [releaseTracks, setReleaseTracks] = useState<Partial<DistributionTrack>[]>([]);
    const [releaseMainArtists, setReleaseMainArtists] = useState<string[]>([]); // Additional main artists

    // Mod Details View State
    const [selectedRelease, setSelectedRelease] = useState<ReleaseRequest | null>(null);

    // Profile Edit State
    const [newBio, setNewBio] = useState("");
    const [newAvatar, setNewAvatar] = useState("");

    // Refs
    const fileInputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        if (currentArtist) setActiveView('ARTIST_DASH');
        else if (currentModerator) setActiveView('MOD_DASH');
        else setActiveView('AUTH');
    }, [currentArtist, currentModerator, isArtistHubOpen]);

    if (!isArtistHubOpen) return null;

    // --- Actions ---

    const handleLogin = (e: React.FormEvent) => {
        e.preventDefault();
        setAuthError("");
        const res = loginArtistOrMod(username, password, authType);
        if (!res.success) setAuthError(res.message || t('invalidCreds'));
    };

    const handleRegister = (e: React.FormEvent) => {
        e.preventDefault();
        setAuthError("");
        if (authType === 'MODERATOR') {
            const res = registerModerator({ username, password });
            if (!res.success) setAuthError(res.message || "Error");
        } else {
            const res = registerArtist({ 
                username, password, artistName, 
                artistPick: undefined, bio: "", avatar: ""
            });
            if (res.success) {
                setAuthMode('LOGIN');
                setAuthError(t('regSent'));
            } else {
                setAuthError(res.message || "Error");
            }
        }
    };

    const handleUploadSubmit = () => {
        if (releaseTracks.length === 0) {
            alert(t('addOneTrack'));
            return;
        }
        if (!releaseDate || !releaseTime) {
            alert(t('specifyDate'));
            return;
        }

        const finalDate = new Date(`${releaseDate}T${releaseTime}:00`).toISOString();

        // Ensure tracks have required fields
        const validTracks = releaseTracks.map(t => ({
            title: t.title || "Untitled",
            explicit: t.explicit || false,
            duration: t.duration || 180,
            fileUrl: t.fileUrl || "https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3",
            genre: t.genre || releaseGenre,
            feat: t.feat,
            mainArtists: t.mainArtists || [],
            existingHueq: t.existingHueq,
            artist: t.artist // Track specific artist override
        }));

        submitRelease({
            title: releaseTitle,
            type: releaseType as any,
            genre: releaseGenre,
            label: releaseLabel || (currentArtist?.artistName + " Records"),
            covers: releaseCovers,
            tracks: validTracks as DistributionTrack[],
            releaseDate: finalDate,
            additionalMainArtists: releaseMainArtists.filter(a => a.trim() !== "")
        });

        alert(t('releaseSubmitted'));
        setDashView('RELEASES');
