                    <form onSubmit={authMode === 'LOGIN' ? handleLogin : handleRegister} className="flex flex-col gap-4">
                        {authError && <div className="bg-red-500/20 text-red-500 p-3 rounded text-sm text-center">{authError}</div>}

                        {authMode === 'REGISTER' && authType === 'ARTIST' && (
                             <input 
                                type="text" 
                                placeholder={t('artist') + " Name"}
                                className="p-3 rounded bg-surface-highlight text-white border border-transparent focus:border-primary focus:outline-none"
                                value={artistName}
                                onChange={e => setArtistName(e.target.value)}
                             />
                        )}

                        <input 
                            type="text" 
                            placeholder={t('username')}
                            className="p-3 rounded bg-surface-highlight text-white border border-transparent focus:border-primary focus:outline-none"
