                            value={password}
                            onChange={e => setPassword(e.target.value)}
                        />

                        <button type="submit" className="w-full py-3 bg-white text-black font-bold rounded hover:bg-gray-200 transition">
                            {authMode === 'LOGIN' ? t('login') : t('signup')}
