                                     <label className="text-sm font-bold text-secondary">{t('bio')}</label>
                                     <textarea className="w-full p-3 bg-surface-highlight rounded text-white h-32 resize-none" value={newBio} onChange={e => setNewBio(e.target.value)} placeholder="Tell your fans about yourself..." />
                                 </div>
                                 <button onClick={handleProfileEditSubmit} className="w-full py-3 bg-white text-black font-bold rounded mt-2">{t('submitChanges')}</button>
                             </div>
                         </div>
                     )}
                </div>
            </div>
        );
    }

    // --- MODERATOR DASHBOARD ---
    if (activeView === 'MOD_DASH' && currentModerator) {
        return (
            <div className="fixed inset-0 bg-background z-[200] flex text-white overflow-hidden">
                {/* Sidebar */}
                <div className="w-64 bg-zinc-900 border-r border-surface-highlight flex flex-col hidden md:flex">
                    <div className="p-6">
                         <h1 className="text-xl font-bold flex items-center gap-2 text-red-500">
                             <Shield className="text-red-500"/> {t('modDash')}
                         </h1>
                         <p className="text-xs text-secondary mt-1">Logged in as {currentModerator.username}</p>
                    </div>
                    <nav className="flex-1 px-4 flex flex-col gap-1">
                        <button onClick={() => setModDashView('PENDING_RELEASES')} className={`p-3 text-left rounded font-medium flex items-center gap-3 ${modDashView === 'PENDING_RELEASES' ? 'bg-surface-highlight text-white' : 'text-secondary hover:text-white'}`}>
                             <Music2 size={18} /> {t('pendingReleases')}
                             {releaseRequests.filter(r => r.status === 'PENDING').length > 0 && <span className="bg-primary text-black text-xs px-1.5 rounded-full">{releaseRequests.filter(r => r.status === 'PENDING').length}</span>}
                        </button>
                        <button onClick={() => setModDashView('PENDING_ARTISTS')} className={`p-3 text-left rounded font-medium flex items-center gap-3 ${modDashView === 'PENDING_ARTISTS' ? 'bg-surface-highlight text-white' : 'text-secondary hover:text-white'}`}>
                             <User size={18} /> {t('pendingArtists')}
                             {artistAccounts.filter(a => a.status === 'PENDING').length > 0 && <span className="bg-primary text-black text-xs px-1.5 rounded-full">{artistAccounts.filter(a => a.status === 'PENDING').length}</span>}
                        </button>
                        <button onClick={() => setModDashView('PROFILE_EDITS')} className={`p-3 text-left rounded font-medium flex items-center gap-3 ${modDashView === 'PROFILE_EDITS' ? 'bg-surface-highlight text-white' : 'text-secondary hover:text-white'}`}>
                             <Edit size={18} /> {t('profileEdits')}
                             {profileEditRequests.filter(r => r.status === 'PENDING').length > 0 && <span className="bg-primary text-black text-xs px-1.5 rounded-full">{profileEditRequests.filter(r => r.status === 'PENDING').length}</span>}
                        </button>
                        <button onClick={() => setModDashView('MANAGE')} className={`p-3 text-left rounded font-medium flex items-center gap-3 ${modDashView === 'MANAGE' ? 'bg-surface-highlight text-white' : 'text-secondary hover:text-white'}`}>
                             <Search size={18} /> Manage Content
