                    </nav>
                    <div className="p-4 border-t border-surface-highlight">
                         <button onClick={() => setArtistHubOpen(false)} className="w-full py-2 bg-surface-highlight rounded mb-2 font-bold text-sm">{t('returnHome')}</button>
                         <button onClick={logoutArtistHub} className="w-full py-2 text-red-500 text-sm font-bold flex items-center justify-center gap-2"><LogOut size={16}/> {t('logout')}</button>
                    </div>
                </div>

                {/* Main Content */}
                <div className="flex-1 overflow-y-auto p-4 md:p-8 relative">
                    <button onClick={() => setArtistHubOpen(false)} className="absolute top-4 right-4 md:hidden text-white"><X size={24}/></button>

                    {/* Pending Releases View */}
                    {modDashView === 'PENDING_RELEASES' && (
                        <div className="max-w-5xl mx-auto">
                            <h2 className="text-3xl font-bold mb-6">{t('pendingReleases')}</h2>
                            <div className="grid gap-4">
                                {releaseRequests.filter(r => (r.status === 'PENDING' || r.deletionRequested)).map(req => (
                                    <div key={req.id} className="bg-surface p-4 rounded-lg flex items-center gap-4 border border-surface-highlight">
                                        <img src={req.covers[0]} className="w-20 h-20 rounded object-cover bg-surface-highlight" />
                                        <div className="flex-1">
                                            <div className="flex items-center gap-2">
                                                <h3 className="font-bold text-xl">{req.title}</h3>
                                                {req.deletionRequested && <span className="bg-red-500 text-white text-xs px-2 py-0.5 rounded font-bold">{t('deleteReq')}</span>}
                                            </div>
                                            <p className="text-secondary">{req.artistName} • {req.type} • {req.genre}</p>
                                            <p className="text-xs text-secondary mt-1">{t('releaseDate')}: {new Date(req.releaseDate).toLocaleString()}</p>
                                        </div>
                                        <div className="flex gap-2">
                                            <button onClick={() => setSelectedRelease(req)} className="px-4 py-2 bg-surface-highlight rounded font-bold text-sm">Review</button>
                                            {req.deletionRequested ? (
                                                <>
                                                    <button onClick={() => approveRelease(req.id)} className="px-4 py-2 bg-red-600 text-white rounded font-bold text-sm">{t('confirmDelete')}</button>
                                                    <button onClick={() => rejectRelease(req.id)} className="px-4 py-2 bg-surface-highlight text-white rounded font-bold text-sm">{t('rejectDel')}</button>
                                                </>
                                            ) : (
                                                <>
                                                    <button onClick={() => approveRelease(req.id)} className="px-4 py-2 bg-green-600 text-white rounded font-bold text-sm">{t('approve')}</button>
                                                    <button onClick={() => rejectRelease(req.id)} className="px-4 py-2 bg-red-600 text-white rounded font-bold text-sm">{t('reject')}</button>
                                                </>
                                            )}
                                        </div>
                                    </div>
                                ))}
                                {releaseRequests.filter(r => r.status === 'PENDING' || r.deletionRequested).length === 0 && (
                                    <div className="text-center text-secondary py-10">{t('noPending')}</div>
                                )}
                            </div>
                        </div>
                    )}

                    {/* Pending Artists View */}
                    {modDashView === 'PENDING_ARTISTS' && (
                        <div className="max-w-4xl mx-auto">
                            <h2 className="text-3xl font-bold mb-6">{t('pendingArtists')}</h2>
                            <div className="grid gap-4">
                                {artistAccounts.filter(a => a.status === 'PENDING').map(artist => (
                                    <div key={artist.id} className="bg-surface p-4 rounded-lg flex items-center justify-between">
                                        <div>
                                            <h3 className="font-bold text-lg">{artist.artistName}</h3>
                                            <p className="text-sm text-secondary">@{artist.username}</p>
                                        </div>
                                        <div className="flex gap-2">
                                            <button onClick={() => approveArtist(artist.id)} className="px-4 py-2 bg-green-600 text-white rounded font-bold text-sm">{t('approve')}</button>
                                            <button onClick={() => rejectArtist(artist.id)} className="px-4 py-2 bg-red-600 text-white rounded font-bold text-sm">{t('reject')}</button>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* Profile Edits View */}
                    {modDashView === 'PROFILE_EDITS' && (
                        <div className="max-w-4xl mx-auto">
                            <h2 className="text-3xl font-bold mb-6">{t('profileEdits')}</h2>
                            <div className="grid gap-4">
                                {profileEditRequests.filter(r => r.status === 'PENDING').map(req => (
                                    <div key={req.id} className="bg-surface p-4 rounded-lg">
                                        <div className="flex justify-between items-start mb-4">
                                            <div>
                                                <h3 className="font-bold text-lg">{req.artistName}</h3>
                                                <p className="text-xs text-secondary">Request ID: {req.id}</p>
                                            </div>
                                            <div className="flex gap-2">
                                                <button onClick={() => approveProfileEdit(req.id)} className="px-4 py-2 bg-green-600 text-white rounded font-bold text-sm">{t('approve')}</button>
                                                <button onClick={() => rejectProfileEdit(req.id)} className="px-4 py-2 bg-red-600 text-white rounded font-bold text-sm">{t('reject')}</button>
                                            </div>
                                        </div>
                                        <div className="grid grid-cols-2 gap-4 text-sm">
                                            {req.newBio && (
                                                <div className="bg-surface-highlight p-3 rounded">
                                                    <span className="font-bold text-secondary block mb-1">New Bio:</span>
                                                    <p>{req.newBio}</p>
                                                </div>
                                            )}
                                            {req.newAvatar && (
                                                <div className="bg-surface-highlight p-3 rounded">
                                                    <span className="font-bold text-secondary block mb-1">New Avatar:</span>
                                                    <img src={req.newAvatar} className="w-20 h-20 rounded object-cover" />
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* Manage View */}
                    {modDashView === 'MANAGE' && (
                        <div className="max-w-4xl mx-auto">
                            <h2 className="text-3xl font-bold mb-6">Manage Content</h2>
                            {/* Simple Delete Functionality for now */}
                            <div className="bg-surface p-6 rounded-lg mb-6">
                                <h3 className="font-bold mb-4">Delete Legacy Test Track</h3>
                                <div className="flex gap-2">
                                    <input type="text" placeholder="Track ID (e.g. t1, t5)" className="p-2 rounded bg-surface-highlight text-white border-none focus:ring-1 focus:ring-primary" id="delTrackInput" />
                                    <button 
                                        onClick={() => {
                                            const el = document.getElementById('delTrackInput') as HTMLInputElement;
                                            if(el.value) { deleteLegacyTrack(el.value); el.value = ''; }
                                        }}
                                        className="px-4 py-2 bg-red-600 text-white rounded font-bold"
                                    >
                                        Delete
                                    </button>
                                </div>
                            </div>

                            <div className="bg-surface p-6 rounded-lg">
                                <h3 className="font-bold mb-4">Delete Artist Account</h3>
                                <div className="flex flex-col gap-2">
                                    {artistAccounts.map(acc => (
                                        <div key={acc.id} className="flex justify-between items-center p-2 bg-surface-highlight rounded">
                                            <span>{acc.artistName} (@{acc.username})</span>
                                            <button onClick={() => { if(confirm("Delete this artist account?")) deleteArtistAccount(acc.id); }} className="text-red-500 hover:text-red-400"><Trash2 size={18}/></button>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        </div>
                    )}
                </div>

                {/* Release Detail Modal (Review) */}
                {selectedRelease && (
                    <div className="fixed inset-0 bg-black/90 z-[250] flex items-center justify-center p-4">
                        <div className="bg-surface w-full max-w-4xl max-h-[90vh] overflow-y-auto rounded-xl p-6 relative border border-surface-highlight">
                            <button onClick={() => setSelectedRelease(null)} className="absolute top-4 right-4 text-white"><X size={24}/></button>
                            <h2 className="text-2xl font-bold mb-2">{selectedRelease.title}</h2>
                            <p className="text-secondary mb-6">{selectedRelease.artistName} • {selectedRelease.type} • {selectedRelease.label}</p>

                            <div className="flex flex-col gap-2">
                                {selectedRelease.tracks.map((track, idx) => (
                                    <div key={idx} className="flex justify-between items-center p-2 hover:bg-surface-highlight rounded">
                                        <div className="flex items-center gap-3">
                                            <span className="text-secondary text-sm w-6">{idx + 1}</span>
                                            <div className="flex flex-col">
                                                <span className="font-bold text-sm">{track.title}</span>
                                                <span className="text-xs text-secondary flex flex-wrap items-center gap-1">
                                                    <span>{track.artist || selectedRelease.artistName} {track.explicit ? `(${t('explicitShort')})` : ''}</span>
                                                </span>
                                            </div>
                                        </div>
                                        <div className="flex items-center gap-4">
                                            {(track.generatedHueq || track.existingHueq || (track as any).hueq) && (
                                                <span className="font-mono text-[10px] text-secondary/70 border border-secondary/30 px-2 py-0.5 rounded select-all hover:text-white hover:border-white transition-colors cursor-text" title="HUEQ / ISRC">
                                                    {track.generatedHueq || track.existingHueq || (track as any).hueq}
                                                </span>
                                            )}
                                            <span className="text-xs text-secondary w-10 text-right font-mono">{formatDuration(track.duration)}</span>
                                        </div>
                                    </div>
                                ))}
                            </div>

                            <div className="mt-6 flex justify-end gap-3">
                                <button onClick={() => setSelectedRelease(null)} className="px-6 py-2 bg-surface-highlight text-white rounded font-bold">Close</button>
                            </div>
                        </div>
                    </div>
                )}
            </div>
        );
    }

    return null;
};

import React, { useState, useRef, useEffect } from 'react';
import { useStore } from '../context/StoreContext.tsx';
import { 
  X, Mic2, Shield, User, UploadCloud, Calendar, FileAudio, 
  CheckCircle, XCircle, Clock, MoreVertical, Image, Plus,
  Edit, ArrowLeft, Camera, LogOut, ChevronDown, Trash2, ListMusic, Check, Search, Play, BarChart2, Globe, Database, Key, Settings, ChevronUp
} from './Icons.tsx';
import { DistributionTrack, ReleaseType, ReleaseRequest } from '../types.ts';

type HubView = 'AUTH' | 'ARTIST_DASH' | 'MOD_DASH' | 'DISTRIBUTION' | 'PROFILE_EDIT' | 'ARTIST_PICK' | 'MOD_CREDENTIALS' | 'MOD_ALL_RELEASES' | 'MOD_SETTINGS' | 'MOD_ALL_TRACKS';

const formatDuration = (seconds: number) => {
    const min = Math.floor(seconds / 60);
    const sec = Math.floor(seconds % 60);
    return `${min}:${sec.toString().padStart(2, '0')}`;
};

export const ArtistHub = () => {
  const { 
    isArtistHubOpen, setArtistHubOpen, currentArtist, currentModerator, 
    loginArtistOrMod, registerArtist, registerModerator, logoutArtistHub, artistAccounts,
    releaseRequests, profileEditRequests, approveArtist, rejectArtist,
    approveRelease, rejectRelease, approveProfileEdit, rejectProfileEdit,
    submitRelease, updateReleaseRequest, getArtistStats, submitProfileEdit, hasModerator, existingArtists,
    deleteRelease, getTrackByHueq, tracks, albums, playlists, showNotification, deleteArtistAccount, getTrackCover, getAlbumCover,
    changeArtistPassword, changeModeratorPassword, deleteLegacyTrack, t
  } = useStore();

  const [view, setView] = useState<HubView>('AUTH');

  // Auth State
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [role, setRole] = useState<'ARTIST' | 'MODERATOR'>('ARTIST');
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");

  // Artist Registration Logic
  const [artistNameSelection, setArtistNameSelection] = useState("");
  const [isCreatingNewArtist, setIsCreatingNewArtist] = useState(false);
  const [newArtistAlias, setNewArtistAlias] = useState("");

  const [message, setMessage] = useState("");

  // Distribution State
  const [distStep, setDistStep] = useState(1);
  const [distTitle, setDistTitle] = useState("");
  const [distArtistName, setDistArtistName] = useState(""); // For Mods to override
  const [distType, setDistType] = useState<ReleaseType>('Single');
  const [distGenre, setDistGenre] = useState("Pop");
  const [distLabel, setDistLabel] = useState("");
  const [distCovers, setDistCovers] = useState<string[]>([]);
  const [distMainArtists, setDistMainArtists] = useState<string[]>([]);
  const [distMainArtistInput, setDistMainArtistInput] = useState("");
  const [distTracks, setDistTracks] = useState<DistributionTrack[]>([]);

  // Editing Mode
  const [isEditing, setIsEditing] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  // Track Tag Inputs (Step 2)
  const [trackArtistInputs, setTrackArtistInputs] = useState<Record<number, string>>({});

  const [distDate, setDistDate] = useState("");
  const [distTime, setDistTime] = useState("00:00");
  const [distMsg, setDistMsg] = useState("");

  // Edit Profile State
  const [editBio, setEditBio] = useState("");
  const [editAvatar, setEditAvatar] = useState("");
  const [editNewPassword, setEditNewPassword] = useState("");

  // Mod Settings State
  const [modNewPassword, setModNewPassword] = useState("");

  // Artist Pick State
  const [pickSearch, setPickSearch] = useState("");

  // Release Detail Modal State
  const [selectedRelease, setSelectedRelease] = useState<ReleaseRequest | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const coverInputRef = useRef<HTMLInputElement>(null);
  const avatarInputRef = useRef<HTMLInputElement>(null);

  // Initialize view based on login state
  useEffect(() => {
      if (isArtistHubOpen) {
          if (currentArtist) {
              setView('ARTIST_DASH');
              setEditBio(currentArtist.bio || "");
              setEditAvatar(currentArtist.avatar || "");
              setEditNewPassword("");
          }
          else if (currentModerator) {
              setView('MOD_DASH');
              setModNewPassword("");
          }
          else setView('AUTH');
      }
  }, [isArtistHubOpen, currentArtist, currentModerator]);

  if (!isArtistHubOpen) return null;

  const handleLogin = (e: React.FormEvent) => {
      e.preventDefault();
      setMessage("");
      const res = loginArtistOrMod(username, password, role);
      if (res.success) {
          if (role === 'ARTIST') {
              setView('ARTIST_DASH');
          }
          else setView('MOD_DASH');
          showNotification(t('welcomeBack'), "success");
      } else {
          setMessage(res.message || t('invalidCreds'));
      }
  };

  const handleRegister = (e: React.FormEvent) => {
      e.preventDefault();

      if (role === 'MODERATOR') {
          if (hasModerator) {
              setMessage(t('modExists'));
              return;
          }
          const res = registerModerator({ username, password });
          if (res.success) {
              setMessage("Moderator registered! Please login.");
              setAuthMode('LOGIN');
          } else {
              setMessage(res.message || "Error registering moderator");
          }
          return;
      }

      // Artist Registration
      const finalArtistName = isCreatingNewArtist ? newArtistAlias : artistNameSelection;

      if (!finalArtistName) {
          setMessage(t('fillAll'));
          return;
      }

      const res = registerArtist({
          artistName: finalArtistName, 
          username, 
          password,
          artistPick: undefined
      });

      if (res.success) {
          setMessage(t('regSent'));
          setAuthMode('LOGIN');
      } else {
          setMessage(res.message || "Error registering");
      }
  };

  // --- Distribution Handlers ---
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          // Convert to Base64 for persistence
          const reader = new FileReader();
          reader.onloadend = () => {
              const base64Audio = reader.result as string;

              // Create temp audio element to get duration
              const audio = new Audio(base64Audio);
              audio.onloadedmetadata = () => {
                  const newTrack: DistributionTrack = {
                      title: file.name.replace(/\.[^/.]+$/, ""),
                      explicit: false,
                      mainArtists: [],
                      genre: distGenre, // Default to release genre
                      duration: audio.duration,
                      fileUrl: base64Audio
                  };
                  setDistTracks(prev => [...prev, newTrack]);
              };
          };
          reader.readAsDataURL(file);
      }
  };

  const updateTrack = (idx: number, field: keyof DistributionTrack, val: any) => {
      setDistTracks(prev => {
          const newTracks = [...prev];
          newTracks[idx] = { ...newTracks[idx], [field]: val };
          return newTracks;
      });
  };

  const moveTrack = (index: number, direction: 'up' | 'down') => {
      if (direction === 'up' && index > 0) {
          setDistTracks(prev => {
              const newTracks = [...prev];
              [newTracks[index], newTracks[index - 1]] = [newTracks[index - 1], newTracks[index]];
              return newTracks;
          });
      } else if (direction === 'down' && index < distTracks.length - 1) {
          setDistTracks(prev => {
              const newTracks = [...prev];
              [newTracks[index], newTracks[index + 1]] = [newTracks[index + 1], newTracks[index]];
              return newTracks;
          });
      }
  };

  // Track Artist Tag Handlers
  const addTrackArtist = (trackIdx: number) => {
      const name = trackArtistInputs[trackIdx];
      if (!name) return;

      setDistTracks(prev => {
          const newTracks = [...prev];
          const currentArtists = newTracks[trackIdx].mainArtists || [];
          newTracks[trackIdx] = { 
              ...newTracks[trackIdx], 
              mainArtists: [...currentArtists, name] 
          };
          return newTracks;
      });

      setTrackArtistInputs(prev => ({ ...prev, [trackIdx]: "" }));
  };

  const removeTrackArtist = (trackIdx: number, artistToRemove: string) => {
      setDistTracks(prev => {
          const newTracks = [...prev];
          const currentArtists = newTracks[trackIdx].mainArtists || [];
          newTracks[trackIdx] = { 
              ...newTracks[trackIdx], 
              mainArtists: currentArtists.filter(a => a !== artistToRemove) 
          };
          return newTracks;
      });
  };

  const handleHueqBlur = (idx: number, hueq: string) => {
      if (!hueq) return;
      const existing = getTrackByHueq(hueq);

      if (existing) {
          setDistTracks(prev => {
              const newTracks = [...prev];
              newTracks[idx] = {
                  ...newTracks[idx],
                  title: existing.title,
                  explicit: existing.explicit || false,
                  feat: existing.feat || "",
                  existingHueq: hueq,
                  fileUrl: existing.url,
                  duration: existing.duration,
                  genre: existing.genre, // Sync genre
                  mainArtists: existing.mainArtists || []
              };
              return newTracks;
          });
          showNotification(`HUEQ Found! Track details auto-filled: ${existing.title}`, "success");
      } else {
          updateTrack(idx, 'existingHueq', hueq);
      }
  };

  const handleNextStep = () => {
      if (distStep === 1) {
          if (!distTitle || !distType || !distGenre || distCovers.length === 0) {
              showNotification(t('completeFields'), "error");
              return;
          }
          if (currentModerator && !distArtistName) {
              showNotification(t('artistNameReq'), "error");
              return;
          }
      }
      if (distStep === 2) {
          if (distTracks.length === 0) {
              showNotification(t('addOneTrack'), "error");
              return;
          }
      }
      setDistStep(prev => prev + 1);
  };

  const handleSubmitRelease = () => {
      if (!distDate || !distTime) {
          showNotification(t('specifyDate'), "error");
          return;
      }

      const dateTime = new Date(`${distDate}T${distTime}:00+03:00`);

      // Determine Artist Identity
      const overrideArtist = currentModerator ? { 
          artistId: isEditing && editingId && !editingId.startsWith('a') ? (releaseRequests.find(r => r.id === editingId)?.artistId || `va_${Date.now()}`) : `va_${Date.now()}`,
          artistName: distArtistName || "Various Artists" 
      } : undefined;

      const payload = {
          title: distTitle,
          type: distType,
          genre: distGenre,
          label: distLabel || (currentArtist?.artistName || distArtistName || "Independent"),
          covers: distCovers, 
          additionalMainArtists: distMainArtists,
          tracks: distTracks,
          releaseDate: dateTime.toISOString(),
          releaseMessage: distMsg
      };

      if (isEditing && editingId) {
          updateReleaseRequest(editingId, {
              ...payload,
              // If mod is editing, allow updating artist name/id
              artistName: overrideArtist?.artistName || releaseRequests.find(r => r.id === editingId)?.artistName || ""
          });
          showNotification(t('releaseUpdated'), "success");
      } else {
          submitRelease(payload, overrideArtist);
          showNotification(t('releaseSubmitted'), "success");
      }

      // Navigate back
      if (currentModerator) {
