      setHistory(h => h.slice(0, -1));
      setViewInternal(prev);
    } else {
      setViewInternal({ type: 'HOME' });
    }
  };

  const getArtistStats = (artistName: string): ArtistStats => {
    const artistPlayMap: Record<string, number> = {};
    tracks.forEach(t => { 
        const primary = t.artist;
        if (primary) artistPlayMap[primary] = (artistPlayMap[primary] || 0) + t.plays;

        if (t.mainArtists) {
            t.mainArtists.forEach(ma => {
                artistPlayMap[ma] = (artistPlayMap[ma] || 0) + t.plays;
            });
        }
    });

    const sortedArtists = Object.entries(artistPlayMap).sort(([, a], [, b]) => b - a);
    const rankIndex = sortedArtists.findIndex(([name]) => name === artistName);
    const totalPlays = artistPlayMap[artistName] || 0;

    return { monthlyPlays: totalPlays, globalRank: rankIndex === -1 ? 999 : rankIndex + 1 };
  };

  const toggleFollowArtist = (artistName: string) => {
    setFollowedArtists(prev => prev.includes(artistName) ? prev.filter(a => a !== artistName) : [...prev, artistName]);
  };
  const isArtistFollowed = (artistName: string) => followedArtists.includes(artistName);

  // --- Player Logic ---
  useEffect(() => {
    cumulativeTimeRef.current = 0;
    lastTimeRef.current = 0;
    setHasCountedListen(false);
  }, [currentTrack]);

  useEffect(() => {
    const audio = audioRef.current;
    const handleTimeUpdate = () => {
      const now = audio.currentTime;
      setProgress(now);
      const diff = now - lastTimeRef.current;

      // Accumulate listen time if playing normally (not scrubbing fast)
      if (diff > 0 && diff < 1.5) {
          cumulativeTimeRef.current += diff;
      }
      lastTimeRef.current = now;

      // Count play ONLY if active listen > 30s AND hasn't counted for this specific track instance yet
      if (cumulativeTimeRef.current > 30 && !hasCountedListen && currentTrack) {
          handleListenCount(currentTrack);
      }
    };
    const handleEnded = () => {
      if (playMode === PlayMode.ONE) { 
          audio.currentTime = 0; 
          // Logic: If user repeats ONE, it counts as a new listen for the next loop
          cumulativeTimeRef.current = 0; 
          setHasCountedListen(false);
          audio.play(); 
      }
      else if (appSettings.autoPlay) { nextTrack(); } 
      else { setIsPlaying(false); audioRef.current.pause(); }
    };
    const handleLoadedMetadata = () => setDuration(audio.duration);
    audio.addEventListener('timeupdate', handleTimeUpdate);
    audio.addEventListener('ended', handleEnded);
    audio.addEventListener('loadedmetadata', handleLoadedMetadata);
    return () => {
      audio.removeEventListener('timeupdate', handleTimeUpdate);
      audio.removeEventListener('ended', handleEnded);
      audio.removeEventListener('loadedmetadata', handleLoadedMetadata);
    };
  }, [currentTrack, hasCountedListen, playMode, tracks, isShuffle, appSettings.autoPlay]);

  const handleListenCount = (track: Track) => {
    const addedPlays = Math.floor(100 + Math.random() * 9900); 
    setTracks(prev => {
        const updated = prev.map(t => t.id === track.id ? { ...t, plays: t.plays + addedPlays } : t);
        const playCounts = updated.reduce((acc, t) => ({ ...acc, [t.id]: t.plays }), {});
        StorageService.save('huevify_plays', playCounts);
        notifySync('TRACKS_UPDATE');
        return updated;
    });
    setHasCountedListen(true);
  };

  const playTrack = (track: Track) => {
    if (!track) return;
    // 1. Check if track is Explicit and allowed
    if (track.explicit && !appSettings.allowExplicitContent) {
        showNotification(t('allowExplicit'), "error");
        return;
    }

    // 2. Check if track is actually live (Deleted tracks check)
    const isLive = tracks.find(t => t.id === track.id);
    if (!isLive) {
        showNotification("This track is no longer available.", "error");
        return;
    }

    // Save to User Specific Recent
    if (currentUser) {
        setRecentlyPlayed(prev => {
            const filtered = prev.filter(t => t.id !== track.id);
            const newHistory = [track, ...filtered].slice(0, 10);
            StorageService.save(`huevify_recent_${currentUser.id}`, newHistory);
            return newHistory;
        });
    }

    if (currentTrack?.id === track.id) { togglePlay(); return; }

    // New Track Logic
    setCurrentTrack(track);
    setHasCountedListen(false); // Reset listen count for new track
    cumulativeTimeRef.current = 0; // Reset time accumulator

    audioRef.current.src = track.url;
    audioRef.current.play().then(() => setIsPlaying(true)).catch(e => console.error("Audio play failed", e));
  };

  const togglePlay = () => {
    if (audioRef.current.paused) { audioRef.current.play(); setIsPlaying(true); }
    else { audioRef.current.pause(); setIsPlaying(false); }
  };
  const setVolume = (vol: number) => { setVolumeState(vol); audioRef.current.volume = vol; };
  const seek = (time: number) => { audioRef.current.currentTime = time; lastTimeRef.current = time; setProgress(time); };

  const getQueue = (): Track[] => {
    if (view.type === 'PLAYLIST' && (view as any).id === 'history') {
        if (!appSettings.allowExplicitContent) {
            return recentlyPlayed.filter(t => !t.explicit);
        }
        return recentlyPlayed;
    }
    if (!appSettings.allowExplicitContent) {
        return tracks.filter(t => !t.explicit);
    }
    return tracks; 
  };
  const nextTrack = () => {
    const queue = getQueue();
    if (isShuffle) { playTrack(queue[Math.floor(Math.random() * queue.length)]); return; }
    const idx = queue.findIndex(t => t.id === currentTrack?.id);
    if (idx !== -1 && idx < queue.length - 1) playTrack(queue[idx + 1]);
    else if (playMode === PlayMode.CONTEXT) playTrack(queue[0]);
    else { setIsPlaying(false); audioRef.current.pause(); audioRef.current.currentTime = 0; }
  };
  const prevTrack = () => {
    if (audioRef.current.currentTime > 3) { audioRef.current.currentTime = 0; lastTimeRef.current = 0; return; }
    const queue = getQueue();
    const idx = queue.findIndex(t => t.id === currentTrack?.id);
    if (idx > 0) playTrack(queue[idx - 1]); else playTrack(queue[queue.length - 1]);
  };
  const toggleRepeat = () => {
    if (playMode === PlayMode.OFF) setPlayMode(PlayMode.CONTEXT);
    else if (playMode === PlayMode.CONTEXT) setPlayMode(PlayMode.ONE);
    else setPlayMode(PlayMode.OFF);
  };
  const toggleShuffle = () => setIsShuffle(!isShuffle);

  const syncPlaylists = (newGlobalPlaylists: Playlist[]) => {
      StorageService.save('huevify_playlists', newGlobalPlaylists);
      setPlaylists(newGlobalPlaylists);
      notifySync('PLAYLISTS_UPDATE');
  };
  const createPlaylist = (name: string, description?: string, cover?: string, isPublic: boolean = false) => {
    if (!currentUser) return;
    const newPl: Playlist = { id: `pl_${Date.now()}`, name, description: description || "", customCover: cover, tracks: [], ownerId: currentUser.id, creatorName: currentUser.displayName, creatorAvatar: currentUser.avatar, isPublic: isPublic, savedBy: [] };
    const all = [...playlists]; 
    syncPlaylists([...all, newPl]);
  };
  const editPlaylist = (id: string, name: string, description?: string, cover?: string, isPublic?: boolean) => {
    const all = [...playlists];
    const updated = all.map(p => { if (p.id === id) { return { ...p, name, description, customCover: cover, isPublic: isPublic !== undefined ? isPublic : p.isPublic }; } return p; });
    syncPlaylists(updated);
  };
  const openDeleteModal = (id: string) => { setPlaylistToDelete(id); setIsDeleteModalOpen(true); };
  const closeDeleteModal = () => { setIsDeleteModalOpen(false); setPlaylistToDelete(null); };
  const confirmDeletePlaylist = () => { if (!playlistToDelete) return; const id = playlistToDelete; if (view.type === 'PLAYLIST' && (view as any).id === id) setViewInternal({ type: 'LIBRARY' }); const all = [...playlists]; const updated = all.filter(p => p.id !== id); syncPlaylists(updated); closeDeleteModal(); };
  const deletePlaylist = (id: string) => openDeleteModal(id);
  const addToPlaylist = (playlistId: string, trackId: string) => { 
      const updated = playlists.map(p => { 
          if (p.id === playlistId && !p.tracks.includes(trackId)) {
              return { ...p, tracks: [...p.tracks, trackId] }; 
          }
          return p; 
      }); 
      syncPlaylists(updated); 
  };
  const removeFromPlaylist = (playlistId: string, trackId: string) => { 
      const updated = playlists.map(p => { 
          if (p.id === playlistId) {
              return { ...p, tracks: p.tracks.filter(id => id !== trackId) }; 
          }
          return p; 
      }); 
      syncPlaylists(updated); 
  };
  const togglePlaylistSave = (playlistId: string) => { if (!currentUser) return; const updated = playlists.map(p => { if (p.id === playlistId) { const saved = p.savedBy || []; const isSaved = saved.includes(currentUser.id); return { ...p, savedBy: isSaved ? saved.filter(id => id !== currentUser.id) : [...saved, currentUser.id] }; } return p; }); syncPlaylists(updated); };

  // Account Isolated Likes
  const toggleLike = (trackId: string) => { 
      if (!currentUser) return;
      const likedId = `liked_${currentUser.id}`;
      const likedPl = playlists.find(p => p.id === likedId); 
      if (!likedPl) return; 
      if (likedPl.tracks.includes(trackId)) removeFromPlaylist(likedId, trackId); 
      else addToPlaylist(likedId, trackId); 
  };
  const isLiked = (trackId: string) => { 
      if (!currentUser) return false;
      const likedId = `liked_${currentUser.id}`;
      const likedPl = playlists.find(p => p.id === likedId); 
      return likedPl ? likedPl.tracks.includes(trackId) : false; 
  };

  const toggleAlbumLike = (albumId: string) => { setLikedAlbumIds(prev => prev.includes(albumId) ? prev.filter(id => id !== albumId) : [...prev, albumId]); };
  const isAlbumLiked = (albumId: string) => likedAlbumIds.includes(albumId);
  const openAddToPlaylist = (trackId: string) => { setTrackIdToAdd(trackId); setAddToPlaylistOpen(true); };
  const closeAddToPlaylist = () => { setAddToPlaylistOpen(false); setTrackIdToAdd(null); };

  if (!isInitialized && currentUser) {
      return (
          <div className="flex h-screen w-full bg-black items-center justify-center flex-col gap-4">
              <div className="w-20 h-20 rounded-full bg-surface-highlight flex items-center justify-center animate-pulse">
                  <span className="text-4xl font-bold text-primary">H</span>
              </div>
              <div className="text-secondary text-sm animate-pulse">Loading Library...</div>
          </div>
      );
  }

  return (
    <StoreContext.Provider value={{
      t,
      currentUser, login, register, logout, updateUserProfile,
      appSettings, updateSettings, dailyChart,
      getAlbumCover, changeAlbumCover, getTrackCover,
      isArtistHubOpen, setArtistHubOpen, currentArtist, currentModerator, artistAccounts,
      registerArtist, registerModerator, loginArtistOrMod, logoutArtistHub, submitRelease, submitProfileEdit, deleteRelease, deleteLegacyTrack, updateReleaseRequest, deleteArtistAccount, changeArtistPassword, changeModeratorPassword,
      approveArtist, rejectArtist, approveRelease, rejectRelease, approveProfileEdit, rejectProfileEdit,
      releaseRequests, profileEditRequests, hasModerator, existingArtists, getTrackByHueq,
      tracks, albums, playlists, recommendations, recentlyPlayed, followedArtists, currentTrack, isPlaying, playMode, isShuffle, volume, progress, duration, view,
      isCreatePlaylistOpen, setCreatePlaylistOpen, playlistIdToEdit, setPlaylistIdToEdit,
      isMobilePlayerOpen, setMobilePlayerOpen,
      isAddToPlaylistOpen, trackIdToAdd, openAddToPlaylist, closeAddToPlaylist,
      isDeleteModalOpen, playlistToDelete, openDeleteModal, closeDeleteModal, confirmDeletePlaylist,
      isProfileModalOpen, setProfileModalOpen, likedPlaylistId, notifications, showNotification, dismissNotification,
      setView, goToArtist, getArtistStats, toggleFollowArtist, isArtistFollowed, goBack, playTrack, togglePlay, nextTrack, prevTrack, seek, setVolume, toggleRepeat, toggleShuffle,
      createPlaylist, editPlaylist, deletePlaylist, addToPlaylist, removeFromPlaylist, togglePlaylistSave, toggleLike, isLiked,
      toggleAlbumLike, isAlbumLiked
    }}>
      {children}
    </StoreContext.Provider>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { useStore } from '../context/StoreContext.tsx';
import { 
  X, Mic2, Shield, User, UploadCloud, Calendar, FileAudio, 
  CheckCircle, XCircle, Clock, MoreVertical, Image, Plus,
  Edit, ArrowLeft, Camera, LogOut, ChevronDown, Trash2, ListMusic, Check, Search, Play, BarChart2, Globe, Database, Key, Settings, ChevronUp
} from './Icons.tsx';
import { DistributionTrack, ReleaseType, ReleaseRequest } from '../types.ts';

type HubView = 'AUTH' | 'ARTIST_DASH' | 'MOD_DASH' | 'DISTRIBUTION' | 'PROFILE_EDIT' | 'ARTIST_PICK' | 'MOD_CREDENTIALS' | 'MOD_ALL_RELEASES' | 'MOD_SETTINGS' | 'MOD_ALL_TRACKS';

const formatDuration = (seconds: number) => {
    const min = Math.floor(seconds / 60);
    const sec = Math.floor(seconds % 60);
    return `${min}:${sec.toString().padStart(2, '0')}`;
};

export const ArtistHub = () => {
  const { 
    isArtistHubOpen, setArtistHubOpen, currentArtist, currentModerator, 
    loginArtistOrMod, registerArtist, registerModerator, logoutArtistHub, artistAccounts,
    releaseRequests, profileEditRequests, approveArtist, rejectArtist,
    approveRelease, rejectRelease, approveProfileEdit, rejectProfileEdit,
    submitRelease, updateReleaseRequest, getArtistStats, submitProfileEdit, hasModerator, existingArtists,
    deleteRelease, getTrackByHueq, tracks, albums, playlists, showNotification, deleteArtistAccount, getTrackCover, getAlbumCover,
    changeArtistPassword, changeModeratorPassword, deleteLegacyTrack, t
  } = useStore();

  const [view, setView] = useState<HubView>('AUTH');

  // Auth State
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [role, setRole] = useState<'ARTIST' | 'MODERATOR'>('ARTIST');
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");

  // Artist Registration Logic
  const [artistNameSelection, setArtistNameSelection] = useState("");
  const [isCreatingNewArtist, setIsCreatingNewArtist] = useState(false);
  const [newArtistAlias, setNewArtistAlias] = useState("");

  const [message, setMessage] = useState("");

  // Distribution State
  const [distStep, setDistStep] = useState(1);
  const [distTitle, setDistTitle] = useState("");
  const [distArtistName, setDistArtistName] = useState(""); // For Mods to override
  const [distType, setDistType] = useState<ReleaseType>('Single');
  const [distGenre, setDistGenre] = useState("Pop");
  const [distLabel, setDistLabel] = useState("");
  const [distCovers, setDistCovers] = useState<string[]>([]);
  const [distMainArtists, setDistMainArtists] = useState<string[]>([]);
  const [distMainArtistInput, setDistMainArtistInput] = useState("");
  const [distTracks, setDistTracks] = useState<DistributionTrack[]>([]);

  // Editing Mode
  const [isEditing, setIsEditing] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  // Track Tag Inputs (Step 2)
  const [trackArtistInputs, setTrackArtistInputs] = useState<Record<number, string>>({});

  const [distDate, setDistDate] = useState("");
  const [distTime, setDistTime] = useState("00:00");
  const [distMsg, setDistMsg] = useState("");

  // Edit Profile State
  const [editBio, setEditBio] = useState("");
  const [editAvatar, setEditAvatar] = useState("");
  const [editNewPassword, setEditNewPassword] = useState("");

  // Mod Settings State
  const [modNewPassword, setModNewPassword] = useState("");

  // Artist Pick State
  const [pickSearch, setPickSearch] = useState("");

  // Release Detail Modal State
  const [selectedRelease, setSelectedRelease] = useState<ReleaseRequest | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const coverInputRef = useRef<HTMLInputElement>(null);
  const avatarInputRef = useRef<HTMLInputElement>(null);

  // Initialize view based on login state
  useEffect(() => {
      if (isArtistHubOpen) {
          if (currentArtist) {
              setView('ARTIST_DASH');
              setEditBio(currentArtist.bio || "");
              setEditAvatar(currentArtist.avatar || "");
              setEditNewPassword("");
          }
          else if (currentModerator) {
              setView('MOD_DASH');
              setModNewPassword("");
          }
          else setView('AUTH');
      }
  }, [isArtistHubOpen, currentArtist, currentModerator]);

  if (!isArtistHubOpen) return null;

  const handleLogin = (e: React.FormEvent) => {
      e.preventDefault();
      setMessage("");
      const res = loginArtistOrMod(username, password, role);
      if (res.success) {
          if (role === 'ARTIST') {
              setView('ARTIST_DASH');
          }
          else setView('MOD_DASH');
          showNotification(t('welcomeBack'), "success");
      } else {
          setMessage(res.message || t('invalidCreds'));
      }
  };

  const handleRegister = (e: React.FormEvent) => {
      e.preventDefault();

      if (role === 'MODERATOR') {
          if (hasModerator) {
              setMessage(t('modExists'));
              return;
          }
          const res = registerModerator({ username, password });
          if (res.success) {
              setMessage("Moderator registered! Please login.");
              setAuthMode('LOGIN');
          } else {
              setMessage(res.message || "Error registering moderator");
          }
          return;
      }

      // Artist Registration
      const finalArtistName = isCreatingNewArtist ? newArtistAlias : artistNameSelection;

      if (!finalArtistName) {
          setMessage(t('fillAll'));
          return;
      }

      const res = registerArtist({
          artistName: finalArtistName, 
          username, 
          password,
          artistPick: undefined
      });

      if (res.success) {
          setMessage(t('regSent'));
          setAuthMode('LOGIN');
      } else {
          setMessage(res.message || "Error registering");
      }
  };

  // --- Distribution Handlers ---
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          // Convert to Base64 for persistence
          const reader = new FileReader();
          reader.onloadend = () => {
              const base64Audio = reader.result as string;

              // Create temp audio element to get duration
              const audio = new Audio(base64Audio);
              audio.onloadedmetadata = () => {
                  const newTrack: DistributionTrack = {
                      title: file.name.replace(/\.[^/.]+$/, ""),
                      explicit: false,
                      mainArtists: [],
                      genre: distGenre, // Default to release genre
                      duration: audio.duration,
                      fileUrl: base64Audio
                  };
                  setDistTracks(prev => [...prev, newTrack]);
              };
          };
          reader.readAsDataURL(file);
      }
  };

  const updateTrack = (idx: number, field: keyof DistributionTrack, val: any) => {
      setDistTracks(prev => {
          const newTracks = [...prev];
          newTracks[idx] = { ...newTracks[idx], [field]: val };
          return newTracks;
      });
  };

  const moveTrack = (index: number, direction: 'up' | 'down') => {
      if (direction === 'up' && index > 0) {
          setDistTracks(prev => {
              const newTracks = [...prev];
              [newTracks[index], newTracks[index - 1]] = [newTracks[index - 1], newTracks[index]];
              return newTracks;
          });
      } else if (direction === 'down' && index < distTracks.length - 1) {
          setDistTracks(prev => {
              const newTracks = [...prev];
              [newTracks[index], newTracks[index + 1]] = [newTracks[index + 1], newTracks[index]];
              return newTracks;
          });
      }
  };

  // Track Artist Tag Handlers
  const addTrackArtist = (trackIdx: number) => {
      const name = trackArtistInputs[trackIdx];
      if (!name) return;

      setDistTracks(prev => {
          const newTracks = [...prev];
          const currentArtists = newTracks[trackIdx].mainArtists || [];
          newTracks[trackIdx] = { 
              ...newTracks[trackIdx], 
              mainArtists: [...currentArtists, name] 
          };
          return newTracks;
      });

      setTrackArtistInputs(prev => ({ ...prev, [trackIdx]: "" }));
  };

  const removeTrackArtist = (trackIdx: number, artistToRemove: string) => {
      setDistTracks(prev => {
          const newTracks = [...prev];
          const currentArtists = newTracks[trackIdx].mainArtists || [];
          newTracks[trackIdx] = { 
              ...newTracks[trackIdx], 
              mainArtists: currentArtists.filter(a => a !== artistToRemove) 
          };
          return newTracks;
      });
  };

  const handleHueqBlur = (idx: number, hueq: string) => {
      if (!hueq) return;
      const existing = getTrackByHueq(hueq);

      if (existing) {
          setDistTracks(prev => {
              const newTracks = [...prev];
              newTracks[idx] = {
                  ...newTracks[idx],
                  title: existing.title,
                  explicit: existing.explicit || false,
                  feat: existing.feat || "",
                  existingHueq: hueq,
                  fileUrl: existing.url,
                  duration: existing.duration,
                  genre: existing.genre, // Sync genre
                  mainArtists: existing.mainArtists || []
              };
              return newTracks;
          });
          showNotification(`HUEQ Found! Track details auto-filled: ${existing.title}`, "success");
      } else {
          updateTrack(idx, 'existingHueq', hueq);
      }
  };

  const handleNextStep = () => {
      if (distStep === 1) {
          if (!distTitle || !distType || !distGenre || distCovers.length === 0) {
              showNotification(t('completeFields'), "error");
              return;
          }
          if (currentModerator && !distArtistName) {
              showNotification(t('artistNameReq'), "error");
              return;
          }
      }
      if (distStep === 2) {
          if (distTracks.length === 0) {
              showNotification(t('addOneTrack'), "error");
              return;
          }
      }
      setDistStep(prev => prev + 1);
  };

  const handleSubmitRelease = () => {
      if (!distDate || !distTime) {
          showNotification(t('specifyDate'), "error");
          return;
      }

      const dateTime = new Date(`${distDate}T${distTime}:00+03:00`);

      // Determine Artist Identity
      const overrideArtist = currentModerator ? { 
          artistId: isEditing && editingId && !editingId.startsWith('a') ? (releaseRequests.find(r => r.id === editingId)?.artistId || `va_${Date.now()}`) : `va_${Date.now()}`,
          artistName: distArtistName || "Various Artists" 
      } : undefined;

      const payload = {
          title: distTitle,
          type: distType,
          genre: distGenre,
          label: distLabel || (currentArtist?.artistName || distArtistName || "Independent"),
          covers: distCovers, 
          additionalMainArtists: distMainArtists,
          tracks: distTracks,
          releaseDate: dateTime.toISOString(),
          releaseMessage: distMsg
      };

      if (isEditing && editingId) {
          updateReleaseRequest(editingId, {
              ...payload,
              // If mod is editing, allow updating artist name/id
              artistName: overrideArtist?.artistName || releaseRequests.find(r => r.id === editingId)?.artistName || ""
          });
          showNotification(t('releaseUpdated'), "success");
      } else {
          submitRelease(payload, overrideArtist);
          showNotification(t('releaseSubmitted'), "success");
      }

      // Navigate back
      if (currentModerator) {
          setView('MOD_ALL_RELEASES');
      } else {
          setView('ARTIST_DASH');
      }

      resetDistForm();
  };

  const resetDistForm = () => {
      setDistStep(1); 
      setDistTitle(""); 
      setDistArtistName("");
      setDistTracks([]); 
      setDistCovers([]); 
      setDistMsg(""); 
      setDistMainArtists([]); 
      setTrackArtistInputs({});
      setIsEditing(false);
      setEditingId(null);
  };

  const handleCoverUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const files = e.target.files;
      if (files && files.length > 0) {
          Array.from(files).forEach((file: File) => {
              const reader = new FileReader();
              reader.onloadend = () => setDistCovers(prev => [...prev, reader.result as string]);
              reader.readAsDataURL(file);
          });
      }
  };

  const handleAvatarUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setEditAvatar(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleProfileUpdate = () => {
      if (!currentArtist) return;
      submitProfileEdit({ newBio: editBio, newAvatar: editAvatar });

      if (editNewPassword) {
          changeArtistPassword(editNewPassword);
      }

      showNotification(t('profileUpdateSent'), "success");
      setView('ARTIST_DASH');
  };

  const handleModPasswordChange = () => {
      if (!modNewPassword) {
          showNotification("Password cannot be empty", "error");
          return;
      }
      changeModeratorPassword(modNewPassword);
      setView('MOD_DASH');
  };

  const handleEditRelease = (release: any) => {
      setIsEditing(true);
      setEditingId(release.id);

      setDistTitle(release.title);
      setDistType(release.type);
      setDistGenre(release.genre);
      setDistLabel(release.label || release.recordLabel || "");
      setDistCovers(release.covers);
      setDistMainArtists(release.additionalMainArtists || release.mainArtists || []);
      setDistTracks(release.tracks || []);

      // If mod, allow editing artist name
      if (currentModerator) {
          setDistArtistName(release.artistName || release.artist);
      }

      // Date Time parsing
      const dateObj = release.releaseDate ? new Date(release.releaseDate) : new Date();
      // Simple ISO to yyyy-MM-dd
      setDistDate(dateObj.toISOString().split('T')[0]);
      // Simple time
      setDistTime(dateObj.toTimeString().slice(0, 5));

      setDistMsg(release.releaseMessage || "");

      setDistStep(1);
      setView('DISTRIBUTION');
  };

  // --- RENDERERS ---

  const renderAuth = () => (
      <div className="fixed inset-0 overflow-y-auto bg-black flex items-center justify-center p-4">
          <div className="w-full max-w-md bg-surface p-8 rounded-xl shadow-2xl border border-surface-highlight animate-zoom-in my-8">
              <div className="flex justify-center mb-6">
                  <div className="w-16 h-16 bg-primary/20 rounded-full flex items-center justify-center animate-bounce">
                      {role === 'ARTIST' ? <Mic2 size={32} className="text-primary" /> : <Shield size={32} className="text-primary" />}
                  </div>
              </div>
              <h2 className="text-2xl font-bold text-center mb-6">{authMode === 'LOGIN' ? `${t('login')} ` : `${t('signup')} `} Huevify For {role === 'ARTIST' ? t('artists') : 'Moderators'}</h2>

              <div className="flex bg-surface-highlight p-1 rounded-full mb-6">
                  <button 
                      onClick={() => setRole('ARTIST')} 
                      className={`flex-1 py-2 rounded-full text-sm font-bold transition-all duration-300 ${role === 'ARTIST' ? 'bg-primary text-black shadow-lg' : 'text-secondary hover:text-white'}`}
                  >
                      {t('artist')}
                  </button>

                  {(!hasModerator || authMode === 'LOGIN') && (
                      <button 
                          onClick={() => setRole('MODERATOR')}
                          className={`flex-1 py-2 rounded-full text-sm font-bold transition-all duration-300 ${role === 'MODERATOR' ? 'bg-primary text-black shadow-lg' : 'text-secondary hover:text-white'}`}
                      >
                          Moderator
                      </button>
                  )}
              </div>

              {message && <div className="bg-red-500/20 text-red-500 p-3 rounded mb-4 text-center text-sm animate-pulse">{message}</div>}

              <form onSubmit={authMode === 'LOGIN' ? handleLogin : handleRegister} className="flex flex-col gap-4">

                  {authMode === 'REGISTER' && role === 'ARTIST' && (
                      <div className="flex flex-col gap-2 animate-slide-up">
                          {!isCreatingNewArtist ? (
                              <div className="relative">
                                  <select 
                                      value={artistNameSelection}
                                      onChange={(e) => setArtistNameSelection(e.target.value)}
                                      className="w-full bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none appearance-none transition-colors"
                                  >
                                      <option value="">{t('select')} {t('artist')}...</option>
                                      {existingArtists.map(a => <option key={a} value={a}>{a}</option>)}
                                  </select>
                                  <ChevronDown className="absolute right-3 top-3 text-secondary pointer-events-none" size={20}/>
                              </div>
                          ) : (
                              <input 
                                  type="text" 
                                  placeholder="New Artist Alias" 
                                  value={newArtistAlias} 
                                  onChange={e => setNewArtistAlias(e.target.value)}
                                  className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none transition-colors"
                              />
                          )}

                          <label className="flex items-center gap-2 cursor-pointer mt-1">
                              <input 
                                  type="checkbox" 
                                  checked={isCreatingNewArtist}
                                  onChange={e => setIsCreatingNewArtist(e.target.checked)}
                              />
                              <span className="text-xs text-secondary">Create new artist</span>
                          </label>
                      </div>
                  )}

                  <input 
                      type="text" placeholder={t('username')} value={username} onChange={e => setUsername(e.target.value)}
                      className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none transition-colors"
                  />
                  <input 
                      type="password" placeholder={t('password')} value={password} onChange={e => setPassword(e.target.value)}
                      className="bg-background p-3 rounded border border-surface-highlight focus:border-primary focus:outline-none transition-colors"
                  />

                  <button type="submit" className="bg-primary text-black font-bold py-3 rounded-full hover:scale-105 transition-transform mt-2 shadow-lg hover:shadow-primary/20">
                      {authMode === 'LOGIN' ? t('login') : 'Submit Application'}
                  </button>
              </form>

              <p className="text-center text-secondary text-sm mt-4">
                  {authMode === 'LOGIN' ? "Don't have an account?" : "Already have an account?"} 
                  <button onClick={() => { setAuthMode(authMode === 'LOGIN' ? 'REGISTER' : 'LOGIN'); setMessage(""); }} className="text-white font-bold ml-1 hover:underline">
                      {authMode === 'LOGIN' ? t('signup') : t('login')}
                  </button>
              </p>
          </div>
      </div>
  );

  const renderModCredentials = () => (
      <div className="w-full h-full flex flex-col p-6 relative animate-fade-in">
          <div className="flex items-center gap-4 mb-8 shrink-0">
               <button onClick={() => setView('MOD_DASH')} className="text-secondary hover:text-white"><ArrowLeft size={24}/></button>
               <h1 className="text-3xl font-bold flex items-center gap-3"><Key className="text-primary"/> {t('artistCreds')}</h1>
          </div>

          <div className="flex-1 overflow-y-auto bg-surface rounded-xl border border-surface-highlight">
              <table className="w-full text-left border-collapse">
                  <thead className="bg-surface-highlight text-secondary text-xs uppercase font-bold sticky top-0 z-10">
